#include <stdio.h>

int main(void)
{
	int a = 1;
	int b = 1;
	
	while (a <= 9){
		if ((a <= 9) && (b <= 9)){
			printf("%dx%d=%d\n", a, b, a * b);
			b++;
		}
		else if (b = 10){
			a++;
			b = b - 9;
		}
	}
	
	return (0);
}

