import java.io.*;
// A filename matches when its final extension equals the requested extension.
public class Main {
    public static void main(String[] args)throws Exception{
        BufferedReader br=new BufferedReader(new InputStreamReader(System.in));
        int n=Integer.parseInt(br.readLine().trim());
        String[] files=new String[n];
        for(int i=0;i<n;i++)files[i]=br.readLine().trim();
        String ext=br.readLine().trim();
        if(!ext.isEmpty()&&!ext.startsWith("."))ext="."+ext;
        boolean any=false;
        for(String file:files){
            int dot=file.lastIndexOf('.');
            if(dot>=0&&file.substring(dot).equalsIgnoreCase(ext)){
                System.out.println(file);
                any=true;
            }
        }
        if(!any)System.out.println("No Records Found");
    }
}

