import java.io.*;
import java.util.*;

public class Main {
    // Search Products with Low Stock — P000401

    // Deterministic input convention: N product records as `name|quantity`; final line is the quantity threshold.

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String first = br.readLine();
        if (first == null || first.trim().isEmpty()) return;

        int n = Integer.parseInt(first.trim());
        String[] records = new String[n];
        for (int i = 0; i < n; i++) {
            String line = br.readLine();
            records[i] = line == null ? "" : line;
        }
        int threshold = Integer.parseInt(br.readLine().trim());
        StringBuilder out = new StringBuilder();

        for (String record : records) {
            String[] fields = record.split("\\|", -1);
            if (fields.length >= 2 && Integer.parseInt(fields[1].trim()) < threshold) {
                if (out.length() > 0) out.append('\n');
                out.append(record);
            }
        }
        System.out.print(out);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    // Search Flights by Destination — P000402

    // Deterministic input convention: N records as `flightNo|destination`; final line is the exact destination.

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String first = br.readLine();
        if (first == null || first.trim().isEmpty()) return;

        int n = Integer.parseInt(first.trim());
        String[] records = new String[n];
        for (int i = 0; i < n; i++) {
            String line = br.readLine();
            records[i] = line == null ? "" : line;
        }
        String target = br.readLine().trim();
        List<String> matches = new ArrayList<>();

        for (String record : records) {
            StringTokenizer fields = new StringTokenizer(record, "|");
            if (fields.hasMoreTokens()) {
                fields.nextToken();
                if (fields.hasMoreTokens() && fields.nextToken().trim().equals(target)) {
                    matches.add(record);
                }
            }
        }

        System.out.print(String.join("\n", matches));
    }
}

import java.io.*;
import java.util.*;

public class Main {
    // Search Trains Departing from a Station — P000403

    // Deterministic input convention: N records as `trainNo|station`; final line is the exact station.

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String first = br.readLine();
        if (first == null || first.trim().isEmpty()) return;

        int n = Integer.parseInt(first.trim());
        String[] records = new String[n];
        for (int i = 0; i < n; i++) {
            String line = br.readLine();
            records[i] = line == null ? "" : line;
        }
        String station = br.readLine().trim();
        StringBuilder result = new StringBuilder();

        for (int i = 0; i < records.length; i++) {
            String record = records[i];
            int separator = record.indexOf('|');

            if (separator >= 0) {
                String departure = record.substring(separator + 1).trim();
                if (departure.equals(station)) {
                    if (result.length() != 0) result.append(System.lineSeparator());
                    result.append(record);
                }
            }
        }

        System.out.print(result);
    }
}

