import java.io.*;
import java.util.*;

public class Main {
    // Search Courses by Instructor — P000405

    // Deterministic input convention: N records as `courseName|instructor`; final line is the instructor name.

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String first = br.readLine();
        if (first == null || first.trim().isEmpty()) return;

        int n = Integer.parseInt(first.trim());
        String[] records = new String[n];
        for (int i = 0; i < n; i++) {
            String line = br.readLine();
            records[i] = line == null ? "" : line;
        }

        String instructor = br.readLine().trim();
        List<String> matches = new ArrayList<>();

        for (String record : records) {
            if (hasInstructor(record, instructor)) {
                matches.add(record);
            }
        }

        for (int i = 0; i < matches.size(); i++) {
            if (i > 0) System.out.println();
            System.out.print(matches.get(i));
        }
    }

    private static boolean hasInstructor(String record, String instructor) {
        int pipe = record.lastIndexOf('|');
        return pipe >= 0 && record.substring(pipe + 1).trim().equals(instructor);
    }
}

import java.io.*;
