public class Main {
    // Search Duplicate Email Addresses — P000424

    // Deterministic input convention: N lines containing one email address; duplicates are printed once in first-seen order.

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String first = br.readLine();
        if (first == null || first.trim().isEmpty()) return;

        int n = Integer.parseInt(first.trim());
        String[] records = new String[n];
        for (int i = 0; i < n; i++) {
            String line = br.readLine();
            records[i] = line == null ? "" : line;
        }
        LinkedHashMap<String, Integer> frequency = new LinkedHashMap<>();

        for (String record : records) {
            String email = record.trim();
            frequency.put(email, frequency.getOrDefault(email, 0) + 1);
        }

        StringBuilder out = new StringBuilder();
        for (Map.Entry<String, Integer> entry : frequency.entrySet()) {
            if (entry.getValue() > 1) {
                if (out.length() > 0) out.append('\n');
                out.append(entry.getKey());
            }
        }
        System.out.print(out);
    }
}

