                a = Integer.parseInt(temp[0]);
                b = Integer.parseInt(temp[1]);
                sb.append(String.valueOf(a + b).length() + "\r\n");

                str = br.readLine();
            }
        } catch (IOException e) {
            // NOP
        } finally {
            if (br != null) {
                br.close();
            }
        }

        System.out.print(sb);
    }
}

