	public static int[] sortInteger(int[] num) {
		int len = num.length;
		for (int i = 0; i < len; i++) {
			for (int j = i+1; j < len; j++) {
				if (num[i] < num[j]) {
					int tmp = num[i];
					num[i] = num[j];
					num[j] = tmp;
				}
			}
		}
		return num;
	}
}

