					System.out.println("YES");
				}else{
					System.out.println("NO");
				}
				break;
			case 2:
				if(Math.pow(triangle[i][2],2) == Math.pow(triangle[i][0],2) + Math.pow(triangle[i][1],2)){
					System.out.println("YES");
				}else{
					System.out.println("NO");
				}
				break;
			}

		}
	}
}

