public class Main{
	
	public static long findGcd(long f1, long f2){
		long gcd = 1;
		long max, min;
		if(f1 > f2){max = f1; min = f2;}
		else{max = f2; min = f1;}
		
		if(max % min == 0){
			return min;
		}
		
		for(long i=1; i<(long)(Math.sqrt(min)+1); i++){
			if((min % i) == 0){
				if((max % i) == 0){
					if(gcd < i)gcd = i;
				}
				long tmp = min/i;
				if((max % tmp) == 0){
					if(gcd < tmp)gcd = tmp;
				}
			}
		}
		return gcd;
	}
	
	
	public static long findlcm(long f1, long f2){
		long lcm = 0;
		long max, min;
		if(f1 > f2){max = f1; min = f2;}
		else{max = f2; min = f1;}
		long i=1;
		while(lcm == 0){
			if((max * i)%min == 0){
				lcm = max * i;
			}
			i++;
		}
		return lcm;
	}
	
