class GL {
	public long GCD,LCM;

	public GL(long a,long b){
		long g = gcd(a,b);
		this.GCD = g;
		this.LCM = a * b / g;
	}
	private long gcd(long a,long b){
		while( a != b ){
			if( a < b ){
				b -= a;
			} else if( a > b ){
				a -= b;
			}
		}
		return a;
	}
}

