		return a * b / LCM(a, b);
	}
	
	static long LCM(long a, long b) {
		long n0 = (a >= b) ? a: b;
		long n1 = (a >= b) ? b: a;
		
		if(n1 == 0) return n0;
		else return LCM(n1, n0 % n1);
	}
}

