	public static int gcd(int a, int b) {
		int r;
		int max = Math.max(a, b);
		int mini = Math.min(a, b);
		do {
			r = max % mini; // max = q*mini + r , mini > r
			max = mini;
			mini = r;
		} while (r != 0);
		return max;
	}

	public static int lcm(int a, int b) {
		int d = gcd(a, b);
		return a/d * b;
	}
}

