	public static long LCM(long a,long b){
		long max=Math.max(a, b),ans=0;
		long min;
		
		if(max==a){
			min=b;
		}else{
			min=a;
		}
		for(long i=1;i<=LONGEST;i++){
			if((max*i)%min==0){
				ans=max*i;
				 break;
			}
		}
		return ans;
	}
	
	public static long GCD(long a,long b){
		long gcd;
		if(b==0){
			gcd=a;
		}else{
			gcd=GCD(b,a%b);
		}
		return gcd;
	}

}

