	      b = a;
	      a = candidate;
	    }
	    return candidate;
	}
    
    static long LCM (long a, long b){
		long GCD = GCD(a, b);
		//System.out.println("GCD("+a+","+b+") is "+GCD);
		return GCD * (a/GCD) * (b/GCD);
	}
 
}

