import java.io.*;
import java.util.*;
public class Main {
    // P000573 - Binary Tree Zigzag Level Order Traversal

    static class Node{
        int v;
        Node l,r;
        Node(int x){
            v=x;
        }
    }
    static Node tree(String line){
        if(line==null||line.trim().isEmpty()||line.trim().equals("#"))return null;
        String[] a=line.trim().split("\\s+");
        if(a.length==0)return null;
        Node root=new Node(Integer.parseInt(a[0]));
        Queue<Node>q=new ArrayDeque<>();
        q.add(root);
        int i=1;
        while(!q.isEmpty()&&i<a.length){
            Node u=q.remove();
            if(i<a.length&&!a[i].equals("#")){
                u.l=new Node(Integer.parseInt(a[i]));
                q.add(u.l);
            }
            i++;
            if(i<a.length&&!a[i].equals("#")){
                u.r=new Node(Integer.parseInt(a[i]));
                q.add(u.r);
            }
            i++;
        }
        return root;
    }
    static void printList(List<Integer>a){
        for(int i=0;i<a.size();i++){
            if(i>0)System.out.print(" ");
            System.out.print(a.get(i));
        }
        System.out.println();
    }

    public static void main(String[] args)throws Exception{
        BufferedReader br=new BufferedReader(new InputStreamReader(System.in));
        Node root=tree(br.readLine());
        if(root==null){
            System.out.println("[]");
            return;
        }
        Deque<Node>q=new ArrayDeque<>();
        q.add(root);
        boolean rev=false;
        StringBuilder z=new StringBuilder();
        while(!q.isEmpty()){
            int n=q.size();
            List<Integer>a=new ArrayList<>();
            while(n-->0){
                Node u=q.remove();
                a.add(u.v);
                if(u.l!=null)q.add(u.l);
                if(u.r!=null)q.add(u.r);
            }
            if(rev)Collections.reverse(a);
            z.append(a).append(" ");
            rev=!rev;
        }
        System.out.println(z);
    }
}

