        }
        Queue<P>q=new ArrayDeque<>();
        q.add(new P(root,0));
        long best=0;
        while(!q.isEmpty()){
            int n=q.size();
            long base=q.peek().i,last=0;
            for(int j=0;j<n;j++){
                P u=q.remove();
                last=u.i-base;
                if(u.n.l!=null)q.add(new P(u.n.l,2*last));
                if(u.n.r!=null)q.add(new P(u.n.r,2*last+1));
            }
            best=Math.max(best,last+1);
        }
        System.out.println(best);
