    if (!root) return 0;
    mask ^= (1 << root->val);
    
    if (!root->left && !root->right) {
        return (mask & (mask - 1)) == 0 ? 1 : 0;
    }
    
    return countPseudoPalindromicPaths(root->left, mask) + 
           countPseudoPalindromicPaths(root->right, mask);
}

