def read_tree(a,p,separate=False):
    n=int(a[p]); p+=1
    v=[0]*n; L=[-1]*n; R=[-1]*n
    if separate:
        for i in range(n): v[i]=int(a[p]); p+=1
        for i in range(n): L[i]=int(a[p]); R[i]=int(a[p+1]); p+=2
    else:
        for i in range(n): v[i]=int(a[p]); L[i]=int(a[p+1]); R[i]=int(a[p+2]); p+=3
    return n,v,L,R,p

def reachable(n,L,R):
    if n==0:return []
    out=[]; seen=set(); st=[0]
    while st:
        u=st.pop()
        if u<0 or u in seen or u>=n: continue
        seen.add(u); out.append(u)
        if R[u]>=0: st.append(R[u])
        if L[u]>=0: st.append(L[u])
    return out

def print_tree(n,v,L,R):
    if n==0:
        print(0); return
    order=reachable(n,L,R); mp={u:i for i,u in enumerate(order)}
    out=[str(len(order))]
    for u in order:
        out.append(f"{v[u]} {mp.get(L[u],-1)} {mp.get(R[u],-1)}")
    sys.stdout.write('\n'.join(out)+'\n')

