#define MAX_ITEMS 1005
typedef struct { char k[64], v[64]; } Entry;
Entry entries[MAX_ITEMS];
int size = 0;
int cmp(const void* a, const void* b) { return strcmp(((Entry*)a)->k, ((Entry*)b)->k); }
int main() {
    int q;
    if (scanf("%d", &q) == 1) {
        while (q--) {
            char cmd[32]; scanf("%31s", cmd);
