                int k; std::cin >> k;
                cursor = std::max(0, cursor - k);
                int l = std::max(0, cursor - 10);
                std::cout << text.substr(l, cursor - l) << std::endl;
            } else if (cmd == "cursorRight") {
                int k; std::cin >> k;
                cursor = std::min((int)text.length(), cursor + k);
                int l = std::max(0, cursor - 10);
                std::cout << text.substr(l, cursor - l) << std::endl;
            }
        }
    }
    return 0;
}

