                int i; std::cin >> i;
                if (i > 0) {
                    std::swap(tabs[i], tabs[i-1]);
                    if (cur_idx == i) cur_idx = i - 1;
                    else if (cur_idx == i - 1) cur_idx = i;
                }
            } else if (cmd == "moveRight") {
                int i; std::cin >> i;
                if (i < (int)tabs.size() - 1) {
                    std::swap(tabs[i], tabs[i+1]);
                    if (cur_idx == i) cur_idx = i + 1;
                    else if (cur_idx == i + 1) cur_idx = i;
                }
            } else if (cmd == "current") {
                std::cout << (tabs.empty() ? "" : tabs[cur_idx]) << std::endl;
            }
        }
    }
    return 0;
}

