    if (std::cin >> s) {
        std::vector<std::string> res;
        case_perm(s, 0, "", res);
        std::sort(res.begin(), res.end());
        for (const auto& p : res) std::cout << p << std::endl;
    }
    return 0;
}

#include <queue>

struct TreeNode {
    int val;
    TreeNode *left;
    TreeNode *right;
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
};

class Solution {
public:
    int firstNonFullNode(TreeNode* root) {
        if (!root) return -1;
        std::queue<TreeNode*> q;
        q.push(root);

        while (!q.empty()) {
            TreeNode* node = q.front();
            q.pop();
            if (!node->left || !node->right) return node->val;
            q.push(node->left);
            q.push(node->right);
        }
        return -1;
    }
};

struct TreeNode {
    int val;
    TreeNode *left;
    TreeNode *right;
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
};

class Solution {
    int maxDepth = -1, res = 0;

    void dfs(TreeNode* node, int depth) {
        if (!node) return;
        if (depth > maxDepth) {
            maxDepth = depth;
            res = node->val;
        }
        dfs(node->left, depth + 1);
        dfs(node->right, depth + 1);
    }
public:
    int findBottomLeftValue(TreeNode* root) {
        maxDepth = -1;
        res = root->val;
        dfs(root, 0);
        return res;
    }
};

