struct TreeNode {
    int val;
    TreeNode *left;
    TreeNode *right;
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
};

class Solution {
    std::unordered_map<int, int> count;

    void dfs(TreeNode* node) {
        if (!node) return;
        count[node->val]++;
        dfs(node->left);
        dfs(node->right);
    }
public:
    std::vector<int> findMode(TreeNode* root) {
        count.clear();
        dfs(root);
        int maxF = 0;
        for (auto& [k, v] : count) maxF = std::max(maxF, v);

        std::vector<int> res;
        for (auto& [k, v] : count) {
            if (v == maxF) res.push_back(k);
        }
        return res;
    }
};

struct TreeNode {
    int val;
    TreeNode *left;
    TreeNode *right;
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
};

class Solution {
    int centroid = -1;
    int totalNodes = 0;

    int countNodes(TreeNode* node) {
        if (!node) return 0;
        return 1 + countNodes(node->left) + countNodes(node->right);
    }

    int dfs(TreeNode* node) {
        if (!node) return 0;
        int l = dfs(node->left);
        int r = dfs(node->right);
        int parentSize = totalNodes - (1 + l + r);

        if (l <= totalNodes / 2 && r <= totalNodes / 2 && parentSize <= totalNodes / 2) {
            centroid = node->val;
        }

        return 1 + l + r;
    }
public:
    int findCentroid(TreeNode* root) {
        centroid = -1;
        totalNodes = countNodes(root);
        dfs(root);
        return centroid;
    }
};

struct TreeNode {
    int val;
    TreeNode *left;
    TreeNode *right;
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
};

class Solution {
public:
    TreeNode* lowestCommonAncestor(TreeNode* root, TreeNode* p, TreeNode* q) {
        TreeNode* cur = root;
        while (cur) {
            if (p->val < cur->val && q->val < cur->val) {
                cur = cur->left;
            } else if (p->val > cur->val && q->val > cur->val) {
                cur = cur->right;
            } else {
                return cur;
            }
        }
        return nullptr;
    }
};

#include <stack>

struct TreeNode {
    int val;
    TreeNode *left;
    TreeNode *right;
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
};

class Solution {
public:
    int kthLargest(TreeNode* root, int k) {
        std::stack<TreeNode*> st;
        TreeNode* cur = root;

        while (cur || !st.empty()) {
            while (cur) {
                st.push(cur);
                cur = cur->right;
            }
            cur = st.top();
            st.pop();
            if (--k == 0) return cur->val;
            cur = cur->left;
        }
        return -1;
    }
};

