    vector<int> vals(n);
    for (int i = 0; i < n; ++i) cin >> vals[i];
    
    TreeNode* root = buildTree(vals);
    int result = findFirstNonFullNode(root);
    
    if (result != -1) cout << result << endl;
    else cout << "NONE" << endl;
    
    return 0;
}

