int findLeftmostDeepestNode(TreeNode* root) {
    if (!root) return -1;
    
    queue<TreeNode*> q;
    q.push(root);
    int result = root->val;
    
    while (!q.empty()) {
        int size = q.size();
        for (int i = 0; i < size; ++i) {
            TreeNode* node = q.front(); q.pop();
            if (i == 0) result = node->val;
            if (node->left) q.push(node->left);
            if (node->right) q.push(node->right);
        }
    }
    return result;
}

