    static java.math.BigInteger validInsertionBig(T t,int u){if(u<0)return java.math.BigInteger.ONE;
int l=t.a.get(u).l,r=t.a.get(u).r;
int ls=l<0?0:sz(t,l),rs=r<0?0:sz(t,r);
return binomBig(ls+rs,ls).multiply(validInsertionBig(t,l)).multiply(validInsertionBig(t,r));
}
    static java.math.BigInteger binomBig(int n,int k){k=Math.min(k,n-k);
java.math.BigInteger z=java.math.BigInteger.ONE;
for(int i=1;i<=k;i++)z=z.multiply(java.math.BigInteger.valueOf(n-k+i)).divide(java.math.BigInteger.valueOf(i));
return z;
}
