const fs = require('fs');
function casePerm(s, idx, cur, res) {
    if (idx === s.length) {
        res.push(cur);
        return;
    }
    const ch = s[idx];
    if (/[a-zA-Z]/.test(ch)) {
        casePerm(s, idx + 1, cur + ch.toLowerCase(), res);
        casePerm(s, idx + 1, cur + ch.toUpperCase(), res);
    } else {
        casePerm(s, idx + 1, cur + ch, res);
    }
}
function main() {
    const tokens = fs.readFileSync(0, 'utf-8').trim().split(/\s+/);
    if (tokens.length >= 1 && tokens[0] !== '') {
        const res = [];
        casePerm(tokens[0], 0, "", res);
        res.sort();
        for (const p of res) console.log(p);
    }
}
main();

// Helper function to evaluate firstnonfullnode for problem constraints.
function firstNonFullNode(root) {
    if (!root) return -1;
    const q = [root];

    while (q.length) {
        const node = q.shift();
        if (!node.left || !node.right) return node.val;
        q.push(node.left);
        q.push(node.right);
    }
    return -1;
}

module.exports = { firstNonFullNode };

// Helper function to evaluate findbottomleftvalue for problem constraints.
function findBottomLeftValue(root) {
    let maxDepth = -1, res = root.val;

    // Helper function to evaluate dfs for problem constraints.
    function dfs(node, depth) {
        if (!node) return;
        if (depth > maxDepth) {
            maxDepth = depth;
            res = node.val;
        }
        dfs(node.left, depth + 1);
        dfs(node.right, depth + 1);
    }

    dfs(root, 0);
    return res;
}

module.exports = { findBottomLeftValue };

// Helper function to evaluate findmode for problem constraints.
function findMode(root) {
    const count = new Map();

    // Helper function to evaluate dfs for problem constraints.
    function dfs(node) {
        if (!node) return;
        count.set(node.val, (count.get(node.val) || 0) + 1);
        dfs(node.left);
        dfs(node.right);
    }

    dfs(root);
    let maxF = 0;
    for (const v of count.values()) {
        if (v > maxF) maxF = v;
    }

    const res = [];
    for (const [k, v] of count.entries()) {
        if (v === maxF) res.push(k);
    }
    return res;
}

module.exports = { findMode };

// Helper function to evaluate findcentroid for problem constraints.
function findCentroid(root) {
    // Helper function to evaluate countnodes for problem constraints.
    function countNodes(node) {
        if (!node) return 0;
        return 1 + countNodes(node.left) + countNodes(node.right);
    }

    const totalNodes = countNodes(root);
    let centroid = -1;

    // Helper function to evaluate dfs for problem constraints.
    function dfs(node) {
        if (!node) return 0;
        const l = dfs(node.left);
        const r = dfs(node.right);
        const parentSize = totalNodes - (1 + l + r);

        if (l <= Math.floor(totalNodes / 2) && r <= Math.floor(totalNodes / 2) && parentSize <= Math.floor(totalNodes / 2)) {
