class Solution:
    def findBottomLeftValue(self, root: TreeNode) -> int:
        max_depth = -1
        res = root.val

        def dfs(node, depth):
            nonlocal max_depth, res
            if not node:
                return
            if depth > max_depth:
                max_depth = depth
                res = node.val
            dfs(node.left, depth + 1)
            dfs(node.right, depth + 1)

        dfs(root, 0)
        return res

