static int possible(const long long *a, int n, int parts, long long limit)
{
    int used = 1;
    long long current = 0;

    for (int i = 0; i < n; ++i) {
        if (a[i] > limit) {
            return 0;
        }

        if (current + a[i] <= limit) {
            current += a[i];
        } else {
            ++used;
            current = a[i];
        }
    }

    return used <= parts;
}

