        int[] a = new int[n];
        long lo = 0, hi = 0;
        for (int i = 0; i < n; i++) {
            a[i] = Integer.parseInt(s[i]);
            lo = Math.max(lo, a[i]);
            hi += a[i];
        }
        while (lo < hi) {
            long mid = lo + (hi - lo) / 2;
            if (feasible(a, m, mid)) hi = mid;
            else lo = mid + 1;
        }
        System.out.println(lo);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static int peak(int[] a) {
        int lo = 0, hi = a.length - 1;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (a[mid] < a[mid + 1]) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }
    static int ascSearch(int[] a, int l, int r, int x) {
        while (l <= r) {
            int m = (l + r) >>> 1;
            if (a[m] == x) return m;
            if (a[m] < x) l = m + 1;
            else r = m - 1;
        }
        return -1;
    }
    static int descSearch(int[] a, int l, int r, int x) {
        while (l <= r) {
            int m = (l + r) >>> 1;
            if (a[m] == x) return m;
            if (a[m] > x) l = m + 1;
            else r = m - 1;
        }
        return -1;
    }
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] h = br.readLine().trim().split("\\s+");
        int n = Integer.parseInt(h[0]), target = Integer.parseInt(h[1]);
        String[] s = br.readLine().trim().split("\\s+");
        int[] a = new int[n];
        for (int i = 0; i < n; i++) a[i] = Integer.parseInt(s[i]);
        int p = peak(a);
        int ans = ascSearch(a, 0, p, target);
        if (ans == -1) ans = descSearch(a, p + 1, n - 1, target);
        System.out.println(ans);
    }
}

