        n = len(arr)
        min_right = [0] * n
        min_right[-1] = arr[-1]

        for i in range(n - 2, -1, -1):
            min_right[i] = min(arr[i], min_right[i + 1])

        max_left = 0
        chunks = 1

        for i in range(n - 1):
