long long merge(int l, int m, int r) {
    int i = l, j = m + 1, k = l;
    long long inv = 0;
    while (i <= m && j <= r) {
        if (nums[i] <= nums[j]) {
            temp[k++] = nums[i++];
        } else {
            temp[k++] = nums[j++];
            inv += (m - i + 1);
        }
    }
    while (i <= m) temp[k++] = nums[i++];
    while (j <= r) temp[k++] = nums[j++];
    for (int p = l; p <= r; p++) nums[p] = temp[p];
    return inv;
}
