long long merge_sort(int l, int r) {
    if (l >= r) return 0;
    int m = l + (r - l) / 2;
    long long inv = merge_sort(l, m);
    inv += merge_sort(m + 1, r);
    inv += merge(l, m, r);
    return inv;
}
