int kthSmallest(struct TreeNode* root, int k) {
    struct TreeNode** stack = (struct TreeNode**)malloc(10005 * sizeof(struct TreeNode*));
    int top = -1;
    struct TreeNode* cur = root;

    while (cur != NULL || top >= 0) {
        while (cur != NULL) {
            stack[++top] = cur;
            cur = cur->left;
        }
        cur = stack[top--];
        if (--k == 0) {
            int ans = cur->val;
            free(stack);
            return ans;
        }
        cur = cur->right;
    }
    free(stack);
    return -1;
}

