long long mergeCount(vector<long long>&a,int lo,int mid,int hi){
    vector<long long>tmp;int i=lo,j=mid+1;long long cnt=0;
    while(i<=mid&&j<=hi){if(a[i]<=a[j])tmp.push_back(a[i++]);else{tmp.push_back(a[j++]);cnt+=mid-i+1;}}
    while(i<=mid)tmp.push_back(a[i++]);while(j<=hi)tmp.push_back(a[j++]);
    for(int k=lo;k<=hi;++k)a[k]=tmp[k-lo];return cnt;
}
long long msort(vector<long long>&a,int lo,int hi){
    if(lo>=hi)return 0;int mid=(lo+hi)/2;
    return msort(a,lo,mid)+msort(a,mid+1,hi)+mergeCount(a,lo,mid,hi);
}
