int findMaxLevelDiff(TreeNode* root) {
    if (!root) return 0;
    
    queue<TreeNode*> q;
    q.push(root);
    long long prevSum = 0;
    int maxDiff = 0;
    bool first = true;
    
    while (!q.empty()) {
        int size = q.size();
        long long currSum = 0;
        
        for (int i = 0; i < size; ++i) {
            TreeNode* node = q.front(); q.pop();
            currSum += node->val;
            if (node->left) q.push(node->left);
            if (node->right) q.push(node->right);
        }
        
        if (!first) {
            maxDiff = max(maxDiff, (int)abs(currSum - prevSum));
        }
        prevSum = currSum;
        first = false;
    }
    return maxDiff;
}

