        int m=(l+r)>>>1;
        long c=sort(a,l,m,t)+sort(a,m+1,r,t);
        int i=l,j=m+1,k=l;
        while(i<=m&&j<=r){
            if(a[i]<=a[j])t[k++]=a[i++];
            else{
                t[k++]=a[j++];
                c+=m-i+1;
            }
        } while(i<=m)t[k++]=a[i++];
        while(j<=r)t[k++]=a[j++];
        for(i=l;i<=r;i++)a[i]=t[i];
        return c;
    }
    public static void main(String[] z)throws Exception{
        FS f=new FS();
        int n=f.nextInt();
        int[]a=new int[n],t=new int[n];
        for(int i=0;i<n;i++)a[i]=f.nextInt();
        System.out.println(sort(a,0,n-1,t));
    }
}

