}

public class Solution {
    private boolean isMirror(TreeNode t1, TreeNode t2) {
        if (t1 == null && t2 == null) return true;
        if (t1 == null || t2 == null || t1.val != t2.val) return false;
        return isMirror(t1.left, t2.right) && isMirror(t1.right, t2.left);
    }

    public boolean isSymmetric(TreeNode root) {
        return isMirror(root, root);
    }
}

import java.util.HashSet;
import java.util.Set;

class TreeNode {
    int val;
    TreeNode left, right;
    TreeNode(int val) { this.val = val; }
}

public class Solution {
    private Set<Integer> seen = new HashSet<>();

    private boolean dfs(TreeNode node) {
        if (node == null) return false;
        if (seen.contains(node.val)) return true;
        seen.add(node.val);
        return dfs(node.left) || dfs(node.right);
    }

    public boolean containsDuplicate(TreeNode root) {
        seen.clear();
        return dfs(root);
    }
}

import java.util.*;

class TreeNode {
    int val;
    TreeNode left, right;
    TreeNode(int val) { this.val = val; }
}

public class Solution {
    public int maxAdjacentLevelDiff(TreeNode root) {
        if (root == null) return 0;
        Queue<TreeNode> q = new LinkedList<>();
        q.offer(root);
        List<Long> levelSums = new ArrayList<>();

        while (!q.isEmpty()) {
            int size = q.size();
            long curSum = 0;
            for (int i = 0; i < size; i++) {
                TreeNode node = q.poll();
                curSum += node.val;
                if (node.left != null) q.offer(node.left);
                if (node.right != null) q.offer(node.right);
            }
            levelSums.add(curSum);
        }

        long maxDiff = 0;
        for (int i = 1; i < levelSums.size(); i++) {
            maxDiff = Math.max(maxDiff, Math.abs(levelSums.get(i) - levelSums.get(i - 1)));
        }
        return (int)maxDiff;
    }
}

import java.util.Stack;

class TreeNode {
    int val;
    TreeNode left, right;
    TreeNode(int val) { this.val = val; }
}

public class Solution {
    public int kthSmallest(TreeNode root, int k) {
        Stack<TreeNode> stack = new Stack<>();
        TreeNode cur = root;

        while (cur != null || !stack.isEmpty()) {
            while (cur != null) {
                stack.push(cur);
                cur = cur.left;
            }
            cur = stack.pop();
            if (--k == 0) return cur.val;
            cur = cur.right;
        }
        return -1;
    }
}

