import sys
from collections import deque

class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def build_tree(nodes):
    if not nodes:
        return None
    root = TreeNode(nodes[0])
    queue = [root]
    i = 1
    while queue and i < len(nodes):
        node = queue.pop(0)
        if i < len(nodes) and nodes[i] is not None:
            node.left = TreeNode(nodes[i])
            queue.append(node.left)
        i += 1
        if i < len(nodes) and nodes[i] is not None:
            node.right = TreeNode(nodes[i])
            queue.append(node.right)
        i += 1
    return root

def max_adjacent_level_diff(root):
    if not root:
        return 0
    q = deque([root])
    prev_sum = None
    max_diff = 0
    while q:
        size = len(q)
        curr_sum = 0
        for _ in range(size):
            node = q.popleft()
            curr_sum += node.val
            if node.left: q.append(node.left)
            if node.right: q.append(node.right)
        if prev_sum is not None:
            max_diff = max(max_diff, abs(curr_sum - prev_sum))
        prev_sum = curr_sum
    return max_diff

