public class Main {
    // Find Maximum in Rotated Sorted Array — P000441

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] a = new int[n];

        for (int i = 0; i < n; i++) a[i] = sc.nextInt();

        int left = 0, right = n - 1;

        // Locate the minimum element; its previous element is the maximum.

        while (left < right) {
            int mid = left + (right - left) / 2;
            if (a[mid] > a[right]) left = mid + 1;
            else right = mid;
        }

        int minimumIndex = left;
        int maximumIndex = (minimumIndex - 1 + n) % n;
        System.out.println(a[maximumIndex]);
    }
}

