            if (cols[c] || posDiag[r + c] || negDiag[r - c + n]) continue;
            cols[c] = true; posDiag[r + c] = true; negDiag[r - c + n] = true;

            count += backtrack(r + 1, n);

            cols[c] = false; posDiag[r + c] = false; negDiag[r - c + n] = false;
        }
