int main() {
    int n; cin >> n;
    vector<long long> a(n), pref(n + 1);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
        pref[i + 1] = pref[i] + a[i];
    }

    unordered_map<long long,int> last;
    deque<int> q;
    int left = 0;
    long long ans = numeric_limits<long long>::lowest();

    q.push_back(0);
