        auto it = last.find(a[r]);
        if (it != last.end()) left = max(left, it->second + 1);
        last[a[r]] = r;

        while (!q.empty() && q.front() < left) q.pop_front();
        while (!q.empty() && pref[q.back()] >= pref[r]) q.pop_back();
        q.push_back(r);

        while (!q.empty() && q.front() < left) q.pop_front();
        ans = max(ans, pref[r + 1] - pref[q.front()]);
    }

    cout << ans;
}
