#include <string.h>

int main(void)
{
    char s[100005];

    if (scanf("%100004s", s) != 1) {
        return 0;
    }

    int remaining[26] = {0};
    int used[26] = {0};
    char stack[100005];
    int top = 0;

    for (size_t i = 0; s[i] != '\0'; ++i) {
        ++remaining[s[i] - 'a'];
    }

    for (size_t i = 0; s[i] != '\0'; ++i) {
        int c = s[i] - 'a';
        --remaining[c];

        if (used[c]) {
            continue;
        }

        while (top > 0) {
            int last = stack[top - 1] - 'a';

            if (stack[top - 1] <= s[i] || remaining[last] == 0) {
                break;
            }

            used[last] = 0;
            --top;
        }

        stack[top++] = s[i];
        used[c] = 1;
    }

    stack[top] = '\0';
    printf("%s\n", stack);
    return 0;
}

