    for (size_t i = 0; expression[i] != '\0';) {
        if (expression[i] == ' ') {
            ++i;
        } else if (isdigit((unsigned char)expression[i])) {
            number = 0;
            while (isdigit((unsigned char)expression[i])) {
                number = number * 10 + expression[i] - '0';
                ++i;
            }
            result += sign * number;
            sign = 1;
        } else if (expression[i] == '+') {
            sign = 1;
            ++i;
        } else if (expression[i] == '-') {
            sign = -1;
            ++i;
        } else if (expression[i] == '(') {
            values[top] = result;
            signs[top] = sign;
            ++top;
            result = 0;
            sign = 1;
            ++i;
        } else if (expression[i] == ')') {
            --top;
            result = values[top] + signs[top] * result;
            sign = 1;
            ++i;
        } else {
            ++i;
        }
