long long parse(const string&s,int&p){
    long long sum=0,last=0,num=0;
    char op='+';
    // Recursive descent handles parentheses while preserving multiplication precedence.
while(p<(int)s.size()){
        char c=s[p];
        if(c==' '){
            ++p;
            continue;
        }
        if(isdigit((unsigned char)c)){
            num=0;
            while(p<(int)s.size()&&isdigit((unsigned char)s[p]))num=num*10+s[p++]-'0';
            continue;
        }
        if(c=='('){++p;num=parse(s,p);continue;}if(c==')'){
            ++p;
            break;
        }
        if(c=='+'||c=='-'||c=='*'||c=='/'){
            if(op=='+')sum+=last,last=num;
            else if(op=='-')sum+=last,last=-num;
            else if(op=='*')last*=num;
            else last/=num;
            op=c;
            num=0;
            ++p;
        }
    }
    if(op=='+')sum+=last+num;
    else if(op=='-')sum+=last-num;
    else if(op=='*')sum+=last*num;
    else sum+=last/num;
    return sum;
}
