// Recursive descent over +, -, and parentheses evaluates the expression without a parser library.
public class Main {
    static String s;
    static int pos;
    static long parseExpr() {
        long value = 0, number = 0, sign = 1;
        while (pos < s.length()) {
            char c = s.charAt(pos++);
            if (Character.isDigit(c)) {
                number = number * 10 + c - '0';
            }
            else if (c == '+' || c == '-') {
                value += sign * number;
                number = 0;
                sign = (c == '+') ? 1 : -1;
            }
            else if (c == '(') {
                long inner = parseExpr();
                value += sign * inner;
                number = 0;
                sign = 1;
            }
            else if (c == ')') {
                value += sign * number;
                return value;
            }
        }
        return value + sign * number;
    }
