public class Main {
    static int hist(int[] h){
        int n=h.length,best=0;
        Deque<Integer> st=new ArrayDeque<>();
        for(int i=0;i<=n;i++){
            int cur=i==n?0:h[i];
            while(!st.isEmpty()&&h[st.peek()]>=cur){
                int x=st.pop(),left=st.isEmpty()?0:st.peek()+1;
                best=Math.max(best,h[x]*(i-left));
            }
            st.push(i);
        }
        return best;
    }
