                for (int j = 0; j < c; j++) {
                    int val = scanner.nextInt();
                    heights[j] = (val == 1) ? heights[j] + 1 : 0;
                }
                maxArea = Math.max(maxArea, largestArea(heights));
            }
            System.out.println(maxArea);
        }
    }
}

