// Helper function to evaluate maxpathsum for problem constraints.
function maxPathSum(root) {
    if (!root) return 0;
    if (!root.left && !root.right) return root.val;
    if (!root.left) return root.val + maxPathSum(root.right);
    if (!root.right) return root.val + maxPathSum(root.left);
    return root.val + Math.max(maxPathSum(root.left), maxPathSum(root.right));
}

module.exports = { maxPathSum };

// Helper function to evaluate maxsubtreesum for problem constraints.
function maxSubtreeSum(root) {
    let maxSum = -Infinity;

    // Helper function to evaluate dfs for problem constraints.
    function dfs(node) {
        if (!node) return 0;
        const curSum = node.val + dfs(node.left) + dfs(node.right);
        if (curSum > maxSum) maxSum = curSum;
        return curSum;
    }

    dfs(root);
    return maxSum;
}

module.exports = { maxSubtreeSum };

