import sys
def num_distinct(s, t):
    memo = {}
    def backtrack(i, j):
        if j == len(t): return 1
        if i == len(s): return 0
        if (i, j) in memo: return memo[(i, j)]
        res = backtrack(i + 1, j)
        if s[i] == t[j]:
            res += backtrack(i + 1, j + 1)
        memo[(i, j)] = res
        return res
    return backtrack(0, 0)
def main():
