        free(stack);
        return 0;
    }

    char *token = strtok(path, "/");

    while (token != NULL) {
        if (strcmp(token, ".") == 0) {
            /* Stay in the current directory. */
        } else if (strcmp(token, "..") == 0) {
            if (top > 0) {
                free(stack[--top]);
            }
        } else {
            stack[top] = malloc(strlen(token) + 1U);
            if (stack[top] == NULL) {
                for (int i = 0; i < top; ++i) {
                    free(stack[i]);
                }
                free(stack);
                return 1;
            }
            strcpy(stack[top], token);
            ++top;
        }

        token = strtok(NULL, "/");
    }

    if (top == 0) {
        printf("/\n");
    } else {
        for (int i = 0; i < top; ++i) {
            printf("/%s", stack[i]);
        }
        printf("\n");
    }

    for (int i = 0; i < top; ++i) {
        free(stack[i]);
    }
    free(stack);
    return 0;
