string simplifyPath(string path) {
    stringstream ss(path);
    string token;
    stack<string> st;
    while(getline(ss, token, '/')) {
        if(token == "" || token == ".") continue;
        if(token == "..") { if(!st.empty()) st.pop(); }
        else st.push(token);
    }
    string res = "";
    while(!st.empty()) { res = "/" + st.top() + res; st.pop(); }
    return res.empty() ? "/" : res;
}
