int main() {
    int n;
    long long target;
    cin >> n >> target;

    vector<long long> a(n);
    for (long long &x : a) {
        cin >> x;
    }

    int first = -1;
    int last = -1;

    int left = 0;
    int right = n - 1;
    while (left <= right) {
        int mid = left + (right - left) / 2;
        if (a[mid] >= target) {
            if (a[mid] == target) {
                first = mid;
            }
            right = mid - 1;
        } else {
            left = mid + 1;
        }
    }

    left = 0;
    right = n - 1;
    while (left <= right) {
        int mid = left + (right - left) / 2;
        if (a[mid] <= target) {
            if (a[mid] == target) {
                last = mid;
            }
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }

    cout << (first == -1 ? 0 : last - first + 1);
    return 0;
}

