public class Main {
    // Count Occurrences using Binary Search — P000435

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int target = sc.nextInt();
        int[] a = new int[n];

        for (int i = 0; i < n; i++) a[i] = sc.nextInt();

        int first = firstIndex(a, target);
        int last = lastIndex(a, target);
        System.out.println(first == -1 ? 0 : last - first + 1);
    }

    static int firstIndex(int[] a, int target) {
        int left = 0, right = a.length - 1, answer = -1;
        while (left <= right) {
            int mid = left + (right - left) / 2;
            if (a[mid] >= target) {
                if (a[mid] == target) answer = mid;
                right = mid - 1;
            }  else left = mid + 1;
        }
        return answer;
    }

    static int lastIndex(int[] a, int target) {
        int left = 0, right = a.length - 1, answer = -1;
        while (left <= right) {
            int mid = left + (right - left) / 2;
            if (a[mid] <= target) {
                if (a[mid] == target) answer = mid;
                left = mid + 1;
            }  else right = mid - 1;
        }
        return answer;
    }
}

