#include <stdlib.h>

int* separateEvenOdd(int* nums, int numsSize, int* returnSize) {
    *returnSize = numsSize;
    int* res = (int*)malloc(numsSize * sizeof(int));
    int idx = 0;
    for (int i = 0; i < numsSize; i++) {
        if (nums[i] % 2 == 0) res[idx++] = nums[i];
    }
    for (int i = 0; i < numsSize; i++) {
        if (nums[i] % 2 != 0) res[idx++] = nums[i];
    }
    return res;
}

