using namespace std;

int main() {
    int n;
    cin >> n;

    vector<long long> even;
    vector<long long> odd;

    for (int i = 0; i < n; ++i) {
        long long x;
        cin >> x;
        if (x % 2 == 0) {
            even.push_back(x);
        } else {
            odd.push_back(x);
        }
    }

    bool first = true;
    for (long long x : even) {
        if (!first) {
            cout << ' ';
        }
        cout << x;
        first = false;
    }
    for (long long x : odd) {
        if (!first) {
            cout << ' ';
        }
        cout << x;
        first = false;
    }

    cout << '\n';
    return 0;
}

