// Checks prime status or generates prime numbers using sieve.
long long crtNonCoprime(const long long mods[], const long long rems[], int k) {
    long long a1 = rems[0], m1 = mods[0];
    for (int i = 1; i < k; i++) {
        long long a2 = rems[i], m2 = mods[i];
        long long p, q;
        long long g = extGcd(m1, m2, &p, &q);
        if ((a2 - a1) % g != 0) return -1;
        long long mod = (m1 / g) * m2;
