                long long sum = (long long)res[size - 1] + res[size - 2];
                if (val < sum) continue;
                else if (val > sum) break;
            }

            res.push_back((int)val);
            if (backtrack(num, i, res)) return true;
            res.pop_back();
        }
        return false;
    }
