#include <algorithm>

struct TreeNode {
    int val;
    TreeNode *left;
    TreeNode *right;
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
};

class Solution {
public:
    TreeNode* lcaMultipleBST(TreeNode* root, std::vector<TreeNode*>& nodes) {
        int minVal = INT_MAX, maxVal = INT_MIN;
        for (auto* n : nodes) {
            minVal = std::min(minVal, n->val);
            maxVal = std::max(maxVal, n->val);
        }

        TreeNode* cur = root;
        while (cur) {
            if (maxVal < cur->val) {
                cur = cur->left;
            } else if (minVal > cur->val) {
                cur = cur->right;
            } else {
                return cur;
            }
        }
        return nullptr;
    }
};

#include <unordered_set>

struct TreeNode {
    int val;
    TreeNode *left;
    TreeNode *right;
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
};

class Solution {
    std::unordered_set<int> seen;

    bool dfs(TreeNode* node, int k) {
        if (!node) return false;
        if (seen.count(k - node->val)) return true;
        seen.insert(node->val);
        return dfs(node->left, k) || dfs(node->right, k);
    }
public:
    bool findTarget(TreeNode* root, int k) {
        seen.clear();
        return dfs(root, k);
    }
};

#include <vector>

struct TreeNode {
    int val;
    TreeNode *left;
    TreeNode *right;
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
};

class Solution {
    void inorder(TreeNode* node, std::vector<int>& vals) {
        if (!node) return;
        inorder(node->left, vals);
        vals.push_back(node->val);
        inorder(node->right, vals);
    }
public:
    bool findTriplet(TreeNode* root, int target) {
        std::vector<int> vals;
        inorder(root, vals);
        int n = vals.size();

        for (int i = 0; i < n - 2; i++) {
            int l = i + 1, r = n - 1;
            while (l < r) {
                int sum = vals[i] + vals[l] + vals[r];
                if (sum == target) return true;
                else if (sum < target) l++;
                else r--;
            }
        }
        return false;
    }
};

