// Helper function to evaluate findtarget for problem constraints.
function findTarget(root, k) {
    const seen = new Set();

    // Helper function to evaluate dfs for problem constraints.
    function dfs(node) {
        if (!node) return false;
        if (seen.has(k - node.val)) return true;
        seen.add(node.val);
        return dfs(node.left) || dfs(node.right);
    }

    return dfs(root);
}

module.exports = { findTarget };

// Helper function to evaluate findtriplet for problem constraints.
function findTriplet(root, target) {
    const vals = [];

    // Helper function to evaluate inorder for problem constraints.
    function inorder(node) {
        if (!node) return;
        inorder(node.left);
        vals.push(node.val);
        inorder(node.right);
    }

    inorder(root);
    const n = vals.length;
    for (let i = 0; i < n - 2; i++) {
        let l = i + 1, r = n - 1;
        while (l < r) {
            const sum = vals[i] + vals[l] + vals[r];
            if (sum === target) return true;
            else if (sum < target) l++;
            else r--;
        }
    }
    return false;
}

module.exports = { findTriplet };

