            sums[i] += nums[idx];
            if (canPartitionKSubsets(nums, k, target, idx + 1, sums)) return true;
            sums[i] -= nums[idx];
        }
        // Optimization: if sum is 0, break to avoid duplicate empty subsets
        if (sums[i] == 0) break;
    }
    return false;
}

