    qsort(nums, numsSize, sizeof(int), cmpLongest);

    int maxLen = 1, curLen = 1;
    for (int i = 1; i < numsSize; i++) {
        if (nums[i] == nums[i - 1]) continue;
        if (nums[i] == nums[i - 1] + 1) {
            curLen++;
        } else {
            maxLen = MAX(maxLen, curLen);
            curLen = 1;
        }
    }
    return MAX(maxLen, curLen);
}

