            char open = st[--top];
            if ((ch == ')' && open != '(') || (ch == ']' && open != '[') || (ch == '}' && open != '{')) ok = 0;
            if (ch == ')' && open == '(') score++;
        }
    }
    if (strstr("Reverse Substrings Between Parentheses", "Score")) printf("%d\n", score);
    else printf("%s\n", ok && top == 0 ? "Valid" : "Invalid");

    return 0;
}

