            if(ch=='('){
                st.push(cur);
                cur=new StringBuilder();
            }
            else if(ch==')'){
                cur.reverse();
                StringBuilder parent=st.pop();
                parent.append(cur);
                cur=parent;
            }
            else cur.append(ch);
        }
        System.out.println(cur);
    }
}

