        self.val = val
        self.left = left
        self.right = right

def build_tree(nodes):
    if not nodes:
        return None
    root = TreeNode(nodes[0])
    queue = [root]
    i = 1
    while queue and i < len(nodes):
        node = queue.pop(0)
        if i < len(nodes) and nodes[i] is not None:
            node.left = TreeNode(nodes[i])
            queue.append(node.left)
        i += 1
        if i < len(nodes) and nodes[i] is not None:
            node.right = TreeNode(nodes[i])
            queue.append(node.right)
        i += 1
    return root

def count_paths_sum_k(node, k):
    if not node:
        return 0
    if not node.left and not node.right:
        return 1 if node.val == k else 0
    return count_paths_sum_k(node.left, k - node.val) + count_paths_sum_k(node.right, k - node.val)

