int main() {
    int n;
    cin >> n;
    cin.ignore();

    vector<string> raw(n);
    vector<vector<string>> records(n);
    for (int i = 0; i < n; ++i) {
        getline(cin, raw[i]);
        records[i] = split(raw[i]);
    }
    string q;
    cin >> q;

    bool found = false;
    for (int i = 0; i < n; ++i) {
        if (records[i][0] == q) {
            cout << raw[i] << '\n';
            found = true;
            break;
        }
    }

    if (!found) {
        cout << "Record Not Found";
    }

    return 0;
}

