// Record convention: employeeId|details... ;
the first field is the unique employee ID.
public class Main {
    static String taskKey371(String row){
        return row.split("\\|",-1)[0].trim();
    }
    public static void main(String[] args)throws Exception{
        BufferedReader br=new BufferedReader(new InputStreamReader(System.in));
        int n=Integer.parseInt(br.readLine().trim());
        String[] rows=new String[n];
        for(int i=0;i<n;i++)rows[i]=br.readLine();
        String id=br.readLine().trim();
        for(String row:rows){
            String key=row.split("\\|",-1)[0].trim();
            if(key.equals(id)){
                System.out.println(row);
                return;
            }
        }
        System.out.println("Record Not Found");
    }
}

