        for (let i = 0; i < n; i++) {
            records.set(tokens[idx], tokens[idx + 1]);
            idx += 2;
        }
        const targetId = tokens[idx];
        if (records.has(targetId)) {
            console.log(`${targetId} ${records.get(targetId)}`);
        } else {
            console.log("Record Not Found");
        }
    }
}

