#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

int main(void)
{
    int n;
    int target;

    if (scanf("%d %d", &n, &target) != 2) {
        return 0;
    }

    int *a = malloc((size_t)n * sizeof(*a));
    if (a == NULL) {
        return 1;
    }

    for (int i = 0; i < n; ++i) {
        scanf("%d", &a[i]);
    }

    int left = 0;
    int right = n - 1;
    int best = a[0];
    long long best_diff = llabs((long long)a[0] - target);

    while (left <= right) {
        int mid = left + (right - left) / 2;
        long long diff = llabs((long long)a[mid] - target);

        if (diff < best_diff) {
            best_diff = diff;
            best = a[mid];
        }

        if (a[mid] == target) {
            best = a[mid];
            break;
        }

        if (a[mid] < target) {
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }

    printf("%d\n", best);
    free(a);
    return 0;
}

