int main() {
    int n;
    long long target;
    cin >> n >> target;

    vector<long long> a(n);
    for (long long &x : a) {
        cin >> x;
    }

    int left = 0;
    int right = n - 1;

    while (left <= right) {
        int mid = left + (right - left) / 2;

        if (a[mid] == target) {
            cout << a[mid];
            return 0;
        }

        if (a[mid] < target) {
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }

    if (left == 0) {
        cout << a[0];
    } else if (left == n) {
        cout << a[n - 1];
    } else {
        long long leftDiff = llabs(a[left - 1] - target);
        long long rightDiff = llabs(a[left] - target);

        cout << (leftDiff <= rightDiff ? a[left - 1] : a[left]);
    }

    return 0;
}

