import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] h = br.readLine().trim().split("\\s+");
        int n=Integer.parseInt(h[0]), target=Integer.parseInt(h[1]);
        String[] s=br.readLine().trim().split("\\s+");
        int[] a=new int[n];
        for(int i=0;i<n;i++)a[i]=Integer.parseInt(s[i]);

        int lo=0,hi=n-1;
        while(lo<hi){
            int mid=(lo+hi)>>>1;
            if(a[mid] < target) lo=mid+1;
            else hi=mid;
        }
        int pos=lo;
        if(pos==0) System.out.println(a[0]);
        else if(pos==n) System.out.println(a[n-1]);
        else if(Math.abs(a[pos]-target) < Math.abs(a[pos-1]-target)) System.out.println(a[pos]);
        else System.out.println(a[pos-1]);
    }
}

