import sys
from bisect import bisect_left

INF = 10**18

def max_subarray_leq(a, k):
    pref = [0]
    for x in a:
        pref.append(pref[-1] + x)
    vals = sorted(set(pref))
    size = len(vals)
    bit = [size + 1] * (size + 1)

    def update(i, rank):
        while i <= size:
            if rank < bit[i]:
                bit[i] = rank
            i += i & -i

    def query(i):
        res = size + 1
        while i:
            if bit[i] < res:
                res = bit[i]
            i -= i & -i
        return res

    best = -INF
    update(size - bisect_left(vals, 0), bisect_left(vals, 0))
    for s in pref[1:]:
        r = bisect_left(vals, s - k)
        if r < size:
            candidate_rank = query(size - r)
            if candidate_rank <= size:
                candidate = s - vals[candidate_rank]
                if candidate > best:
                    best = candidate
        rank = bisect_left(vals, s)
        update(size - rank, rank)
    return best

