        put_idx(0, -1);
        long long cur = 0; int max_len = 0;
        for (int i = 0; i < n; i++) {
            cur += nums[i];
            int prev = find_idx(cur - k);
            if (prev != -999999) {
                if (i - prev > max_len) max_len = i - prev;
            }
            put_idx(cur, i);
        }
        printf("%d\n", max_len);
    }
    return 0;
}

