int main(void)
{
    int target;
    int *a = NULL;
    int n = 0;
    int capacity = 128;
    int x;

    if (scanf("%d", &target) != 1) {
        return 0;
    }

    a = malloc((size_t)capacity * sizeof(*a));
    if (a == NULL) {
        return 1;
    }

    while (scanf("%d", &x) == 1) {
        if (n == capacity) {
            capacity *= 2;
            int *tmp = realloc(a, (size_t)capacity * sizeof(*a));
            if (tmp == NULL) {
                free(a);
                return 1;
            }
            a = tmp;
        }
        a[n++] = x;
    }

    int left = 0;
    int right = n - 1;
    int answer = -1;

    while (left <= right) {
        int mid = left + (right - left) / 2;
        if (a[mid] == target) {
            answer = mid;
            break;
        }
        if (a[mid] < target) {
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }

    printf("%d\n", answer);
    free(a);
    return 0;
}

