        if (!root->left && !root->right) return root->val;
        if (!root->left) return root->val + minPathSum(root->right);
        if (!root->right) return root->val + minPathSum(root->left);
        return root->val + std::min(minPathSum(root->left), minPathSum(root->right));
    }
};

#include <algorithm>
#include <climits>

struct TreeNode {
    int val;
    TreeNode *left;
    TreeNode *right;
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
};

class Solution {
    int minSum = INT_MAX;

    int dfs(TreeNode* node) {
        if (!node) return 0;
        int curSum = node->val + dfs(node->left) + dfs(node->right);
        minSum = std::min(minSum, curSum);
        return curSum;
    }
public:
    int minSubtreeSum(TreeNode* root) {
        minSum = INT_MAX;
        dfs(root);
        return minSum;
    }
};

#include <iostream>
#include <vector>
#include <queue>
#include <climits>
using namespace std;

struct TreeNode {
    int val;
    TreeNode *left;
    TreeNode *right;
    TreeNode(int x) : val(x), left(NULL), right(NULL) {}
};

TreeNode* buildTree(vector<int>& vals) {
    if (vals.empty() || vals[0] == -1) return NULL;
    TreeNode* root = new TreeNode(vals[0]);
    queue<TreeNode*> q;
    q.push(root);
    int i = 1;
    while (!q.empty() && i < vals.size()) {
        TreeNode* node = q.front(); q.pop();
        if (i < vals.size() && vals[i] != -1) {
            node->left = new TreeNode(vals[i]);
            q.push(node->left);
        }
        i++;
        if (i < vals.size() && vals[i] != -1) {
            node->right = new TreeNode(vals[i]);
            q.push(node->right);
        }
        i++;
    }
    return root;
}

long long minRootToLeafSum(TreeNode* root) {
    if (!root) return 0;
    if (!root->left && !root->right) return root->val;
    
    long long leftSum = root->left ? minRootToLeafSum(root->left) : LLONG_MAX;
    long long rightSum = root->right ? minRootToLeafSum(root->right) : LLONG_MAX;
    
    return root->val + min(leftSum, rightSum);
}

