        if i < len(nodes) and nodes[i] is not None:
            node.right = TreeNode(nodes[i])
            queue.append(node.right)
        i += 1
    return root

def min_root_to_leaf_sum(node):
    if not node:
        return float('inf')
    if not node.left and not node.right:
        return node.val
    return node.val + min(min_root_to_leaf_sum(node.left), min_root_to_leaf_sum(node.right))

