            h=h.next;
        }
        System.out.println(s);
    }

    // Reversing first lets a running maximum identify every node that survives.

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int n=fs.nextInt();
        Node h=readList(fs,n), rev=null;
        while(h!=null){
            Node nx=h.next;
            h.next=rev;
            rev=h;
            h=nx;
        }
        long max=Long.MIN_VALUE;
        Node kept=null, tail=null;
        for(Node p=rev;p!=null;p=p.next) if(p.v>=max){
            max=p.v;
            Node z=new Node(p.v);
            if(kept==null)kept=z;
            else tail.next=z;
            tail=z;
        }
        Node ans=null;
        while(kept!=null){
            Node nx=kept.next;
            kept.next=ans;
            ans=kept;
            kept=nx;
        }
        printList(ans);
    }
