#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int *data;
    int front;
    int size;
    int capacity;
} Queue;

static void init_queue(Queue *q, int capacity)
{
    q->data = malloc((size_t)capacity * sizeof(*q->data));
    q->front = 0;
    q->size = 0;
    q->capacity = capacity;
}

static void push_queue(Queue *q, int value)
{
    int index = (q->front + q->size) % q->capacity;
    q->data[index] = value;
    ++q->size;
}

static int pop_queue(Queue *q)
{
    int value = q->data[q->front];
    q->front = (q->front + 1) % q->capacity;
    --q->size;
    return value;
}

int main(void)
{
    int q;
    if (scanf("%d", &q) != 1) {
        return 0;
    }

    Queue queue;
    init_queue(&queue, q + 2);

    char command[16];
    for (int i = 0; i < q; ++i) {
        scanf("%15s", command);

        if (strcmp(command, "push") == 0) {
            int value;
            scanf("%d", &value);

            int count = queue.size;
            push_queue(&queue, value);

            for (int j = 0; j < count; ++j) {
                push_queue(&queue, pop_queue(&queue));
            }
        } else if (strcmp(command, "pop") == 0) {
            printf("%d\n", pop_queue(&queue));
        } else if (strcmp(command, "top") == 0) {
            printf("%d\n", queue.data[queue.front]);
        } else if (strcmp(command, "empty") == 0) {
            printf("%s\n", queue.size == 0 ? "true" : "false");
        }
    }

    free(queue.data);
    return 0;
}

