        st.pop();
    }
    
    // Remove leading zeros
    int i = 0;
    while (i < result.length() && result[i] == '0') i++;
    result = result.substr(i);
    
    if (result.empty()) cout << "0" << endl;
    else cout << result << endl;
    
    return 0;
}

