        DNode head=null, tail=null;
        for(int i=0;i<n;i++){
            DNode x=new DNode(fs.nextLong());
            if(head==null) head=x;
            else {
                tail.next=x;
                x.prev=tail;
            }
            tail=x;
        }
        return head;
