            if(h!=null)pq.add(h);
        }
        DNode head=null,tail=null;
        while(!pq.isEmpty()){
            DNode x=pq.poll(),nx=x.next;
            x.next=null;
            x.prev=tail;
            if(tail!=null)tail.next=x;
            else head=x;
            tail=x;
            if(nx!=null)pq.add(nx);
        }
        printDList(head);
    }
