            for (let v = 0; v < n; v++) {
                if (parent[v] === -1 && cap[u][v] > 0) {
                    parent[v] = u;
                    curCap[v] = Math.min(curCap[u], cap[u][v]);
                    q.push(v);
                }
            }
        }
        if (parent[sink] === -1) break;
        const aug = curCap[sink];
        let curr = sink;
        while (curr !== src) {
            const p = parent[curr];
            cap[p][curr] -= aug;
            cap[curr][p] += aug;
            curr = p;
        }
    }

    const vis = new Array(n).fill(false);
    vis[src] = true;
    const q = [src];
    while (q.length > 0) {
        const u = q.shift();
        for (let v = 0; v < n; v++) {
            if (!vis[v] && cap[u][v] > 0) {
                vis[v] = true;
                q.push(v);
            }
        }
