            for (int j = i + 1; j < n; j++) {
                String s1 = num.substring(0, i), s2 = num.substring(i, j);
                if ((s1.charAt(0) == '0' && s1.length() > 1) || (s2.charAt(0) == '0' && s2.length() > 1)) {
