class Solution:
    def isAdditiveNumber(self, num: str) -> bool:
        n = len(num)
        for i in range(1, n):
            for j in range(i + 1, n):
                s1, s2 = num[:i], num[i:j]
                if (s1[0] == '0' and len(s1) > 1) or (s2[0] == '0' and len(s2) > 1):
                    continue

                n1, n2 = int(s1), int(s2)
                k = j
                while k < n:
                    n3 = n1 + n2
                    s3 = str(n3)
                    if not num.startswith(s3, k):
                        break
                    k += len(s3)
                    n1, n2 = n2, n3

                if k == n:
                    return True
        return False

from typing import List
from collections import defaultdict

class Solution:
    def leastBricks(self, wall: List[List[int]]) -> int:
        gap_count = defaultdict(int)
        for row in wall:
            edge = 0
            for brick in row[:-1]:
                edge += brick
                gap_count[edge] += 1
        return len(wall) - max(gap_count.values(), default=0)

import sys

def solve():
    s = sys.stdin.readline().strip()
    n = len(s)
    
    def backtrack(first_len, second_len):
        if first_len + second_len > n:
            return False
        try:
            a = int(s[:first_len])
            b = int(s[first_len:first_len+second_len])
        except:
            return False
            
        pos = first_len + second_len
        while pos < n:
            c = a + b
            c_str = str(c)
            if not s[pos:].startswith(c_str):
                return False
            pos += len(c_str)
            a, b = b, c
        return True
        
    for i in range(1, n):
        for j in range(1, n - i + 1):
            if backtrack(i, j):
                print("YES")
                return
                
    print("NO")

