    for (int i = 0; i < n; i++) {
        long long d[100000], dc[100000];
        int idx = 0;
        for (int j = 0; j < n; j++) {
            if (i == j) continue;
            long long dist = (x[i] - x[j]) * (x[i] - x[j]) + (y[i] - y[j]) * (y[i] - y[j]);
