            for (int k = 0; k < idx; k++) {
                if (d[k] == dist) {
                    dc[k]++;
                    f = 1;
                    break;
                }
            }
            if (!f) {
                d[idx] = dist;
                dc[idx] = 1;
                idx++;
            }
        }
        for (int k = 0; k < idx; k++) {
            cnt += dc[k] * (dc[k] - 1);
        }
    }
    printf("%lld\n", cnt);
    return 0;
}

