void backtrackDigits(char* digits, int idx, char* cur, char** res, int* count) {
    if (digits[idx] == '\0') {
        cur[idx] = '\0';
        res[*count] = strdup(cur);
        (*count)++;
        return;
    }
    char* letters = phoneMap[digits[idx] - '0'];
    for (int i = 0; letters[i]; i++) {
        cur[idx] = letters[i];
        backtrackDigits(digits, idx + 1, cur, res, count);
    }
}

