class Solution {
    std::vector<std::string> phone = {"", "", "abc", "def", "ghi", "jkl", "mno", "pqrs", "tuv", "wxyz"};
    void backtrack(const std::string& digits, int idx, std::string cur, std::vector<std::string>& res) {
