        for (int i = 0; i < n; i++) scanf("%lld", &arr[i]);
        for (int i = n / 2 - 1; i >= 0; i--) minHeapify(arr, n, i);
        long long total = 0;
        int size = n;
        while (size > 1) {
            long long a = popMin(arr, &size);
            long long b = popMin(arr, &size);
            long long cost = a + b;
            total += cost;
