# Tree serialization convention: N followed by N lines value leftIndex rightIndex.
# Indices are 1-based; -1 means null; node 1 is the root.
class Node:
    __slots__=("v","l","r")
    def __init__(self,v): self.v=v; self.l=None; self.r=None

def read_tree(a,p,values=False):
    n=int(a[p]); p+=1
    if n==0: return None,[],p
    vals=[]
    if values:
        vals=list(map(int,a[p:p+n])); p+=n
    else:
        vals=[None]*n
    L=[-1]*n; RR=[-1]*n; nodes=[None]*n
    for i in range(n):
        if values: v=vals[i] ; l=int(a[p]); r=int(a[p+1]); p+=2
        else: v=int(a[p]); l=int(a[p+1]); r=int(a[p+2]); p+=3
        nodes[i]=Node(v); L[i]=l; RR[i]=r
    for i in range(n):
        if L[i]>0: nodes[i].l=nodes[L[i]-1]
        if RR[i]>0: nodes[i].r=nodes[RR[i]-1]
    return nodes[0],nodes,p

def tree_lines(root):
    if root is None:return ["0"]
    nodes=[]; q=deque([root]); seen=set()
    while q:
        x=q.popleft()
        if id(x) in seen: continue
        seen.add(id(x)); nodes.append(x)
        if x.l:q.append(x.l)
        if x.r:q.append(x.r)
    idx={id(x):i+1 for i,x in enumerate(nodes)}
    out=[str(len(nodes))]
    for x in nodes: out.append(f"{x.v} {idx.get(id(x.l),-1)} {idx.get(id(x.r),-1)}")
    return out

def inorder(root):
    out=[]; st=[]; x=root
    while st or x:
        while x: st.append(x); x=x.l
        x=st.pop(); out.append(x.v); x=x.r
    return out

def preorder(root):
    if not root:return []
    out=[]; st=[root]
    while st:
        x=st.pop(); out.append(x.v)
        if x.r:st.append(x.r)
        if x.l:st.append(x.l)
    return out

def postorder(root):
    if not root:return []
    out=[]; st=[(root,0)]
    while st:
        x,s=st.pop()
        if s: out.append(x.v); continue
        st.append((x,1))
        if x.r:st.append((x.r,0))
        if x.l:st.append((x.l,0))
    return out

def levels(root):
    if not root:return []
    q=deque([root]); out=[]
    while q:
        cur=[]
