        qSum += workers[i].q;
        if (heapSize > k) {
            qSum -= popMax(heap, &heapSize);
        }
        if (heapSize == k) {
            double cost = qSum * workers[i].ratio;
            if (cost < ans) ans = cost;
        }
    }
    free(workers);
    free(heap);
    return ans;
}

