        maxHeap.splice(low, 0, w.q);
        qSum += w.q;
        if (maxHeap.length > k) {
            qSum -= maxHeap.pop();
        }
        if (maxHeap.length === k) {
            minCost = Math.min(minCost, qSum * w.r);
        }
