int firstOccurrence(const vector<long long>& a, int left, int right, long long target) {
    // On a match, continue left so the earliest valid index is retained.
    if (left > right) return -1;
    int mid = left + (right - left) / 2;
    if (a[mid] == target) {
        int earlier = firstOccurrence(a, left, mid - 1, target);
        return earlier == -1 ? mid : earlier;
    }
    if (a[mid] < target) return firstOccurrence(a, mid + 1, right, target);
    return firstOccurrence(a, left, mid - 1, target);
}

