public class Main {
    static long gcd(long a,long b){
        while(b!=0){
            long t=a%b;
            a=b;
            b=t;
        }
        return Math.abs(a);
    }
    static void printArray(long[] a){
        StringBuilder s=new StringBuilder();
        for(long x:a){
            if(s.length()>0)s.append(' ');
            s.append(x);
        }
        System.out.println(s);
    }
    static void reverse(long[] a,int l,int r){
        while(l<r){
            long t=a[l];
            a[l++]=a[r];
            a[r--]=t;
        }
    }
    static String circularValues(Node h,int count){
        StringBuilder s=new StringBuilder();
        Node p=h;
        for(int i=0;i<count&&p!=null;i++){
            if(i>0)s.append(' ');
            s.append(p.v);
            p=p.next;
        }
        return s.toString();
    }

    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buf = new byte[1 << 16];
        private int ptr = 0, len = 0;
        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buf);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buf[ptr++];
        }
        String next() throws IOException {
            StringBuilder s = new StringBuilder();
            int c;
            do {
                c = read();
            }  while (c <= 32 && c != -1);
            while (c > 32 && c != -1) {
                s.append((char)c);
                c = read();
            }
            return s.toString();
        }
        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
        long nextLong() throws IOException {
            return Long.parseLong(next());
        }
    }
    static class Node {
        long v;
        Node next;
        Node(long v) {
            this.v = v;
        }
    }
    static class DNode {
        long v;
        DNode next, prev;
        DNode(long v) {
            this.v = v;
        }
    }
    static Node readList(FastScanner fs, int n) throws IOException {
        Node dummy = new Node(0), t = dummy;
        for (int i=0;i<n;i++){
            t.next=new Node(fs.nextLong());
            t=t.next;
        }
        return dummy.next;
    }
    static DNode readDList(FastScanner fs, int n) throws IOException {
        DNode head=null, tail=null;
        for(int i=0;i<n;i++){
            DNode x=new DNode(fs.nextLong());
            if(head==null) head=x;
            else {
                tail.next=x;
                x.prev=tail;
            }
            tail=x;
        }
        return head;
    }
    static void printList(Node h) {
        StringBuilder s=new StringBuilder();
        while(h!=null){
            if(s.length()>0)s.append(' ');
            s.append(h.v);
            h=h.next;
        }
        System.out.println(s);
    }
    static void printDList(DNode h) {
        StringBuilder s=new StringBuilder();
        while(h!=null){
            if(s.length()>0)s.append(' ');
            s.append(h.v);
            h=h.next;
        }
        System.out.println(s);
    }

    // The Josephus recurrence computes the survivor in O(n) time without explicitly storing the circle.

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        long n=fs.nextLong(),k=fs.nextLong(),survivor=0;
        for(long i=2;i<=n;i++)survivor=(survivor+k)%i;
        System.out.println(survivor+1);
    }
}

