            wScore += score[code];
            if (wCount[code] > count[code]) canForm = false;
        }

        if (canForm) {
            for (let i = 0; i < 26; i++) count[i] -= wCount[i];
            maxS = Math.max(maxS, wScore + backtrack(idx + 1));
            for (let i = 0; i < 26; i++) count[i] += wCount[i];
        }
        return maxS;
    }

    return backtrack(0);
}

