        for c in s:
            if c == '(':
                left_rem += 1
            elif c == ')':
                if left_rem > 0:
                    left_rem -= 1
                else:
                    right_rem += 1

        res = set()

        def backtrack(idx: int, open_c: int, close_c: int, l_rem: int, r_rem: int, cur: List[str]):
