void generateHappyStrings(int n, int k, string current, vector<string>& result) {
    if (current.length() == n) {
        result.push_back(current);
        return;
    }
    
    for (char c = 'a'; c <= 'c'; ++c) {
        if (current.empty() || current.back() != c) {
            generateHappyStrings(n, k, current + c, result);
            if (result.size() == k) return;
