int upper_bound_idx(int c, int target) {
    int l = 0, r = pos_sz[c] - 1, ans = -1;
    // Binary search loop to narrow down range
    while (l <= r) {
        // Calculate midpoint to prevent potential overflow
        int mid = (l + r) / 2;
        if (pos[c][mid] > target) {
            ans = pos[c][mid];
            r = mid - 1;
        } else {
            l = mid + 1;
        }
