public class Main {
    static boolean isSub(String s,String w,Map<Character,int[]> pos){
        int at=0;
        for(char c:w.toCharArray()){
            int[] a=pos.get(c);
            if(a==null)return false;
            int lo=0,hi=a.length;
            while(lo<hi){
                int md=(lo+hi)>>>1;
                if(a[md]>=at)hi=md;
                else lo=md+1;
            }
            if(lo==a.length)return false;
            at=a[lo]+1;
        }
        return true;
    }
