public class Main {
    static BigInteger sq(long dx,long dy){
        return BigInteger.valueOf(dx).multiply(BigInteger.valueOf(dx))
        .add(BigInteger.valueOf(dy).multiply(BigInteger.valueOf(dy)));
    }
    public static void main(String[] args)throws Exception{
        Scanner s=new Scanner(System.in);
        long x1=s.nextLong(),y1=s.nextLong(),x2=s.nextLong(),y2=s.nextLong(),x3=s.nextLong(),y3=s.nextLong();
        BigInteger a=sq(x1-x2,y1-y2),b=sq(x2-x3,y2-y3),c=sq(x3-x1,y3-y1);
        if(a.signum()==0||b.signum()==0||c.signum()==0){
            System.out.println("Not a Triangle");
            return;
        }
        BigInteger area=BigInteger.valueOf(x2-x1).multiply(BigInteger.valueOf(y3-y1))
        .subtract(BigInteger.valueOf(y2-y1).multiply(BigInteger.valueOf(x3-x1))).abs();
        if(area.signum()==0){
            System.out.println("Not a Triangle");
            return;
        }
        if(a.equals(b)&&b.equals(c))System.out.println("Equilateral");
        else if(a.equals(b)||b.equals(c)||a.equals(c))System.out.println("Isosceles");
        else System.out.println("Scalene");
    }
}

