        for (int l : last) {
            if (l == -1) {
                allPresent = false;
                break;
            }
            minLast = min(minLast, l);
        }
        
        if (allPresent) {
            count += (minLast + 1);
        }
    }
    
    cout << count << endl;
    return 0;
}

