bool backtrack(const std::string& s, int idx, unsigned long long prev) {
    if (idx == (int)s.length()) return true;
    unsigned long long cur = 0;
    for (int i = idx; i < (int)s.length(); i++) {
        cur = cur * 10 + (s[i] - '0');
        if (prev != 0 && cur == prev - 1) {
