using namespace std;

void generatePermutations(string s, int l, int r, vector<string>& result) {
    if (l == r) {
        result.push_back(s);
    } else {
        for (int i = l; i <= r; i++) {
            swap(s[l], s[i]);
            generatePermutations(s, l + 1, r, result);
            swap(s[l], s[i]); // backtrack
        }
    }
}

