public class Main {
    static class FS {
        private final InputStream in = System.in;
        private final byte[] b = new byte[1 << 16];
        private int p=0,n=0;
        int read() throws IOException {
            if(p>=n){
                n=in.read(b);
                p=0;
                if(n<0)return -1;
            }
            return b[p++];
        }
        String next() throws IOException {
            StringBuilder s=new StringBuilder();
            int c;
            do{
                c=read();
            } while(c<=32 && c!=-1);
            while(c>32 && c!=-1){
                s.append((char)c);
                c=read();
            }
            return s.toString();
        }
        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
        long nextLong() throws IOException {
            return Long.parseLong(next());
        }
    }
    static void outArr(int[] a) {
        for(int i=0;i<a.length;i++){
            if(i>0) System.out.print(" ");
            System.out.print(a[i]);
        }
        System.out.println();
    }
    static void outLongArr(long[] a) {
        for(int i=0;i<a.length;i++){
            if(i>0) System.out.print(" ");
            System.out.print(a[i]);
        }
        System.out.println();
    }

    static class Node{
        int v;
        Node l,r;
        Node(int v){
            this.v=v;
        }
    }
    static ArrayList<Node> gen(int lo,int hi){
        ArrayList<Node> res=new ArrayList<>();
        if(lo>hi){
            res.add(null);
            return res;
        }
        for(int x=lo;x<=hi;x++)for(Node l:gen(lo,x-1))for(Node r:gen(x+1,hi)){
            Node n=new Node(x);
            n.l=l;
            n.r=r;
            res.add(n);
        }
        return res;
    }
    static void ser(Node n,StringBuilder s){
        if(n==null){
            s.append("# ");
            return;
        }
        s.append(n.v).append(' ');
        ser(n.l,s);
        ser(n.r,s);
    }
    public static void main(String[] z)throws Exception{
        FS f=new FS();
        int n=f.nextInt();
        for(Node x:gen(1,n)){
            StringBuilder s=new StringBuilder();
            ser(x,s);
            System.out.println(s.toString().trim());
        }
    }
}

