public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String s = sc.next();
        Set<String> res = new TreeSet<>();
        int left = 0, right = 0;
        for(char c : s.toCharArray()) {
            if(c == '(') left++;
            else if(c == ')') {
                if(left > 0) left--;
                else right++;
            }
        }
        removeInv(s, 0, new StringBuilder(), left, right, 0, res);
        for(String str : res) System.out.println(str);
    }
    static void removeInv(String s, int idx, StringBuilder curr, int lRem, int rRem, int open, Set<String> res) {
        if(idx == s.length()) {
            if(lRem == 0 && rRem == 0) res.add(curr.toString());
            return;
        }
        char c = s.charAt(idx);
        if(c != '(' && c != ')') {
            curr.append(c);
            removeInv(s, idx + 1, curr, lRem, rRem, open, res);
            curr.deleteCharAt(curr.length() - 1);
        } else {
            if(c == '(') {
