int main(void)
{
    int n;

    if (scanf("%d", &n) != 1) {
        return 0;
    }

    int *a = malloc((size_t)(n - 1) * sizeof(*a));
    if (a == NULL) {
        return 1;
    }

    for (int i = 0; i < n - 1; ++i) {
        scanf("%d", &a[i]);
    }

    long long first = a[0];
    long long last = a[n - 2];
    long long difference = (last - first) / (n - 1);
    long long answer = first - difference;

    if (difference == 0) {
        difference = 1;
    }

    for (int i = 1; i < n - 1; ++i) {
        if ((long long)a[i] - a[i - 1] != difference) {
            answer = (long long)a[i - 1] + difference;
            break;
        }
    }

    if (answer == first - difference) {
        answer = last + difference;
    }

    printf("%lld\n", answer);
    free(a);
    return 0;
}

