        int bestNeed=-1;
        long bm=0;
        // For n<=30, direct subset enumeration is 2^30; use two halves and binary search.

        int L=n/2,R=n-L;
        ArrayList<long[]> right=new ArrayList<>();
        for(int mask=0;mask<(1<<R);mask++){
            int c=Integer.bitCount(mask);
            if(c==k1||c==k2){
                long s=0;
                for(int j=0;j<R;j++)if((mask&(1<<j))!=0)s+=a[L+j];
                right.add(new long[]{
