public class Main {
    static class FS {
        private final InputStream in = System.in;
        private final byte[] b = new byte[1<<16];
        int p=0,n=0;
        int read() throws IOException {
            if(p>=n){
                n=in.read(b);
                p=0;
                if(n<0)return -1;
            }
            return b[p++];
        }
        String next() throws IOException {
            StringBuilder s=new StringBuilder();
            int c;
            do{
                c=read();
            } while(c<=32&&c!=-1);
            while(c>32&&c!=-1){
                s.append((char)c);
                c=read();
            }
            return s.toString();
        }
        long nextLong() throws IOException {
            return Long.parseLong(next());
        }
        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
    static BigInteger powMod(BigInteger a,BigInteger b,BigInteger m){
        BigInteger r=BigInteger.ONE.mod(m);
        a=a.mod(m);
        while(b.signum()>0){
            if(b.testBit(0))r=r.multiply(a).mod(m);
            a=a.multiply(a).mod(m);
            b=b.shiftRight(1);
        }
        return r;
    }
    public static void main(String[] args)throws Exception{
        FS f=new FS();
        System.out.println(powMod(new BigInteger(f.next()),new BigInteger(f.next()),new BigInteger(f.next())));
    }
}

