def levels(n,L,R):
    if n==0:return []
    q=deque([0]); ans=[]
    while q:
        cur=[]
        for _ in range(len(q)):
            u=q.popleft(); cur.append(u)
            if L[u]>=0:q.append(L[u])
            if R[u]>=0:q.append(R[u])
        ans.append(cur)
    return ans

def postorder(n,L,R):
    if n==0:return []
    out=[]; st=[(0,0)]
    while st:
        u,s=st.pop()
        if u<0:continue
        if s==0:
            st.append((u,1))
            if L[u]>=0:st.append((L[u],0))
        elif s==1:
            st.append((u,2))
            if R[u]>=0:st.append((R[u],0))
        else:
