        vals.append(v if v != -1 else None)
        
    target = int(input_data[idx]); idx += 1
    k = int(input_data[idx]); idx += 1
    
    root = build_tree(vals)
    res = find_kth_ancestor(root, target, k)
    print(res if res is not None else "NONE")

