    else if (strstr("TITLE", "LCM") || strstr("TITLE", "Least")) { long long x = a, y = b; while (y) { long long r = x % y; x = y; y = r; } printf("%lld\n", llabs(a / x * b)); }
    else if (strstr("TITLE", "Modular") || strstr("TITLE", "Modulo")) printf("%lld\n", ((a % m) + (b % m) + m) % m);
