struct Fenwick {
    vector<int> tree;

    explicit Fenwick(int n) : tree(n + 1, 0) {}

    void add(int index, int value) {
        for (++index; index < static_cast<int>(tree.size()); index += index & -index) {
            tree[index] += value;
        }
    }

    int sum(int index) const {
        int result = 0;
        for (++index; index > 0; index -= index & -index) {
            result += tree[index];
        }
        return result;
    }
};

