public class Main {
    static class Item {
        int value, index;
        Item(int v, int i) {
            value = v;
            index = i;
        }
    }

    static void sort(Item[] a, Item[] tmp, int l, int r, int[] count) {
        if (r - l <= 1) return;
        int m = (l + r) >>> 1;
        sort(a, tmp, l, m, count);
        sort(a, tmp, m, r, count);

        int i = l, j = m, k = l, rightTaken = 0;
        while (i < m && j < r) {
            if (a[j].value < a[i].value) {
                tmp[k++] = a[j++];
                rightTaken++;
            }  else {
                count[a[i].index] += rightTaken;
                tmp[k++] = a[i++];
            }
        }
        while (i < m) {
            count[a[i].index] += rightTaken;
            tmp[k++] = a[i++];
        }
        while (j < r) tmp[k++] = a[j++];
        for (i = l; i < r; i++) a[i] = tmp[i];
    }

