    if (depth == 1) {
        TreeNode* newNode = new TreeNode(val);
        newNode->left = root;
        return newNode;
    }
    
    queue<TreeNode*> q;
    q.push(root);
    int currDepth = 1;
    
    while (!q.empty()) {
        int size = q.size();
        if (currDepth == depth - 1) {
            for (int i = 0; i < size; ++i) {
                TreeNode* node = q.front(); q.pop();
