        scanf("%d", &a[i]);
        if (a[i] > high) {
            high = a[i];
        }
    }

    while (low < high) {
        int mid = low + (high - low) / 2;
        if (divisor_sum(a, n, mid) <= threshold) {
            high = mid;
        } else {
            low = mid + 1;
        }
    }

    printf("%d\n", low);
