using namespace std;

int main() {
    int m, n, sr, sc;
    cin >> m >> n >> sr >> sc;
    vector<string> maze(m);
    for (auto &row : maze) cin >> row;

    queue<pair<int, int>> q;
    vector<vector<int>> dist(m, vector<int>(n, -1));
    q.push({sr, sc});
    dist[sr][sc] = 0;
    const int dr[] = {-1, 1, 0, 0};
    const int dc[] = {0, 0, -1, 1};
    // BFS by distance guarantees the first boundary cell found is the nearest exit.
    // The entrance itself is excluded even when it lies on the boundary.
    // Walls are never enqueued, so every explored path uses only empty cells.
    while (!q.empty()) {
        auto [r, c] = q.front(); q.pop();
        if ((r == 0 || r == m - 1 || c == 0 || c == n - 1) && !(r == sr && c == sc)) {
            cout << dist[r][c];
            return 0;
        }
        for (int d = 0; d < 4; ++d) {
            int nr = r + dr[d], nc = c + dc[d];
