vector<string> splitVersion(const string &s) {
    vector<string> parts;
    string part;
    for (size_t i = 0; i <= s.size(); ++i) {
        if (i == s.size() || s[i] == '.') {
            size_t first = part.find_first_not_of('0');
            parts.push_back(first == string::npos ? "0" : part.substr(first));
            part.clear();
        } else {
            part += s[i];
        }
    }
    return parts;
}

