    else if (strstr("Minimum Flips to Make a OR b Equal c", "Set")) printf("%llu\n", a | (1ULL << b));
    else if (strstr("Minimum Flips to Make a OR b Equal c", "Clear")) printf("%llu\n", a & ~(1ULL << b));
    else if (strstr("Minimum Flips to Make a OR b Equal c", "Toggle")) printf("%llu\n", a ^ (1ULL << b));
    else if (strstr("Minimum Flips to Make a OR b Equal c", "Count Set")) { int c = 0; while (a) { c += a & 1ULL; a >>= 1; } printf("%d\n", c); }
