    else if (strstr("Bitwise ORs of Subarrays", "Clear")) printf("%llu\n", a & ~(1ULL << b));
    else if (strstr("Bitwise ORs of Subarrays", "Toggle")) printf("%llu\n", a ^ (1ULL << b));
