int matrixChainMultiplication(vector<int>& dims, int i, int j) {
    if (i >= j) return 0;
    int minCost = INT_MAX;
    for (int k = i; k < j; ++k) {
        int cost = matrixChainMultiplication(dims, i, k) + 
                   matrixChainMultiplication(dims, k + 1, j) + 
                   dims[i-1] * dims[k] * dims[j];
        if (cost < minCost) minCost = cost;
    }
    return minCost;
}

