    cin >> n2;
    vector<int> vals2(n2);
    for (int i = 0; i < n2; ++i) cin >> vals2[i];
    
    TreeNode* t1 = buildTree(vals1);
    TreeNode* t2 = buildTree(vals2);
    
    cout << (isIsomorphic(t1, t2) ? "YES" : "NO") << endl;
    
    return 0;
}

