#include <stdio.h>
#include <stdlib.h>

#define MOD 1000000007LL

int main(void)
{
    int n;

    if (scanf("%d", &n) != 1) {
        return 0;
    }

    long long *a = malloc((size_t)n * sizeof(*a));
    int *left = malloc((size_t)n * sizeof(*left));
    int *right = malloc((size_t)n * sizeof(*right));
    int *stack = malloc((size_t)n * sizeof(*stack));

    if (a == NULL || left == NULL || right == NULL || stack == NULL) {
        free(a);
        free(left);
        free(right);
        free(stack);
        return 1;
    }

    for (int i = 0; i < n; ++i) {
        scanf("%lld", &a[i]);
    }

    int top = 0;

    for (int i = 0; i < n; ++i) {
        while (top > 0 && a[stack[top - 1]] > a[i]) {
            --top;
        }
        left[i] = top == 0 ? -1 : stack[top - 1];
        stack[top++] = i;
    }

    top = 0;

    for (int i = n - 1; i >= 0; --i) {
        while (top > 0 && a[stack[top - 1]] >= a[i]) {
            --top;
        }
        right[i] = top == 0 ? n : stack[top - 1];
        stack[top++] = i;
    }

    long long answer = 0;

    for (int i = 0; i < n; ++i) {
        long long left_count = i - left[i];
        long long right_count = right[i] - i;
        long long contribution = (a[i] % MOD) *
                                 (left_count % MOD) % MOD;
        contribution = contribution * (right_count % MOD) % MOD;
        answer = (answer + contribution) % MOD;
    }

    printf("%lld\n", answer);

    free(a);
    free(left);
    free(right);
    free(stack);
    return 0;
}

