int main() {
    const long long MOD = 1000000007LL;

    int n;
    cin >> n;

    vector<long long> a(n);
    for (long long &x : a) {
        cin >> x;
    }

    vector<int> left(n);
    vector<int> right(n);
    stack<int> indices;

    for (int i = 0; i < n; ++i) {
        while (!indices.empty() && a[indices.top()] > a[i]) {
            indices.pop();
        }

        left[i] = indices.empty() ? i + 1 : i - indices.top();
        indices.push(i);
    }

    while (!indices.empty()) {
        indices.pop();
    }

    for (int i = n - 1; i >= 0; --i) {
        while (!indices.empty() && a[indices.top()] >= a[i]) {
            indices.pop();
        }

        right[i] = indices.empty() ? n - i : indices.top() - i;
        indices.push(i);
    }

    long long answer = 0;

    for (int i = 0; i < n; ++i) {
        long long contribution = (a[i] % MOD) *
                                  (left[i] % MOD) % MOD *
                                  (right[i] % MOD) % MOD;
        answer = (answer + contribution) % MOD;
    }

    cout << answer;
    return 0;
}

