#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>
#include <stdbool.h>
#include <math.h>
int main(void)
{
    int n;
    long long a[1000];
    scanf("%d",&n);
    for(int i=0;i<n;++i)scanf("%lld",&a[i]);
    long long mx=a[0],mn=a[0],best=a[0];
    for(int i=1;i<n;++i) {
        long long x=a[i],p=mx*x,q=mn*x;
        mx=p>q&&p>x?p:(q>x?q:x);
        mn=p<q&&p<x?p:(q<x?q:x);
        long long v=mx;
        if(v>best)best=v;
        if(mn>best)best=mn;
    }
    printf("%lld\n",best);
}

