#include <iostream>
#include <algorithm>
using namespace std;

int main() {
    int n;
    cin >> n;

    long long x;
    cin >> x;

    long long maximum = x;
    long long minimum = x;
    long long answer = x;

    for (int i = 1; i < n; ++i) {
        cin >> x;

        if (x < 0) {
            swap(maximum, minimum);
        }

        maximum = max(x, maximum * x);
        minimum = min(x, minimum * x);
        answer = max(answer, maximum);
    }

    cout << answer << '\n';
    return 0;
}

