public class Main {
    static class FS {
        private final InputStream in = System.in;
        private final byte[] b = new byte[1<<16];
        int p=0,n=0;
        int read() throws IOException {
            if(p>=n){
                n=in.read(b);
                p=0;
                if(n<0)return -1;
            }
            return b[p++];
        }
        String next() throws IOException {
            StringBuilder s=new StringBuilder();
            int c;
            do{
                c=read();
            } while(c<=32&&c!=-1);
            while(c>32&&c!=-1){
                s.append((char)c);
                c=read();
            }
            return s.toString();
        }
        long nextLong() throws IOException {
            return Long.parseLong(next());
        }
        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
    static int val(char c){
        return c<='9'?c-'0':c-'A'+10;
    }
    static char dig(int x){
        return x<10?(char)('0'+x):(char)('A'+x-10);
    }
    public static void main(String[] args)throws Exception{
        FS f=new FS();
        String s=f.next().toUpperCase();
        int a=f.nextInt(),b=f.nextInt();
        BigInteger v=BigInteger.ZERO,ba=BigInteger.valueOf(a);
        for(char c:s.toCharArray())v=v.multiply(ba).add(BigInteger.valueOf(val(c)));
        if(v.signum()==0){
            System.out.println("0");
            return;
        }
        StringBuilder z=new StringBuilder();
        BigInteger bb=BigInteger.valueOf(b);
        while(v.signum()>0){
            BigInteger[] q=v.divideAndRemainder(bb);
            z.append(dig(q[1].intValue()));
            v=q[0];
        }
        System.out.println(z.reverse());
    }
}

