int main(void)
{
    int n;

    if (scanf("%d", &n) != 1) {
        return 0;
    }

    int *a = malloc((size_t)n * sizeof(*a));
    if (a == NULL) {
        return 1;
    }

    for (int i = 0; i < n; ++i) {
        scanf("%d", &a[i]);
    }

    int left = 0;
    int right = n - 1;
    int answer = -1;

    while (left <= right) {
        int mid = left + (right - left) / 2;
        if (a[mid] == mid) {
            answer = mid;
            break;
        }
        if (a[mid] < mid) {
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }

    printf("%d\n", answer);
    free(a);
    return 0;
}

