static int can_place(const int *stalls, int n, int cows, int distance)
{
    int placed = 1;
    int last = stalls[0];

    for (int i = 1; i < n; ++i) {
        if (stalls[i] - last >= distance) {
            ++placed;
            last = stalls[i];

            if (placed >= cows) {
                return 1;
            }
        }
    }

    return 0;
}

static int compare_ints(const void *left, const void *right)
{
    int a = *(const int *)left;
    int b = *(const int *)right;
    return (a > b) - (a < b);
}

int main(void)
{
    int n;
    int cows;

    if (scanf("%d %d", &n, &cows) != 2) {
        return 0;
    }

    int *stalls = malloc((size_t)n * sizeof(*stalls));
    if (stalls == NULL) {
        return 1;
    }

    for (int i = 0; i < n; ++i) {
        scanf("%d", &stalls[i]);
    }

    qsort(stalls, (size_t)n, sizeof(*stalls), compare_ints);

    int low = 0;
    int high = stalls[n - 1] - stalls[0];
    int answer = 0;

    while (low <= high) {
        int mid = low + (high - low) / 2;

        if (can_place(stalls, n, cows, mid)) {
            answer = mid;
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }

    printf("%d\n", answer);
    free(stalls);
    return 0;
}

