        if (eval == target) res.push_back(cur);
        return;
    }
    for (int len = 1; len <= (int)num.size() - pos; ++len) {
        string part = num.substr(pos, len);
        if (part.size() > 1 && part[0] == '0') break;
        long long n = stoll(part);
        if (pos == 0) bt(num, target, pos+len, n, n, part);
        else {
            bt(num, target, pos+len, eval+n, n, cur+"+"+part);
            bt(num, target, pos+len, eval-n, -n, cur+"-"+part);
            bt(num, target, pos+len, eval-mult+mult*n, mult*n, cur+"*"+part);
        }
    }
}
