struct TreeNode {
    int val;
    TreeNode *left;
    TreeNode *right;
    TreeNode(int x) : val(x), left(NULL), right(NULL) {}
};

TreeNode* buildTree(vector<int>& vals) {
    if (vals.empty() || vals[0] == -1) return NULL;
    TreeNode* root = new TreeNode(vals[0]);
    queue<TreeNode*> q;
    q.push(root);
    int i = 1;
    while (!q.empty() && i < vals.size()) {
        TreeNode* node = q.front(); q.pop();
        if (i < vals.size() && vals[i] != -1) {
            node->left = new TreeNode(vals[i]);
            q.push(node->left);
        }
        i++;
        if (i < vals.size() && vals[i] != -1) {
            node->right = new TreeNode(vals[i]);
            q.push(node->right);
        }
        i++;
    }
    return root;
}

void replaceWithCousinSum(TreeNode* root) {
    if (!root) return;
    queue<TreeNode*> q;
    q.push(root);
    root->val = 0;
    
    while (!q.empty()) {
        int size = q.size();
        long long levelSum = 0;
        vector<TreeNode*> nodes;
        
        for (int i = 0; i < size; ++i) {
            TreeNode* node = q.front(); q.pop();
            nodes.push_back(node);
            if (node->left) {
                levelSum += node->left->val;
                q.push(node->left);
            }
            if (node->right) {
                levelSum += node->right->val;
                q.push(node->right);
            }
        }
        
        for (TreeNode* parent : nodes) {
            long long siblingSum = 0;
            if (parent->left) siblingSum += parent->left->val;
            if (parent->right) siblingSum += parent->right->val;
            
            if (parent->left) parent->left->val = levelSum - siblingSum;
            if (parent->right) parent->right->val = levelSum - siblingSum;
        }
    }
}

void printLevelOrder(TreeNode* root) {
    if (!root) return;
    queue<TreeNode*> q;
    q.push(root);
    while (!q.empty()) {
        TreeNode* node = q.front(); q.pop();
        cout << node->val << " ";
        if (node->left) q.push(node->left);
        if (node->right) q.push(node->right);
    }
    cout << endl;
}

