 static int lca(N[]a,int u,int v){ArrayList<Integer>p=new ArrayList<>(),q=new ArrayList<>();
path(a,0,u,p);
path(a,0,v,q);
int z=-1;
for(int i=0;i<Math.min(p.size(),q.size())&&p.get(i).equals(q.get(i));
i++)z=p.get(i);
