class Solution {
public:
    std::vector<int> nextSmallerElement(std::vector<int>& nums) {
        int n = nums.size();
        std::vector<int> res(n, -1);
        std::stack<int> st;

        for (int i = n - 1; i >= 0; i--) {
            // Maintain monotonic stack property by popping smaller elements
            while (!st.empty() && st.top() >= nums[i]) {
                st.pop();
            }
            if (!st.empty()) res[i] = st.top();
            st.push(nums[i]);
        }
        return res;
    }
