int square(int s, int n) {
    int row = (s - 1) / n;
    int col = (s - 1) % n;
    if (row & 1) col = n - 1 - col;
    return (n - 1 - row) * n + col;
}

int main() {
    int n;
    cin >> n;
    vector<vector<int>> board(n, vector<int>(n));
    for (auto &row : board) for (int &x : row) cin >> x;

    vector<int> dist(n * n + 1, -1);
    queue<int> q;
    dist[1] = 0;
    q.push(1);
    // BFS explores all die outcomes, so the first visit to the final square is optimal.
    // Each snake or ladder is applied immediately after the die move.
    // The distance array prevents revisiting squares.
    while (!q.empty()) {
        int s = q.front(); q.pop();
        if (s == n * n) {
            cout << dist[s];
            return 0;
        }
        for (int d = 1; d <= 6 && s + d <= n * n; ++d) {
            int t = s + d;
            int pos = square(t, n);
            int jump = board[pos / n][pos % n];
            if (jump != -1) t = jump;
            if (dist[t] == -1) {
                dist[t] = dist[s] + 1;
                q.push(t);
            }
        }
    }
    cout << -1;
    return 0;
}

