long long bestOrder(
    const vector<long long>& a,
    int firstLength,
    int secondLength
) {
    int n = static_cast<int>(a.size());
    vector<long long> prefix(n + 1, 0);

    for (int i = 0; i < n; ++i) {
        prefix[i + 1] = prefix[i] + a[i];
    }

    long long best = numeric_limits<long long>::min();
    long long bestFirst = numeric_limits<long long>::min();

    for (int end = firstLength + secondLength; end <= n; ++end) {
        int firstEnd = end - secondLength;
        int firstStart = firstEnd - firstLength;

        bestFirst = max(
            bestFirst,
            prefix[firstEnd] - prefix[firstStart]
        );

        long long secondStart = firstEnd;
        long long secondSum = prefix[end] - prefix[secondStart];

        best = max(best, bestFirst + secondSum);
    }

    return best;
}

