        private final InputStream in = System.in;
        private final byte[] b = new byte[1<<16];
        int p=0,n=0;
        int read() throws IOException {
            if(p>=n){
                n=in.read(b);
                p=0;
                if(n<0)return -1;
            }
            return b[p++];
        }
        String next() throws IOException {
            StringBuilder s=new StringBuilder();
            int c;
            do{
                c=read();
            } while(c<=32&&c!=-1);
            while(c>32&&c!=-1){
                s.append((char)c);
                c=read();
            }
            return s.toString();
        }
        long nextLong() throws IOException {
            return Long.parseLong(next());
        }
        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
    public static void main(String[] args)throws Exception{
        FS f=new FS();
        int n=f.nextInt(),m=f.nextInt(),p=f.nextInt();
        long[][]a=new long[n][m],b=new long[m][p];
        for(int i=0;i<n;i++)for(int j=0;j<m;j++)a[i][j]=f.nextLong();
        for(int i=0;i<m;i++)for(int j=0;j<p;j++)b[i][j]=f.nextLong();
        long[][]c=new long[n][p];
        for(int i=0;i<n;i++)for(int k=0;k<m;k++)if(a[i][k]!=0)for(int j=0;j<p;j++)if(b[k][j]!=0)c[i][j]+=a[i][k]*b[k][j];
        StringBuilder o=new StringBuilder();
        for(int i=0;i<n;i++){
            for(int j=0;j<p;j++){
                if(j>0)o.append(' ');
                o.append(c[i][j]);
            }
            o.append('\n');
        }
        System.out.print(o);
    }
}

public class Solution {
    public int[][] multiply(int[][] mat1, int[][] mat2) {
        int r1 = mat1.length, c1 = mat1[0].length;
        int c2 = mat2[0].length;
        int[][] res = new int[r1][c2];
        for (int i = 0; i < r1; i++) {
            for (int k = 0; k < c1; k++) {
                if (mat1[i][k] != 0) {
                    for (int j = 0; j < c2; j++) {
                        if (mat2[k][j] != 0) {
                            res[i][j] += mat1[i][k] * mat2[k][j];
                        }
                    }
                }
            }
        }
        return res;
    }
}

