            if((e&1)==1)r=mul(r,a,m);
            a=mul(a,a,m);
            e>>=1;
        }
        return r;
    }
    static long mul(long a,long b,long m){
        return BigInteger.valueOf(a).multiply(BigInteger.valueOf(b)).mod(BigInteger.valueOf(m)).longValue();
