    static long comb(long n,long r,long p){
        if(r<0||r>n)return 0;
        if(p==1)return 0;
        if(n<p){
            int nn=(int)n,rr=(int)r;
            long[] fact=new long[nn+1];
            fact[0]=1%p;
            for(int i=1;i<=nn;i++)fact[i]=mul(fact[i-1],i,p);
            return mul(fact[nn],mul(modPow(fact[rr],p-2,p),modPow(fact[nn-rr],p-2,p),p),p);
        }
        long ni=n%p,ri=r%p;
        if(ri>ni)return 0;
        return mul(comb(ni,ri,p),comb(n/p,r/p,p),p);
    }
