    else if (strstr("Count Trailing Zeros in Binary Representation", "Set")) printf("%llu\n", a | (1ULL << b));
    else if (strstr("Count Trailing Zeros in Binary Representation", "Clear")) printf("%llu\n", a & ~(1ULL << b));
    else if (strstr("Count Trailing Zeros in Binary Representation", "Toggle")) printf("%llu\n", a ^ (1ULL << b));
    else if (strstr("Count Trailing Zeros in Binary Representation", "Count Set")) { int c = 0; while (a) { c += a & 1ULL; a >>= 1; } printf("%d\n", c); }
    else if (strstr("Count Trailing Zeros in Binary Representation", "Power of Two")) printf("%s\n", a && !(a & (a - 1)) ? "Yes" : "No");
    else if (strstr("Count Trailing Zeros in Binary Representation", "Sum of Two")) { while (b) { unsigned long long carry = a & b; a ^= b; b = carry << 1; } printf("%llu\n", a); }
    else printf("%llu\n", a ^ b);

    return 0;
}

