                if (used.has(nums[i])) continue;
                if (curr.length === 0 || nums[i] >= curr[curr.length - 1]) {
                    used.add(nums[i]);
                    curr.push(nums[i]);
                    findInc(i + 1, curr);
                    curr.pop();
                }
            }
        }
        findInc(0, []);
