def reachable(n,L,R):
    if n==0:return []
    out=[]; seen=set(); st=[0]
    while st:
        u=st.pop()
        if u<0 or u in seen or u>=n: continue
        seen.add(u); out.append(u)
        if R[u]>=0: st.append(R[u])
        if L[u]>=0: st.append(L[u])
    return out

def print_tree(n,v,L,R):
    if n==0:
        print(0); return
    order=reachable(n,L,R); mp={u:i for i,u in enumerate(order)}
    out=[str(len(order))]
    for u in order:
        out.append(f"{v[u]} {mp.get(L[u],-1)} {mp.get(R[u],-1)}")
    sys.stdout.write('\n'.join(out)+'\n')

def children(u,L,R):
    if u<0:return []
    z=[]
    if L[u]>=0:z.append(L[u])
    if R[u]>=0:z.append(R[u])
    return z

def parents(n,L,R):
    p=[-1]*n
    for u in range(n):
        if L[u]>=0:p[L[u]]=u
        if R[u]>=0:p[R[u]]=u
    return p

def levels(n,L,R):
    if n==0:return []
    q=deque([0]); ans=[]
    while q:
        cur=[]
        for _ in range(len(q)):
            u=q.popleft(); cur.append(u)
            if L[u]>=0:q.append(L[u])
            if R[u]>=0:q.append(R[u])
        ans.append(cur)
    return ans

def postorder(n,L,R):
    if n==0:return []
    out=[]; st=[(0,0)]
    while st:
        u,s=st.pop()
        if u<0:continue
        if s==0:
            st.append((u,1))
            if L[u]>=0:st.append((L[u],0))
        elif s==1:
            st.append((u,2))
            if R[u]>=0:st.append((R[u],0))
        else:
            out.append(u)
    return out

def preorder(n,L,R):
    if n==0:return []
    out=[]; st=[0]
    while st:
        u=st.pop(); out.append(u)
        if R[u]>=0:st.append(R[u])
        if L[u]>=0:st.append(L[u])
    return out

def inorder(n,L,R):
    out=[]; st=[]; u=0 if n else -1
    while st or u>=0:
        while u>=0: st.append(u); u=L[u]
        u=st.pop(); out.append(u); u=R[u]
    return out

def find_value(n,v,x):
    for i in range(n):
        if v[i]==x:return i
    return -1

