        cin >> x;
    }

    sort(a.begin(), a.end());
    long long count = 0;

    for (int i = 0; i < n - 2; ++i) {
        int left = i + 1;
        int right = n - 1;

        while (left < right) {
            long long sum = a[i] + a[left] + a[right];

            if (sum < target) {
                ++left;
            } else if (sum > target) {
                --right;
            } else if (a[left] == a[right]) {
                long long length = right - left + 1;
                count += length * (length - 1) / 2;
                break;
            } else {
                long long left_value = a[left];
                long long right_value = a[right];
                long long left_count = 0;
                long long right_count = 0;

                while (left <= right && a[left] == left_value) {
                    ++left_count;
                    ++left;
                }

                while (right >= left && a[right] == right_value) {
                    ++right_count;
                    --right;
                }

                count += left_count * right_count;
            }
        }
    }

    cout << count << '\n';
    return 0;
}

