static void dfs(const char *s, int pos, int part, char *path)
{
    if (part == 4) {
        if (s[pos] == '\0') {
            printf("%s\n", path);
        }
        return;
    }
    int len = (int)strlen(s);
    for (int take = 1; take <= 3 && pos + take <= len; ++take) {
        if (take > 1 && s[pos] == '0') break;
        int value = 0;
        for (int i = 0; i < take; ++i) value = value * 10 + s[pos + i] - '0';
