bool validPart(const string &s, int start, int length) {
    if (length <= 0 || length > 3 || start + length > static_cast<int>(s.size())) {
        return false;
    }
    if (length > 1 && s[start] == '0') {
        return false;
    }
    int value = 0;
    for (int i = start; i < start + length; ++i) {
        value = value * 10 + s[i] - '0';
    }
    return value <= 255;
}

void build(const string &s, int pos, int parts, string current) {
    if (parts == 4) {
        if (pos == static_cast<int>(s.size())) {
            cout << current << '\n';
        }
        return;
    }

    for (int len = 1; len <= 3; ++len) {
        if (!validPart(s, pos, len)) {
            continue;
        }
        string next = current;
        if (!next.empty()) {
            next += '.';
        }
        next += s.substr(pos, len);
        build(s, pos + len, parts + 1, next);
    }
}

