// Generate every valid IPv4 address by choosing four bounded numeric segments.
public class Main {
    static void dfs(String s, int pos, int parts, StringBuilder path, List<String> out) {
        if (parts == 4) {
            if (pos == s.length()) out.add(path.substring(1));
            return;
        }
        int remain = s.length() - pos;
        int maxLen = Math.min(3, remain);
        for (int len = 1; len <= maxLen; len++) {
            if (pos + len > s.length()) break;
            if (len > 1 && s.charAt(pos) == '0') break;
            int value = 0;
            for (int i = pos; i < pos + len; i++) value = value * 10 + s.charAt(i) - '0';
            if (value > 255) break;
            int before = path.length();
            path.append('.').append(s, pos, pos + len);
            dfs(s, pos + len, parts + 1, path, out);
            path.setLength(before);
        }
    }
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String s = br.readLine();
        if (s == null) return;
        List<String> ans = new ArrayList<>();
        dfs(s.trim(), 0, 0, new StringBuilder(), ans);
        for (String ip : ans) System.out.println(ip);
    }
}

