public class Main {
    static BigInteger[] eg(BigInteger a,BigInteger b){
        if(b.signum()==0)return new BigInteger[]{
            a,BigInteger.ONE,BigInteger.ZERO
        };
        BigInteger[] t=eg(b,a.mod(b));
        return new BigInteger[]{
            t[0],t[2],t[1].subtract(a.divide(b).multiply(t[2]))
        };
    }
    public static void main(String[] args)throws Exception{
        Scanner sc=new Scanner(System.in);
        BigInteger a=sc.nextBigInteger(),b=sc.nextBigInteger(),n=sc.nextBigInteger();
        if(n.signum()<0){
            System.out.println(false);
            return;
        }
        BigInteger g=a.gcd(b);
        if(!n.mod(g).equals(BigInteger.ZERO)){
            System.out.println(false);
            return;
        }
        BigInteger aa=a.divide(g),bb=b.divide(g),nn=n.divide(g);
        BigInteger[] e=eg(aa,bb);
        BigInteger x=e[1].multiply(nn).mod(bb);
        System.out.println(x.multiply(aa).compareTo(nn)<=0);
    }
}

