        for(int[]a:d)Arrays.fill(a,1<<29);
        for(int[]u:q){
            d[u[0]][u[1]]=0;
        }
        int[]dr={
            1,-1,0,0
        },dc={
            0,0,1,-1
        };
        while(!q.isEmpty()){
            int[]u=q.remove();
            for(int k=0;k<4;k++){
                int x=u[0]+dr[k],y=u[1]+dc[k];
                if(x>=0&&x<r&&y>=0&&y<c&&g[x][y]!=2&&d[x][y]>(d[u[0]][u[1]]+1)){
                    d[x][y]=d[u[0]][u[1]]+1;
                    q.add(new int[]{
                        x,y
                    }
                    );
                }
            }
        }
        return d;
    }
    static boolean can(int wait,int[][]f,int[][]g){
        int r=g.length,c=g[0].length;
        if(wait>=f[0][0])return false;
        Queue<int[]>q=new ArrayDeque<>();
        int[][]d=new int[r][c];
        for(int[]x:d)Arrays.fill(x,-1);
        d[0][0]=0;
        q.add(new int[]{
