long long sumDigitsUpTo(long long n) {
    if (n <= 0) return 0;
    char s[30];
    sprintf(s, "%lld", n);
    int d = strlen(s);
    if (d == 1) return n * (n + 1) / 2;
    long long first = s[0] - '0';
    long long rem = atoll(s + 1);
    long long p = (long long)pow(10, d - 1);

