    static BigInteger pref(BigInteger n){
        if(n.signum()<0)return BigInteger.ZERO;
        if(n.compareTo(BigInteger.TEN)<0)return n.multiply(n.add(BigInteger.ONE)).divide(BigInteger.TWO);
        BigInteger p=BigInteger.ONE;
        while(p.multiply(BigInteger.TEN).compareTo(n)<=0)p=p.multiply(BigInteger.TEN);
        BigInteger high=n.divide(p),cur=n.divide(p).mod(BigInteger.TEN),low=n.mod(p);
        BigInteger res=high.multiply(BigInteger.valueOf(45)).multiply(p);
        res=res.add(high.multiply(cur).multiply(p));
        res=res.add(cur.multiply(cur.subtract(BigInteger.ONE)).divide(BigInteger.TWO).multiply(p));
        res=res.add(cur.multiply(low.add(BigInteger.ONE)));
        return res.add(pref(n.mod(p)));
    }
