void addStrings(const char* num1, const char* num2, char* out) {
    int i = strlen(num1) - 1, j = strlen(num2) - 1, carry = 0, k = 0;
    char temp[2005];
    while (i >= 0 || j >= 0 || carry) {
        int sum = carry;
        if (i >= 0) sum += num1[i--] - '0';
        if (j >= 0) sum += num2[j--] - '0';
        temp[k++] = (sum % 10) + '0';
        carry = sum / 10;
    }
    for (int l = 0; l < k; l++) {
        out[l] = temp[k - 1 - l];
    }
    out[k] = '\0';
}

