public class Main {
    static BigInteger floorDiv(BigInteger a,BigInteger b){
        BigInteger q=a.divide(b), r=a.remainder(b);
        return r.signum()!=0 && a.signum()!=b.signum()?q.subtract(BigInteger.ONE):q;
    }
    static BigInteger ceilDiv(BigInteger a,BigInteger b){
        BigInteger q=a.divide(b), r=a.remainder(b);
        return r.signum()!=0 && a.signum()==b.signum()?q.add(BigInteger.ONE):q;
    }
    static BigInteger[] eg(BigInteger a,BigInteger b){
        if(b.signum()==0)return new BigInteger[]{
            a,BigInteger.ONE,BigInteger.ZERO
        };
        BigInteger[] t=eg(b,a.mod(b));
        return new BigInteger[]{
            t[0],t[2],t[1].subtract(a.divide(b).multiply(t[2]))
        };
    }
    static BigInteger lowK(BigInteger lo,BigInteger hi,BigInteger base,BigInteger step){
        if(step.signum()>0)return ceilDiv(lo.subtract(base),step);
        return ceilDiv(hi.subtract(base),step);
    }
    static BigInteger highK(BigInteger lo,BigInteger hi,BigInteger base,BigInteger step){
        if(step.signum()>0)return floorDiv(hi.subtract(base),step);
        return floorDiv(lo.subtract(base),step);
    }
