        if(!C.mod(g).equals(BigInteger.ZERO)){
            System.out.println(0);
            return;
        }
        BigInteger[] e=eg(aa,bb);
        BigInteger mul=C.divide(g);
        BigInteger x0=e[1].multiply(mul), y0=e[2].multiply(mul);
        if(A.signum()<0)x0=x0.negate();
        if(B.signum()<0)y0=y0.negate();
        BigInteger dx=B.divide(g), dy=A.divide(g).negate();
        BigInteger lo1=lowK(xl,xh,x0,dx), hi1=highK(xl,xh,x0,dx);
        BigInteger lo2=lowK(yl,yh,y0,dy), hi2=highK(yl,yh,y0,dy);
