static int can_ship(const int *w, int n, int days, long long capacity)
{
    int used_days = 1;
    long long current = 0;

    for (int i = 0; i < n; ++i) {
        if (w[i] > capacity) {
            return 0;
        }

        if (current + w[i] <= capacity) {
