int solve(vector<int>& nums) {
    int n = nums.size(), res = 0;
    stack<int> st;
    for (int i = 0; i < n; i++) {
        while (!st.empty() && nums[st.top()] <= nums[i]) {
            res = max(res, i - st.top());
            st.pop();
        }
        st.push(i);
    }
    return res;
}

