#define MOD 1000000007LL

void matMul(int n, long long a[n][n], long long b[n][n], long long res[n][n]) {
    long long temp[n][n];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) temp[i][j] = 0;
    }
    for (int i = 0; i < n; i++) {
        for (int k = 0; k < n; k++) {
            for (int j = 0; j < n; j++) {
                temp[i][j] = (temp[i][j] + a[i][k] * b[k][j]) % MOD;
            }
        }
    }
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) res[i][j] = temp[i][j];
    }
}

