    static String s,p;
    static int[][] memo;
    static boolean dfs(int i,int j){
        if(j==p.length())return i==s.length();
        if(memo[i][j]!=-1)return memo[i][j]==1;
        boolean first=i<s.length()&&(p.charAt(j)=='.'||p.charAt(j)==s.charAt(i));
