    int n; scanf("%d", &n);
    int arr[n], left=0, right=n-1;
    for(int i=0; i<n; i++) scanf("%d", &arr[i]);
    while(left < right) {
        while(left < right && arr[left] == 0) left++;
        while(left < right && arr[right] == 1) right--;
        if(left < right) { arr[left] = 0; arr[right] = 1; left++; right--; }
    }
