        int high = Arrays.stream(boards).sum();
        while(low < high) {
            int mid = low + (high - low) / 2;
            if(canPaint(boards, painters, mid)) high = mid;
            else low = mid + 1;
        }
        System.out.println(low);
    }
    static boolean canPaint(int[] boards, int painters, int time) {
        int p = 1, sum = 0;
        for(int b : boards) {
            if(sum + b > time) { p++; sum = b; }
            else sum += b;
        }
        return p <= painters;
    }
}

