    EdgeNode* cur = adj[u];
    while (cur) {
        int v = cur->v;
        if (v != p) {
            if (tin[v] != -1) {
                if (tin[v] < low[u]) low[u] = tin[v];
            } else {
                dfs(v, u, adj, tin, low, bridges, bCount);
                if (low[v] < low[u]) low[u] = low[v];
                if (low[v] > tin[u]) {
                    bridges[*bCount] = (int*)malloc(2 * sizeof(int));
                    bridges[*bCount][0] = u;
                    bridges[*bCount][1] = v;
                    (*bCount)++;
                }
            }
        }
        cur = cur->next;
    }
