    *returnSize = bCount;
    *returnColumnSizes = (int*)malloc(bCount * sizeof(int));
    for (int i = 0; i < bCount; i++) (*returnColumnSizes)[i] = 2;

    free(tin);
    free(low);
    free(adj);
    return bridges;
