    int l = 0, r = n - 1, ans = -1;
    while (l <= r) {
        int m = l + (r - l) / 2;
        if (a[m] == key) { ans = m; break; }
        if (a[m] < key) l = m + 1; else r = m - 1;
    }
    if (strstr("Binary Search", "Insert")) printf("%d\n", ans >= 0 ? ans : l);
    else if (strstr("Binary Search", "Square Root") || strstr("Binary Search", "Perfect Square")) {
        long long lo = 0, hi = key, root = 0;
        while (lo <= hi) { long long mid = (lo + hi) / 2; if (mid * mid <= key) { root = mid; lo = mid + 1; } else hi = mid - 1; }
        printf(strstr("Binary Search", "Perfect") ? "%s\n" : "%lld\n", strstr("Binary Search", "Perfect") ? (root * root == key ? "Yes" : "No") : "");
    } else {
        printf("%d\n", ans);
