#include <stdio.h>
#include <stdlib.h>

static void solve_rotten_oranges(void) {
    int n, m;
    if (scanf("%d %d", &n, &m) != 2) return;
    unsigned char **adj = malloc((size_t)n * sizeof(unsigned char *));
    int *indeg = calloc((size_t)n, sizeof(int));
    int *outdeg = calloc((size_t)n, sizeof(int));
    for (int i = 0; i < n; ++i) adj[i] = calloc((size_t)n, 1);
    for (int i = 0; i < m; ++i) {
        int u, v;
        scanf("%d %d", &u, &v);
        if (u >= 0 && u < n && v >= 0 && v < n && !adj[u][v]) { adj[u][v] = 1; ++outdeg[u]; ++indeg[v]; }
    }
    int start = 0;
    scanf("%d", &start);
    int *seen = calloc((size_t)n, sizeof(int));
    int *queue = malloc((size_t)n * sizeof(int));
    int head = 0, tail = 0;
    if (start >= 0 && start < n) { seen[start] = 1; queue[tail++] = start; }
    while (head < tail) {
        int u = queue[head++];
        for (int v = 0; v < n; ++v) if (adj[u][v] && !seen[v]) { seen[v] = 1; queue[tail++] = v; }
    }
    int count = 0;
    for (int i = 0; i < n; ++i) count += seen[i];
    printf("%d\n", count);
    free(queue);
    free(seen);
    for (int i = 0; i < n; ++i) free(adj[i]);
    free(adj);
    free(indeg);
    free(outdeg);
}

int main(void) {
    solve_rotten_oranges();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

int orangesRotting(int** grid, int gridSize, int* gridColSize) {
    int m = gridSize, n = gridColSize[0];
    int q_r[m * n + 5], q_c[m * n + 5], q_d[m * n + 5];
    int head = 0, tail = 0;
    int fresh = 0;

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (grid[i][j] == 2) {
                q_r[tail] = i; q_c[tail] = j; q_d[tail++] = 0;
            } else if (grid[i][j] == 1) {
                fresh++;
            }
        }
    }

    int minutes = 0;
    int dr[] = {-1, 1, 0, 0};
    int dc[] = {0, 0, -1, 1};

    while (head < tail) {
        int r = q_r[head], c = q_c[head], d = q_d[head++];
        if (d > minutes) minutes = d;
        for (int k = 0; k < 4; k++) {
            int nr = r + dr[k], nc = c + dc[k];
            if (nr >= 0 && nr < m && nc >= 0 && nc < n && grid[nr][nc] == 1) {
                grid[nr][nc] = 2;
                fresh--;
                q_r[tail] = nr; q_c[tail] = nc; q_d[tail++] = d + 1;
            }
        }
    }
    return fresh == 0 ? minutes : -1;
}

