            pq.offer(new int[]{0, 0});
            long total = 0;

            while (!pq.isEmpty()) {
                int[] cur = pq.poll();
                int w = cur[0], u = cur[1];
                if (vis[u]) continue;
                vis[u] = true;
                total += w;
                for (int[] edge : adj.get(u)) {
                    if (!vis[edge[0]]) {
                        pq.offer(new int[]{edge[1], edge[0]});
                    }
                }
            }
            System.out.println(total);
        }
        sc.close();
    }
}

