    return res; 
}
int countSmaller(struct Node* root, int key) {
    if(!root) return 0;
    if(root->val >= key) return countSmaller(root->left, key);
    return 1 + countSmaller(root->left, key) + countSmaller(root->right, key); // O(N) fallback
}
