        u = int(input_data[idx]); idx += 1
        v = int(input_data[idx]); idx += 1
        w = int(input_data[idx]); idx += 1
        edges.append((u, v, w))
        
    dist = [float('inf')] * (n+1)
    dist[s] = 0
    
    for _ in range(n-1):
        updated = False
        for u, v, w in edges:
            if dist[u] != float('inf') and dist[v] > dist[u] + w:
                dist[v] = dist[u] + w
                updated = True
        if not updated:
            break
            
    # Check negative cycle
    for u, v, w in edges:
        if dist[u] != float('inf') and dist[v] > dist[u] + w:
            print("NEGATIVE CYCLE")
            return
            
    result = []
