    public int maximumCandies(int[] candies, long k) {
        int left = 1, right = 0;
        for (int c : candies) right = Math.max(right, c);
        int ans = 0;
        // Binary search loop to narrow down range
        while (left <= right) {
            // Calculate midpoint to prevent potential overflow
            int mid = left + (right - left) / 2;
            long children = 0;
            for (int c : candies) {
                children += c / mid;
            }
            if (children >= k) {
                ans = mid;
                left = mid + 1;
            } else {
                right = mid - 1;
