            if (ch === "/") {
                g[i * 3][j * 3 + 2] = 1;
                g[i * 3 + 1][j * 3 + 1] = 1;
                g[i * 3 + 2][j * 3] = 1;
            } else if (ch === "\\") {
                g[i * 3][j * 3] = 1;
                g[i * 3 + 1][j * 3 + 1] = 1;
                g[i * 3 + 2][j * 3 + 2] = 1;
            }
        }
    }
    function dfs(x, y) {
        if (x < 0 || x >= size || y < 0 || y >= size || g[x][y] === 1) return;
        g[x][y] = 1;
        dfs(x + 1, y);
        dfs(x - 1, y);
        dfs(x, y + 1);
        dfs(x, y - 1);
    }
    let regions = 0;
    for (let i = 0; i < size; i++) {
        for (let j = 0; j < size; j++) {
            if (g[i][j] === 0) {
                regions++;
                dfs(i, j);
            }
        }
    }
    console.log(regions);
