    function union(i, j) {
        const ri = find(i), rj = find(j);
        if (ri !== rj) parent[ri] = rj;
    }

    for (let r = 0; r < n; r++) {
        for (let c = 0; c < n; c++) {
            const root = 4 * (r * n + c);
            const val = grid[r][c];
            if (val !== '/') {
