long long largestHistogram(vector<int>&h){
    int n=h.size();
    stack<int> st; long long ans=0;
    for(int i=0;i<=n;i++){
        while(!st.empty()&&(i==n||h[st.top()]>h[i])){
            int height=h[st.top()]; st.pop();
            int width=st.empty()?i:i-st.top()-1;
            ans=max(ans,(long long)height*width);
        }
        st.push(i);
    }
    return ans;
}
