        int[] rowMap = new int[26];
        String[] rows = {"qwertyuiop", "asdfghjkl", "zxcvbnm"};
        for (int r = 0; r < 3; r++) {
            for (char c : rows[r].toCharArray()) rowMap[c - 'a'] = r;
