bool canSplitBags(const vector<int>& nums, int maxOperations, int maxSize) {
    int operations = 0;
    for (int num : nums) {
        if (num > maxSize) {
            operations += (num - 1) / maxSize; // Equivalent to ceil(num/maxSize) - 1
        }
        if (operations > maxOperations) return false;
    }
    return true;
