long long countSubarraysXorK(const std::vector<int>& arr, int k) {
    int prefixXor = 0;
    long long count = 0;
    std::unordered_map<int, int> freq;
    freq[0] = 1;
    for (int num : arr) {
        prefixXor ^= num;
        if (freq.find(prefixXor ^ k) != freq.end()) {
            count += freq[prefixXor ^ k];
        }
        freq[prefixXor]++;
    }
    return count;
}

