    int l = 0, r = n - 1, ans = -1;
    while (l <= r) {
        int m = l + (r - l) / 2;
        if (a[m] == key) { ans = m; break; }
        if (a[m] < key) l = m + 1; else r = m - 1;
    }
    if (strstr("Split Array Largest Sum", "Insert")) printf("%d\n", ans >= 0 ? ans : l);
    else if (strstr("Split Array Largest Sum", "Square Root") || strstr("Split Array Largest Sum", "Perfect Square")) {
        long long lo = 0, hi = key, root = 0;
        while (lo <= hi) { long long mid = (lo + hi) / 2; if (mid * mid <= key) { root = mid; lo = mid + 1; } else hi = mid - 1; }
        printf(strstr("Split Array Largest Sum", "Perfect") ? "%s\n" : "%lld\n", strstr("Split Array Largest Sum", "Perfect") ? (root * root == key ? "Yes" : "No") : "");
