bool canSplit(const vector<int>& nums, int k, int maxSum) {
    int splits = 1;
    long long currentSum = 0;
    for (int num : nums) {
        if (currentSum + num > maxSum) {
            splits++;
            currentSum = num;
            if (splits > k) return false;
        } else {
            currentSum += num;
        }
    }
    return true;
}

