int main(){int n;cin>>n;vector<ll>a(n);for(auto&x:a)cin>>x;Tree t;t.a.reserve(n);function<int(int,int)>f=[&](int l,int r){if(l>=r)return -1;int m=(l+r)/2,id=t.a.size();t.a.push_back({a[m],-1,-1});t.a[id].l=f(l,m);t.a[id].r=f(m+1,r);return id;};t.root=f(0,n);printTree(t);}

struct ListNode {
    int val;
    ListNode *prev, *next;
    ListNode(int x) : val(x), prev(nullptr), next(nullptr) {}
};

struct TreeNode {
    int val;
    TreeNode *left, *right;
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
};

class Solution {
    ListNode* cur = nullptr;

    TreeNode* build(int count) {
        if (count <= 0) return nullptr;
        TreeNode* left = build(count / 2);
        TreeNode* root = new TreeNode(cur->val);
        cur = cur->next;
        root->left = left;
        root->right = build(count - count / 2 - 1);
        return root;
    }
public:
    TreeNode* sortedListToBST(ListNode* head) {
        int count = 0;
        ListNode* temp = head;
        while (temp) {
            count++;
            temp = temp->next;
        }
        cur = head;
        return build(count);
    }
};

