    static int buildLevel(T t,long[] lev,int lo,int hi,Map<Long,Integer>pos){if(lo>=hi)return -1;
long rv=lev[lo];
int id=t.a.size();
t.a.add(new N(rv));
int m=pos.get(rv);
long[] tmp=new long[hi-lo-1];
int k=0;
for(int i=lo+1;i<hi;i++)if(pos.get(lev[i])<m)tmp[k++]=lev[i];
long[] tmp2=new long[hi-lo-1];
int q=0;
for(int i=lo+1;i<hi;i++)if(pos.get(lev[i])>m)tmp2[q++]=lev[i];
t.a.get(id).l=buildLevel(t,tmp,0,k,pos);
t.a.get(id).r=buildLevel(t,tmp2,0,q,pos);
