    static int buildPost(T t,long[] a,int l,int r,long lo,long hi){if(l>r)return -1;
long v=a[r];
if(v<=lo||v>=hi)return -1;
int id=t.a.size();
t.a.add(new N(v));
int m=r-1;
while(m>=l&&a[m]>v)m--;
t.a.get(id).l=buildPost(t,a,l,m,lo,v);
t.a.get(id).r=buildPost(t,a,m+1,r-1,v,hi);
if(t.root<0)t.root=id;
return id;
}
