    static boolean isComplete(T t,int u){if(u<0)return true;
ArrayDeque<Integer>q=new ArrayDeque<>();
q.add(u);
boolean gap=false;
while(!q.isEmpty()){int x=q.remove();
int l=t.a.get(x).l,r=t.a.get(x).r;
if(l<0)gap=true;
else{if(gap)return false;
q.add(l);
}if(r<0)gap=true;
else{if(gap)return false;
q.add(r);
}}return true;
}
    static int largestPerfect(T t,int u){if(u<0)return 0;
