                if low[v] >= tin[u] and p != -1:
                    is_ap[u] = True
                children += 1
        if p == -1 and children > 1:
            is_ap[u] = True

    for i in range(n):
        if tin[i] == -1:
            dfs(i)

    return [i for i in range(n) if is_ap[i]]

