void backtrackBin(int n, char* cur, int len, char** res, int* count) {
    if (len == n) {
        cur[len] = '\0';
        res[*count] = strdup(cur);
        (*count)++;
        return;
    }
    cur[len] = '1';
    backtrackBin(n, cur, len + 1, res, count);

    if (len == 0 || cur[len - 1] != '0') {
        cur[len] = '0';
        backtrackBin(n, cur, len + 1, res, count);
    }
}

