        long th=f.nl();
        int lo=0,hi=Math.min(n,m);
        while(lo<hi){
            int s=(lo+hi+1)>>>1;
            boolean ok=false;
            for(int i=0;i+s<=n&&!ok;i++)for(int j=0;j+s<=m;j++)if(p[i+s][j+s]-p[i][j+s]-p[i+s][j]+p[i][j]<=th){
                ok=true;
                break;
            }
            if(ok)lo=s;
            else hi=s-1;
        }
        System.out.println(lo);
    }
