def count_at_distance_k(n: int, edges: List[List[int]], src: int, k: int) -> int:
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    dist = [-1] * n
    dist[src] = 0
    q = deque([src])

