    for (int i = 0; i < m; ++i) {
        int u, v;
        scanf("%d %d", &u, &v);
        if (u >= 0 && u < n && v >= 0 && v < n && !adj[u][v]) { adj[u][v] = 1; ++outdeg[u]; ++indeg[v]; }
    }
    int u, v;
    if (scanf("%d %d", &u, &v) != 2) return;
    printf("%s\n", u >= 0 && u < n && v >= 0 && v < n && adj[u][v] ? "YES" : "NO");
    for (int i = 0; i < n; ++i) free(adj[i]);
    free(adj);
    free(indeg);
    free(outdeg);
}

