            int count = leaves.size();
            remaining -= count;
            for (int i = 0; i < count; i++) {
                int leaf = leaves.front();
                leaves.pop();
                int neighbor = *adj[leaf].begin();
                adj[neighbor].erase(leaf);
                if (adj[neighbor].size() == 1) leaves.push(neighbor);
            }
        }
        std::vector<int> res;
        while (!leaves.empty()) {
            res.push_back(leaves.front());
            leaves.pop();
        }
