    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            cin >> maze[i][j];
            
    vector<string> result;
    if (maze[0][0] == 1)
        findPaths(maze, 0, 0, "", result, n);
        
    for (const string& p : result) {
        cout << p << endl;
    }
    return 0;
}

