#define MAX(a, b) ((a) > (b) ? (a) : (b))

int* partitionLabels(char* s, int* returnSize) {
    int last[26] = {0};
    int len = strlen(s);
    for (int i = 0; i < len; i++) last[s[i] - 'a'] = i;

    int* res = (int*)malloc(len * sizeof(int));
    int count = 0, start = 0, end = 0;

    for (int i = 0; i < len; i++) {
        end = MAX(end, last[s[i] - 'a']);
        if (i == end) {
            res[count++] = end - start + 1;
            start = i + 1;
        }
    }
    *returnSize = count;
    return res;
}

