            dp[i] = -float('inf')
            for k in range(1, 4):
                if i + k <= n:
                    take += stoneValue[i + k - 1]
                    # Update dynamic programming state transition
                    dp[i] = max(dp[i], take - dp[i + k])

        if dp[0] > 0:
            return "Alice"
        elif dp[0] < 0:
            return "Bob"
        return "Tie"

