    NodeStr nodes[100];
    int nSize = 0;
    double dist[100][100];
    for (int i = 0; i < 100; i++) {
        for (int j = 0; j < 100; j++) dist[i][j] = (i == j) ? 1.0 : -1.0;
    }

    for (int i = 0; i < equationsSize; i++) {
        int u = getNodeIdx(equations[i][0], nodes, &nSize);
