        "", "", "abc", "def", "ghi", "jkl", "mno", "pqrs", "tuv", "wxyz"
    };

    private static void backtrack(String digits, int index, StringBuilder current, List<String> res) {
        if (index == digits.length()) {
            res.add(current.toString());
