bool canAllocate(const vector<int>& pages, int students, int maxPages) {
    int studentsUsed = 1;
    long long currentPages = 0;
    for (int p : pages) {
        if (currentPages + p > maxPages) {
            studentsUsed++;
            currentPages = p;
            if (studentsUsed > students) return false;
        } else {
            currentPages += p;
        }
    }
    return true;
}

