    int side = total / 4;

    qsort(matchsticks, matchsticksSize, sizeof(int), cmpDescMatch);
    if (matchsticks[0] > side) return false;

    int sides[4] = {0};
    return backtrackMatch(matchsticks, matchsticksSize, 0, side, sides);
}

