        DNode(long v) {
            this.v = v;
        }
    }
    static Node readList(FastScanner fs, int n) throws IOException {
        Node dummy = new Node(0), t = dummy;
        for (int i=0;i<n;i++){
            t.next=new Node(fs.nextLong());
            t=t.next;
        }
        return dummy.next;
    }
    static DNode readDList(FastScanner fs, int n) throws IOException {
        DNode head=null, tail=null;
        for(int i=0;i<n;i++){
            DNode x=new DNode(fs.nextLong());
            if(head==null) head=x;
            else {
                tail.next=x;
                x.prev=tail;
            }
            tail=x;
        }
