        dp[0][j] = grid[0][j]
        
    for j in range(1, c):
        for i in range(r):
            dp[i][j] = grid[i][j] + max(dp[i][j-1], dp[i-1][j-1] if i > 0 else 0, dp[i+1][j-1] if i < r - 1 else 0)
            
    print(max(dp[i][c-1] for i in range(r)))

