                    node.next = prev;
                    prev = node;
                    node = next;
                }
                prevGroupEnd.next = prev;
                prevGroupEnd = start;
            } else {
                prevGroupEnd = end == null ? findLast(start) : getPrev(start, end);
                // Actually just move prevGroupEnd to last node of this group
                ListNode last = start;
                for(int i=1; i<count; i++) last = last.next;
                prevGroupEnd = last;
            }
            curr = end;
            groupSize++;
        }
        
