void solve(int L,int R,vector<int>zan){
	if(L == R){
		ans[L] = zan[0];
		return;
	}
	vector<int>lb,ub;
	for(int i=L;i<R;i+=2){
		if(zan[i-L] > zan[i+1-L]) bad = 1;
