/**
 * Given a sorted array of numbers, determine if there exists a fixed point, if so return index, or return -1. Fixed point in array is when i = arr[i].
 */

#include<iostream>
#include<vector>

int binarySearchFixedPoint( const std::vector<int> & arr) {
	int high = arr.size() -1;
	int low = 0;
	while ( low <= high ) {
		int mid = (low + high)/2;
		if ( arr[mid] == mid ) {
			return mid;
		} else if ( mid > arr[mid] ) {
			low = mid + 1;
		} else {
			high = mid - 1;
		}
	}
	return -1;
}

