    for(int v=0; v<n; v++) {
      if (parent[k][v]<0) {
        parent[k+1][v] = -1;
      } else {
        parent[k+1][v] = parent[k][parent[k][v]];
      }
    }
  }
}

int lca(int u, int v) {
  debug(u, depth[u], v, depth[v]);
  if (depth[u] > depth[v]) swap(u, v);
  for(int k=0; k<MAX_LOG_V; k++) {
    if ((depth[v] - depth[u]) >> k & 1) {
      v = parent[k][v];
    }
  }
  if (u==v) return u;
  for(int k=MAX_LOG_V-1; k>=0; k--) {
    debug(k, u, v);
    if (parent[k][u] != parent[k][v]) {
      u = parent[k][u];
      v = parent[k][v];
    }
  }
  return parent[0][u];
}

