public class AnagramsByCounting {
    static boolean areAnagrams(String s, String t) {
        if (s.length() != t.length()) {
            return false;
        }

        for (char ch = 'a'; ch <= 'z'; ch++) {
            if (countOccurrences(ch, s) != countOccurrences(ch, t)) {
                return false;
            }
        }

        return true;
    }

