#include<stdio.h>

typedef struct term {
    int r;
    int c;
    int v;
} term;

int add_sparse_matrix(term a[], term b[], int na, int nb, term sc[]) {
    int k1, k2, k3;
    k1 = k2 = k3 = 0;

    while (k1 < na && k2 < nb) {
        if (a[k1].r == b[k2].r) {
            if (a[k1].c == b[k2].c) {
                sc[k3].r = a[k1].r;
                sc[k3].c = a[k1].c;
                sc[k3].v = a[k1].v + b[k2].v;

                k3++;
                k2++;
                k1++;
            } else if (a[k1].c < b[k2].c) {
                sc[k3].r = a[k1].r;
                sc[k3].c = a[k1].c;
                sc[k3].v = a[k1].v;

                k3++;
                k1++;
            } else if (b[k2].c < a[k1].c) {
                sc[k3].r = b[k2].r;
                sc[k3].c = b[k2].c;
                sc[k3].v = b[k2].v;

                k3++;
                k2++;
            }
        } else if (a[k1].r < b[k2].r) {
            sc[k3].r = a[k1].r;
            sc[k3].c = a[k1].c;
            sc[k3].v = a[k1].v;

            k1++;
            k3++;
        } else if (b[k2].r < a[k1].r) {
            sc[k3].r = b[k2].r;
            sc[k3].c = b[k2].c;
            sc[k3].v = b[k2].v;

            k3++;
            k2++;
        }
    }

    while (k1 < na) {
        sc[k3].r = a[k1].r;
        sc[k3].c = a[k1].c;
        sc[k3].v = a[k1].v;

        k3++;
        k1++;
    }

    while (k2 < nb) {
        sc[k3].r = b[k2].r;
        sc[k3].c = b[k2].c;
        sc[k3].v = b[k2].v;

        k3++;
        k2++;
    }

    printf("%d %d %d\n", k1, k2, k3);
    return k3;
}

