    temp->data = value;
    temp->prev = NULL;

    // Diagram logic
    temp->next = head;
    if (head != NULL) {
        head->prev = temp;
    }
    head = temp;
    return head;
}

void display(struct Node* head) {
    struct Node* ptr = head;
    printf("\nDoubly Linked List:\n");
    while (ptr != NULL) {
        printf("%d ", ptr->data);
        ptr = ptr->next;
    }
}

