def answer(l):
    q0=[]
    q1=[]
    q2=[]
    
    l.sort()
    sums = sum(l)
    
    for i in l:
        if (i % 3) == 0:
            q0.insert(0, i)
        if (i % 3) == 1:
            q1.insert(0, i)
        if (i % 3) == 2:
            q2.insert(0, i)
            
    if sums % 3 == 1:
        if len(q1):
            q1.pop()
        elif len(q2) >= 2:
            q2.pop()
            q2.pop()
        else:
            return 0
    elif sums % 3 == 2:
        if len(q2):
            q2.pop()
        elif len(q1) >=2:
            q1.pop()
            q1.pop()
        else:
            return 0
    
    q0.extend(q1)
    q0.extend(q2)
    
    if len(q0) <= 0:
        return 0
        
    q0.sort()
    q0.reverse()
    
    result = ''.join(str(x) for x in q0)
    
    return int(result)

public class Heap {

	static int N, heapSize;
	static int[] arr;

	static void init(int n) {
		N = n;
		arr = new int[N+1];
		heapSize = 0;
	}

	static void add(int n) {
		arr[++heapSize] = n;

		for (int i = heapSize; i > 1; i/=2) {
			if(arr[i] < arr[i/2]) {
				swap(i/2, i);
			}
			else break;
		}
	}
	static int remove(int[] arr) {
		if(heapSize == 0) return 0;

		int rm = arr[1];
		arr[1] = arr[heapSize];
		arr[heapSize--] = 0;

		for (int i = 1; i*2 <= heapSize;) {

			if(i*2+1 <= heapSize) {

				if(arr[i] < arr[i*2] && arr[i] < arr[i*2+1]) break;

				else if(arr[i*2] < arr[i*2+1]) {
					swap(i, i*2);
					i = i*2;
				}
				else {
					swap(i, i*2+1);
					i = i*2+1;
				}
			}
			else {
				if(arr[i] > arr[i*2]) {
					swap(i, i*2);
					i = i*2;
				}
				else
					break;
			}
		}

		return rm;
	}

	static void swap(int a, int b) {
		int temp = arr[a];
		arr[a] = arr[b];
		arr[b] = temp;
	}
}

import java.util.Random;

class Node {
    public double data;
    public Node next;

    public Node(double data) {
        this.data = data;
        next = null;
    }
}

// Time Complexity O(n)-> avg case and O(n^2)-> Worst Case
// constraints:- 0<=A[i]<1
public class BinSort {
    public static void binSort(Node[] b, double[] a) {
        for (int i = 0; i < a.length; i++) {
            int ins = (int) (a[i] * b.length);
            if (b[ins] == null) {
                b[ins] = new Node(a[i]);
            } else {
                boolean check = true;
                Node temp = b[ins];
                while (temp.next != null) {
                    if (a[i] > temp.next.data) {
                        temp = temp.next;
                    } else {
                        if (a[i] < temp.data)
                            break;
                        Node newNode = new Node(a[i]);
                        newNode.next = temp.next;
                        temp.next = newNode;
                        check = false;
                        break;
                    }
                }
                if (check) {
                    if (a[i] >= temp.data) {
                        Node newNode = new Node(a[i]);
                        temp.next = newNode;
                    } else {
                        double loc = temp.data;
                        temp.data = a[i];
                        Node newNode = new Node(loc);
                        newNode.next = temp.next;
                        temp.next = newNode;
                    }
                }
            }
        }
        int j = 0;
        for (int i = 0; i < b.length; i++) {
            while (b[i] != null) {
                a[j++] = b[i].data;
                b[i] = b[i].next;
            }
        }
    }

    public static void main(String[] args) {
        Node[] b = new Node[10];
        Random ran = new Random();
        int n = 100;
        double[] a = new double[n];
        for (int i = 0; i < n; i++) {
            a[i] = ran.nextDouble();
        }
        binSort(b, a);
        for (int i = 0; i < n; i++) {
            System.out.print(a[i] + " ");
        }
        System.out.println(" ");
    }
}

