sealed abstract class AbstractBinaryTreeMap<K, V, N extends AbstractBinaryMapNode<K, V, N>> extends AbstractMap<K, V>
        implements SearchTreeMap<K, V>, Serializable, Cloneable permits AvlTreeMap, RedBlackTreeMap {

    @Serial
    private static final long serialVersionUID = 0xCAFEBABE000C4A05L;

    protected final Comparator<? super K> comparator;
    protected transient Set<K> keySetView;
    protected transient Collection<V> valuesView;
    protected transient Set<Map.Entry<K, V>> entrySetView;
    protected transient N root;
    protected transient int size;
    protected transient long modCount;

    protected AbstractBinaryTreeMap() {
        this.comparator = null;
    }

    protected AbstractBinaryTreeMap(Comparator<? super K> comparator) {
        this.comparator = comparator;
    }

    protected static int computeRedLevel(int sz) {
        int level = 0;
        for (int m = sz - 1; m >= 0; m = (m / 2) - 1) level++;
        return level;
    }

    final void buildFromSorted(int size, Iterator<? extends Map.Entry<? extends K, ? extends V>> it) {
        this.size = size;
        root = buildFromSortedRecursive(0, 0, size - 1, computeRedLevel(size), it);
        this.modCount++;
    }

    final N buildFromSortedRecursive(int level, int lo, int hi, int redLevel, Iterator<? extends Map.Entry<? extends K, ? extends V>> it) {
        if (hi < lo) return null;
        int mid = lo + ((hi - lo) >>> 1);
        N left = null;
        if (lo < mid) {
            left = buildFromSortedRecursive(level + 1, lo, mid - 1, redLevel, it);
        }
        Map.Entry<? extends K, ? extends V> entry = it.next();
        N middle = createNode(entry.getKey(), entry.getValue());
        if (left != null) {
            middle.left = left;
            left.parent = middle;
        }

        if (mid < hi) {
            N right = buildFromSortedRecursive(level + 1, mid + 1, hi, redLevel, it);
            middle.right = right;
            right.parent = middle;
        }
        afterNodeBuiltFromSorted(middle, level, redLevel);
        return middle;
    }

    abstract void afterNodeBuiltFromSorted(N node, int level, int redLevel);

    @Override
    public Comparator<? super K> comparator() {
        return this.comparator;
    }

    @SuppressWarnings("unchecked")
    protected int compare(K k1, K k2) {
        if (comparator != null) {
            return comparator.compare(k1, k2);
        }
        return ((Comparable<? super K>) k1).compareTo(k2);
    }

    protected N nodeFinder(K key) {
        if (root == null) {
            compare(key, key);
            return null;
        }
        N current = root;
        while (current != null) {
            int cmp = compare(key, current.key);
            if (cmp == 0) return current;
            current = cmp < 0 ? current.left : current.right;
        }
        return null;
    }

    protected N leftMostNode() {
        N current = root;
        if (current == null) return null;
        while (current.left != null) current = current.left;
        return current;
    }

    protected N rightMostNode() {
        N current = root;
        if (current == null) return null;
        while (current.right != null) current = current.right;
        return current;
    }

    abstract N createNode(K key, V value);

    abstract void afterInsert(N node);

    @Override
    public V put(K key, V value) {
        if (root == null) {
            compare(key, key);
            root = createNode(key, value);
            size = 1;
            modCount++;
            afterInsert(root);
            return null;
        }

        N parent = null;
        N current = root;
        int cmp = 0;

        while (current != null) {
            parent = current;
            cmp = compare(key, current.key);
            if (cmp == 0) {
                V oldVal = current.value;
                current.value = value;
                return oldVal;
            } else if (cmp < 0) current = current.left;
            else current = current.right;
        }
        N newNode = createNode(key, value);
        newNode.parent = parent;

        if (cmp < 0) parent.left = newNode;
        else parent.right = newNode;

        size++;
        modCount++;
        afterInsert(newNode);
        return null;
    }

    @Override
    public void putAll(Map<? extends K, ? extends V> m) {
        if (size == 0 && m instanceof SortedMap && ((SortedMap<?, ?>) m).comparator() == comparator) {
            buildFromSorted(m.size(), m.entrySet().iterator());
            return;
        }
        for (Map.Entry<? extends K, ? extends V> e : m.entrySet()) {
            put(e.getKey(), e.getValue());
        }
    }

    @Override
    public V putIfAbsent(K key, V value) {
        if (root == null) {
            compare(key, key);
            root = createNode(key, value);
            size = 1;
            modCount++;
            afterInsert(root);
            return null;
        }

        N parent = null;
        N current = root;
        int cmp = 0;
        while (current != null) {
            parent = current;
            cmp = compare(key, current.key);
            if (cmp == 0) {
                V oldValue = current.value;
                if (oldValue == null) {
                    current.value = value;
                }
                return oldValue;
            } else if (cmp < 0) current = current.left;
            else current = current.right;
        }
        N newNode = createNode(key, value);
        newNode.parent = parent;
        if (cmp < 0) parent.left = newNode;
        else parent.right = newNode;
        size++;
        modCount++;
        afterInsert(newNode);
        return null;
    }

    @Override
    public V computeIfAbsent(K key, Function<? super K, ? extends V> mappingFunction) {
        Objects.requireNonNull(mappingFunction);
        if (root == null) {
            compare(key, key);
            V newValue;
            {
                long expectedModCount = modCount;
                newValue = mappingFunction.apply(key);
                if (modCount != expectedModCount) throw new ConcurrentModificationException();
            }
            if (newValue != null) {
                root = createNode(key, newValue);
                size = 1;
                modCount++;
                afterInsert(root);
            }
            return newValue;
        }

        N parent = null;
        N current = root;
        int cmp = 0;
        while (current != null) {
            parent = current;
            cmp = compare(key, current.key);
            if (cmp == 0) {
                V oldValue = current.value;
                if (oldValue != null) {
                    return oldValue;
                }
                V newValue;

                long expectedModCount = modCount;
                newValue = mappingFunction.apply(key);
                if (modCount != expectedModCount) throw new ConcurrentModificationException();

                if (newValue != null) {
                    current.value = newValue;
                }
                return newValue;
            } else if (cmp < 0) current = current.left;
            else current = current.right;
        }
        V newValue;
        {
            long expectedModCount = modCount;
            newValue = mappingFunction.apply(key);
            if (modCount != expectedModCount) throw new ConcurrentModificationException();
        }
        if (newValue != null) {
            N newNode = createNode(key, newValue);
            newNode.parent = parent;
            if (cmp < 0) parent.left = newNode;
            else parent.right = newNode;
            size++;
            modCount++;
            afterInsert(newNode);
        }
        return newValue;
    }

    @Override
    public V computeIfPresent(K key, BiFunction<? super K, ? super V, ? extends V> remappingFunction) {
        Objects.requireNonNull(remappingFunction);
        if (root == null) {
            compare(key, key);
            return null;
        }
        N current = root;
        while (current != null) {
            int cmp = compare(key, current.key);
            if (cmp == 0) {
                V oldValue = current.value;
                if (oldValue != null) {
                    V newValue;

                    long expectedModCount = modCount;
                    newValue = remappingFunction.apply(key, oldValue);
                    if (modCount != expectedModCount) throw new ConcurrentModificationException();

                    if (newValue != null) {
                        current.value = newValue;
                        return newValue;
                    } else {
                        remove(key);
                        return null;
                    }
                }
                return null;
            } else if (cmp < 0) {
                current = current.left;
            } else {
                current = current.right;
            }
        }
        return null;
    }

    @Override
    public V compute(K key, BiFunction<? super K, ? super V, ? extends V> remappingFunction) {
        Objects.requireNonNull(remappingFunction);
        if (root == null) {
            compare(key, key);
            V newValue;

            long expectedModCount = modCount;
            newValue = remappingFunction.apply(key, null);
            if (modCount != expectedModCount) throw new ConcurrentModificationException();

            if (newValue != null) {
                root = createNode(key, newValue);
                size = 1;
                modCount++;
                afterInsert(root);
            }
            return newValue;
        }

        N parent = null;
        N current = root;
        int cmp = 0;
        while (current != null) {
            parent = current;
            cmp = compare(key, current.key);
            if (cmp == 0) {
                V oldValue = current.value;
                V newValue;

                long expectedModCount = modCount;
                newValue = remappingFunction.apply(key, oldValue);
                if (modCount != expectedModCount) throw new ConcurrentModificationException();

                if (newValue != null) {
                    current.value = newValue;
                    return newValue;
                } else {
                    remove(key);
                    return null;
                }
            } else if (cmp < 0) current = current.left;
            else current = current.right;
        }
        V newValue;

        long expectedModCount = modCount;
        newValue = remappingFunction.apply(key, null);
        if (modCount != expectedModCount) throw new ConcurrentModificationException();

        if (newValue != null) {
            N newNode = createNode(key, newValue);
            newNode.parent = parent;
            if (cmp < 0) parent.left = newNode;
            else parent.right = newNode;
            size++;
            modCount++;
            afterInsert(newNode);
        }
        return newValue;
    }

    @Override
    public V merge(K key, V value, BiFunction<? super V, ? super V, ? extends V> remappingFunction) {
        Objects.requireNonNull(remappingFunction);
        Objects.requireNonNull(value);
        if (root == null) {
            compare(key, key);
            root = createNode(key, value);
            size = 1;
            modCount++;
            afterInsert(root);
            return value;
        }
        N parent = null;
        N current = root;
        V newValue;
        int cmp = 0;
        while (current != null) {
            parent = current;
            cmp = compare(key, current.key);
            if (cmp == 0) {
                V oldValue = current.value;
                long expectedModCount = modCount;
                newValue = (oldValue == null) ? value : remappingFunction.apply(oldValue, value);
                if (modCount != expectedModCount) throw new ConcurrentModificationException();

                if (newValue != null) {
                    current.value = newValue;
                } else {
                    remove(key);
                }
                return newValue;
            } else if (cmp < 0) current = current.left;
            else current = current.right;
        }
        N newNode = createNode(key, value);
        newNode.parent = parent;
        if (cmp < 0) parent.left = newNode;
        else parent.right = newNode;
        size++;
        modCount++;
        afterInsert(newNode);
        return value;
    }

