    protected N getCeilingNode(K key) {
        N p = root;
        while (p != null) {
            int cmp = compare(key, p.key);
            if (cmp < 0) {
                if (p.left != null) p = p.left;
                else return p;
            } else if (cmp > 0) {
                if (p.right != null) p = p.right;
                else return successor(p);
            } else return p;
        }
        return null;
    }

    protected N getFloorNode(K key) {
        N p = root;
        while (p != null) {
            int cmp = compare(key, p.key);
            if (cmp > 0) {
                if (p.right != null) p = p.right;
                else return p;
            } else if (cmp < 0) {
                if (p.left != null) p = p.left;
                else return predecessor(p);
            } else return p;
        }
        return null;
    }

    protected N getHigherNode(K key) {
        N p = root;
        while (p != null) {
            int cmp = compare(key, p.key);
            if (cmp < 0) {
                if (p.left != null) p = p.left;
                else return p;
            } else {
                if (p.right != null) p = p.right;
                else return successor(p);
            }
        }
        return null;
    }

    protected N getLowerNode(K key) {
        N p = root;
        while (p != null) {
            int cmp = compare(key, p.key);
            if (cmp > 0) {
                if (p.right != null) p = p.right;
                else return p;
            } else {
                if (p.left != null) p = p.left;
                else return predecessor(p);
            }
        }
        return null;
    }

