    }

    private final class ValueIterator extends MapIterator<V> {
        ValueIterator(N first) {
            super(first);
        }

        public V next() {
            return stepForward().value;
        }
    }

    final class TreeSubMap extends AbstractMap<K, V> implements NavigableMap<K, V>, Serializable {
        final K lo, hi;
        final boolean fromStart, toEnd;
        final boolean loInclusive, hiInclusive;
        final boolean descending;

        TreeSubMap(boolean fromStart, K lo, boolean loInclusive, boolean toEnd, K hi, boolean hiInclusive, boolean descending) {
            if (!fromStart && !toEnd) {
                if (compare(lo, hi) > 0) throw new IllegalArgumentException("fromKey > toKey");
            } else {
                if (!fromStart) compare(lo, lo);
                if (!toEnd) compare(hi, hi);
            }
            this.fromStart = fromStart;
            this.lo = lo;
            this.loInclusive = loInclusive;
            this.toEnd = toEnd;
            this.hi = hi;
            this.hiInclusive = hiInclusive;
            this.descending = descending;
        }

        boolean tooLow(Object key) {
            if (!fromStart) {
                @SuppressWarnings("unchecked")
                int c = compare((K) key, lo);
                return c < 0 || (c == 0 && !loInclusive);
            }
            return false;
        }

        boolean tooHigh(Object key) {
            if (!toEnd) {
                @SuppressWarnings("unchecked")
                int c = compare((K) key, hi);
                return c > 0 || (c == 0 && !hiInclusive);
            }
            return false;
        }

        boolean inClosedRange(Object key) {
            @SuppressWarnings("unchecked") K k = (K) key;
            return (fromStart || compare(k, lo) >= 0) && (toEnd || compare(k, hi) <= 0);
        }

        boolean inRange(Object key) {
            return !tooLow(key) && !tooHigh(key);
        }

        boolean outOfBounds(Object key, boolean inclusive) {
            if (!inClosedRange(key)) return true;
            @SuppressWarnings("unchecked") K k = (K) key;
            if (inclusive) {
                if (!fromStart && !loInclusive && compare(k, lo) == 0) return true;
                return !toEnd && !hiInclusive && compare(k, hi) == 0;
            }
            return false;
        }

        @Override
        public V put(K key, V value) {
            if (!inRange(key)) throw new IllegalArgumentException("key out of range");
            return AbstractBinaryTreeMap.this.put(key, value);
        }


        @Override
        public V merge(K key, V value, BiFunction<? super V, ? super V, ? extends V> rf) {
            if (!inRange(key)) throw new IllegalArgumentException("key out of range");
            return AbstractBinaryTreeMap.this.merge(key, value, rf);
        }

        @Override
        public V get(Object key) {
            if (!inRange(key)) return null;
            return AbstractBinaryTreeMap.this.get(key);
        }

        @Override
        public boolean containsKey(Object key) {
            return inRange(key) && AbstractBinaryTreeMap.this.containsKey(key);
        }

        @Override
        public V remove(Object key) {
            if (!inRange(key)) return null;
            return AbstractBinaryTreeMap.this.remove(key);
        }

        N subCeiling(K key) {
            if (tooLow(key)) return absLowest();
            N n = getCeilingNode(key);
            return (n == null || tooHigh(n.key)) ? null : n;
        }

        N subHigher(K key) {
            if (tooLow(key)) return absLowest();
            N n = getHigherNode(key);
            return (n == null || tooHigh(n.key)) ? null : n;
        }

        N subFloor(K key) {
            if (tooHigh(key)) return absHighest();
            N n = getFloorNode(key);
            return (n == null || tooLow(n.key)) ? null : n;
        }

        N subLower(K key) {
            if (tooHigh(key)) return absHighest();
            N n = getLowerNode(key);
            return (n == null || tooLow(n.key)) ? null : n;
        }

        @Override
        public Map.Entry<K, V> lowerEntry(K k) {
            N n = descending ? subHigher(k) : subLower(k);
            return n == null ? null : new AbstractMap.SimpleImmutableEntry<>(n.key, n.value);
        }

        @Override
        public K lowerKey(K k) {
            N n = descending ? subHigher(k) : subLower(k);
            return n == null ? null : n.key;
        }

        @Override
        public Map.Entry<K, V> floorEntry(K k) {
            N n = descending ? subCeiling(k) : subFloor(k);
            return n == null ? null : new AbstractMap.SimpleImmutableEntry<>(n.key, n.value);
        }

        @Override
        public K floorKey(K k) {
            N n = descending ? subCeiling(k) : subFloor(k);
            return n == null ? null : n.key;
        }

        @Override
        public Map.Entry<K, V> ceilingEntry(K k) {
            N n = descending ? subFloor(k) : subCeiling(k);
            return n == null ? null : new AbstractMap.SimpleImmutableEntry<>(n.key, n.value);
        }

        @Override
        public K ceilingKey(K k) {
            N n = descending ? subFloor(k) : subCeiling(k);
            return n == null ? null : n.key;
        }

        @Override
        public Map.Entry<K, V> higherEntry(K k) {
            N n = descending ? subLower(k) : subHigher(k);
            return n == null ? null : new AbstractMap.SimpleImmutableEntry<>(n.key, n.value);
        }

        @Override
        public K higherKey(K k) {
            N n = descending ? subLower(k) : subHigher(k);
            return n == null ? null : n.key;
        }

        @Override
        public Map.Entry<K, V> firstEntry() {
            N n = descending ? absHighest() : absLowest();
            return n == null ? null : new AbstractMap.SimpleImmutableEntry<>(n.key, n.value);
        }

        @Override
        public Map.Entry<K, V> lastEntry() {
            N n = descending ? absLowest() : absHighest();
            return n == null ? null : new AbstractMap.SimpleImmutableEntry<>(n.key, n.value);
        }

        @Override
        public Map.Entry<K, V> pollFirstEntry() {
            N n = descending ? absHighest() : absLowest();
            if (n == null) return null;
            Map.Entry<K, V> result = new AbstractMap.SimpleImmutableEntry<>(n.key, n.value);
            TreeSubMap.this.remove(n.key);
            return result;
        }

        @Override
        public Map.Entry<K, V> pollLastEntry() {
            N n = descending ? absLowest() : absHighest();
            if (n == null) return null;
            Map.Entry<K, V> result = new AbstractMap.SimpleImmutableEntry<>(n.key, n.value);
            TreeSubMap.this.remove(n.key);
            return result;
        }

        @Override
        public NavigableSet<K> navigableKeySet() {
            return new KeySetView<>(this);
        }

        @Override
        public NavigableSet<K> descendingKeySet() {
            return descendingMap().navigableKeySet();
        }

        @Override
        public Comparator<? super K> comparator() {
            if (descending) {
                return Collections.reverseOrder(AbstractBinaryTreeMap.this.comparator);
            }
            return AbstractBinaryTreeMap.this.comparator;
        }

        @Override
        public SortedMap<K, V> subMap(K k, K k1) {
            return subMap(k, true, k1, false);
        }

        @Override
        public SortedMap<K, V> headMap(K k) {
            return headMap(k, false);
        }

        @Override
        public SortedMap<K, V> tailMap(K k) {
            return tailMap(k, true);
        }

        @Override
        public NavigableMap<K, V> descendingMap() {
            return new TreeSubMap(fromStart, lo, loInclusive, toEnd, hi, hiInclusive, !descending);
        }

        private boolean endUnbounded() {
            return descending ? fromStart : toEnd;
        }

        private Map.Entry<K, V> iterationEnd() {
            return lastEntry();
        }

        private final class UntilValueIterator implements Iterator<V> {
            private final Iterator<Map.Entry<K, V>> it;
            private final K lastKey;
            private boolean done;

            UntilValueIterator(Iterator<Map.Entry<K, V>> it, K lastKey) {
                this.it = it;
                this.lastKey = lastKey;
            }

            @Override
            public boolean hasNext() {
                return !done && it.hasNext();
            }

            @Override
            public V next() {
                if (done) throw new NoSuchElementException();
                Map.Entry<K, V> e = it.next();
                if (e.getKey() == lastKey) done = true;
                return e.getValue();
            }

            @Override
            public void remove() {
                it.remove();
            }
        }

        private Iterator<Map.Entry<K, V>> baseEntryIterator() {
            return new Iterator<>() {
                N nextNode = descending ? absHighest() : absLowest();
                N lastReturned = null;
                long expectedModCount = modCount;

                @Override
                public boolean hasNext() {
                    if (modCount != expectedModCount) throw new ConcurrentModificationException();
                    return nextNode != null;
                }

                @Override
                public Map.Entry<K, V> next() {
                    if (modCount != expectedModCount) {
                        throw new ConcurrentModificationException();
                    }
                    if (nextNode == null) {
                        throw new NoSuchElementException();
                    }

                    lastReturned = nextNode;

                    if (descending) {
                        nextNode = predecessor(nextNode);
                    } else {
                        nextNode = successor(nextNode);
                    }

                    return lastReturned;
                }

                @Override
                public void remove() {
                    if (lastReturned == null) {
                        throw new IllegalStateException();
                    }
                    if (modCount != expectedModCount) {
                        throw new ConcurrentModificationException();
                    }

                    if (!descending && lastReturned.left != null && lastReturned.right != null) {
                        nextNode = lastReturned;
                    }
                    TreeSubMap.this.remove(lastReturned.key);
                    expectedModCount = modCount;
                    lastReturned = null;
                }
            };
        }

        private transient Collection<V> subMapValuesView;

        @Override
        public Collection<V> values() {
            Collection<V> vs = subMapValuesView;
            return (vs != null) ? vs : (subMapValuesView = new AbstractCollection<>() {
                @Override
                public Iterator<V> iterator() {
                    Map.Entry<K, V> end = iterationEnd();
                    if (end == null) return Collections.emptyIterator();
                    Iterator<Map.Entry<K, V>> it = baseEntryIterator();
                    return endUnbounded() ? new Iterator<>() {
                        @Override
                        public boolean hasNext() {
                            return it.hasNext();
                        }
                        @Override
                        public V next() {
                            return it.next().getValue();
                        }
                        @Override
                        public void remove() {
                            it.remove();
                        }
                    } : new UntilValueIterator(it, end.getKey());
                }
                @Override
                public int size() {
                    return TreeSubMap.this.size();
                }
                @Override
                public boolean contains(Object o) {
                    return TreeSubMap.this.containsValue(o);
                }
                @Override
                public void clear() {
                    TreeSubMap.this.clear();
                }
            });
        }

        public NavigableMap<K, V> subMap(K fromKey, boolean fromInclusive, K toKey, boolean toInclusive) {
            compare(fromKey, fromKey);
            compare(toKey, toKey);
            if (outOfBounds(fromKey, fromInclusive) || outOfBounds(toKey, toInclusive))
                throw new IllegalArgumentException("Requested bounds out of range");
            if (descending) {
                return new TreeSubMap(false, toKey, toInclusive, false, fromKey, fromInclusive, true);
            } else {
                return new TreeSubMap(false, fromKey, fromInclusive, false, toKey, toInclusive, false);
            }
        }

        @Override
        public NavigableMap<K, V> headMap(K toKey, boolean inclusive) {
            compare(toKey, toKey);
            if (outOfBounds(toKey, inclusive)) throw new IllegalArgumentException("Requested bounds out of range");
            if (descending) {
                return new TreeSubMap(false, toKey, inclusive, toEnd, hi, hiInclusive, true);
            } else {
                return new TreeSubMap(fromStart, lo, loInclusive, false, toKey, inclusive, false);
            }
        }

        @Override
        public NavigableMap<K, V> tailMap(K fromKey, boolean inclusive) {
            compare(fromKey, fromKey);
            if (outOfBounds(fromKey, inclusive)) throw new IllegalArgumentException("Requested bounds out of range");
            if (descending) {
                return new TreeSubMap(fromStart, lo, loInclusive, false, fromKey, inclusive, true);
            } else {
                return new TreeSubMap(false, fromKey, inclusive, toEnd, hi, hiInclusive, false);
            }
        }

        private final class UntilEntryIterator implements Iterator<Map.Entry<K, V>> {
            private final Iterator<Map.Entry<K, V>> it;
            private final K lastKey;
            private boolean done;

            UntilEntryIterator(Iterator<Map.Entry<K, V>> it, K lastKey) {
                this.it = it;
                this.lastKey = lastKey;
            }

            @Override
            public boolean hasNext() {
                return !done && it.hasNext();
            }

            @Override
            public Map.Entry<K, V> next() {
                if (done) throw new NoSuchElementException();
                Map.Entry<K, V> e = it.next();
                if (e.getKey() == lastKey) done = true;
                return e;
            }

            @Override
            public void remove() {
                it.remove();
            }
        }

        @Override
        public Set<Map.Entry<K, V>> entrySet() {
            return new AbstractSet<>() {

                @Override
                public Iterator<Map.Entry<K, V>> iterator() {
                    Map.Entry<K, V> end = iterationEnd();
                    if (end == null) return Collections.emptyIterator();
                    Iterator<Map.Entry<K, V>> it = baseEntryIterator();
                    return endUnbounded() ? it : new UntilEntryIterator(it, end.getKey());
                }

                @Override
                public int size() {
                    int count = 0;
                    for (Map.Entry<K, V> ignored : this) {
                        count++;
                    }
                    return count;
                }

                @Override
                @SuppressWarnings("unchecked")
                public boolean contains(Object o) {
                    if (!(o instanceof Map.Entry<?, ?> e)) return false;
                    K key = (K) e.getKey();
                    if (!inRange(key)) return false;

                    N node = nodeFinder(key);
                    return node != null && Objects.equals(node.value, e.getValue());
                }

                @Override
                @SuppressWarnings("unchecked")
                public boolean remove(Object o) {
                    if (!(o instanceof Map.Entry<?, ?> e)) return false;
                    K key = (K) e.getKey();
                    if (!inRange(key)) return false;

                    N node = nodeFinder(key);
                    if (node != null && Objects.equals(node.value, e.getValue())) {
                        TreeSubMap.this.remove(key); // SubMap remove correctly updates modCount!
                        return true;
                    }
                    return false;
                }
            };
        }

        @Override
        public NavigableSet<K> keySet() {
            return navigableKeySet();
        }

        public K firstKey() {
            N e = descending ? absHighest() : absLowest();
            if (e == null) throw new NoSuchElementException();
            return e.key;
        }

        @Override
        public K lastKey() {
            N e = descending ? absLowest() : absHighest();
            if (e == null) throw new NoSuchElementException();
            return e.key;
        }

        N absLowest() {
            N e = fromStart ? leftMostNode() : (loInclusive ? getCeilingNode(lo) : getHigherNode(lo));
            return (e == null || tooHigh(e.key)) ? null : e;
        }

        N absHighest() {
            N e = toEnd ? rightMostNode() : (hiInclusive ? getFloorNode(hi) : getLowerNode(hi));
            return (e == null || tooLow(e.key)) ? null : e;
        }
    }
}

