#include <algorithm>
#include <cstdio>
struct data
{
	int mn, pos; 
	inline bool operator <(const data &a) const
	{
		return mn < a.mn; 
	}
} seg[800005]; 
int arr[200005], app[200005], lazy[800005];
inline void paint(int u, int x)
{
	seg[u].mn += x; 
	lazy[u] += x; 
}
inline void push_down(int u)
{
	if (lazy[u])
	{
		paint(u << 1, lazy[u]);
		paint(u << 1 | 1, lazy[u]); 
		lazy[u] = 0; 
	}
}
void build(int u, int l, int r)
{
	if (l == r)
	{
		seg[u] = {app[l], l}; 
		return; 
	}
	int m = l + r >> 1; 
	build(u << 1, l, m); 
	build(u << 1 | 1, m + 1, r); 
	seg[u] = std::min(seg[u << 1], seg[u << 1 | 1]); 
}
void modify(int u, int l, int r, int L, int R, int x)
{
	if (L <= l && r <= R)
	{
		paint(u, x);
		return; 
	}
	push_down(u); 
	int m = l + r >> 1; 
	if (L <= m)
		modify(u << 1, l, m, L, R, x); 
	if (m < R)
		modify(u << 1 | 1, m + 1, r, L, R, x); 
	seg[u] = std::min(seg[u << 1], seg[u << 1 | 1]); 
}
data query(int u, int l, int r, int L, int R)
{
	if (L <= l && r <= R)
		return seg[u]; 
	push_down(u); 
	int m = l + r >> 1; 
	if (R <= m)
		return query(u << 1, l, m, L, R); 
	if (m < L)
		return query(u << 1 | 1, m + 1, r, L, R); 
	return std::min(query(u << 1, l, m, L, R), query(u << 1 | 1, m + 1, r, L, R)); 
}
int main()
{
	// freopen("CF17-ex-B.in", "r", stdin); 
	int n; 
	scanf("%d", &n); 
	for (int i = 0; i < n; i++)
	{
		scanf("%d", arr + i); 
		app[i] = arr[i]; 
	}
	std::sort(app, app + n); 
	int cnt = std::unique(app, app + n) - app;
	build(1, 0, cnt - 1); 
	long long ans = 0; 
	for (int i = 0; i < n; i++)
	{
		int pos = std::lower_bound(app, app + cnt, arr[i]) - app; 
		auto res = query(1, 0, cnt - 1, pos, cnt - 1); 
		ans += res.mn - arr[i]; 
		if (res.pos)
			modify(1, 0, cnt - 1, 0, res.pos - 1, 1); 
	}
	printf("%lld\n", ans);
	return 0; 
}

/* Insertion Sort implementation in C++
 * Author : Manvi Gupta
 * Input : array length and elements
 * Output : Sorted array elements
 */  

#include <iostream>
using namespace std;

int n;
void insertionSort(int A[])
{
	int key;
  for(int i=0;i<n;i++)
  {
    key = A[i];
    int j = i-1;
    while(j>=0 and key<A[j])
    {
      A[j+1] = A[j];
      j--;
    }
    A[j+1]=key;
    }
}

int main()
{
  std::cout << "Enter the array length: ";
  std::cin >> n;
  int A[n];
  std::cout << "Enter the array elements :" << '\n';
  for(int i=0; i<n; i++)
  cin >> A[i];
  insertionSort(A);
  std::cout << "Sorted Array :" << '\n';
  for(int i=0;i<n;i++)
  cout << A[i] << endl;
  return 0;
}

