		for(int i = 0; i < 3; i++) x[i] = st.x[i], y[i] = st.y[i];
		
		for(int ad = 0; ad < 5; ad++){
			nx[0] = x[0] + dx[ad], ny[0] = y[0] + dy[ad];
			if(y[0] < 14 && (nx[0] < 0 || nx[0] >= w || ny[0] < 0 || ny[0] >= h)) continue;
