				if(map[nx[1]][ny[1]] == '#') continue;
				
				for(int cd = 0; cd < 5; cd++){
					if(y[2] == 14 && cd < 4) continue;
					nx[2] = x[2] + dx[cd], ny[2] = y[2] + dy[cd];
					if(y[2] < 14 && (nx[2] < 0 || nx[2] >= w || ny[2] < 0 || ny[2] >= h)) continue;
					if(map[nx[2]][ny[2]] == '#') continue;
					
					
					if(nx[0] == nx[1] && ny[0] == ny[1] && ny[1] != 14) continue;
					if(nx[1] == nx[2] && ny[1] == ny[2] && ny[2] != 14) continue;
					if(nx[2] == nx[0] && ny[2] == ny[0] && ny[0] != 14) continue;
					
					if(nx[0] == x[1] && ny[0] == y[1] && x[0] == nx[1] && y[0] == ny[1] && ny[1] != 14) continue;
					if(nx[1] == x[2] && ny[1] == y[2] && x[1] == nx[2] && y[1] == ny[2] && ny[2] != 14) continue;
					if(nx[2] == x[0] && ny[2] == y[0] && x[2] == nx[0] && y[2] == ny[0] && ny[0] != 14) continue;
					
					if(dist[nx[0]][ny[0]][nx[1]][ny[1]][nx[2]][ny[2]] < inf) continue;
					dist[nx[0]][ny[0]][nx[1]][ny[1]][nx[2]][ny[2]] = dist[x[0]][y[0]][x[1]][y[1]][x[2]][y[2]] + 1;
					Q.push( state(nx[0], ny[0], nx[1], ny[1], nx[2], ny[2]) );
				}
			}
		}
	}
