            int64_t add = 1LL * (x + y) * a[m];
            res = min(res, Dfs(x, x + y, l, m) + Dfs(x + y, y, m, r) + add);
        }
        dp[key] = res;
        return res;
    };

    cout << Dfs(1, 1, 0, n - 1) + a[0] + a[n - 1] << "\n";
}

