class TreeNode{
    public:
    int val;
    TreeNode* left;
    TreeNode* right;

    TreeNode (int data){
        this->val=data;
        this->left=NULL;
        this->right=NULL;
    }
};


// Function to Build Tree 

TreeNode* Buildtree()
{
    int a;
    cin >> a;
    TreeNode *root = new TreeNode(a);
    queue<TreeNode*> q;
    q.push(root);
    while (!q.empty())
    {
        cin >> a;
        if (a != -1)
        {
            TreeNode *temp = new TreeNode(a);
            if (q.front()->left == NULL){
                q.front()->left = temp;
            }
            else
            {
                q.front()->right = temp;
                q.pop();
            }
            q.push(temp);
        }
        else
        {
            if (q.front()->left == NULL)
            {
                cin >> a;
                if (a == -1){
                    q.pop();
                }
                else{
                    TreeNode *temp1 = new TreeNode(a);
                    q.front()->right = temp1;
                    q.pop();
                    q.push(temp1);
                }
            }
            else{
                q.pop();
            }
        }
    }
    return root;
}


