void PrintVerticalOrder(TreeNode* root, int d, map<int, vector<int> > &m){
    if(root==NULL){
        return;
    }
    m[d].push_back(root->val);
    PrintVerticalOrder(root->left,d-1,m);
    PrintVerticalOrder(root->right,d+1,m);
}

