#include <stdio.h>

int n;

void bubble_sort(int v[]){
	int i,k,aux = 0;
	for(i = 0; i < n; i++){
		for(k = 0; k < n-1; k++){
			if(v[k] > v[k+1]){
				aux = v[k+1];
				v[k+1] = v[k];
				v[k] = aux;
			}
		}
	}

}


