	scanf("%d",&n);
	int v[n];

	for(j = 0; j < n; j++){
		scanf("%d",&v[j]);
	}
	bubble_sort(v);
	for(j = 0; j < n; j++){
		if(j != n-1){
			printf("%d ",v[j]);
		}
		
		else{
			printf("%d\n",v[j]);
		}
	}
	
	return 0;
}

