#define PB push_back
#define MP make_pair
using namespace std;

typedef long long ll;
typedef pair<ll, ll> pii;
typedef vector<ll> vi;
typedef deque<ll> di;
typedef deque<pii> dii;

const int MAX_N = 200001;
const ll MOD = 1000000007;

ll N, p;
ll l2[MAX_N], max_depth = 0;

vi tree[MAX_N];

class Children {
public:
  di children_cnts;
  dii one_zero;
  int second_length;

  Children():second_length(0) {
    this->children_cnts.resize(0);
    this->one_zero.resize(0);
  }

  int size() {
    return this->one_zero.size();
  }

  void firstMarge(Children* cld) {
    for (int i=0; i<cld->size(); i++) {
      this->one_zero[i].first  = (this->one_zero[i].first  * cld->one_zero[i].second) % MOD
                                + (this->one_zero[i].second * cld->one_zero[i].first) % MOD;
      this->one_zero[i].first %= MOD;
      this->one_zero[i].second = (this->one_zero[i].second * cld->one_zero[i].second) % MOD;
      this->children_cnts[i] += cld->children_cnts[i];
    }
    second_length = max(second_length, cld->size());
  }

  void lastMarge(pii ab) {
    for (int i=0; i<this->second_length; i++) {
      this->one_zero[i].second = (l2[this->children_cnts[i]] + MOD - this->one_zero[i].first) % MOD;
    }
    this->children_cnts.push_front(ab.first);
    this->one_zero.push_front(ab);
    second_length = 0;
  }
};

ll inv(ll x) {
  ll res = 1, n = MOD - 2;
  while (0 < n) {
    if (n & 1) {
      res = x * res % MOD;
    }
    x = x * x % MOD;
    n >>= 1;
  }
  return res;
}

void swap(Children** a, Children** b) {
  Children* tmp = *a; *a = *b; *b = tmp;
}

Children* dfs(ll x) {
  ll a = tree[x].size();
  Children* res = new Children();
  if (a == 0) return res;

  res = dfs(tree[x][0]);
  for (int i=1; i<tree[x].size(); i++) {
    Children* dfs_res = dfs(tree[x][i]);
    if (res->size() < dfs_res->size()) swap(&res, &dfs_res);
    res->firstMarge(dfs_res);
  }
  res->lastMarge(MP(a, (l2[a] + MOD - a) % MOD));
  return res;
}

void init() {
  cin >> N;
  for (int i=0; i<N; i++) {
    cin >> p;
    tree[p].PB(i + 1);
  }
  l2[0] = 1;
  for (int i=1; i<MAX_N; i++) {
    l2[i] = (l2[i-1] * 2) % MOD;
  }
}

ll solve() {
  ll ans = l2[N];
  Children* res = dfs(0);
  for (int i=0; i<res->size(); i++) {
    ans += res->one_zero[i].first * l2[N+1-res->children_cnts[i]] % MOD;
    ans %= MOD;
  }
  return ans;
}

int main() {
  init();
  cout << solve() << endl;
  return 0;
}

