'use strict';

import _ from '../utils';

export class Node {
  constructor(value, next = null) {
    this.value = value;
    this.next = next;
  }
}

export class List {
  constructor(root) {
    this.root = root;
    this.length = 1;
  }

  append(value) {
    let node = this.root;

    while (node.next !== null) {
      node = node.next;
    }

    this.length++;
    let newNode = new Node(value);
    node.next = newNode;

    return newNode;
  }

  delete(value, node = this.root) {
    if (node === this.root && node.value === value) {
      this.root = this.root.next;
      return;
    }

    while (node.next) {
      if (node.next.value === value) {
        node.next = node.next.next;
        this.length--;
      }
      node = node.next;
    }
  }

  // Cracking the Coding Interview challenges
  deleteDuplicates() {
    let node = this.root;

    do {
      this.delete(node.value, node.next);
      node = node.next;
    } while (node.next !== null)
  }

  last(n) {
    let target = this.length - n;

    let i = 0;
    let node = this.root;

    while (i < target && node.next !== null) {
      node = node.next;
      i++;
    }

    return node;
  }

  partition(x) {
    let less = [],
        greater = [];

    let node = this.root;

    while (node !== null) {
      if (node.value < x) {
        less.push(node.value);
      } else {
        greater.push(node.value);
      }

      node = node.next;
    }

    this.root = new Node(less[0]);
    less.slice(1).concat(greater).reduce((a, b) => {
      a.next = new Node(b);
      return a.next;
    }, this.root);
  }
}

