	if(ss==se){
		st[si].t=arr[ss];
		st[si].lazy=0;
		return;
	}
	ll mid=(ss+se)/2;
	build(ss,mid,2*si+1);
	build(mid+1,se,2*si+2);
	st[si].t=st[2*si+1].t+st[2*si+2].t;
}
