/**
 * Linear search algorithm.
 *
 * @param int a Search array
 * @param int find Data to search
 * @param int n Number of data in search array
 *
 * @return int Index of found data or -1
 */
int linear_search(int *a, int find, int n)
{
    for (int i = 0; i < n; i++) {
        if (find == *(a+i)) {
            return i;
        }
    }

    return -1;
}

int main()
{
    int n, find;

    printf("How many items? ");
    scanf("%d", &n);

    int *input = (int *) malloc(n * sizeof(int));

    printf("Enter numbers: ");
    for (int i = 0; i < n; i++) {
        scanf("%d", input + i);
    }

    printf("Find: ");
    scanf("%d", &find);

    int position = linear_search(input, find, n);

    if (position != -1) {
        printf("Data found at position %d", position);
    } else {
        printf("Data not found");
    }

    free(input);

    return 0;
}

#include <stdio.h>

int max(int a, int b) { return (a > b)? a : b; }
// Returns the maximum value that can be put in a knapsack of capacity W
int knapsack(int W, int wt[], int val[], int n)
{
   int i, w;
   int K[n+1][W+1];

   // Build table K[][] in bottom up manner
   for (i = 0; i <= n; i++)
   {
       for (w = 0; w <= W; w++)
       {
           if (i==0 || w==0)
               K[i][w] = 0;
           else if (wt[i-1] <= w)
                 K[i][w] = max(val[i-1] + K[i-1][w-wt[i-1]],  K[i-1][w]);
           else
                 K[i][w] = K[i-1][w];
       }
   }

   return K[n][W];
}

int main()
{
    int val[] = {60, 100, 120};
    int wt[] = {10, 20, 30};
    int  W = 50;
    int n = sizeof(val)/sizeof(val[0]);
    printf("\nValue = %d", knapsack(W, wt, val, n));
    return 0;
}

#include <stdio.h>
#define SIZE 5

void print_answer(int *answer,int size){
	static int count;
	int i;
	for(i=0;i<size;i++)
		printf("%d ",answer[i]);
	printf("\n");
	count++;
}

void create_candidate(int *answer,int k,int *candidate,int *candidate_size){
	int sp=0;
	int hash[SIZE]={};
	int i;
	for(i=0;i<k;i++)
		hash[answer[i]-1]=1;
	for(i=0;i<SIZE;i++)
		if(!hash[i])
			candidate[sp++]=i+1;
	*candidate_size=sp;
}

void backtrack(int *set,int size,int *answer,int k){
	if(k==size)
		print_answer(answer,size);
	else{
		int candidate[SIZE];
		int candidate_size;
		create_candidate(answer,k,candidate,&candidate_size);
		int i;
		for(i=0;i<candidate_size;i++){
			answer[k]=candidate[i];
			backtrack(set,size,answer,k+1);
		}
	}
}

int main(int argc, char const *argv[])
{
	int set[]={1,2,3,4,5};
	int size=sizeof(set)/sizeof(int);
	int answer[SIZE];
	backtrack(set,size,answer,0);
	return 0;
}

