  rep(i, n) {
    cin >> a[i];
  }

  int count = 1;
  bool uping = false;
  bool downing = false;
  repf(i, 1, n) {
    int diff = a[i] - a[i - 1];

    if(uping && diff < 0) {
      uping = false;
      count++;
      continue;
    }
    if(downing && diff > 0) {
      downing = false;
      count++;
      continue;
    }

    unless(uping || downing) {
      uping = diff > 0;
      downing = diff < 0;
    }
  }

  cout << count << endl;
}

