  REP(i, 1, N+1) cin >> A[i];

  T[0] = -1; T[N+1] = INF;
  A[0] = INF; A[N+1] = -1;
  
  vector<ll> pattern(N, 0LL);
  for(int i = 1; i <= N; i++) {
