    else if (T[i-1] == T[i] && A[i] > A[i+1] && T[i] >= A[i]) pattern[i-1] = 1LL;
    else if (T[i-1] == T[i] && A[i] == A[i+1]) pattern[i-1] = min(T[i], A[i]);
