def ceil(root, inp):     
    # Base Case 
        if root == None: 
            return -1
      
    # We found equal key 
        if root.data == inp : 
            return root.data  
      
    # If root's key is smaller, ceil must be in right subtree 
        if root.data < inp: 
            return ceil(root.right, inp) 
      
    # Else, either left subtre or root has the ceil value 
        val = ceil(root.left, inp) 
        return val if val >= inp else root.data  


