void selectionSort(int arr[], int s)
{
	int i, j, temp;

	for (i=0; i<s-1; ++i)
	{
		for (j=i+1; j<s; ++j)
		{
			if (arr[i] > arr[j])
			{
				temp = arr[i];
				arr[i] = arr[j];
				arr[j] = temp;
			}
		}
	}

	printf("\n After sorting...\n");
	for (i=0; i<s; ++i)
	{
		printf(" %d ", arr[i]);
	}
	printf("\n");
}


