Node* listSearch(int key){
    Node *cur=nil->next;
    while(cur!=nil && cur->key!=key){
        cur=cur->next;
    }
    return cur;
}
 
void deleteNode(Node *t){
    if(t==nil)return;
    t->prev->next=t->next;
    t->next->prev=t->prev;
    free(t);
}
 
void deleteFirst(){
    deleteNode(nil->next);
}
 
void deleteLast(){
    deleteNode(nil->prev);
}
 
void deleteKey(int key){
    deleteNode(listSearch(key));
