function sortMergeArray(left, right) {
  let sortedArr = []
  let i = 0
  let j = 0

  while (i < left.length && j < right.length) {
    if (left[i] < right[j]) {
      sortedArr.push(left[i])
      i++
    } else {
      sortedArr.push(right[j])
      j++
    }
  }

  while (i < left.length) {
    sortedArr.push(left[i])
    i++
  }
  while (j < right.length) {
    sortedArr.push(right[j])
    j++
  }
  console.log(sortedArr, 'sorted');

  return sortedArr
}

