    for(int i = 0; i < m; i++) {
      for(int j = 0; j < m; j++) {
        ov[i][j] = overlap(i, j);
      }
    }
    vector<vector<int>> memo(m, vector<int>(1<<m, -1));
    function<int(int,int)> rec = [&memo,&ov,m,&rec](int c, int cs) {
      if(cs==0) return 0;
      if(memo[c][cs] >= 0) return memo[c][cs];
      int ans = 0;
      for(int i = 0; i < m; i++) {
        const int ii = 1<<i;
        if(ii & cs) {
          ans = max(ans, ov[c][i] + rec(i, cs-ii));
        }
      }
      memo[c][cs] = ans;
      return ans;
    };
    int maxov = 0;
    for(int i = 0; i < m; i++) {
      maxov = max(maxov, rec(i, ((1<<m)-1)-(1<<i)));
    }
    int ans = -maxov;
    for(auto t : ts) {
      ans += t.length();
    }
    cout << ans << endl;
  }
  return 0;
}

