int selectionSort(int arr[], int n) {
    int i, j, minIndex, temp, steps = 0;
    for (i = 0; i < n - 1; i++) {
        minIndex = i;
        for (j = i + 1; j < n; j++) {
            steps++; // comparison
            if (arr[j] < arr[minIndex])
                minIndex = j;
        }
        if (minIndex != i) {
            temp = arr[i];
            arr[i] = arr[minIndex];
            arr[minIndex] = temp;
            steps++; // swap
        }
    }
    return steps;
}

