  }

  for(int i = 0; i < (int)graph.size(); i++){
    for(int j = 0; j < (int)graph[i].size(); j++){
      graph2[graph[i][j].first].push_back(make_pair(i, graph[i][j].second));
    }
  }

  used.clear();
