  for(int i = (int)graph.size()-1, same = 0; i >= 0; i--){
    if(!used[num[i]]){
      dfs2(graph2, scc, used, num[i], same);
      same++;
    }
  }
}

class union_find{
  vector<int> par, nume;
 public:

  union_find(){
  }

  void init(){
    for(int i = 0; i < (int)par.size(); i++){
      par[i] = i;
      nume[i] = 1;
    }
  }

  void resize(int x){
    par.resize(x);
    nume.resize(x);
    init();
  }

  int find(int x){
    return par[x] == x ? x : par[x] = find(par[x]);
  }

  void unite(int x, int y){
    x = find(x);
    y = find(y);

    if(x == y) return ;

    if(nume[x] > nume[y]) swap(x, y);

    par[x] = y;
    nume[y] += nume[x];
  }

  bool same(int x, int y){
    return find(x) == find(y);
  }

};


