/**Problem statement:
 Given the array nums consisting of 2n elements in the form [x1,x2,...,xn,y1,y2,...,yn].
 Return the array in the form [x1,y1,x2,y2,...,xn,yn].

 Example 1:
 Input: nums = [2,5,1,3,4,7], n = 3
 Output: [2,3,5,4,1,7]
 Explanation: Since x1=2, x2=5, x3=1, y1=3, y2=4, y3=7 then the answer is [2,3,5,4,1,7].

 Example 2:
 Input: nums = [1,2,3,4,4,3,2,1], n = 4
 Output: [1,4,2,3,3,2,4,1]
 Example 3:
 Input: nums = [1,1,2,2], n = 2
 Output: [1,2,1,2]
 Constraints:

 1 <= n <= 500
 nums.length == 2n
 1 <= nums[i] <= 10^3
 Leetcode link: https://leetcode.com/problems/shuffle-the-array/description/
 **/
public class ShuffleTheArray {
    public int[] shuffle(int[] nums, int n) {
        int[] result = new int[nums.length];
        int i = 0;
        int j = n;
        int p1 = 0;
        while (j < nums.length) {
            result[p1] = nums[i];
            p1++;
            i++;
            result[p1] = nums[j];
            p1++;
            j++;
        }
        return result;
    }
}

/* Implementation of LCS problem using Dynamic Programming*/
#include <bits/stdc++.h>

using namespace std;

void lcs(string X, string Y){
  int m = X.length();
  int n = Y.length();
  int L[m+1][n+1];
  for (int i=0; i<=m; i++){
    for (int j=0; j<=n; j++){
      if (i == 0 || j == 0)
        L[i][j] = 0;
      else if (X[i-1] == Y[j-1])
        L[i][j] = L[i-1][j-1] + 1;
      else
        L[i][j] = max(L[i-1][j], L[i][j-1]);
    }
  }
  int index = L[m][n];
  char lcs[index+1];
  lcs[index] = ' ';
  int i = m, j = n;
  while (i > 0 && j > 0){
    if (X[i-1] == Y[j-1]){
      lcs[index-1] = X[i-1];
      i--;
      j--;
      index--;
    }
    else if (L[i-1][j] > L[i][j-1])
    i--;
    else
    j--;
  }
  //output
  cout << "LCS of " << X << " and " << Y << " is " << lcs;
}

int main(){
  string a,b;
  //input two strings
  cin>>a;
  cin>>b;
  lcs(a,b);
  return 0;
}

