		case 'S':
			l[i] = di[0];
			r[i] = di[1];
			break;
		case 'W':
			l[i] = di[1];
			r[i] = di[2];
			break;
		case 'N':
			l[i] = di[2];
			r[i] = di[3];
			break;
		default:
			assert(false);
		}
		r[i]++;
	}
