        if (i > 0) pref[i] += pref[i - 1];
    }
    constexpr int kMod = 1'000'000'000 + 7;
    vector<int> dp(n + 1, 0);
    dp[0] = 1;
    for (int i = 0; i < n; ++i) {
        if (sh[i] == -1) {
            if (s[i] == '0') {
                for (int j = n; j > 0; --j) dp[j] = dp[j - 1];
                dp[0] = 0;
            }
        } else {
            vector<int> nxt(n + 1, 0);
            for (int j = 0; j <= n; ++j) {
                if (dp[j] == 0) continue;
                int cnt = pref[sh[i]] - j;
                assert(cnt >= 0);
                if (cnt > 0) (nxt[j + 1] += dp[j]) %= kMod;
                if (sh[i] - i + 1 - cnt > 0) (nxt[j] += dp[j]) %= kMod;
            }
            dp = nxt;
        }
    }
    cout << dp[pref[n - 1]] << "\n";
}

