    PointType type;
    EndPoint() {}
    EndPoint(Point p, size_t s, PointType t): p(p), seg(s), type(t) {}
    bool operator<(const EndPoint &rhs) const {
        return imag(p)!=imag(rhs.p)? imag(p)<imag(rhs.p) : type<rhs.type;
    }
};

size_t num_mintersect(vector<LineSeg> g) {
    size_t V=g.size();

    vector<EndPoint> h;
    for (size_t i=0; i<V; ++i) {
        if (imag(g[i].first) == imag(g[i].second)) {
            if (real(g[i].first) > real(g[i].second))
                swap(g[i].first, g[i].second);
        } else if (imag(g[i].first) > imag(g[i].second)) {
            swap(g[i].first, g[i].second);
        }

        if (imag(g[i].first) == imag(g[i].second)) {
            h.push_back(EndPoint(g[i].first, i, LEFT));
            h.push_back(EndPoint(g[i].second, i, RIGHT));
        } else {
            h.push_back(EndPoint(g[i].first, i, BOTTOM));
            h.push_back(EndPoint(g[i].second, i, TOP));
        }
    }
    sort(h.begin(), h.end());

    set<double> vlines;
    vlines.insert(INF);

    size_t count=0;
    for (size_t i=0; i<(V<<1); ++i) {
        if (h[i].type == TOP) {
            vlines.erase(real(h[i].p));
        } else if (h[i].type == BOTTOM) {
            vlines.insert(real(h[i].p));
        } else if (h[i].type == LEFT) {
            set<double>::iterator lb=lower_bound(
                vlines.begin(), vlines.end(), real(g[h[i].seg].first)
            );
            set<double>::iterator ub=upper_bound(
                vlines.begin(), vlines.end(), real(g[h[i].seg].second)
            );
            count += distance(lb, ub);
        }
    }

    return count;
}

int main() {
    size_t n;
    scanf("%zu", &n);

    vector<LineSeg> g(n);
    for (size_t i=0; i<n; ++i) {
        double x, y;
        scanf("%lf %lf", &x, &y);
        Point p1(x, y);

        scanf("%lf %lf", &x, &y);
        Point p2(x, y);

        g[i] = LineSeg(p1, p2);
    }

    printf("%zu\n", num_mintersect(g));
    return 0;
}

