#include <algorithm>
#include <cassert>
#include <cstring>
#include <iostream>

using namespace std;

#define FOR(i, a, b) for (int i = (a); i < (b); ++i)
#define REP(i, n) FOR(i, 0, n)
#define TRACE(x) cout << #x << " = " << x << endl
#define _ << " _ " <<

typedef long long llint;

const int MAX = 16;

int R[MAX][MAX];
int f[5][MAX][1<<MAX];
int bio[5][MAX][1<<MAX];
int cookie, n;

int solve(int h, int w, int s) {
  if (bio[h][w][s] == cookie) return f[h][w][s];
  bio[h][w][s] = cookie;

  int cnt = 0;
  REP(i, n) 
    if (s&(1<<i)) cnt++;
  if (cnt == 1) return f[h][w][s] = (s>>w) & 1;

  int nh = 0;
  while (cnt > 1) nh++, cnt = (cnt + 1) / 2;
  if (nh > h) return f[h][w][s] = 0;

  f[h][w][s] = 0;
  for (int s1 = s; s1 > 0; s1 = s & (s1 - 1))
    if ((s1 & s) == s1) {
      if (!(s1 & (1<<w))) continue;
      if (s1 == s) continue;

      int s2 = s ^ s1;

      REP(i, n)
        if (s2 & (1<<i))
          if (R[w][i]) f[h][w][s] += solve(h-1, w, s1) * solve(h-1, i, s2);
    }
  return f[h][w][s];
}

int main(void) {
  int m;
  while (scanf("%d %d", &n, &m) == 2) {
    if (n == 0 && m == 0) break;

    --m;
    REP(i, n) REP(j, n) scanf("%d", &R[i][j]);

    cookie++;
    int h = 0, tmp = n;
    while (tmp > 1) tmp = (tmp + 1) / 2, h++;
    printf("%d\n", solve(h, m, (1<<n) - 1));
  }
  
  return 0;
}

