int partition(int a[],int l,int h)
{
	int pivot=a[h];
	int i,small=l-1;
	for(i=l;i<=h-1;i++)
	{
		if(a[i]<=pivot)
		{
			small++;
			swap(&a[small],&a[i]);
		}
	}
	small++;
	swap(&a[small],&a[h]);
	return(small);
}
void quicksort(int a[],int l,int h)
{
	if(l<h)
	{
		int p=partition(a,l,h);
		quicksort(a,l,p-1);
		quicksort(a,p+1,h);
		
	}
}

