bool check(vector<int> &dist, int mx, int target) {
    if (mx < abs(target)) return false;
    if (mx == abs(target)) return true;
    
    int range = mx * 2 + 1;
    vector<bool> prev(range);
    prev[mx] = true;
    for (int i = 0; i < dist.size(); i++) {
        vector<bool> pos(range);
        for (int j = 0; j < range; j++) {
            if (prev[j]) {
                pos[j - dist[i]] = true;
                pos[j + dist[i]] = true;
            }
        }
        prev = pos;
    }
    if (prev[target + mx]) return true;
    else return false;
}

