bool shell_sort(int value[], int n) {
    for (int gap = n / 2; gap > 0; gap /= 2) {
        for (int i = gap; i < n; i++) {
            int temp = value[i];
            int j;
            for (j = i; j >= gap && value[j - gap] > temp; j -= gap) {
                value[j] = value[j - gap];
            }
            value[j] = temp;
        }
    }
}

