function gcd(a, b) {
	while (a !== b) {
		if (a < b) {
			var tmp = a;
			a = b;
			b = tmp;
		}
		if (a % b === 0) return b;
		a -= b;
	}
	return a;
}

function lcm(a, b) {
	var g = gcd(a, b);
	return g * (a / g) * (b / g);
}

// Given a binary tree, count the number of nodes in the tree.

// Include Insert node Function
// Include Inorder Traversal Function


#include <stdio.h>
#include <stdlib.h>

struct Node {
  int data;
  struct Node *left;
  struct Node *right;
};
typedef struct Node NODE;

NODE *getnode(int x) {
  NODE *newnode = (NODE*)malloc(sizeof(NODE));
  newnode->data = x;
  newnode->left = newnode->right = NULL;
  return newnode;
}

// Function to insert in BST, return the Node
NODE *Insert(NODE *new, int x) {
  if(new == NULL) {  // Empty tree
    new = getnode(x);
    return new;
  }
  else if(x <= new->data) {
    new->left = Insert(new->left, x);
  }
  else if(x >= new->data) {
    new->right = Insert(new->right, x);
  }
  return new;
}
// Function to count the Number of nodes in a tree
int count(NODE *temp) {
  int c = 1;
  if(temp == NULL) {
    return 0;
  }
  else {
    c = c + count(temp->left);
    c = c + count(temp->right);
  }
	return c;
}


// Inorder Traversal of a tree
void inorder_display(NODE *temp) {
  if(temp == NULL) {
    return;
  }
  else {
    inorder_display(temp->left);
    printf(" %d ", temp->data);
    inorder_display(temp->right);
  }
  return;
}


