#define N 10000
int prime[N] = {0, 0, 1, 1};

void primes()
{
    for (int i = 2; i < N; i++)
        prime[i] = 1;
    for (int i = 2; i < N; i++)
    {
        if (prime[i])
            for (int j = i; j < N - i; j += i)
                prime[j + i] = 0;
    }
}

