  var primeCounts = new Int32Array(50001);

  for(var i = 1; i < 5035; i++){
    for(var k = 1; k <= i; k++){
      var sum = primeNumbers[i] + primeNumbers[k];
      if(sum > 50000)
        break;
        primeCounts[sum]++;
    }
  }

  var i = 0;
  while(c = +input[i++]){
    console.log(c%2?0:primeCounts[c]);
  }
  
}
   
function calcPrimeNumbers(){
  var max = 50021;
  var primeNumbers = new Int8Array(max + 1);
   
  // 除外
  primeNumbers[0] = primeNumbers[1] = 1;
  for(var i = 2, maxI = ~~Math.sqrt(max); i <= maxI; i++){
    if(primeNumbers[i]){
      continue;
    }
       
    for(var j = (i<<1); j <= max; j+=i){
      primeNumbers[j] = 1;
    }
  }
   
  var primeNums = new Int32Array(5134 + 1);
  var c = 0;
  for(var i = 1; i <= max; i++){
    if(!primeNumbers[i]){
      primeNums[++c] = i;
    }
  }
     
  return primeNums;
}

