int p;

ll mpow(ll x, ll n) { ll y = 1; for (; n > 0; n /= 2) { y = n % 2 ? y * x % p : y; x = x * x % p; } return y; }

struct Combination {
    vector<ll> fact, ifact;
    Combination(int n) : fact(n + 1), ifact(n + 1) {
        fact[0] = 1; for (int i = 0; i < n; ++i)
            fact[i + 1] = fact[i] * (i + 1) % p;
        for (int i = 0; i <= n; ++i)
            ifact[i] = mpow(fact[i], p - 2);
    }
    ll operator ()(int n, int k) { return /*k < 0 || k > n ? 0 :*/ fact[n] * ifact[n - k] * ifact[k] % p; }
};

vector<int> a;
vector<ll> b;

int main() {
    cin >> p;
    a.resize(p);
    rep(i, p) cin >> a[i];

    Combination C(3072);

    b.resize(p);
    rep(i, 0, p) {
        if (a[i]) {
            b[0] += 1 + ((p - 1) % 2 ? 1 : -1) * mpow(i, p - 1) + p;
        }
    }

    rep(j, 1, p) {
        rep(i, 0, p) {
            if (a[i]) {
                b[j] += ((p - 1 - j) % 2 ? 1 : -1) * C(p - 1, j) * mpow(i, p - 1 - j) + p * p;
