#include <stdio.h>
#include <stdlib.h>

struct CircularQueue {
    int size;
    int front;
    int rear;
    int *arr;
};

struct CircularQueue* createQueue(int size) {
    struct CircularQueue* queue = (struct CircularQueue*)malloc(sizeof(struct CircularQueue));
    queue->size = size;
    queue->front = queue->rear = -1;
    queue->arr = (int*)malloc(size * sizeof(int));
    return queue;
}

int isEmpty(struct CircularQueue* q) {
    return q->front == -1;
}

int isFull(struct CircularQueue* q) {
    return (q->rear + 1) % q->size == q->front;
}

void enqueue(struct CircularQueue* q, int val) {
    if (isFull(q)) {
        printf("Queue is full!\n");
    } else {
        if (q->front == -1) q->front = 0;  // First element
        q->rear = (q->rear + 1) % q->size;
        q->arr[q->rear] = val;
        printf("Enqueued: %d\n", val);
    }
}

int dequeue(struct CircularQueue* q) {
    if (isEmpty(q)) {
        printf("Queue is empty!\n");
        return -1;
    } else {
        int dequeuedValue = q->arr[q->front];
        if (q->front == q->rear) {
            // Reset to empty queue
            q->front = q->rear = -1;
        } else {
            q->front = (q->front + 1) % q->size;
        }
        return dequeuedValue;
    }
}

void traverse(struct CircularQueue* q) {
    if (isEmpty(q)) {
        printf("Queue is empty!\n");
    } else {
        printf("Queue elements: ");
        int i = q->front;
        do {
            printf("%d ", q->arr[i]);
            i = (i + 1) % q->size;
        } while (i != (q->rear + 1) % q->size);
        printf("\n");
    }
}

void freeQueue(struct CircularQueue* q) {
    free(q->arr);
    free(q);
}

int main() {
    struct CircularQueue* q = createQueue(5);

    enqueue(q, 10);
    enqueue(q, 20);
    enqueue(q, 30);
    enqueue(q, 40);

    traverse(q);

    printf("Dequeued: %d\n", dequeue(q));
    printf("Dequeued: %d\n", dequeue(q));

    traverse(q);

    enqueue(q, 50);
    enqueue(q, 60);

    traverse(q);

    enqueue(q, 70); 
    enqueue(q, 80); // Queue is full

    traverse(q);

    freeQueue(q);

    return 0;
}

package com.practice.hashmapproblems;
import java.util.*;
/**Problem statement:
 Given an array nums of size n, return the majority element.

 The majority element is the element that appears more than ⌊n / 2⌋ times. You may assume that the majority element always exists in the array.

 Example 1:

 Input: nums = [3,2,3]
 Output: 3
 Example 2:

 Input: nums = [2,2,1,1,1,2,2]
 Output: 2

 Constraints:
 n == nums.length
 1 <= n <= 5 * 104
 -109 <= nums[i] <= 109


 Leetcode link: https://leetcode.com/problems/majority-element/description/

 **Special note: This problem can be solved more efficiently using the Moore's Voting algorithm
 **/
public class MajorityElement {
    public int majorityElement(int[] nums) {
        int maxCount = Integer.MIN_VALUE;
        Map < Integer, Integer > map = new HashMap < > ();
        int result = 0;

        for (int i: nums) {
            if (!map.containsKey(i)) {
                map.put(i, 1);
                if (map.get(i) > maxCount) {
                    maxCount = map.get(i);
                    result = i;
                }
            } else {
                int tempCount = map.get(i) + 1;
                map.put(i, tempCount);

                if (tempCount > maxCount) {
                    maxCount = tempCount;
                    result = i;
                }
            }
        }
        return result;
    }
}

package Recursion_By_Anuj_bhaiya;

import java.util.Arrays;

public class NQueens {
    public static void main(String[] args) {
        int n = 4;
        boolean[][] board = {
                {false, false, false, false},
                {false, false, false, false},
                {false, false, false, false},
                {false, false, false, false}
        };

        System.out.println(nQueens(board, 0));
        System.out.println(Arrays.deepToString(board));
    }

    static int nQueens(boolean[][] board, int row) {
        if (row == board.length) {
            display(board);
            return 1;
        }
        int count = 0;
        for (int col = 0; col < board.length; col++) {
            if (isSafe(board, row, col)) {
                board[row][col] = true;
                count += nQueens(board, row + 1);
                board[row][col] = false;

            }
        }
        return count;
    }

    private static void display(boolean[][] board) {
        for (boolean[] row : board) {
            for (boolean element : row) {
                if (element) System.out.print("Q  ");
                else System.out.print("X  ");
            }
            System.out.println();
        }
        System.out.println();
    }

    static boolean isSafe(boolean[][] board, int row, int col) {

        for (int i = 0; i < row; i++) {
            if (board[i][col])
                return false;
        }
        int maxLeft = Math.min(row, col);
        for (int i = 1; i <= maxLeft; i++) {
            if (board[row - i][col - i])
                return false;
        }

        int maxRight = Math.min(row, board.length - col - 1);
        for (int i = 1; i <= maxRight; i++) {
            if (board[row - i][col + i])
                return false;
        }
        return true;
    }
}

