using namespace std;

class Node{
	public:
		Node* left;
		Node* right;
		int data;
		Node(int x){
			data = x;
			left = NULL;
			right = NULL;
		}
};

class Solution{
	public:
  		Node* insert(Node* root, int data) {
            if(root == NULL) {
                return new Node(data);
            } else {
                Node* cur;
                if(data <= root->data) {
                    cur = insert(root->left, data);
                    root->left = cur;
                } else {
                    cur = insert(root->right, data);
                    root->right = cur;
               }

               return root;
           }
        }

		Node* flatten(Node* A) {
		    if(!A)return NULL;

		    // Take the left and right subtree
		    Node* tempr = A->right;
	        Node* templ = A->left;

	        // Recursively Flatten them
	        flatten(templ);
	        flatten(tempr);

	        // If left subtree exists, place it as the right subtree and make the right subtree
	        // as the child of this new right subtree
	        if(templ){
	            A->right = templ;
	            Node* x = templ;
	            // Go to the end of the right subtree (which was earlier left subtree)
	            while(x->right){
	                x = x->right;
	            }
	            // Place the earlier right subtree as the right subtree of the current right subtree
	            x->right = tempr;

	            // Make the new left subtree as NULL
	            templ->left = NULL;
	        }

	       	// Nullify the left subtree.
	       	A->left = NULL;

	       	// Return the tree.
	        return A;
		}

		void inOrder(Node* tree){
			if(!tree) return;

			inOrder(tree->left);
			cout << tree->data << " " ;
			inOrder(tree->right);
		}
};

