typedef int ElementType;

ElementType *ReadInput(int N);
void solve(ElementType A[], ElementType ansArr[], int N);
void PrintArr(ElementType A[], int N);

void PercDown(ElementType A[], int p, int N);

int Check_Insertion_Sort(ElementType A[], ElementType ansArr[], int N);
void Heap_Sort(ElementType A[], int N);

int main()
{
    int N;
    ElementType *arr, *ansArr;
    scanf("%d", &N);
    arr = ReadInput(N);
    ansArr = ReadInput(N);
    solve(arr, ansArr, N);
    free(arr);
    free(ansArr);

    return 0;
}

ElementType *ReadInput(int N)
{
    ElementType *arr;
    int i;
    arr = (ElementType *)malloc(sizeof(ElementType) * N);
    for (i = 0 ; i < N; ++i)
        scanf("%d", &arr[i]);
    return arr;
}

void PrintArr(ElementType A[], int N)
{
    int i;
    for ( i = 0; i < N - 1; ++i)
        printf("%d ", A[i]);
    printf("%d", A[i]);
}

void solve(ElementType A[], ElementType ansArr[], int N)
{
    if (Check_Insertion_Sort(A, ansArr, N)) {   // 判断是否为插入排序
        printf("Insertion Sort\n");
        PrintArr(ansArr, N);
    }
    else {  // 此时一定是堆排序
        Heap_Sort(ansArr, N);
        printf("Heap Sort\n");
        PrintArr(ansArr, N);
    }
}

void PercDown(ElementType A[], int p, int N)
{
    int Parent, Child;
    ElementType X;

    X = A[p];
    for (Parent = p; (Parent * 2 + 1) < N; Parent = Child) {
        Child = Parent * 2 + 1;
        if ((Child != N - 1) && (A[Child] < A[Child + 1]))
            ++Child;
        if (X >= A[Child]) break;
        else
            A[Parent] = A[Child];
    }
    A[Parent] = X;
}

int Check_Insertion_Sort(ElementType A[], ElementType ansArr[], int N)
{
    int i, pos, flag;
    ElementType tmp;

    flag = 1;
    for (i = 0; i < N - 1; ++i) {   // 找到第一个非有序位置
        if (ansArr[i] > ansArr[i + 1]) {
            pos = i + 1;
            break;
        }
    }
    for (i = pos; i < N; ++i) {     // 判断非有序部分是否和输入数据对应位置一样
        if (A[i] != ansArr[i]) {
            flag = 0;
            break;
        }
    }
    if (flag) { // 如果是插入排序，进行下一次插入排序操作
        tmp = ansArr[pos];
        for (; pos > 0 && tmp < ansArr[pos - 1]; --pos)
            ansArr[pos] = ansArr[pos - 1];
        ansArr[pos] = tmp;
    }
    return flag;
}

void Heap_Sort(ElementType A[], int N)
{
    ElementType Tmp;
    int i;

    for (i = N - 1; i > 0 && A[i] >= A[0] ; --i) ;
    if (i != 0) {
        Tmp = A[0];
        A[0] = A[i];
        A[i] = Tmp;
        PercDown(A, 0, i);
    }
}

// 參考 Fundamentals of data structures in c 2nd edition 第 177 頁
#include <stdio.h>
#include <stdlib.h>
#define MAX_SIZE 24

enum boolean { FALSE, TRUE };
typedef enum boolean bool;

struct node {
    int data;
    struct node* next;
};
typedef struct node* nodePointer;

int main() {
    short int out[MAX_SIZE];
    nodePointer seq[MAX_SIZE];  // 建立MAX_SIZE個陣列 (linked-list 堆疊)
    nodePointer x, y, top;
    int i, j, n;

    printf("Enter the size (<=%d)", MAX_SIZE);
    scanf("%d", &n);
    for (i = 0; i < n; i++) {
        // initialize seq and out
        out[i] = TRUE;  // 輸出時標記有沒有輸出過(可輸出標記為 TRUE)
        seq[i] = NULL;  // 初始化為空的 (linked-list 堆疊)
    }

    // phase 1: Input the equivalence pairs:
    do {
        printf("Enter a pair of number (-1 -1 to quit): ");
        scanf("%d %d", &i, &j);

        x = malloc(sizeof(*x));
        x->data = j;
        x->next = seq[i];
        seq[i] = x;

        x = malloc(sizeof(*x));
        x->data = i;
        x->next = seq[j];
        seq[j] = x;
    } while (i >= 0);
    /*
        seq[] 存放的樣的如下
        比如輸入 0 1
        [0] -> 1 -> NULL
        [1] -> 0 -> NULL
        [2] -> NULL
        [3] -> NULL
        ...

        再輸入 1 3
        [0] -> 3 -> 1 -> NULL
        [1] -> 0 -> NULL
        [2] -> NULL
        [3] -> 1 -> NULL
        ...
    */

    // phase 2: Output the equivalence classes:
    for (i = 0; i < n; i++) {
        if (out[i]) {  // 如果可印出(輸出)
            printf("\nNew class:%5d", i);
            out[i] = FALSE;  // 因為已印出，不可再輸出所以標記為 FALSE
            x = seq[i];
            top = NULL;  // 初始化堆疊
            for (;;) {
                // 再 x 能走的情況盡可能往右走
                while (x) {
                    j = x->data;
                    if (out[j]) {
                        printf("%5d", j);
                        out[j] = FALSE;
                        y = x->next;    // (1)
                        x->next = top;  // (2)
                        top = x;        // (3)
                        x = y;          // (4)
                /*
                    ## 注意 x->next 表示不同概念
                    ## x->next 在等號左側是 (b)
                    ## x->next 在等號右側是 (f)

                        x  (e)        x->next (f)
                    [ data (a)]      [data2 (c)]
                    [ next (b)] ->   [next2 (d)]

                    (1) 暫存 x->next (f)的位置
                    (2) 更動 (b) 的位置 (也就是為何 (1) 要暫存)
                    (3) top = x (e)
                    (4) x = y 其實也就是 (f)

                    (1)(4) 是為了讓 x 能繼續往下
                    (2)(3) 是為了形成 top 串鏈堆疊

                    也就是說在以印出的情況下
                    x 會往繼續往串列下方走 i.e. x 會從指向 (e) 被更動成 (f)
                    而 x 走過的地方的 next 值 (b) 部份 會被更動成 top 值
                    目的是為了形成 top 鏈
                    top 是為了提供其他可走訪的 node 所組成的 linked list

                    *****************************************************************
                    *  top 本身就是一個 linked list stack 只是他是用現有的 node 串起來 *
                    *****************************************************************

                    如果不用現有的空間另外開一個堆疊來實作也是可
                    (浪費記憶體)
                    課本提供的版本過於精簡，實在令人難懂，助教最愛出這種
                    所以有可能會挖空 (1)(2)(3)(4) 出成題目
                */
                    } else {
                        x = x->next;
                    }
                }

                // 若 x 沒了就把 top 鏈 pop 出來
                if (!top) {
                    break;
                } else {
                    // top->data 會儲存在這個 "equivalence" 中的值
                    x = seq[top->data];
                    // top->next 會儲存上一個 top 值
                    top = top->next;
                    // 可以回翻上一步的程式碼，應該能理解
                    // 我是覺得不太好理解了，我自己看了很多遍
                }
            }
        }
    }

    printf("\n");
    return 0;
}

