int get_rank(VV<int> A) { //mod 2
	const int n = A.size(), m = A[0].size();
	int r = 0;
	for (int i = 0; r < n && i < m; ++i) {
		int pivot = r;
		for (int j = r+1; j < n; ++j) {
			if (A[j][i]) {
				pivot = j;
				break;
			}
		}
		swap(A[pivot], A[r]);
		if (A[r][i] == 0) continue;
		for (int j = r+1; j < n; ++j) {
			if (A[j][i]) {
				for (int k = i; k < m; ++k) {
					A[j][k] ^= A[r][k];
				}       
			}
		}
		++r;
	}
	return r;
}

const ll MOD = TEN(9) + 7;
const int maxn = 310;

ll powmod(ll x, ll k) {
    ll res = 1;
    for (; k; k /= 2, x = x * x % MOD) {
        if (k & 1) {
            res = res * x % MOD;
        }
    }
    return res;
}

ll a[maxn], b[maxn], c[maxn][maxn], d[maxn][maxn], f[maxn][maxn], g[maxn][maxn];
ll p2[maxn];

void precalc(int N) {
	p2[0] = 1;
	rep(i, maxn - 1) {
		p2[i+1] = p2[i] * 2 % MOD;
	}

	rep(i, maxn) {
		g[i][0] = 1;
		for (int j = 1; j <= i; ++j) {
			g[i][j] = g[i][j-1] * (p2[i] - p2[j-1] + MOD) % MOD;
		}
	}

	for (int i = 0; i <= N; ++i) {
		for (int j = 0; j <= i; ++j) {
			d[i][j] = g[i][j] * powmod(g[j][j], MOD - 2) % MOD;
		}
	}

	for (int i = 0; i <= N; ++i) {
		for (int j = 0; j <= i; ++j) {
			f[i][j] = g[j][j] * d[i][i-j] % MOD;
		}
	}

	for (int i = 0; i <= N; ++i) {
		for (int j = 0; j <= i; ++j) {
			c[i][j] = d[N][j] * f[i][j] % MOD * powmod(2, N*(N-i)) % MOD;
		}
	}

	for (int i = 0; i <= N; ++i) {
		b[i] = d[N][i] * f[N][i] % MOD;
	}

	for (int i = 0; i <= N; ++i) {
		for (int j = i; j <= N; ++j) {
			a[i] = (a[i] + b[j] * c[j][i]) % MOD;
		}
	}
}

int main() {
	int N; cin >> N;
	VV<int> C(N, V<int>(N));
	rep(i, N) rep(j, N) cin >> C[i][j];

	precalc(N);

	int R = get_rank(C);

	cout << a[R] * powmod(b[R], MOD - 2) % MOD << endl;
	
	return 0;
}

