#include<cassert>
#include<iostream>
#include<vector>

using namespace std;

template <class T>
class Deque {

private:
    vector<T> data_;
    int size_;
    int head_;
    int tail_;
    int capacity_;

public:

    Deque(int size) : size_(0), head_(0), tail_(size-1), capacity_(size), data_(size) {}

    void push_front(T v) {
        assert(head_ <= tail_);
        data_[head_++] = v;
        size_++;
    }

    void push_back(T v) {
        assert(head_ <= tail_);
        data_[tail_--] = v;
        size_++;
    }

    void pop_front() {
        assert(head_ > 0);
        head_--;
        size_--;
    }

    void pop_back() {
        assert(tail_ < capacity_);
        tail_++;
        size_--;
    }

    T front() const { 
        assert(head_ > 0);
        return data_[head_-1];
    }

    T back() const {
        assert(tail_ < capacity_-1);
        return data_[tail_+1];
    }

    int size() const { return size_; }

    int empty() const { return size_ == 0; }


    ~Deque() {}
};

int main() {
    Deque<int> mydeque(3);
    mydeque.push_front(1);
    mydeque.push_back(3);
    cout << mydeque.front() << " " << mydeque.back() << endl;
    cout << mydeque.size();
}

//設定値
var input = {};

//2次元長方形配列。 要素は-1(横棒の右側),0,1(横棒の左側)
var data = [];

//経路取得
var f = function(startLine, startStep){
	if(!startStep) startStep = 0;
	var now = startLine;
	var result = [now];
	for(var y=startStep; y<data.length; y++){
		now += data[y][now];
		result.push(now);
	}
	return result;
};
//ゴール指定時の経路取得 (経路はスタートから)
var rf = function(endLine){
	var now = endLine;
	var result = [now];
	for(var y=data.length-1; y>=0; y--){
		now += data[y][now];
		result.push(now);
	}
	return result.reverse();
};
 
