void preprocess(const std::string &s, std::vector<std::string> &t) {
  t.clear();
  for (size_t i=0; i<s.length(); ++i) {
    if (s[i] == 'a') {
      if (s[i+1] == ' ') {
        // "a list of "
        t.push_back("(");
        i += 9;
      } else if (s[i+1] == 'n') {
        // "and "
        t.push_back("&");
        i += 3;
      } else {
        assert(false);
      }
      continue;
    }

    std::string word(1, s[i]);
    while (++i < s.length() && isupper(s[i]))
      word += s[i];

    t.push_back(word);
    if (i < s.length() && s[i] == ',') {
      ++i;
    }
  }
}

