void change(int *a, int i) {
    int p = i % 2 == 0 ? i/2 : (i-1)/2;
    if(p >= 1 && a[i] > a[p]) {
        int tmp = a[i];
        a[i] = a[p];
        a[p] = tmp;
        change(a, p);
    }
}

void maxHeapify(int *a, int i) {

  int l = i*2;
  int r = i*2+1;

  int largest = i;
  if(l <= count && a[l] > a[largest])  largest = l;

  if(r <= count && a[r] > a[largest]) largest = r;

  if(largest != i) {
    int s = a[i];
    a[i] = a[largest];
    a[largest] = s;
    maxHeapify(a, largest);
  }
}

