#include<iostream>
#define max_in 1048575
using namespace std;

void constructTree(int inp[],int segTree[],int low, int high, int pos)
{
    if(high == low)
    {
        segTree[pos] = inp[low];
        return;
    }
    int mid = (low + high)/2;
    constructTree(inp,segTree,low,mid,2*pos+1);
    constructTree(inp,segTree,mid+1,high,2*pos+2);
    segTree[pos] = segTree[2*pos+1] & segTree[2*pos+2];
}

int minQuery(int segTree[],int qlow, int qhigh, int low, int high, int pos)
{
    if(qlow <= low && qhigh >= high ) //total overlap
    return segTree[pos];
    if(qlow > low || qhigh < high)
    return max_in;
    int mid = (low + high)/2;
    return(minQuery(segTree,qlow,qhigh,low,mid,2*pos+1) & minQuery(segTree,qlow,qhigh,mid+1,high,2*pos+2));
}

int main()
{
    int n = 3;
    int a[] = {1,2,3};
    int seg[7];
    for(int i=0;i<7;i++)
    seg[i] = max_in;

    constructTree(a,seg,0,n-1,0);
    cout<<minQuery(seg,1,3,0,n-1,0);
    for(int i=0;i<7;i++)
    cout<<seg[i]<<endl;
}

#include <cstdio>
#include <cstring>

#define STRING_LENGTH 100000

using namespace std;

struct sortinfo
{
	int x, y, ord;
};

int l;
char s[STRING_LENGTH];
int rank[STRING_LENGTH * 2], sa[STRING_LENGTH];

void radix_sort(sortinfo *d)
{
	static sortinfo _d[STRING_LENGTH], res[STRING_LENGTH];
	static int c[STRING_LENGTH];
	memset(c, 0, sizeof(c));
	for (int i = 0; i < l; i++)
	{
		c[d[i].y]++;
	}
	for (int i = 1; i <= l; i++)
	{
		c[i] += c[i - 1];
	}
	for (int i = l - 1; i >= 0; i--)
	{
		_d[--c[d[i].y]] = d[i];
	}
	memset(c, 0, sizeof(c));
	for (int i = 0; i < l; i++)
	{
		c[_d[i].x]++;
	}
	for (int i = 1; i <= l; i++)
	{
		c[i] += c[i - 1];
	}
	for (int i = l - 1; i >= 0; i--)
	{
		res[--c[_d[i].x]] = _d[i];
	}
	for (int i = 0; i < l; i++)
	{
		d[i] = res[i];
	}
}

void init_rank()
{
	static int c[256];
	static sortinfo d[STRING_LENGTH];
	int x = 1;
	for (int i = 0; i < l; i++)
	{
		c[(int)s[i]] = 1;
	}
	for (int i = 0; i < 256; i++)
	{
		if (c[i] == 1)
		{
			c[i] = x++;
		}
	}
	for (int i = 0; i < l; i++)
	{
		rank[i] = c[(int)s[i]];
	}
	for (int k = 1; k < l; k <<= 1)
	{
		for (int i = 0; i < l; i++)
		{
			d[i].x = rank[i];
			d[i].y = rank[i + k];
			d[i].ord = i;
		}
		radix_sort(d);
		x = 1;
		rank[d[0].ord] = 1;
		for (int i = 1; i < l; i++)
		{
			rank[d[i].ord] = (d[i].x == d[i - 1].x && d[i].y == d[i - 1].y ? x : ++x);
		}
		if (x == l)
		{
			break;
		}
	}
}

void rank_to_sa()
{
	for (int i = 0; i < l; i++)
	{
		sa[rank[i] - 1] = i + 1;
	}
}

int main()
{
	scanf("%d%s", &l, s);
	init_rank();
	rank_to_sa();
	for (int i = 0; i < l; i++)
	{
		printf("%d\n", sa[i]);
	}
	return 0;
}

