class graph {
    constructor() {
        this.adjList = {}
    }
    // add vertex 
    addvertex(value) {
        if (!this.adjList[value]) {
            this.adjList[value] = new Set()
        }
    } 
    // adding edge to connect with the each
    addEdge(v1, v2) { 
        let obj = this.adjList  
        if (!obj[v1]) {   
            this.addvertex(v1) 
        } 
        if (!obj[v2]) {  
            this.addvertex(v2)
        } 
        obj[v1].add(v2) 
    }
    //remove edge
    removeEdge(v1, v2) {
        this.adjList[v1].delete(v2)
    }
    //remove vertex
    removeVertex(val) {
        for (let key in this.adjList) {
            if (this.adjList[key].has(val)) {
                this.adjList[key].delete(val)
            }
        }
        delete this.adjList[val]
    }
    //depth first search
    dfs(start) {
        let seen = new Set()
        let fun = (start, seen) => {
            console.log(start)
            seen.add(start)
            for (let val of this.adjList[start]) {
                if (!seen.has(val)) {
                    fun(val, seen)
                }
            }
        }
        fun(start, seen)
    }
    //breadth first search
    bfs(start) {
        const queue = [start]
        let seen = new Set()
        seen.add(start)
        while (queue.length) {
            let value = queue.shift()
            console.log(value)
            for (let val of this.adjList[value]) {
                if (!seen.has(val)) {
                    queue.push(val)
                    seen.add(val)
                }
            }
        }
    }
    //shoertedst path funny thing in graph
    shortest(start, end) {
        let seen = new Set()
        seen.add(start)
        let parent = {}
        let queue = [start]
        let saw = false
        while (queue.length) {
            let node = queue.shift()
            if (node == end) {
                saw = true
                break
            }
            for (let val of this.adjList[node]) {
                if (!seen.has(val)) {
                    seen.add(val)
                    queue.push(val)
                    parent[val] = node
                }
            }
        }
        let arr = []
        if (saw) {
            for (let val in parent) {
                arr.push(end)
                end = parent[end]
            }
        }
        return arr.reverse()
    }
    //update application path exissts
    pathExisists(start, end) {
        if (!this.adjList[start] || !this.adjList[end]) {
            return false
        }
        const queue = [start]
        let seen = new Set()

        seen.add(start)
        while (queue.length) {
            let value = queue.shift()
            if (value == end) {
                return true
            }
            for (let val of this.adjList[value]) {
                if (!seen.has(val)) {
                    queue.push(val)
                    seen.add(val)
                }
            }
        }
        return false
    }
    // print the graph for feature
    print() {
        for (let key in this.adjList) {
            console.log(`${key}  -> ${[...this.adjList[key]]}`)
        }
    }
}

