		//**** COPY ACTIVE EDGES IN POP2 AS ACTIVE EDGES IN COALESCENT POP ****
		for(int i = 0; i < act_edges_pop2.size(); i++) {
			act_e = pop2.getGraphEdges().get(act_edges_pop2.get(i));
