int partition(int arr[],int p, int r){
	int key = arr[r];
	int i, j=p-1, temp;
	
	for(i=p; i<r; i++){
		if(arr[i] <= key){
			//swapping is small
			temp = arr[i];
			j++;
			arr[i] = arr[j];
			arr[j] = temp;
		}
	}
	//swapping j+1 with last element 'key'
	++j;
	arr[r]=arr[j];
	arr[j] = key;

	for(int z=0; z<r+1;z++){
		printf("%d ", arr[z]);
	}
	printf("\n");

	return j;

	printf("value of new array is\n");

	

}

void quick_sort(int arr[], int p, int r){
	int q;
	if(p<r){
		q = partition(arr,p,r);
		quick_sort(arr,p,q-1);
		quick_sort(arr,q+1,r);
	}
}
 
