template<class T> inline bool chmin(T& a, T b) { if (a > b) { a = b; return 1; } return 0; }

const int MAX_N = 2000;
const int MAX_C = 1000000000;

int W, H, N;
ll X1[MAX_N], X2[MAX_N], Y1[MAX_N], Y2[MAX_N];

int G[MAX_N*4+1][MAX_N*4+1];

vector<ll> compress(ll *c1, ll *c2){
    vector<ll> xs;
    rep(i,N){
        for(int d = 0; d <= 1; d++){
            int tx1 = c1[i] + d;
            int tx2 = c2[i] + d;
            xs.push_back(tx1);
            xs.push_back(tx2);
        }
    }
    xs.push_back(MAX_C+1);
    sort(xs.begin(), xs.end());
    xs.erase(unique(xs.begin(), xs.end()), xs.end());
    rep(i,N){
        c1[i] = find(xs.begin(), xs.end(), c1[i]) - xs.begin();
        c2[i] = find(xs.begin(), xs.end(), c2[i]) - xs.begin();
    }
    return xs;
}

int main(){
	cin.tie(0);
	ios::sync_with_stdio(false);
    cin >> N;
    rep(i,N){
        cin >> X1[i] >> Y1[i] >> X2[i] >> Y2[i];
        assert(X1[i] < X2[i]);
        assert(Y1[i] < Y2[i]);
    }
    vector<ll> X = compress(X1, X2);
    vector<ll> Y = compress(Y1, Y2);
    memset(G, 0, sizeof(G));
    rep(i,N){
        G[Y1[i]][X1[i]]++;
        G[Y2[i]][X2[i]]++;
        G[Y1[i]][X2[i]]--;
        G[Y2[i]][X1[i]]--;
    }
    for(int y = 0; y < Y.size()-1; y++){
        for(int x = 1; x < X.size()-1; x++){
            G[y][x] += G[y][x-1];
        }
    }
    for(int x = 0; x < X.size()-1; x++){
        for(int y = 1; y < Y.size()-1; y++){
            G[y][x] += G[y-1][x];
        }
    }
    ll ans = 0;
    rep(y,Y.size()-1){
        rep(x,X.size()-1){
            if(G[y][x]) ans += (X[x+1]-X[x])*(Y[y+1]-Y[y]);
        }
    }
    cout << ans << endl;
	return 0;
}

