#include <stdarg.h>
#include <stdio.h>
#include <stdlib.h>

#define INFINITY 32767

typedef char VexType;
typedef int ArcType;

/*
 * Define arc(边) struct
 * vexIndex: the index's value of vex array
 * weight: the weight of this arc
 * next: the pointer of next arc
 */
typedef struct ArcNode{
    int vexIndex;
    ArcType weight;
    struct ArcNode* next;
}ArcNode;

/*
 * Define vex(顶点) struct
 * data: the name of this vex
 * firstVex: the first arc's pointer of this vex
 */
typedef struct VexNode{
    VexType data;
    ArcNode* firstVex;
}VexNode;

/*
 * Define Graph struct
 * vexs: the pointer of ver array
 * vexNum: the num of this graph's vexs
 * arcNum: the num of this graph's arcs
 */
typedef struct ALGraph{
    VexNode* vexs;
    int vexNum;
    int arcNum;
}ALGraph;

/*
 * Init graph
 * vexNum: the vex's num of this graph
 */
ALGraph* initGraph(int vexNum){
    ALGraph* G = (ALGraph*)malloc(sizeof(ALGraph));
    G->vexs = (VexNode*)malloc(sizeof(VexNode) * vexNum);
    for(int i = 0; i < vexNum; i++){
        G->vexs[i].data = '0';
        G->vexs[i].firstVex = NULL;
    }
    G->vexNum = vexNum;
    G->arcNum = 0;
    return G;
}

/*
 * Create graph
 * vexs: the pointer of vex's name array
 * weight: the pointer of arc's value
 * G: the pointer of graph
 */
void createGraph(VexType* vexs, ArcType* weight, ALGraph* G){
    for(int i = 0; i < G->vexNum; i++){
        G->vexs[i].data = vexs[i];
        for(int j = 0; j < G->vexNum; j++){
            if(*(weight + G->vexNum * i + j) != INFINITY && \
               *(weight + G->vexNum * i + j) != 0){
                ArcNode* node = (ArcNode*)malloc(sizeof(ArcNode));
                node->vexIndex = j;
                node->weight = *(weight + G->vexNum * i + j);
                node->next = G->vexs[i].firstVex;
                G->vexs[i].firstVex = node;
                G->arcNum++;
            }
        }
    }
}

/**
 * main function
 * @param argc the num of args
 * @param argv the command args
 * @return int
 */
int main()
{
    ALGraph* G = initGraph(2);
    ArcType weight[2][2] = {
        0,2,
        2,0
    };
    createGraph("ABC", (int*)weight, G);
    printf("G->vexNum = %d\n", G->vexNum);
    printf("G->arcNum = %d\n", G->arcNum);
    return 0;
}

import java.util.HashSet;
import java.util.Iterator;
import java.util.LinkedList;
import java.util.Set;
import java.util.ArrayList;


public class DepthFirstTraversal {

    // ArrayList for Adjacency List Representation
    public static ArrayList<LinkedList<Integer>> adj;

    // Function to add an edge into the DepthFirstTraversal
    private static void addEdge(int v, int w) {
        adj.get(v).add(w);
    }

    // A function used by DFS
    private static void depthFirstTraversal(int v, Set<Integer> visited) {
        // Mark the current node as visited
        visited.add(v);
        System.out.println(v);
        Iterator<Integer> i = adj.get(v).listIterator();
        while (i.hasNext()) {
            int n = i.next();
            if (!visited.contains(n)) {
                depthFirstTraversal(n, visited);
            }
        }
    }

    public static void dfs(int v) {
        // false by default in java)
        Set<Integer> visited = new HashSet<Integer>();
        // Call the recursive helper function to print DFS traversal
        depthFirstTraversal(v, visited);
    }

    public static void initEdges(int n) {
        adj = new ArrayList<LinkedList<Integer>>();
        for (int i = 0; i < n; ++i) {
            adj.add(new LinkedList<Integer>());
        }
    }

    public static void main(String[] args) {
        initEdges(4);
        addEdge(0, 1);
        addEdge(0, 2);
        addEdge(1, 2);
        addEdge(2, 0);
        addEdge(2, 3);
        addEdge(3, 0);
        System.out.println("Depth First Traversal starting from vertex 2");
        dfs(2);
    }
}

