public class RandomGraph {
    // precondition: n >= 2
    public static List<Integer>[] getRandomTree(int V, Random rnd) {
        int[] a = new int[V - 2];
        for (int i = 0; i < a.length; i++) {
            a[i] = rnd.nextInt(V);
        }
        return PruferCode.pruferCode2Tree(a);
    }

    public static List<Integer>[] getRandomTree2(int n, Random rnd) {
        List<Integer>[] t = Stream.generate(ArrayList::new).limit(n).toArray(List[] ::new);
        int[] p = new int[n];
        for (int i = 0, j; i < n; j = rnd.nextInt(i + 1), p[i] = p[j], p[j] = i, i++); // random permutation
        for (int i = 1; i < n; i++) {
            int parent = p[rnd.nextInt(i)];
            t[parent].add(p[i]);
            t[p[i]].add(parent);
        }
        return t;
    }

    // precondition: V >= 2, V-1 <= E <= V*(V-1)/2
    public static List<Integer>[] getRandomUndirectedConnectedGraph(int V, int E, Random rnd) {
        List<Integer>[] g = getRandomTree(V, rnd);
        Set<Long> edgeSet = new LinkedHashSet<>();
        for (int i = 0; i < V; i++) {
            for (int j = i + 1; j < V; j++) {
                edgeSet.add(((long) i << 32) + j);
            }
        }
        for (int i = 0; i < V; i++) {
            for (int j : g[i]) {
                edgeSet.remove(((long) i << 32) + j);
            }
        }
        List<Long> edges = new ArrayList<>(edgeSet);
        for (int x : getRandomArrangement(edges.size(), E - (V - 1), rnd)) {
            long e = edges.get(x);
            int u = (int) (e >>> 32);
            int v = (int) e;
            g[u].add(v);
            g[v].add(u);
        }
        for (int i = 0; i < V; i++) Collections.sort(g[i]);
        return g;
    }

    // precondition: V >= 2, V-1 <= E <= V*(V-1)/2
    public static List<Integer>[] getRandomUndirectedConnectedGraph2(int V, int E, Random rnd) {
        List<Integer>[] g = getRandomTree(V, rnd);
        Set<Long> edgeSet = new LinkedHashSet<>();
        for (int i = 0; i < V; i++) {
            for (int j : g[i]) {
                edgeSet.add(((long) i << 32) + j);
            }
        }
        for (int i = 0; i < E - (V - 1); i++) {
            int u;
            int v;
            long edge;
            while (true) {
                u = rnd.nextInt(V);
                v = rnd.nextInt(V);
                edge = ((long) u << 32) + v;
                if (u < v && !edgeSet.contains(edge))
                    break;
            }
            edgeSet.add(edge);
            g[u].add(v);
            g[v].add(u);
        }
        for (int i = 0; i < V; i++) Collections.sort(g[i]);
        return g;
    }

    static int[] getRandomArrangement(int n, int m, Random rnd) {
        int[] res = new int[n];
        for (int i = 0; i < n; i++) {
            res[i] = i;
        }
        for (int i = 0; i < m; i++) {
            int j = n - 1 - rnd.nextInt(n - i);
            int t = res[i];
            res[i] = res[j];
            res[j] = t;
        }
        return Arrays.copyOf(res, m);
    }

    // Usage example
    public static void main(String[] args) {
        List<Integer>[] tree = PruferCode.pruferCode2Tree(new int[] {3, 3, 3, 4});
        System.out.println(Arrays.toString(tree));
        System.out.println(Arrays.toString(PruferCode.tree2PruferCode(tree)));
        System.out.println(Arrays.toString(PruferCode.pruferCode2Tree(new int[] {0, 0})));

        Random rnd = new Random(1);
        for (int step = 0; step < 1000; step++) {
            int V = rnd.nextInt(50) + 2;
            checkGraph(V, V - 1, rnd);
            checkGraph(V, V * (V - 1) / 2, rnd);
            checkGraph(V, rnd.nextInt(V * (V - 1) / 2 - (V - 1) + 1) + V - 1, rnd);
        }
    }

    static void checkGraph(int V, int E, Random rnd) {
        List<Integer>[] g = getRandomUndirectedConnectedGraph(V, E, rnd);
        int n = g.length;
        int[][] a = new int[n][n];
        int edges = 0;
        for (int i = 0; i < n; i++) {
            for (int j : g[i]) {
                ++a[i][j];
                ++edges;
            }
        }
        if (edges != 2 * E) {
            throw new RuntimeException();
        }
        for (int i = 0; i < n; i++) {
            if (a[i][i] != 0) {
                throw new RuntimeException();
            }
            for (int j = 0; j < n; j++) {
                if (a[i][j] != a[j][i] || a[i][j] != 0 && a[i][j] != 1) {
                    throw new RuntimeException();
                }
            }
        }
    }
}

class Solution {
    public int search(int[] nums, int target) {

        int start = 0;
        int end = nums.length-1;


        while(start<=end)
        {
            int mid = start + (end-start)/2;

            if(nums[mid]==target) 
                return mid;


            //to check which part is sorted

            //for left half is sorted , otherwise right is sorted
            if(nums[mid]>= nums[start])
            {
                //if element is present on the left half
                if(target>=nums[start] && target<nums[mid])
                    end = mid-1;
                //else on the right side
                else 
                    start = mid+1;
            }
            else
            {
               if(target>nums[mid] && target<=nums[end])
                    start= mid+1;
                else 
                    end = mid-1;
            }
        }

        return -1;
    }
}

/**
 * Minimum spanning tree using Prim's algorithm.
 * Approach greedy
 * Calculate the weight of minimum spanning tree(sum of weight of edges of MST)
 * and print the edges which makes MST.
 * Input format:
 * ROW 1 :: V - number of vertices, E - number of Edges.
 * Next E lines give details of each edge in format x y w.
 * where x is start of edge, y is end of edge and w is weight of xy edge
 * After that, S - Index of the starting point of finding the MST.
 * all the input is not 0 indexed.
 */



#include <iostream>
#include <limits>

const int MIN = std::numeric_limits<int>::min();
const int MAX = std::numeric_limits<int>::max();


/**
 * Print the Minimum spanning tree
 */
void printMST( int ** graph, int * MST, int V ) {
	std::cout << " Edge    Weight \n";
	for ( int v = 0; v < V; ++v ) {
		if (MST[v] != -1 && graph[v][MST[v]] != -1 ) {
			std::cout << v+1 << "<-->" << MST[v]+1 << "   " << graph[v][MST[v]] << std::endl;
		}
	}
}


/**
 * minKey
 * returns the index of the vertex which is not yet part of MST
 * and has minimum key.
 */

int minKey( int * keys, bool * inMST, int V ) {
	int min = MAX, minIndex;
	for ( int v = 0; v < V; ++v ) {
		if ( inMST[v] == false && min > keys[v] ) {
			minIndex = v;
			min = keys[v];
		}
	}
	return minIndex;
}


/**
 * primsMSTWeight
 * returns the weight of the minimum spanning tree of the graph
 * Args:
 * graph: adjacency matrix of the graph
 * V :    Total number of vertices in the graph
 * S :	  Starting index of MST
 */
int primsMSTWeight( int ** graph, int V, int S, int * MST)
{
	int * key = new int[V];
	bool * inMST = new bool[V];

	for ( int v = 0; v < V; ++v ) {
		inMST[v] = false;
		key[v] = MAX;
	}

	key[S] = 0;
	for ( int count = 0; count < V-1; ++count ) {
		int u = minKey(key, inMST, V);
		inMST[u] = true;
		for ( int v = 0; v < V; ++v ) {
			if ( (graph[u][v] != -1) && (inMST[v] == false) && (key[v] > graph[u][v]) ) {
				key[v] = graph[u][v];
				MST[v] = u;
			}
		}
	}

	int sum = 0;
	for ( int v = 0 ;v < V; ++v ) {
		if ( MST[V] != -1  && graph[v][MST[v]] != -1 ) {
			sum += graph[v][MST[v]];
		}
	}
	delete[] key;
	delete[] inMST;
	return sum;
}


int main()
{
	int V, E, x, y, w, S;
	/**
	 * V -- number of vertices
	 * E -- number of edges
	 * xy-- edge with endpoints x and y
	 * w -- weight of edge
	 * S -- Starting index
	 */

	std::cin >> V >> E;
	int ** graph = new int*[V];
	for ( int v = 0; v < V; ++v ) {
		graph[v] = new int[V];
		for ( int w = 0; w < V; ++w ) {
			graph[v][w] = -1;
		}
	}

	for ( int i = 0; i < E; ++i ) {
		std::cin >> x >> y >> w;
		if ( graph[x-1][y-1] == -1 ||
			 ( (graph[x-1][y-1] > 0) && (graph[x-1][y-1] > w ))) {
			graph[x-1][y-1] = w;
			graph[y-1][x-1] = w;
		}
	}

	std::cin >> S;
	int * MST = new int[V];
	MST[S-1] = -1;
	std::cout << "Min Spanning tree weight " << primsMSTWeight(graph, V, S-1, MST) << std::endl;
	std::cout << "Min Spanning tree:\n";
	printMST(graph, MST, V);
	return 0;
}

