function intersect(x1,y1,x2,y2,x3,y3,x4,y4) {
  var
  c = ((x1-x2)*(y3-y1)+(y1-y2)*(x1-x3))*((x1-x2)*(y4-y1)+(y1-y2)*(x1-x4)),
  ta = (x3-x4)*(y1-y3)+(y3-y4)*(x3-x1),
  tb = (x3-x4)*(y2-y3)+(y3-y4)*(x3-x2);
  
  return c < 0 && ta * tb < 0;
}
 
