            idx++;
            n -= term();
        } else {
            break;
        }
    }
    return n;
}

function term() {
    var n = factor();

    while(true) {
        if ( line[idx] == "*" ) {
            idx++;
            n *= factor();
        } else if ( line[idx] == "/" ) {
            idx++;
            n = ~~(n / factor());
        } else {
            break;
        }
    }
    return n;
}

function factor() {
    if ( line[idx] == "(" ) {
        idx++;  // (
        var ret = expression();
        idx++;  // )
        return ret;
    } else {
        return number();
    }
}

function number() {
