        printf("%d, ", yarr[i]);	
    printf("\b\b]\n");
    return 0;
}

#include <bits/stdc++.h>

using namespace std;

struct point
{
    double x,y;
};

void chmin(double &x, double y)
{
    if(x>y) x=y;
}

constexpr double sq3=sqrt(3);

void solve()
{
    int n,k; cin>>n;
    if(!n) exit(0);
    cin>>k;
    k=n-k;
    vector<point> pnt(n);

    for(point &e:pnt)
    {
        cin>>e.x>>e.y;
    }
    sort(begin(pnt), end(pnt),
    [](point p1, point p2)
    {
        if(p1.y==p2.y)
        {
            return p1.x>p2.x;
        }
        return p1.y>p2.y;
    });

    struct left_comp
    {
        bool operator()(point p1, point p2)
        {
            return p2.y-sq3*p2.x>p1.y-sq3*p1.x;
        }
    };
    auto lpnt=pnt;
    sort(begin(lpnt),end(lpnt), left_comp());

    struct right_comp
    {
        bool operator()(point p1, point p2)
        {
            return p2.y+sq3*p2.x>p1.y+sq3*p1.x;
        }
    };
    auto rpnt=pnt;

    sort(begin(rpnt), end(rpnt), right_comp());

    double ans=1e5;

    for(auto i=begin(pnt),j=i; i!=end(pnt); i=j)
    {
        const double nowy=i->y;
        vector<point> clf,crg;
        for(auto &p: lpnt)
        {
            if(p.y>=nowy) clf.emplace_back(p);
        }
        // for(auto &p: rpnt)
        // {
        //     if(p.y>=nowy) crg.emplace_back(p);
        // }
        // auto itr=end(crg);
        priority_queue<point,vector<point>,right_comp> que;

        for(const auto &p: clf)
        {
                // cerr << "p: " << p.x << " " << p.y << endl;

            if(que.size()<k || right_comp()(p,que.top()))
            {
                que.emplace(p);
            }
            if(que.size()>k) que.pop();
            if(que.size()==k) // update
            {
                const double lx=p.x-(p.y-nowy)/sq3;
                auto tp=que.top();
                const double rx=tp.x+(tp.y-nowy)/sq3;
                // cerr << nowy << endl;
                // cerr << "p: " << p.x << " " << p.y << endl;
                // cerr << "tp: " << tp.x << " " << tp.y << endl;
                chmin(ans, rx-lx);
            }
        }

        while(j!=end(pnt) && i->y==j->y) ++j;
    }

    cout << fixed << setprecision(10) << ans*3 << "\n";
}

main()
{
    ios::sync_with_stdio(false);
    cin.tie(0);
    while(true) solve();
}

