		}
		if (V[i].ideg == 0)
		{
			cnt++;
		}
	}
	int vhe;
	for (int i = 1; i <= ivc; i++)
	{
		if (V[i].ideg != 0)
		{
			connect(i);
			vhe = i;
			break;
		}
	}
	if (cnt < ivc)
	{
		printf("NO");
		return 0;
	}
	printf("YES\n");
	if (iec == 0)
	{
		return 0;
	}
	DFS(vhe, vhe);
	for (int i = pc - 1; i >= 0; i--)
	{
		printf("%d ", path[i]);
	}
	return 0;
}

import numpy

def knapsack(W, n, items):
	value = numpy.zeros((W+1, n+1))
	for i in range(1, W+1):
		for j in range(1, n+1):
            # if item i is not part of optimal knapsack
			value[i][j] = value[i][j-1]
			if items[j-1]<=i:
                # if item i is part of optimal knapsack
				temp = value[i-items[j-1]][j-1] + items[j-1]
                # max(i in knapsack, i not in knapsack)
				if temp > value[i][j]:
					value[i][j] = temp

	return (int(value[W][n]))


