class BinaryTree{
    constructor() { 
        this.root = null
    }
    // insert 
    insert(value) {
        let node = new Node(value)
        let queue = [this.root]
        if (!this.root) {
            this.root = node
            return
        }
        while (true) {
            let current = queue.shift()
            if (!current.left) {
                current.left = node
                return
            }
            queue.push(current.left)
            if (!current.right) {
                current.right = node
                return
            }
            queue.push(current.right)
        }
    }
    // print value
    print() {
        if (!this.root) return
        let data = ''
        let queue = [this.root]
        while (queue.length) {
            let current = queue.shift()
            data+=` ${current.value} -> `
            if (current.left) {
                queue.push(current.left)
            }
            if (current.right) {
                queue.push(current.right)
            }
        }
        console.log(data)
    }
    larggestNumber() {
        let larggest = -Infinity
        let queue = [this.root]
        while (queue.length) {
            let current = queue.shift()
            if (current.value > larggest) {
                larggest = current.value
            }
            if (current.left) {
                queue.push(current.left)
            }
            if (current.right) {
                queue.push(current.right)
            }
        }
        return larggest
    }
    KthLarggest(k) {
        let data = []
        let queue = [this.root]
        while (queue.length) {
            let current = queue.shift()
            data.push(current.value)
            if (current.left) {
                queue.push(current.left)
            }
            if (current.right) {
                queue.push(current.right)
            }
        }
        let value = data.sort((a, b) => b - a)
        console.log(value.slice(0,k))
    }
}

