int search(int key, struct Record table[])
{
	int i, h, location;
    h = hash(key);				

	location = h;

	for( i=1; i<TSIZE; i++ )
	{
		if( table[location].status == EMPTY  ) 
			return -1;
		if( table[location].info.studentId == key )
			return location;
		location = ( h + i ) % TSIZE;								
	}
	return -1;
}

