int lcm(int x, int y){
    return x/__gcd(x,y)*y;
}

int euler_phi(int n){
    if(n==0) return 0;
    int ret = n;
    for(int i=2; i*i<=n; ++i){
        if(n%i==0){
            ret -= ret/i;
            while(n%i==0) n/=i;
        }
    }
    if(n!=1) ret -= ret/n;
    return ret;
}

map<int,int> factorize(int n){
    map<int,int> ret;
    for(int i=2; i*i<=n; ++i){
        while(n%i==0){
            n/=i;
            ++ret[i];
        }
    }
    if(n>1) ++ret[n];
    return ret;
}

ll mod_pow(ll x, ll n, ll mod){
    ll ret = 1;
    while(n){
        if(n&1) (ret*=x)%=mod;
        (x*=x)%=mod;
        n>>=1;
    }
    return ret;
}

