    h=low;
    j=mid+1;
    while((h<=mid)&&(j<=high))
    {
        if (a[h]<a[j])
        {
            b[i]=a[h];
            h=h+1;
        }
        else
        {
            b[i]=a[j];
            j=j+1;
        }
        i=i+1;
    }
    while(h<=mid)
    {
        b[i]=a[h];
        h=h+1;
        i=i+1;
    }
    while(j<=high)
    {
        b[i]=a[j];
        j=j+1;
        i=i+1;
    }
    for(i=low;i<=high;i++)
    {
        a[i]=b[i];
    }
}
 
