long long N, M, fact[1000009], factinv[1000009], dp[33][100009], mod = 1000000007; vector<long long>vec;
bool used[3009][3009];

long long modpow(long long a, long long b, long long m) {
	long long p = 1, q = a;
	for (int i = 0; i < 30; i++) {
		if ((b / (1LL << i)) % 2 == 1) { p *= q; p %= m; }
		q *= q; q %= m;
	}
	return p;
}

long long Div(long long a, long long b, long long m) {
	return (a * modpow(b, m - 2, m)) % m;
}

void init() {
	fact[0] = 1;
	for (int i = 1; i <= N; i++) fact[i] = (fact[i - 1] * i) % mod;
	for (int i = 0; i <= N; i++) factinv[i] = Div(1, fact[i], mod);
}

long long ncr(long long n, long long r) {
	if (r < 0 || n < r) return 0;
	return (fact[n] * factinv[r] % mod) * factinv[n - r] % mod;
}

int main() {
	cin >> N >> M; init();
	for (long long i = 1; i*i <= M; i++) {
		if (M%i != 0) continue;
		vec.push_back(i);
		vec.push_back(M / i);
	}
	sort(vec.begin(), vec.end());
	vec.erase(unique(vec.begin(), vec.end()), vec.end());


	for (int i = 0; i < vec.size(); i++) {
		for (int j = 0; j < vec.size(); j++) {
			if (vec[j] % vec[i] == 0 && j > i) used[i][j] = true;
		}
	}
	dp[0][0] = 1;
	for (int i = 0; i < 32; i++) {
		for (int j = 0; j < vec.size(); j++) {
			for (int k = 0; k < vec.size(); k++) {
				if (used[j][k] == true) {
					dp[i + 1][k] += dp[i][j];
					dp[i + 1][k] %= mod;
				}
			}
		}
	}
	long long sum = 0;
	for (int i = 0; i < 33; i++) {
		sum += ncr(N, i) * dp[i][vec.size() - 1];
		sum %= mod;
	}
	cout << sum << endl;
	return 0;
}

