void sieve(int n)
{
	for (int i = 2; i <= n; i++)
	{
		if (div[i] == 0)
		{
			prime[pc++] = i;
			div[i] = i;
		}
		for (int j = 0; j < pc; j++)
		{
			if (i * prime[j] > n) break;
			div[i * prime[j]] = prime[j];
			if (div[i] == prime[j]) break;
		}
	}
}

