#include <bits/stdc++.h>

using namespace std;

typedef long double ld;
typedef long long ll;

const int mod = 1e9 + 7;

int add(int x, int y) {
  x += y;
  if (x >= mod)
    x -= mod;
  return x;
}

int sub(int x, int y) {
  return add(x, mod - y);
}

int mul(ll x, ll y) {
  return x * y % mod;
}

int uul(int &x, int y) {
  return x = mul(x, y);
}

void udd(int &x, int y) {
  x = add(x, y);
}

int bin(int x, int to) {
  int y = 1;
  while (to) {
    if (to & 1)
      y = mul(x, y);
    x = mul(x, x);
    to >>= 1;
  }
  return y;
}

int inv(int x) {
  assert(x != 0);
  return bin(x, mod - 2);
}

const int M = 307;

bitset<M> c[M];

int n, k;
int d[M][M][M];
int pw[M];

void pre() {
  for (int i = 0; i < M; ++i)
    pw[i] = bin(2, i);

  for (int n = 0; n < M; ++n) {
    d[n][0][0] = 1;
    for (int k = 0; k + 1 < M; ++k)
      for (int r = 0; r + 1 < M; ++r) {
        int nx = pw[r];
        int ny = sub(pw[n], nx);
        int cur = d[n][k][r];
        udd(d[n][k + 1][r], mul(nx, cur));
        udd(d[n][k + 1][r + 1], mul(ny, cur));
      }
  }
}

void read() {
  cin >> n;
  for (int i = 0; i < n; ++i)
    for (int j = 0; j < n; ++j) {
      int x;
      cin >> x;
      c[i][j] = x;
    }
}

void gaub() {
  int last = 0;
  for (int i = 0; i < n; ++i) {
    int x = -1;
    for (int j = last; j < n; ++j)
      if (c[j][i]) {
        x = j;
      }

    if (x == -1)
      continue;

    swap(c[last], c[x]);
    for (int j = last + 1; j < n; ++j)
      if (c[j][i])
        c[j] ^= c[last];

    ++last;
  }

  k = last;

  cerr << "k = " << k << endl;
}


void kill() {
  int ans = 0;

  for (int m = k; m <= n; ++m) {
    int cnt = mul(d[n][n][m], d[m][n][k]);
    uul(cnt, bin(2, (n - m) * n));
    udd(ans, cnt);
  }

  uul(ans, inv(d[n][n][k]));


  cout << ans << endl;
}


int main() {
#ifdef LOCAL
  assert(freopen("h.in", "r", stdin));
#endif

  ios_base::sync_with_stdio(false);

  pre();
  read();
  gaub();
  kill();
}

