int power(int a,long long k){
	int res=1;
	for(;k;k>>=1,a=mul(a,a))if(k&1)res=mul(res,a);
	return res;
}

Matrix power(Matrix a,long long k){
	Matrix res;
	res.a[0][0]=res.a[1][1]=1;	
	for(;k;k>>=1,a=a*a)if(k&1)res=res*a;
	return res;
}

