int isPrime(lldu n) {
	if(n<=1) return 0;
	if(n==2) return 1;
	if((n&1) == 0) return 0;
	int i;
	for(i=3;i<=sqrt(n);i+=2) {
		if(n%i == 0) return 0;
	}
	return 1;
}
void generateSpiralMatrix(int n) {
	lldu sm[n][n],num = n*n;
	int fri = 0,fci=0,lci=n,lri=n,i,j;
	while(fri<lri && fci<lci) {
		for(i=lci-1;i>=fci;i--) {
			sm[lri-1][i] = num--;
		}
		lri--;
		for(i=lri-1;i>=fri;i--) {
			sm[i][fci]=num--;
		}
		fci++;
		for(i=fci;i<lci;i++) {
			sm[fri][i]=num--;
		}
		fri++;
		for(i=fri;i<lri;i++) {
			sm[i][lci-1]=num--;
		}
		lci--;
	}
	for(i=0;i<n;i++) {
		for(j=0;j<n;j++) {
