int main()
{
  int n;
  cin>>n;
  ll arr[n];
  ll sum=0;
  for(int i=0;i<n;i++)
  {cin>>arr[i];
   sum+=arr[i];
  }
  ll table[n][n]; 
  
    // Fill table using above recursive formula. Note  
    // that the table is filled in diagonal fashion (similar 
    // to http:// goo.gl/PQqoS), from diagonal elements to 
    // table[0][n-1] which is the result. 
    for (int gap = 0; gap < n; ++gap) { 
        for (int i = 0, j = gap; j < n; ++i, ++j) { 
  
            // Here x is value of F(i+2, j), y is F(i+1, j-1) and 
            // z is F(i, j-2) in above recursive formula 
            ll x = ((i + 2) <= j) ? table[i + 2][j] : 0; 
            ll y = ((i + 1) <= (j - 1)) ? table[i + 1][j - 1] : 0; 
            ll z = (i <= (j - 2)) ? table[i][j - 2] : 0; 
  
            table[i][j] = max(arr[i] + min(x, y), arr[j] + min(y, z)); 
        } 
    } 
  
    cout<<2*table[0][n - 1]-sum; 
}

public class ChangeTheCoin {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int array[] = {1, 2, 3};
		int sum = 4;
		int[][] dp = new int[array.length + 1][sum + 1];
		dp = Utils.fillMatrix(dp, -1);
		for(int i = 1 ; i < dp[0].length; i++){
			dp[0][i] = 0;
		}
		for(int i = 0 ; i < dp.length; i++){
			dp[i][0] = 1;
		}
		int result = getChange(array, dp, sum, array.length);
		System.out.println("No of ways : " + result);
	}

	private static int getChange(int[] array, int[][] dp, int sum, int count) {
		// TODO Auto-generated method stub

		if(sum < 0 || count < 0) return 0;
		if(dp[count][sum] != -1) return dp[count][sum];
		dp[count][sum] = getChange(array, dp, sum - array[count - 1], count) 
						+ getChange(array, dp, sum, count - 1);
		return dp[count][sum];
	}

}

/**
 * Get the nth Fibonacci number.
 *
 * @param {number} n - The position of the Fibonacci number to find.
 * @returns {number} - The nth Fibonacci number.
 *
 * @description
 * The Fibonacci sequence is defined as follows: the first number of the sequence is 0, the second number is 1,
 * and the nth number is the sum of the (n - 1)th and (n - 2)th numbers.
 *
 * For the purpose of this function, the first Fibonacci number is F0; therefore, getNthFib(1) is equal to F0,
 * getNthFib(2) is equal to F1, and so on.
 *
 * The function uses a recursive approach to calculate the Fibonacci number for a given position.
 *
 * @Complexity
 * The time complexity of this function is O(2^n), which makes it inefficient for large values of n.
 * This is because it recalculates Fibonacci numbers multiple times for the same values.
 */
function getNthFib(n) {
  if (n === 0) return 0;
  if (n === 1) return 0;
  if (n === 2) return 1;
  return getNthFib(n - 1) + getNthFib(n - 2);
}

export { getNthFib };

