const ll N = 1e5 + (1 << 16), inf = 1e9;

ll n, a[N], cnt[N], dp[N];
vector <int> adj[N];

ll dfs(ll w) {
	if(dp[w] >= 0)	return dp[w];
	else
		dp[w] = inf;
	for (int i = 0; i < 15; i++) {
		for (int j = 0; j < 15; j++) {
			if(i == j)	continue;
			if(!(w & (1 << i)) || !(w & (1 << j)))
				continue;
			int k = (i + 1) ^ (j + 1);
			k--;
			ll small = dfs(w ^ (1 << i) ^ (1 << j) ^ (1 << k)) + 1;
			if(w & (1 << k))
				dp[w] = min(dp[w], small + 1);
			else
				dp[w] = min(dp[w], small);
		}
	}
	return dp[w];
}

