            cin >> p.x >> p.y >> p.z >> the;
            for (int j = 0; j < n; j++) {
                if (can_watch(s[j], p, the)) {
                    stars.insert(j);
                }
            }
        }
        cout << stars.size() << endl;
    }
    return 0;
}

