ll f[202020], rf[202020];
ll inv(ll x) {
    ll res = 1;
    ll k = MOD - 2;
    ll y = x;
    while (k) {
        if (k & 1) res = (res * y) % MOD;
        y = (y * y) % MOD;
        k /= 2;
    }
    return res;
}
void init() {
    f[0] = 1;
    rf[0] = inv(f[0]);
    for(ll i=1;i<202020;i++){
      f[i] = (f[i - 1] * i) % MOD;
      rf[i] = inv(f[i]);
    }
}
 
ll C(int n, int k) {
    ll a = f[n]; // = n!
    ll b = rf[n-k]; // = (n-k)!
    ll c = rf[k]; // = k!
 
    ll bc = (b * c) % MOD;
 
    return (a * bc) % MOD;
}

int main(){
