function isFixed(nums, prev) {
    if ( prev === undefined || nums.length != prev.length ) return false;
    for ( var i = 0; i < nums.length; i++ ) {
        if ( nums[i] != prev[i] ) return false;
    }
    return true;
}

function toFrequency(nums) {
    var memo = [],
        ret = [];

    for ( var i = 0; i < nums.length; i++ ) {
        var n = nums[i],
            cnt = 1;

        if ( memo[n] === undefined ) {
            for ( var j = i + 1; j < nums.length; j++ ) {
                if ( n == nums[j] ) cnt++;
            }
            memo[n] = cnt;
        }
        ret[i] = memo[n];
    }
    return ret;
}

