using namespace std;
const int maxn = 1000000 + 10;
const int N = maxn << 1;
const int maxE = 3000000;
const int INF = 0x3f3f3f3f;

int n, h[N], ecnt, tot, S, T;
struct enode{
	int v, n, w, op;
	enode() {}
	enode(int _v, int _n, int _w, int _op):v(_v), n(_n), w(_w), op(_op) {}
}e[maxE << 1];

inline void addedge(int u, int v, int w) {
	ecnt ++; e[ecnt] = enode(v,h[u],w,ecnt + 1); h[u] = ecnt;
	ecnt ++; e[ecnt] = enode(u,h[v],0,ecnt - 1); h[v] = ecnt;
}

int level[N], q[N << 1], cur[N];
inline bool bfs() {
	memset(level,0,sizeof(level));
	int head = 1, tail = 0;
	level[S] = 1; q[++ tail] = S;
	for(int i = S;i <= tot;i ++) cur[i] = h[i];
	while(head <= tail) {
		int u = q[head]; head ++;
		for(int i = h[u];~ i;i = e[i].n) {
			int v = e[i].v;
			if(!level[v] && e[i].w > 0) {
				level[v] = level[u] + 1;
				q[++ tail] = v;
				if(v == T) return 1;
			}
		}
	}
	return 0;
}

int dfs(int u, int c) {
	if(u == T || c == 0) return c;
	int tmp = 0;
	for(int &i = cur[u];~ i;i = e[i].n) {
		int v = e[i].v;
		if(level[v] == level[u] + 1) {
			int x = dfs(v,min(c,e[i].w));
			if(x) {
				e[i].w -= x; e[e[i].op].w += x;
				tmp += x; c -= x;
				if(!c) break;
			}
		}
	}
	if(!tmp) level[u] = -1;
	return tmp;
}

int pre[maxn], used[maxn], lis[maxn];
vector<int> g[maxn], from[maxn];

int main() {
	scanf("%d", &n); tot = n;
	S = 0; T = ++ tot; ecnt = 0;
	memset(h,-1,sizeof(h));
	for(int i = 2;i <= n;i ++) addedge(i,T,1);
	for(int i = 1;i < n;i ++) {
		int p = ++ tot;
		addedge(S,p,1);
		int k; scanf("%d", &k);
		for(int j = 1;j <= k;j ++) {
			int x; scanf("%d", &x);
			g[i].push_back(x);
			from[x].push_back(i);
			addedge(p,x,INF);
		}
	}
	int flow = 0;
	while(bfs())
		flow += dfs(S,INF);
	if(flow < n - 1) {
		puts("-1");
		return 0;
	}
	for(int u = 2;u <= n;u ++) {
		for(int i = h[u];~ i;i = e[i].n) {
			int v = e[i].v;
			if(v != T && e[i].w) lis[v - n - 1] = u;
		}
	}
	int head = 1, tail = 0;
	q[++ tail] = 1; pre[1] = -1;
	while(head <= tail) {
		int u = q[head]; head ++;
		for(int i = 0, Sz = from[u].size();i < Sz;i ++) {
			int id = from[u][i];
			if(used[id]) continue;
			used[id] = 1;
			int v = lis[id];
			pre[v] = u;
			q[++ tail] = v;
		}
	}
	for(int i = 2;i <= n;i ++) {
		int u = lis[i - 1], v = pre[u];
		printf("%d %d\n", u, v);
	}
	return 0;
}

