void SortString(char *ptr[], int n)
{
    char *t;
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n - 1 - i; j++)
            if (strcmp(ptr[j], ptr[j + 1]) > 0)
                t = ptr[j], ptr[j] = ptr[j + 1], ptr[j + 1] = t;
}

