                passengers[counter%7][counter/7] = "empty";

            }
            else
            {
                if (counter % 7 == 3)
                {
                    // aisle
                    passengers[counter%7][counter/7] = "aisle";
                }
                else
                {
                    namelist.add(sb.toString());
                    // not an aisle, put the passenger name
                    passengers[counter%7][counter/7] = sb.toString();
                }
