        public void padder(int num_passengers)
        {
            // numbers of rows is known
            // pad the remaining seatas as empty
            for (int i = num_passengers; i < 7*passengers[0].length; i++)
            {
                if (i % 7 != 3)
                passengers[i%7][i/7] = "empty";
                else
                passengers[i%7][i/7] = "aisle";
            }
        }
        public void getPositive()
        {
            // get the list of passengers that are diagonised as positive
            Random rand = new Random();
            positivecases = new ArrayList<>();
            int num_positive = rand.nextInt(namelist.size());
            for (int i = 0; i < num_positive; i++)
            {
                String pos_case = namelist.get(rand.nextInt(namelist.size()));
                if (positivecases.contains(pos_case))
                {
                    // duplicate, nope

                }
                else
                {
                    positivecases.add(pos_case);
                }
            }
        }
