    public static void solver()
    {
        // test case data must have already been generated by now
        // precompute the data to a hashmap
        HashMap<String, Pair> core = new HashMap<>();
        // now add everyone into the hashmap
        for (int i = 0; i < 7; i++)
        {
            for (int j = 0; j < passengers[0].length; j++)
            {
                if (passengers[i][j].equals("empty") || passengers[i][j].equals("aisle"))
                {
                    // don't add
                }
                else
                {
                    Pair P = new Pair(i, j);
                    core.put(passengers[i][j], P); // add into hashmap
                }
            }
        }
        // now check who all needs to be self-quarantined based on the list of positive cases

        for (String s:positivecases)
        {
            // get the coordinate
            Pair P = core.get(s);
            // now use the roster to find out who else should be in the list
            if (P.x != 0)
            {
                // leftward checking allowed
                if (!passengers[P.x - 1][P.y].equals("empty") && !passengers[P.x - 1][P.y].equals("aisle"))
                {
                    ans.add(passengers[P.x - 1][P.y]);
                }
            }
            if (P.x < passengers.length - 1)
            {
                // rightward checking allowed
                if (!passengers[P.x + 1][P.y].equals("empty") && !passengers[P.x + 1][P.y].equals("aisle"))
                ans.add(passengers[P.x + 1][P.y]);
            }
            if (P.y != 0)
            {
                // upward checking allowed
                if (!passengers[P.x][P.y - 1].equals("empty"))
                ans.add(passengers[P.x][P.y - 1]);
            }
            if (P.y < passengers[0].length - 1)
            {
                // downward checking allowed
                if (!passengers[P.x][P.y + 1].equals("empty"))
                ans.add(passengers[P.x][P.y + 1]);
            }
            // the passengers self-quarantining should also be affected
            ans.add(s);
        }
    }
