            mat[tar][j]+=mat[i][j];
            if(mat[tar][j]>0){
                plus[j]=tar;
            }
            else if(mat[tar][j]<0){
                minus[j]=tar;
            }
        }
    }
    int cnt=0;
    for(int i=0;i<n;i++){
        if(all_of(mat[i].begin(),mat[i].end(),[](int x){return x==0;})){
            cnt++;
        }
    }
    cout<<m-(n-cnt)<<endl;
    return 0;
}

