            deq();
            break;
        case 3: // Return front element
            e = frontelement();
            if (e != 0)
                printf("Front element : %d", e);
            else
                printf("\n No front element in Queue as queue is empty");
            break;
        case 4: // Check if queue is empty
            empty();
            break;
        case 5: // Exit
            exit(0);
