		pat[za].push_back(zb);
	}
	for (int p = 0; p < (1 << num); p++)
	{
		for (int i = 0; i < num; i++)
		{
			for (int j = 0; j < pat[i].size(); j++)
			{
				if (p&(1 << pat[i][j]))cnt[i][p]++;
			}
		}
	}
	dp[0] = 1;
	for (int p = 0; p < (1 << num); p++)
	{
		if (((p & 1) == 0) != ((p & 2) == 0))
		{
			dp[p] = 0;
			continue;
		}
		//printf("%d %lld\n", p, dp[p]);
		int v[15];
		int pt = 0;
		for (int i = 0; i < num; i++)if ((p&(1 << i)) == 0)v[pt++] = i;
		for (int q = 0; q < (1 << pt); q++)
		{
			int x = 0;
			for (int i = 0; i < pt; i++)if (q&(1 << i))x += 1 << v[i];
			if (x == 0)continue;
			ll tim = 1;
			for (int i = 0; i < pt; i++)if ((q&(1 << i)) == 0)tim = (tim*((1 << cnt[v[i]][x]) - 1)) % mod;
			for (int i = 0; i < num; i++)if (p&(1 << i))tim = (tim*(1 << cnt[i][x])) % mod;
			dp[p + x] = (dp[p + x] + tim*dp[p]) % mod;
		}
	}
	ll ans = 1;
	for (int i = 0; i < way; i++)ans = ans * 2 % mod;
	printf("%lld\n", (ans + mod - dp[(1 << num) - 1]) % mod);
}

