            ll high=mx1.F;
            if(node[I].S==mx1.F){cnt-=node[I].F;}
            if(cnt>b){high++; cnt=1;}
            else if(cnt==b){high++; cnt=0;}
            dfs2(I,{cnt,high});
        }
    }
}


