/*
Implement the following stack operations : 
1. Push 
2. Pop 
3. Peek
4. Display
*/

#include <stdio.h>
#include <stdlib.h>

struct Stack
{
    int data;
    struct Stack *next;
};

struct Stack *top = NULL;


// Push Operation
void push()
{
    int x;
    printf("Enter Element to be pushed\n");
    scanf("%d", &x);
    struct Stack *newNode = (struct Stack *)malloc(sizeof(struct Stack));
    newNode->data = x;
    newNode->next = top;
    top = newNode;
}

// Pop Operation
void pop()
{
    struct Stack *temp = (struct Stack *)malloc(sizeof(struct Stack));
    temp = top;
    if (top == NULL)
    {
        printf("Stack is empty\n");
    }
    else
    {
        printf("Popped Element is %d\n", top->data);
        top = top->next;
        free(temp);
    }
}

// Peek Operation
void peek()
{
    if (top == NULL)
    {
        printf("Stack is empty\n");
    }
    else
    {
        printf("Top element is %d\n", top->data);
    }
}

// Display
void display()
{
    struct Stack *temp = (struct Stack *)malloc(sizeof(struct Stack));
    temp = top;
    if (top == NULL)
    {
