package dp;

import java.util.Arrays;

public class DynamicProgrammingBasic {

	public static void main(String[] args) {

		int n = 18;
		int a[] = {7, 5, 1};

		int dp[] = new int[n+1];
		Arrays.fill(dp, -1);
		dp[0] = 0;

		int ans = minCoins(n, a, dp);
		System.out.println(ans);

		for(int x: dp) {
			System.out.print(x+" ");
		}
	}

	static int minCoins(int n, int a[], int dp[]) {

		if(n == 0) return 0;

		int ans = Integer.MAX_VALUE;

		for(int i = 0; i<a.length; i++) {
			if(n-a[i] >= 0) {
				int subAns = 0;
				if(dp[n-a[i]] != -1) {
					subAns = dp[n-a[i]];
				} else {
					subAns = minCoins(n-a[i], a, dp);
				}
				if(subAns != Integer.MAX_VALUE && 
						subAns + 1 < ans) {
					ans = subAns + 1;
				}
			}
		}
		return dp[n] = ans;
	}
}

package DivideAndConquerAlgorithms.LongestCommonSubsequenceProblem;

public class LongestCommonSequence {
    private int findLCSLength(String s1, String s2, int i1, int i2) {
        if (i1 == s1.length() || i2 == s2.length()) {
            return 0;
        }
        int c1 = 0;
        if (s1.charAt(i1) == s2.charAt(i2)) {
            c1 = 1 + findLCSLength(s1, s2, i1+1, i2+1);
        }
        int c2 = findLCSLength(s1, s2, i1, i2+1);
        int c3 = findLCSLength(s1, s2, i1+1, i2);
        return Math.max(c1, Math.max(c2, c3));
    }

    public int findLCSLength(String s1, String s2) {
        return findLCSLength(s1, s2, 0, 0);
    }
}

//! For this section, we will be building an UNDIRECTED graph
class Graph {
  constructor() {
    this.adjacencyList = {};
  }

  addVertex(vertex) {
    //  If vertex is not currently in adjacency list:
    if (!this.adjacencyList[vertex]) {
      //  Initialize the new vertex with an empty array
      this.adjacencyList[vertex] = [];
    }

    //  Optionally return the graph for easy chaining
    return this;
  }

  addEdge(vertex1, vertex2) {
    //  For undirected graphs,
    //  simply add directed edge going both ways
    this.addDirectedEdge(vertex1, vertex2).addDirectedEdge(vertex2, vertex1);

    //  Optionally return the graph for easy chaining
    return this;
  }

  addDirectedEdge(vertex1, vertex2) {
    //  If vertices are not already connected,
    //  simply push one vertex to the other's adjacency list
    if (!this.adjacencyList[vertex1].includes(vertex2)) {
      this.adjacencyList[vertex1].push(vertex2);
    }

    //  Optionally return the graph for easy chaining
    return this;
  }

  removeVertex(vertex) {
    //  Remove all edges connected to the vertex
    for (let adjacentVertex of this.adjacencyList[vertex]) {
      this.removeDirectedEdge(adjacentVertex, vertex);
    }

    //  Remove the vertex itself
    delete this.adjacencyList[vertex];

    //  Optionally return the graph for easy chaining
    return this;
  }

  removeEdge(vertex1, vertex2) {
    //  For undirected graphs,
    //  simply remove directed edges going both ways
    this.removeDirectedEdge(vertex1, vertex2).removeDirectedEdge(
      vertex2,
      vertex1
    );

    //  Optionally return the graph for easy chaining
    return this;
  }

  removeDirectedEdge(vertex1, vertex2) {
    //  Simply filter out vertex2 from vertex1's adjacency list
    this.adjacencyList[vertex1] = this.adjacencyList[vertex1].filter(
      (v) => v !== vertex2
    );

    //  Optionally return the graph for easy chaining
    return this;
  }

  depthFirstSearch(startVertex) {
    //  Create an array to store results
    const res = [];
    //  Create an object to track visited vertices
    const visited = {};

    //  Create recursive helper function to traverse the graph
    const traverseDepthFirst = (vertex) => {
      //  Add vertex to results list
      res.push(vertex);
      //  Mark vertex as visited
      visited[vertex] = true;
      //  Loop over vertex's neighbors
      for (let neighbor of this.adjacencyList[vertex]) {
        //  If neighbor is not visited:
        if (!visited[neighbor]) {
          //  Make recursive call on neighbor
          traverseDepthFirst(neighbor);
        }
      }
    };

    //  Invoke the recursive helper function
    traverseDepthFirst(startVertex);

    //  Return results array
    return res;
  }

  depthFirstSearchIterative(startVertex) {
    //  Create an array to store results
    const res = [];
    //  Create an object to track visited vertices
    const visited = {};
    //  Create a stack to store vertices to visit
    //  and push start vertex to that stack
    const toVisit = [startVertex];
    //  While stack is not empty:
    while (toVisit.length) {
      //  Get the next vertex to visit from the stack
      const vertex = toVisit.pop();
      //  If vertex has not yet been visited:
      if (!visited[vertex]) {
        //  Add vertex to results list
        res.push(vertex);
        //  Mark vertex as visited
        visited[vertex] = true;
        //  Push all neighbors of the vertex to the stack
        for (let neighbor of this.adjacencyList[vertex]) {
          toVisit.push(neighbor);
        }
      }
    }

    //  Return results array
    return res;
  }

  breadthFirstSearch(startVertex) {
    //  Create an array to store results
    const res = [];
    //  Create an object to track visited vertices
    const visited = {};
    //  Create a queue to store vertices to visit
    //  and enqueue start vertex to that queue
    const toVisit = [startVertex];
    //  Mark start vertex as visited
    visited[startVertex] = true;

    //  Create recursive helper function to traverse the graph
    const traverseBreadthFirst = () => {
      //  Get the next vertex to visit from the queue
      const vertex = toVisit.shift();
      //  Add vertex to results list
      res.push(vertex);
      //  Loop over its neighbors
      for (let neighbor of this.adjacencyList[vertex]) {
        //  If the neighbor is not yet visited:
        if (!visited[neighbor]) {
          //  Mark it as visited
          visited[neighbor] = true;
          //  Enqueue it to the queue
          toVisit.push(neighbor);
        }
      }
      //  If there are still vertices in the queue, keep going
      if (toVisit.length) traverseBreadthFirst();
    };

    //  Invoke the recursive helper function
    traverseBreadthFirst();
    //  Return results array
    return res;
  }

  breadthFirstSearchIterative(startVertex) {
    //  Create an array to store results
    const res = [];
    //  Create an object to track visited vertices
    const visited = {};
    //  Create a queue to store vertices to visit
    //  and enqueue start vertex to that queue
    const toVisit = [startVertex];
    //  While queue is not empty:
    while (toVisit.length) {
      //  Get the next vertex to visit from the queue
      const vertex = toVisit.shift();
      //  If vertex has not yet been visited:
      if (!visited[vertex]) {
        //  Add vertex to results list
        res.push(vertex);
        //  Mark vertex as visited
        visited[vertex] = true;
        //  Enqueue all neighbors of the vertex to the queue
        for (let neighbor of this.adjacencyList[vertex]) {
          toVisit.push(neighbor);
        }
      }
    }

    //  Return results array
    return res;
  }
}

#include<iostream>
#include<vector>
#include<algorithm>
#include<cmath>
using namespace std;
#define REP(i,b,n) for(int i=b;i<n;i++)
#define rep(i,n)   REP(i,0,n)
#define pb         push_back

const int N = 300;
const double inf = 1000;
const double eps=1e-10;

double cost[N][N];
double dp[N][N];

double le(vector<double> &tmp,double tar){
  int l=0,r=tmp.size()-1;
  double ret=-inf;
  while(l <= r){
    int mid=(l+r)/2;
    if (fabs(tmp[mid]-tar)<eps)return tmp[mid];
    else if (tmp[mid] > tar)r=mid-1;
    else l=mid+1,ret=tmp[mid];
  }
  return ret;
}

double ge(vector<double> &tmp,double tar){
  int l=0,r=tmp.size()-1;
  double ret=inf;
  while(l <= r){
    int mid=(l+r)/2;
    if (fabs(tmp[mid]-tar)<eps)return tmp[mid];
    else if (tmp[mid] > tar)r=mid-1,ret=tmp[mid];
    else l=mid+1;
  }
  return ret;
}

void pre(int n,double *in,double div,int L){
  rep(i,n){
    REP(j,i+1,n){
      double maxi=0;
      double mini=10000000;
      cost[i][j]=0;
      for(int k=i;k<=j;k++){
	mini=min(mini,in[k]);
	maxi=max(maxi,in[k]);
      }
      double tmp=(maxi-mini)/div;
      vector<double> hoge;
      REP(k,1,(1<<L)+1){
	hoge.pb(mini+(k-1)*tmp);
      }
      sort(hoge.begin(),hoge.end());
      for(int k=i;k<=j;k++){
	double a=le(hoge,in[k]);
	double b=ge(hoge,in[k]);
	a=(a-in[k])*(a-in[k]);
	b=(b-in[k])*(b-in[k]);
	cost[i][j]+=min(a,b);
      }
    }
  }
}

double solve(int n,int M){
  rep(i,n+1){
    rep(j,M+1)dp[i][j]=inf;
  }
  dp[0][0]=0;
  REP(i,2,n+1){
    REP(j,1,M+1){
      rep(k,i-1){
	dp[i][j]=min(dp[i][j],dp[k][j-1]+cost[k][i-1]);
      }
    }
  }
  return dp[n][M];
}

main(){
  //test();
  int n,M,L;
  double in[N];
  while(cin>>n>>M>>L && n){
    rep(i,n)cin>>in[i];
    pre(n,in,(1<<L)-1,L);
    printf("%.7lf\n",solve(n,M));
  }
  return false;
}

