#include <bits/stdc++.h>

#define rep(i, n) for(int i = 0; i < (int)(n); i++)
typedef long long ll;
using namespace std;

bool isPrime(ll num) {
    if (num < 2) return false;

    for (ll i = 2; i * i <= num; i++) {
        if (num % i == 0) {
            return false;
        }
    }
    return true;
}

vector<pair<ll, ll >> prime_factorize(ll n) {
    vector<pair<ll, ll>> res;

    for (ll i = 2; i * i <= n; i++) {
        if (n % i != 0) continue;
        int num = 0;
        while (n % i == 0) {
            num++;
            n /= i;
        }
        res.push_back(make_pair(i, num));
    }
    if (n != 1) res.push_back(make_pair(n, 1));

    return res;
}

int main() {
    ll n;
    cin >> n;
    auto x = prime_factorize(n);
    ll ans = 0;

    // for (int i = 0; i <= 14; i++) {
    //     cout << x[i].first << " " << x[i].second << endl;
    // }

    for (auto i:x) {
        ll current = i.first;
        while (n % current == 0) {
            ans++;
            n /= current;
            current *= i.first;
        }
    }


    cout << ans << endl;

    return 0;
}

