	avl_tree_t *tree = NULL;



	tree = avl_create();



	avl_insert( tree, 2 );

	avl_insert( tree, 3 );

	avl_insert( tree, 4 );

	avl_insert( tree, 5 );

	avl_insert( tree, 1 );



