#include <stdio.h>
#include <stdlib.h>

struct Node
{
    int data;
    struct Node *next;
};

void swap(struct Node *a, struct Node *b)
{
    int temp = a->data;
    a->data = b->data;
    b->data = temp;
}

struct Node *bubbleSort(struct Node *head)
{
    int swapped = 0;
    struct Node *curr = head, *prev = NULL, *curr2 = NULL;
    do
    {
        swapped = 0;
        for (curr = head; curr->next != curr2; curr = curr->next)
        {
            swapped = 0;
            if (curr->data > curr->next->data)
            {
                swapped = 1;
                swap(curr, curr->next);
            }
        }
        curr2 = curr;
    } while (swapped);

    return head;
}

