template<class T = int> using V = vector<T>;
template<class T = int> using VV = V< V<T> >;

#define double long double
constexpr double inf = 1e+10;
constexpr double eps = 1e-10;

template<class T> struct ConvexHullTrick {
  struct Line { T a, b; };
  deque<Line> deq;
  bool monotone_query;
  bool need(const Line& l, const Line& m, const Line& r) const {
    return m.b * (r.a - l.a) > l.b * (r.a - m.a) + r.b * (m.a - l.a);
  }
  ConvexHullTrick(bool monotone_query = false) : monotone_query(monotone_query) {}
  void add(T a, T b) {
    if (deq.empty() or a - deq[0].a < eps) {
      if (!deq.empty() and a - deq[0].a > -eps) return;
      while (deq.size() >= 2 and !need({a, b}, deq[0], deq[1])) {
        deq.pop_front();
      }
      deq.emplace_front(Line{a, b});
    } else if (a - deq.back().a > -eps) {
      if (a - deq.back().a < eps) return;
      while (deq.size() >= 2 and !need(deq[deq.size() - 2], deq.back(), {a, b})) {
        deq.pop_back();
      }
      deq.emplace_back(Line{a, b});
    } else assert(false);
  }
  T max(T x) {
    if(deq.empty()) return -inf;
    if (monotone_query) {
      while (deq.size() >= 2 and deq[0].a * x + deq[0].b <= deq[1].a * x + deq[1].b) {
        deq.pop_front();
      }
      return deq[0].a * x + deq[0].b;
    }
    int ok = 0, ng = deq.size();
    while (ng - ok > 1) {
      int m = ok + ng >> 1;
      (deq[m - 1].a * x + deq[m - 1].b <= deq[m].a * x + deq[m].b ? ok : ng) = m;
    }
    return deq[ok].a * x + deq[ok].b;
  }
};

int main() {
  cin.tie(nullptr); ios::sync_with_stdio(false);
  int n; cin >> n;
  double xz, vz; cin >> xz >> vz;
  V<double> x(n), v(n);
  for (int i = 0; i < n; ++i) {
    cin >> x[i] >> v[i];
    x[i] -= xz;
    v[i] -= vz;
  }

  V<double> res(n, inf);
  auto solve = [&]() -> void {
    V<> idx(n);
    iota(begin(idx), end(idx), 0);
    sort(begin(idx), end(idx), [&](int i, int j) { 
      if (abs(v[i] - v[j]) > eps) return v[i] > v[j]; 
      return x[i] - x[j] > eps;
    });
    ConvexHullTrick<double> cht;
    auto itr = begin(idx);
    for (int i : idx) if (x[i] > 0) {
      while (itr != end(idx) and v[*itr] - v[i] > eps) {
        if (x[*itr] < 0) {
          cht.add(v[*itr], x[*itr]);
        }
        ++itr;
      }
      if (v[i] < 0) {
        res[i] = x[i] / -v[i];
      }
      if (cht.deq.empty()) {
        continue;
      }
      auto fn = [&](const auto& l) -> double {
        assert(abs(l.a - v[i]) > eps);
        return (x[i] - l.b) / (l.a - v[i]);
      };
      int ok = 0, ng = cht.deq.size();
      while (ng - ok > 1) {
        int mid = ok + ng >> 1;
        (fn(cht.deq[mid - 1]) > fn(cht.deq[mid]) ? ok : ng) = mid;
      }
      res[i] = min(res[i], fn(cht.deq[ok]));
    }
  };

  solve();
  for (auto&& e : x) e = -e;
  for (auto&& e : v) e = -e;
  solve();

  for (auto e : res) {
    if (e == inf) {
      cout << -1 << '\n';
    } else {
      cout << fixed << setprecision(15) << e << '\n';
    }
  }
}

