#include <stdio.h>
#include <math.h>

int max(int a, int b)
{
    return a < b ? b : a;
}

int solveWithBruteForce(int p)
{
    int count = 0;

    for (int a = 1; a <= p / 3; ++a) {
        int b = max(a, (p - 2 * a) / 2 + 1);
        int c = p - a - b;
        while (c >= b) {
            // fprintf(stderr, "%d = %d + %d + %d\n", p, a, b, c);
            ++count;
            ++b;
            --c;
        }
    }

    return count;
}

int solveWithFormula(int p)
{
    long double f;
    
    if (p % 2 == 0) {
       f = (long double) (p * p) / 48;
    } else {
        f = (long double) ((p + 3) * (p + 3)) / 48;
    }

    return (int) llroundl(f);
}

