const long long MOD = 1000000007;

void solve(long long N, std::vector<long long> A) {
    std::vector<long long> B(N);
    for (int i = N - 2; 0 <= i; i--) {
        B[i] = B[i + 1] + A[i + 1];
        B[i] %= MOD;
    }
    long long ans = 0;
    rep (i, N) {
        ans += A[i] * B[i];
        ans %= MOD;
    }
    cout << ans << endl;
}

