using namespace std;
typedef long long LL;
const int MAXN = 200005;
const int MAXM = 1000005;
const int INF = 0x3f3f3f3f;

template <typename T> inline void read(T &AKNOI) {
    T x = 0, flag = 1;
    char ch = getchar();
    while (!isdigit(ch)) {
        if (ch == '-') flag = -1;
        ch = getchar();
    }
    while (isdigit(ch)) {
        x = x * 10 + ch - '0';
        ch = getchar();
    }
    AKNOI = flag * x;
}

int n, a[MAXN], b[MAXN], aid[MAXN], bid[MAXN], ID;
int S, T, level[MAXN], q[MAXN], head, tail, ans;

struct Edge {
	int v, w, nxt;
} e[MAXM << 1];
int first[MAXN], used[MAXN], eCnt;

inline void AddEdge(int u, int v, int w) {
	e[++eCnt].v = v;
	e[eCnt].w = w;
	e[eCnt].nxt = first[u];
	first[u] = eCnt;
}

inline void Add(int u, int v, int w) {
	AddEdge(u, v, w);
	AddEdge(v, u, 0);
}

bool BFS() {
	for (int i = 1; i <= T; ++i) {
		level[i] = -1;
		used[i] = first[i];
	}
	level[S] = 0;
	q[head = tail = 1] = S;
	while (head <= tail) {
		int u = q[head++];
		if (u == T) return 1;
		for (int i = first[u]; i; i = e[i].nxt) {
			int v = e[i].v;
			if (e[i].w && level[v] == -1) {
				level[v] = level[u] + 1;
				q[++tail] = v;
			}
		}
	}
	return 0;
}

int DFS(int u, int flow) {
	if (u == T) return flow;
	int ret = 0;
	for (int i = used[u]; i; i = e[i].nxt, used[u] = i) {
		int v = e[i].v;
		if (e[i].w && level[v] == level[u] + 1) {
			int tmp = DFS(v, min(flow, e[i].w));
			e[i].w -= tmp;
			e[i ^ 1].w += tmp;
			flow -= tmp;
			ret += tmp;
			if (!flow) break;
		}
	}
	return ret;
}

void init() {
	read(n);
	for (int i = 1; i <= n; ++i) {
		read(a[i]); ++a[i];
	}
	for (int i = 1; i <= n; ++i) {
		read(b[i]); ++b[i];
		ans += (a[i] != b[i]);
	}
	for (int i = 1; i <= n; ++i) {
		if (aid[i]) continue;
		++ID; int x = i;
		while (!aid[x]) {
			aid[x] = ID;
			x = a[x];
		}
	}
	for (int i = 1; i <= n; ++i) {
		if (bid[i]) continue;
		++ID; int x = i;
		while (!bid[x]) {
			bid[x] = ID;
			x = b[x];
		}
	}
}

void solve() {
	S = ID + 1; T = S + 1;
	eCnt = 1;
	for (int i = 1; i <= n; ++i) {
//printf("%d %d\n", aid[i], bid[i]);
		if (a[i] == b[i]) {
			if (a[i] == i) continue;
			++ans;
			Add(aid[i], bid[i], 1);
			Add(bid[i], aid[i], 1);
		} else {
			if (a[i] == i) {
				Add(S, bid[i], 1);
			} else if (b[i] == i) {
				Add(aid[i], T, 1);
			} else {
				Add(aid[i], bid[i], 1);
			}
		}
	}
	while (BFS()) {
		ans -= DFS(S, INF);
	}
	printf("%d\n", ans);
}

int main() {
	init();
	solve();
	return 0;
}

