        for (j = n - i - 2; j >= i; j--)
            a[n - i - 1][j] = k++;
            
        for (j = n - i - 2; j > i; j--)
            a[j][i] = k++;
    }
    if (n % 2 == 1)
        a[n / 2][n / 2] = k;

    for (i = 0; i < n; i++)
    {
