#define MAX 100
int queue[MAX];
int front = -1, rear = -1;
int isEmpty(){
    return (front == -1 && rear == -1);
}
int isFull(){
    return (rear == MAX -1);
}
void enqueue(int value){
    if(isFull()){
        printf("Queue is full");
        return;
    } else {
        if(front == -1){
            front = 0;
        }
        rear++;
        queue[rear] = value;
        printf("%d is enqueued", value);
    }
}

int dequeue(){
    if(isEmpty()){
        printf("Queue is empty");
        return -1;
    } else {
        int value = queue[front];
        if(front == rear){
            front = rear = -1;
        } else {
            front++;
        }
        return value;
    }
}
int peek(){
    if(isEmpty()){
        printf("Queue is empty");
        return -1;
    } else {
        return queue[front];
    }
}
int main(){
    enqueue(1);
    enqueue(2);
    enqueue(3);
    printf("Dequeued %d\n", dequeue());
    printf("Peeked %d\n", peek());
    return 0;
}

