public class MyLinkedList<E> {


//E is the Class defining the type of the inputs accepted
	Node<E> head;

	public void add(E data) {
		Node<E> toAdd = new Node<E>(data);

		if (isEmpty()) {
			head = toAdd;
			return;
		}

//initialising temp as head to traverse the Linked list without breaking the chain
		Node<E> temp = head;
      // control from loop exits as soon as next element becomes null
		while (temp.next != null) {

			temp = temp.next;
		}
    // adding the new node after reaching to the end of linked list
		temp.next = toAdd;
	}

	void print() {
		Node<E> temp = head;
		while (temp != null) {
			System.out.print(temp.data + " ");
			temp = temp.next;
		}
	}

	public boolean isEmpty() {
		return head == null;
	}

	public E removeLast() throws Exception {
		Node<E> temp = head;

		if (temp == null) {
			throw new Exception("Cannot remove last element from empty linked list");
		}

		if (temp.next == null) {
			Node<E> toRemove = head;
			head = null;
			return toRemove.data;
		}

		while (temp.next.next != null) {
			temp = temp.next;
		}
		Node<E> toRemove = temp.next;
		temp.next = null; // changing the pointer of temp.next from toRemove to null,and garbage collection is done automatically
		return toRemove.data;
	}

	public E getLast() throws Exception {
		Node<E> temp = head;

		if (temp == null) {
			throw new Exception("Cannot peek last element from empty linked list");
		}
		while (temp.next != null) {
			temp = temp.next;
		}
		return temp.data;
	}

	public static class Node<E> {
		public E data;
		public Node<E> next;

//constructor
		public Node(E data) {

			this.data = data;
			next = null;
		}
	}
}

def run_all_one(solution_class: type, operations: list[str], inputs: list[list[str]]):
    implementation = None
    results: list[str | None] = []
    for i, op in enumerate(operations):
        if op == "AllOne":
            implementation = solution_class()
            results.append(None)
        elif op == "inc" and implementation is not None:
            implementation.inc(inputs[i][0])
            results.append(None)
        elif op == "dec" and implementation is not None:
            implementation.dec(inputs[i][0])
            results.append(None)
        elif op == "get_max_key" and implementation is not None:
            results.append(implementation.get_max_key())
        elif op == "get_min_key" and implementation is not None:
            results.append(implementation.get_min_key())
    return results, implementation


def assert_all_one(result: list[str | None], expected: list[str | None]) -> bool:
    assert result == expected
    return True

