#define sz(a) (ll)(a.size())
const int M = 1002;
int ct[M][M],D;
vector<int> eth[M],bth[M];
int ind[M],deg[M];
bool f[M],fl[M];
int getVal(int z)
{
	set<int> st;
	multiset<int> mlt;
	int c = 0;
	for(int i=0;i<D;i++)
		if(fl[i])
			c++;
	for(int j=0;j<D;j++)
	{
		deg[j] = ind[j];
		if(deg[j] || f[j])
			st.insert(j);
	}
	for(auto it = st.begin(); it != st.end(); it++)
	{
		auto prev = it;
		if(it == st.begin())
			prev = --st.end();
		else
			prev--;
		int df = (*prev)-(*it)+D;
		mlt.insert(df%D);
	}
	int res = D;
	for(int j=0;j<D;j++)
	{
		int x = (z+j)%D;
		for(auto u: eth[x])
		{
			deg[u]--;
			if(deg[u] || f[u])
				continue;
			auto it = st.find(u);
			auto prev = it;
			auto next = it;
			if(it == st.begin())
				prev = --st.end();
			else
				prev--;
			if(it == --st.end())
				next = st.begin();
			else
				next++;
			int d1 = ((*prev)-(*it)+D)%D;
			int d2 = ((*it)-(*next)+D)%D;
			int d3 = ((*prev)-(*next)+D)%D;
			auto p = mlt.find(d1);
			if(p != mlt.end())
				mlt.erase(p);
			p = mlt.find(d2);
			if(p != mlt.end())
				mlt.erase(p);
			st.erase(u);
			if(sz(st))
				mlt.insert(d3);
		}
		if(fl[x])
			c--;
		if(c==0)
		{
			if(sz(mlt))
				res = min(res, max(j,*mlt.begin()));
			else
				res = min(res, j);
		}
	}
	return res;
}
int solve(int len)
{
	for(int i=0;i<D;i++)
	{
		for(int j=0;j<D;j++)
		{
			if(len*1LL*len >= ct[i][j])	
				continue;
			if((len+1)*1LL*len >= ct[i][j])
			{
				eth[i].pb(j);
				ind[j]++;
				continue;
			}
			if((len+1)*1LL*(len+1) >= ct[i][j])
			{
				f[j] = 1;
				fl[i] = 1;
				continue;
			}
			return -1;
		}
	}
	int res = D;
	for(int i=0;i<D;i++)
		res = min(res, getVal(i));
	return res;
}
