using namespace std;

int main(){
    int N,M;
    while(cin >> N >> M && N){
        vector<int> A(N+1,(int)1e9),B(N+1,(int)1e9);
        for(int i=1;i<=N;i++){
            cin >> A[i];
        }
        for(int i=1;i<=N;i++){
            cin >> B[i];
        }
        vector<vector<int>> dp(N+1,vector<int>(1010,(int) 1e9));
        vector<vector<int>> mi(N+1,vector<int>(1010,(int) 1e9));
        dp[0][0] = 0;
        for(int i=1;i<=N;i++){
            for(int j=0;j<=N;j++){
                int now = B[i]-A[i]+j*M;
                if(now<0) continue;
                int pre = B[i-1]-A[i-1]+j*M;
                if(pre>=0) dp[i][j] = min(dp[i][j],dp[i-1][j]+max(now-pre,0));
                if(j>=1){
                    for(int k=1;k<=2;k++){
                        pre = B[i-1]-A[i-1]+(j-k)*M;
                        if(pre>=0) dp[i][j] = min(dp[i][j],dp[i-1][j-k]+max(now-pre,0));
                    }
                }
                dp[i][j] = min(dp[i][j],mi[i-1][j+2]);
                pre = B[i-1]-A[i-1]+(j+1)*M;
                if(pre>=0) dp[i][j] = min(dp[i][j],dp[i-1][j+1]+max(now-pre,0));
            }
            for(int j=1000;j>=0;j--) mi[i][j] = min(mi[i][j+1],dp[i][j]);
        }
        cout << mi[N][0] << endl;
    }
}

