bool has_path_sum(struct TreeNode *root, int sum)
{
    if (NULL == root)  // only root trigger this
        return false;
    sum -= root->val;
    if (0 == sum && NULL == root->left && NULL == root->right)
        return true;
    return has_path_sum(root->left, sum) || has_path_sum(root->right, sum);
}

from functools import cache

from leetcode_py import TreeNode


class Solution:
    # Time: O(Catalan(n/2) * n)
    # Space: O(Catalan(n/2) * n)
    def all_possible_fbt(self, n: int) -> list[TreeNode[int] | None]:
        @cache
        def build(count: int) -> list[TreeNode[int] | None]:
            if count == 1:
                return [TreeNode(0)]
            trees: list[TreeNode[int] | None] = []
            for left_count in range(1, count - 1, 2):
                for left in build(left_count):
                    for right in build(count - 1 - left_count):
                        root = TreeNode(0)
                        root.left = left
                        root.right = right
                        trees.append(root)
            return trees

        if n % 2 == 0:
            return []
        return build(n)

class Solution:
    def search(self, nums: List[int], target: int) -> int:
        if nums[0] < nums[-1] or len(nums) == 1:
            return self.bin_search(nums, target)
        else:
            left, right = 0, len(nums) - 1
            while left <= right:
                index = (right + left) // 2
                if nums[index] >= nums[0]:
                    left = index + 1
                else:
                    right = index - 1
            if nums[left] > nums[right]:
                pivot = right
            else:
                pivot = left
            if nums[0] <= target <= nums[pivot - 1]:
                return self.bin_search(nums[:pivot], target)
            elif nums[pivot] <= target <= nums[-1]:
                index = self.bin_search(nums[pivot:], target)
                if index != -1:
                    return pivot + index
            return -1
        
    def bin_search(self, nums, target):
        left, right = 0, len(nums) - 1
        while left <= right:
            index = (right + left) // 2
            if nums[index] > target:
                right = index - 1
            elif nums[index] < target:
                left = index + 1
            else:
                return index
        return -1

