typedef complex<double> P;

double modf(double x){
  while(x>2*PI){
    x-=2*PI;
  }
  while(x<0){
    x+=2*PI;
  }
  return x;
}

double x,y,a,b;

double compute(double v,double m,double rate){
  double R=v/b;

  P target=polar(R,m);
  double distA=abs( target - P(x,y) ) / v;
  P base=target-P(x,y);
  P p = P(x,y) + ( base * rate );
  double f = modf(arg(p)) - distA*b*rate;
  
  return f;
}

double check(double v,double m){
  double left=0,right=1,midL,midR;
  
  for(int i=0;i<100;i++){
    double dist=( right-left ) /3.0;
    midL=left+dist;
    midR=right-dist;
    
    double fl = compute(v,m,midL);
    double fr = compute(v,m,midR);
    
    if( fl < fr ){
      right=midR;
    }else{
      left=midL;
    }
  }

  return compute(v,m,left);
}

