int calck(int a, int b){
  if(a > b)swap(a,b);
  return b/(a+1) + (b % (a+1) != 0);
}

void solve(){
  Int a, b, c, d;
  cin >> a >> b >> c >> d;
  int k = calck(a, b);
  int bottom = 0, top = a+b;
  if((a+b)/(k+1) == a)top = 0;
  if((a+b)/(k+1) == b)bottom =a+b;
  while(top - bottom > 1){
    int mid = (top + bottom) / 2;
    int l = mid;
    while(l > 0 && l % (k+1) == k && (a+b-l) % (k+1) == 0 && (a+b-l) > 0 || l % (k+1) == 0 && l > 0 && (a+b-l) % (k+1) == k)l--;
    if(l / (k+1) * k + l % (k+1) + (a+b-l) / (k+1) >= a)top = mid;
    else bottom = mid;
  }
  int l = top;
  if(l % (k+1) == k && (a+b-l) % (k+1) == 0 && (a+b-l) > 0)l--;
  else if(l % (k+1) == 0 && l > 0 && (a+b-l) % (k+1) == k)l--;
