using namespace std;

const int MAX_LEN = 6;
const int MAX_N = 40;
const int LIMIT = MAX_LEN * MAX_N;
const string INF(LIMIT, 'z');

struct edge {
	int to;
	string cost;
	edge(int t, const string& c):to(t), cost(c){}
};

bool to_goal[MAX_N];
vector<vector<edge> > es;

string dijkstra(int s, int g) {
	typedef pair<string, int> P;
	const int n = es.size();
	vector<vector<string> > dist(n, vector<string>(LIMIT + MAX_LEN + 1, INF));
	dist[s][0] = "";
	priority_queue<P, vector<P>, greater<P> > que;
	que.push(make_pair("", s));

	while(!que.empty()) {
		const string spell = que.top().first;
		const int v = que.top().second, len = spell.size();
		que.pop();

		if(!to_goal[v] || dist[v][len] != spell)
			continue;

		if(len > LIMIT)
			return "NO";

		if(v == g)
			return spell;

		for(int i = 0; i < es[v].size(); ++i) {
			const edge& e = es[v][i];
			const string next_spell = spell + e.cost;
			const int next_len = next_spell.size();
			if(dist[e.to][next_len] > next_spell) {
				dist[e.to][next_len] = next_spell;
				que.push(make_pair(next_spell, e.to));
			}
		}
	}

	return "NO";
}

int main() {
	cin.tie(0);
	ios::sync_with_stdio(false);

	for(int n, a, s, g; cin >> n >> a >> s >> g, n;) {
		es.clear();
		es.resize(n);
		for(int i = 0; i < a; ++i) {
			int x, y;
			string lab;
			cin >> x >> y >> lab;
			es[x].push_back(edge(y, lab));
		}

		memset(to_goal, false, sizeof(to_goal));
		to_goal[g] = true;
		for(int i = 0; i < n; ++i)
			for(int j = 0; j < n; ++j)
				for(int k = 0; k < (int)es[j].size(); ++k)
					if(to_goal[es[j][k].to])
						to_goal[j] = true;

		cout << dijkstra(s, g) << endl;
	}

	return EXIT_SUCCESS;
}

class Solution {
    public String alienOrder(String[] words) {
        if (words == null || words.length == 0) {
            return "";
        }
        HashMap<Character, HashSet<Character>> graph = new HashMap<>();
        int[] inDegreeMap = new int[26]; //to keep a track of indegrees to a 
        // character
            /* according to given dictionary with specified order, traverse every pair of words,
         * then put each pair into graph map to build the graph, and then update inDegree map
         * for every "nextChar" (increase their inDegree by 1 every time) */
        for (String s: words) {
            for( char x: s.toCharArray()) {
                graph.putIfAbsent(x, new HashSet<>());
            }
        }
    for (int i=0; i< words.length - 1; i++) {
        String first = words[i];
        String second = words[i+1];
        int len = Math.min(first.length(), second.length());
        for (int j=0; j<len; j++) {
            if (first.charAt(j) != second.charAt(j)) {
                char f = first.charAt(j);
                char s = second.charAt(j);
                if (!graph.get(f).contains(s)) {
                    graph.get(f).add(s);
                    inDegreeMap[(int)(s - 'a')]++;
                }
            }
            break;
        }
    }
        // Doing a BFS but putting all starting nodes i.e ones with inDegree 0 in the queue
        // and then exploring their neighbours, if we get indegree 0, we add to queue to 
        // further evaluate.
        Queue<Character> q = new LinkedList<>();
        StringBuilder sb = new StringBuilder();
        for (char c: graph.keySet()) {
            if (inDegreeMap[(int)(c-'a')] == 0) {
                q.offer(c);
            }
        }

        while(!q.isEmpty()) {
            char out = q.poll();
            sb.append(out);
            if (graph.get(out) == null) {
                continue;
            }
            System.out.println(out);
            for (char neighbour: graph.get(out)) {
                inDegreeMap[(int)(neighbour -'a')]--;
                if (inDegreeMap[(int)(neighbour - 'a')] == 0) {
                    q.offer(neighbour);
                }
            } 
        }
        return sb.length() == graph.size() ? sb.toString() : "";
    }
}

