struct FFT{ // just call multiply
    typedef pair<double, double> com;
    int n;
    vector<com> a, b;
    vector<com> f[2];
    void init(vector<int>& p, vector<int>& q, int x){
        n = 1;
        while(n < x) n *= 2;
        a.resize(n, com(0,0));
        b.resize(n, com(0,0));
        rep(i,2) f[i].resize(n, com(0,0));
        rep(i,p.size()) a[i] = com(p[i],0);
        rep(i,q.size()) b[i] = com(q[i],0);
    }

    inline com com_add (com a, com b) {
        return com(a.first+b.first, a.second+b.second);
    }

    inline com com_mul (com a, com b) {
        return com(a.first*b.first-a.second*b.second, a.first*b.second+a.second*b.first);
    }
    
    vector<com> dft(vector<com>& v, bool rev){
        int x = n, u = 0;
        f[0] = v;
        int ho = 0, ge = 1;
        for(int i = 2; i <= n; i <<= 1){
            u++; x >>= 1;
            com zeta;
            if(!rev) zeta = com(cos(2*PI/i),sin(2*PI/i));
            else zeta = com(cos(2*PI/i),-sin(2*PI/i));
            com pz;
            rep(j,x){
                pz = com(1,0);
                rep(k,i){
                    if(k>=i/2) f[ge][j*i+k] = com_add(f[ho][j*(i/2)+k-i/2],com_mul(pz,f[ho][j*(i/2)+n/2+k-i/2]));
                    else f[ge][j*i+k] = com_add(f[ho][j*(i/2)+k],com_mul(pz,f[ho][j*(i/2)+n/2+k]));
                    pz = com_mul(pz, zeta);
                }
            }
            swap(ho,ge);
        }
        return f[ho];
    }
    
    vector<com> multiply(vector<int>& p, vector<int>& q){ // x: max degree
        a.clear(); b.clear(); f[0].clear(); f[1].clear();
        int x = p.size() + q.size()+1;
        init(p,q,x);
        a = dft(a,0);
        b = dft(b,0);
        rep(i,n) a[i] = com_mul(a[i],b[i]);
        a = dft(a,1);
        rep(i,n) a[i] = com(a[i].first/n, a[i].second/n);
        return a;
    }
} fft;

