	temp1=temp1-p;
	temp1/=2;
	ll minn=temp1*w;
	ll fans=maxx-minn;
	temp2/=2;
	temp1=h-p;
	ll ntemp=maxx;
	maxx=max(maxx,(temp2*temp1));
	minn=min(ntemp,(temp2*temp1));
	if(w%2)
	{
