        while (true) {
            if (snakeLength == hamiltonianIndex - 1) {
                System.out.println("Game Over");
                System.out.println("Score = " + snakeLength);
                break;
            }
            try {
                switch (mode) {
                    case 0 -> movement();

                    case 1 -> pathFindingAi();

                    case 2 -> hamiltonianPath();

                }
            } catch (Exception e) {
