//Knuth-Morris-Pratt algoritam za string matching
//Slozenost: O(N + M)

inline void KMP()
{
    for (int i=0;i<m;i++) P[i] = -1;
    for (int i=0, j=-1;i<m;)
    {
        while (j > -1 && needle[i] != needle[j]) j = P[j];
        i++;
        j++;
        P[i] = j;
    }
    for (int i=0, j=0;i<n;)
    {
        while (j > -1 && haystack[i] != needle[j]) j = P[j];
        i++;
        j++;
        if (j == m)
        {
            matches.push_back(i - m);
            j = P[j];
        }
    }
}

