int nonRepeating(int *arr, int size){
	std::map<int, int> m;
	std::map<int,int>::iterator it;
	for(int i = 0; i < size; ++i){
		it = m.find(arr[i]);
		if( it != m.end()){
			m[arr[i]] = ++(it->second);
		}
		else{
			m[arr[i]] = 1;
		}
	}

	for(int i = 0; i < size; ++i){
		it = m.find(arr[i]);
		if( it != m.end()){
			if(it->second == 1)
				return arr[i];
		}
	}
	return -1;

}

