#         self.right = right
class Solution:
    def searchBST(self, root, val):
      if not root:
        return root
      
      if root.val == val:
        return root
      
      elif root.val > val:
        return self.searchBST(root.left, val)
      else:
        return self.searchBST(root.right, val)

