BUBBLE SORT

Elements are compared in pairs to see if they are sorted, if not they are swapped
In each iteration one greatest element moves to its correct position.
It can be remembered as in each iteration the bubble(largest element) comes to the top (last in array)

Time Complexity:
Best case: O(n) -- already sorted just checking by looping once or for value very less than n
Worst case: O(n^2) -- nested loop

Space Complexity:
O(1)

*/
#include <stdio.h>
#include <math.h>

int main(){

	int a[] = {9,6,5,4,0,7,3,5,11};
	int length = sizeof(a)/sizeof(a[0]);
	int swapped,i,j;
	for(i=0; i<length;i++){
		swapped = 0;
		for(j=0;j<length-i-1;j++){
			if(a[j] > a[j+1]){
				int temp = a[j+1];
				a[j+1] = a[j];
				a[j] = temp;
				swapped = 1;
			}
		}
		if(swapped == 0){
			break;
		}
	}

	printf("sorted array is\n");
	for(int z=0; z<length; z++){
		printf("%d ", a[z]);
	}

}

/* C Program to implement a queue using two stacks */
#include <stdio.h>
#include <stdlib.h>

/* structure of a stack node */
struct sNode
{
    int data;
    struct sNode *next;
};

/* Function to push an item to stack*/
void push(struct sNode **top_ref, int new_data);

/* Function to pop an item from stack*/
int pop(struct sNode **top_ref);

/* structure of queue having two stacks */
struct queue
{
    struct sNode *stack1;
    struct sNode *stack2;
};

/* Function to enqueue an item to queue */
void enQueue(struct queue *q, int x)
{
    push(&q->stack1, x);
}

/* Function to deQueue an item from queue */
int deQueue(struct queue *q)
{
    int x;

    /* If both stacks are empty then error */
    if (q->stack1 == NULL && q->stack2 == NULL)
    {
        printf("Q is empty");
        getchar();
        exit(0);
    }

    /* Move elements from stack1 to stack 2 only if
       stack2 is empty */
    if (q->stack2 == NULL)
    {
        while (q->stack1 != NULL)
        {
            x = pop(&q->stack1);
            push(&q->stack2, x);
        }
    }

    x = pop(&q->stack2);
    return x;
}

/* Function to push an item to stack*/
void push(struct sNode **top_ref, int new_data)
{
    /* allocate node */
    struct sNode *new_node = (struct sNode *)malloc(sizeof(struct sNode));
    if (new_node == NULL)
    {
        printf("Stack overflow \n");
        getchar();
        exit(0);
    }

    /* put in the data */
    new_node->data = new_data;

    /* link the old list off the new node */
    new_node->next = (*top_ref);

    /* move the head to point to the new node */
    (*top_ref) = new_node;
}

/* Function to pop an item from stack*/
int pop(struct sNode **top_ref)
{
    int res;
    struct sNode *top;

    /*If stack is empty then error */
    if (*top_ref == NULL)
    {
        printf("Stack underflow \n");
        getchar();
        exit(0);
    }
    else
    {
        top = *top_ref;
        res = top->data;
        *top_ref = top->next;
        free(top);
        return res;
    }
}

int main()
{
    /* Create a queue with items 1 2 3*/
    struct queue *q = (struct queue *)malloc(sizeof(struct queue));
    q->stack1 = NULL;
    q->stack2 = NULL;
    enQueue(q, 1);
    enQueue(q, 2);
    enQueue(q, 3);

    /* Dequeue items */
    printf("%d ", deQueue(q));
    printf("%d ", deQueue(q));
    printf("%d ", deQueue(q));

    return 0;
}

#include <cstdio>

#define INF 1000000000
#define VERTEX_COUNT 1000
#define EDGE_COUNT 1000

using namespace std;

struct vertex
{
	int first, dis;
}V[VERTEX_COUNT];

struct edge
{
	int endp, next, flow;
}E[EDGE_COUNT];

int ec = 2, iec, ivc, src, sink;

inline int min(int x, int y)
{
	return x < y ? x : y;
}

void add_edge(int u, int v, int f)
{
	E[ec].next = V[u].first;
	V[u].first = ec;
	E[ec].endp = v;
	E[ec].flow = f;
	ec++;
}

int DFS(int u, int curf)
{
	if (u == sink)
	{
		return curf;
	}
	int totalf = 0, mindis = INF;
	for (int cur = V[u].first; cur != 0 && totalf < curf; cur = E[cur].next)
	{
		if (E[cur].flow > 0)
		{
			if (V[u].dis == V[E[cur].endp].dis + 1)
			{
				int t = DFS(E[cur].endp, min(curf - totalf, E[cur].flow));
				E[cur].flow -= t;
				E[cur ^ 1].flow += t;
				totalf += t;
			}
			mindis = min(mindis, V[E[cur].endp].dis);
		}
	}
	if (totalf == 0)
	{
		V[u].dis = mindis + 1;
	}
	return totalf;
}

int max_flow()
{
	int res = 0;
	while (V[src].dis < ivc)
	{
		res += DFS(src, INF);
	}
	return res;
}

int main()
{
	int u, v, f;
	scanf("%d%d", &iec, &ivc);
	for (int i = 0; i < iec; i++)
	{
		scanf("%d%d%d", &u, &v, &f);
		add_edge(u, v, f);
		add_edge(v, u, 0);
	}
	src = 1;
	sink = ivc;
	printf("%d", max_flow());
	return 0;
}

# Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def bstFromPreorder(self, preorder: List[int]) -> Optional[TreeNode]:
        root = TreeNode(preorder[0])
        
        stack = [root]
        for n in preorder[1:]:
            
            if n < stack[-1].val:
                stack[-1].left = TreeNode(n)
                stack.append(stack[-1].left)
            
            else:
                
                while stack and stack[-1].val < n:
                    parent = stack.pop()
                
                parent.right = TreeNode(n)
                stack.append(parent.right)
                
        return root

/*
 Title: Sum of Nodes Using Recursion
 Author: Inam Ul Haq

 Description:
	This program calculates the sum of all nodes in a singly linked list
	using a recursive approach. The linked list is traversed node by node
	by making recursive function calls until the pointer reaches NULL.
	Each recursive call adds the data of the current node to the sum
	returned by the next call.

 Working:
	- If the current node is not NULL, the function calls itself with the
	  next node and adds the current node's data.
	- If the pointer becomes NULL, the function returns 0 (base case).

 Time Complexity:
	The function visits each node exactly once.
	For n nodes, there will be n recursive calls.
	Therefore, the time complexity is O(n).

 Space Complexity:
	Due to recursion, each function call occupies stack space.
	For n nodes, n stack frames are created.
	Therefore, the space complexity is O(n).
*/



#include <stdio.h>
#include <stdlib.h>
struct Node{
	int data;
	struct Node* next;
};

void initNode(struct Node *newNode,int value){
	newNode->data=value;
	newNode->next=NULL;
}
struct Node* insertAtBeginning(struct Node *head,int value){
	struct Node *newNode=malloc(sizeof(struct Node));
	if(!newNode){
		printf("Memory allocation failed!\n");
		exit(1);
	}
	initNode(newNode,value);
	if(head){
		newNode->next=head;
	}
	return newNode;
}

int nodesSum(struct Node *head){
	if(head){
		return nodesSum(head->next)+head->data;
	}else{
		return 0;
	}
}
void freeNodes(struct Node *head){
	if(head){
		freeNodes(head->next);
		free(head);
	}
}
int main(){
	struct Node *head=NULL;
	for(int i=0;i<10;i++){
		int value;
		printf("Enter value: ");
		scanf("%d",&value);
		head=insertAtBeginning(head,value);
	}
	
	int sum=nodesSum(head);
	printf("Sum of Nodes: %d\n",sum);
	
	freeNodes(head);
	return 0;
}

