				a[i] = i;
			}
		}
		friend Perm operator*(const Perm &a, const Perm &b) {
			Perm ret;
			ret.n = a.n;
			for (int i = 1; i <= ret.n; ++i) {
				ret.a[i] = b.a[a.a[i]];
			}
			return ret;
		}
		friend Perm operator^(Perm base, LL k) {
			Perm ret;
			for (ret.init(base.n); k; k >>= 1, base = base*base) {
				if (k&1) {
					ret = base*ret;
				}
			}
