/*Implementation of Counting sort in C. This implementation works only 
	with integers.*/
#include <stdio.h>
#include <stdlib.h>
void counting_sort(int [], int);
int find_max(int [], int);
void print_array(int [], int);

int main(){
	puts("-----Counting Sort-----");
	int a[] = {0, 3, 2, 3, 3, 0, 5, 2, 3};
	int length = sizeof(a) / sizeof(int);
	
	printf("Unsorted: ");
	print_array(a, length);
	counting_sort(a, length);
	
	printf("Sorted: ");
	print_array(a, length);
	
	return EXIT_SUCCESS;
}
void counting_sort(int a[], int length){
	/*for a[] = {0, 3, 2, 3, 3, 0, 5, 2, 3} range will be	0, ... , 5. 
		So we will need 6 spots in our new sub-array which is max + 1*/
	int i, max = find_max(a, length);
	int c[max+1];
	
	for(i = 0; i < max + 1; c[i++] = 0); // first c[i] = 0 will be done, then i++;
	
	for(i = 0; i < length; i++) c[a[i]]++;
	
	for(i = 1; i < max + 1; i++) c[i] = c[i - 1] + c[i];
	
	
	int b[length]; //this is gonna be our new sorted array
	int j = length - 1;
	for(i = 0; i < length; i++) {
		b[--c[a[j]]] = a[j];
		j--;
	}	
	
	/*Right now B represents sorted array of A. But i want to change A (original) 
		so i will overwrite B over A array.*/
	for(i = 0; i < length; i++)	a[i] = b[i];

}
int find_max(int a[], int length){
	int i, max = a[0];
	for(i = 1; i < length; i++) {
		if(max < a[i]) max = a[i];
	}
	return max;
}
void print_array(int a[], int length){
	int i = 0;
	putchar('[');
	do {
		if(i > 0) printf(", ");
		printf("%d", a[i]);
	} while(++i < length);
	puts("]");
}

function Node(data) {
    this.data = data;
    this.left = null;
    this.right = null;
}

class BinarySearchTree {
    constructor() {
        this.root = null;
    }

    add(data) {
        const node = new Node(data);

        if (!this.root) {
            // Set root node if there are no nodes
            this.root = node;
        } else {
            this.insertNode(node)
        }
    }

    insertNode(node) {
        let current = this.root;

        while (current) {
            // Nodes data is smaller than current node's data
            if (node.data < current.data) {
                // There is no node at current's left pointer
                if (!current.left) {
                    current.left = node;
                    break;
                }
                // Loop until !current.left returns true
                current = current.left
            } else if (node.data > current.data) {
                if (!current.right) {
                    current.right = node;
                    break;
                }

                current = current.right;
            } else
                break;
        }
    }

    remove(data) {
        this.root = this.removeNode(this.root, data);
    }

    removeNode(node, data) {
        if (!node) {
            return null;
        }

        if (data === node.data) {
            if (!node.left && !node.right) {
                return null
            }

            if (!node.left) {
                return node.right;
            }

            if (!node.right) {
                return node.left;
            }

            const temp = this.getMin(node.right);
            node.data = temp;

            node.right = this.removeNode(node.right, temp);
            return node;
        } else if (data < node.data) {
            node.left = this.removeNode(node.left, data);
            return node;
        } else {
            node.right = this.removeNode(node.right, data);
            return node;
        }
    }

    getMin(node) {
        if (!node) {
            node = this.root;
        }

        while (node.left) {
            node = node.left;
        }

        return node.data;
    }

    preOrder(node, fn) {
        if (node) {
            if (fn) {
                fn(node);
            }

            this.preOrder(node.left, fn);
            this.preOrder(node.right, fn);
        }
    }

    traverseDFS(cb, method) {
        const current = this.root;

        if (method) {
            this[`${method}`](current, cb);
        } else {
            this.preOrder(current, cb);
        }
    }

    printDFS() {
        this.traverseDFS((node) => {
            console.log(
                `Node.data: ${node.data}`,
                `Node.left: ${node.left ? node.left.data : null}`,
                `Node.right: ${node.right ? node.right.data : null}`
            )
        })
    }
}

