            bool ok = B.size() == 2;
            for(int j=2; i+j+1<A.size() && j+1<B.size(); j += 2) {
                if(j == B.size() - 2) {
                    if(A[i+j] == B[j] && stoi(A[i+j+1]) >= stoi(B[j+1])) {
                        ok = true;
                        break;
                    }
                } else if(A[i+j] != B[j] || stoi(A[i+j+1]) != stoi(B[j+1])) {
                    break;
                }
            }
