            cout << res[i] << endl;
          }
          cout << "#" << endl;
          res = vector<string>(plen);
          cnt = 0;
        }
      }
    }
    if (cnt) {
      while(cnt < plen * cnum) {
        if (cnt >= plen) {
          res[cnt%plen] += string(cspace, '.');
        }
        res[cnt%plen] += string(width, '.');
        cnt++;
      }
      REP(i,plen)
        cout << res[i] << endl;
      cout << "#" << endl;
    }
    cout << "?" << endl;
  }
}

