    if (s[0] == t[0]) return -1;
    int ans = -1;
    {
        L l1 = L(t[0], s[0]);
        L l2 = L(s[2], s[1]);
        if (!sgncrs(l1.vec(), l2.vec())) {
            auto s2 = s;
            s2[0] = t[0];
            ans = max(ans, dfs(s2, t, rem-1));
        }
    }

    for (int ph = 0; ph < 2; ph++) {
        int x = 1, y = 2;
        if (ph) swap(x, y);
        //move x
        L l1 = L(s[y], s[y] + (t[0] - s[0]));
        L l2 = L(s[x], s[x] + (s[0] - s[y]));
        if (sgncrs(l1.vec(), l2.vec())) {
            P p;
            assert(crossLL(l1, l2, p));
            auto s2 = s;
            s2[x] = p;
            ans = max(ans, dfs(s2, t, rem-1));
        }
    }
    return ans;
}

int dfs(T s, T t, int rem) {
    bool ok = true;
    for (int i = 0; i < 3; i++) {
        if (s[i] != t[i]) {
            ok = false;
            break;
        }
    }
    if (ok) return rem;
    int ans = -1;
    for (int i = 0; i < 3; i++) {
        for (int j = 0; j < 3; j++) {
            ans = max(ans, dfs2(s, t, rem));
            rotate(begin(t), begin(t)+1, end(t));
        }
        rotate(begin(s), begin(s)+1, end(s));
    }
    return ans;
}

bool solve() {
    T s, t;
    for (int i = 0; i < 3; i++) {
        D x, y;
        if (!(cin >> x >> y)) return false;
        s[i] = P(x, y);
    }
    for (int i = 0; i < 3; i++) {
        D x, y;
        if (!(cin >> x >> y)) return false;
        t[i] = P(x, y);
    }
    if (cross(s[1] - s[0], s[2] - s[0]) < 0) swap(s[1], s[2]);
    if (cross(t[1] - t[0], t[2] - t[0]) < 0) swap(t[1], t[2]);

    int res = 4 - dfs(s, t, 4);
    if (res > 4) cout << "Many" << endl;
    else cout << res << endl;

    return true;
}


