void bucketSort(float a[], int n)
{
    vector<float> t[n];

    for (int i=0; i<n; i++)
    {
       int x = n*a[i];
       t[x].push_back(a[i]);
    }

    for (int i=0; i<n; i++)
       sort(t[i].begin(), t[i].end());

    int k= 0;
    for (int i = 0; i < n; i++)
        for (int j = 0; j < t[i].size(); j++)
          a[k++] = t[i][j];
}

