    return 0;
}

void Enqueue(int element)
{
    if(is_empty())
    {
        front = rear = 0;
    } else {
        rear = (rear+1)%MAXSIZE;
    }
    queue[rear] = element;
}

int Dequeue()
{
    int temp;
    if(front == rear){
        temp = queue[front];
        front = rear = -1;
    } else {
        temp = queue[front];
        front = (front+1)%MAXSIZE;
    }

    return temp;
}

