        for(trav = Q; *trav != -1; trav = &V->VHNode[*trav].next) {}
        int temp = mallocVH(V);
        if(temp != -1) {
            V->VHNode[temp].elem.data = data;
            V->VHNode[temp].next = -1;
            *trav = temp;
        }
    }
}


