void initVH(VHeap *V) {
    V->avail = 0;

    for(int i = 0; i < VHSIZE; i++) {
        V->VHNode[i].next = i + 1;
    }

    V->VHNode[VHSIZE - 1].next = -1;
}

int mallocVH(VHeap *V) {
    int temp = -1;

    if(V->avail != -1) {
        temp = V->avail;
        V->avail = V->VHNode[temp].next;
    }

    return temp;
}

void freeVH(VHeap *V, int index) {
    if(index > 0 && index < VHSIZE) {
        V->VHNode[index].next = V->avail;
        V->avail = index;
    }
}

