void binarySearch(int s, int arr[], int num)
{	
	int i, last, first, mid;

	first = 0;
	last = s-1;
	mid = (last + first)/2;

	while(first <= last)
	{
		if (num == arr[mid])
		{
			printf("\n Element found at position : %d", mid+1);
			break;
		}
		else if (num > arr[mid])
		{
			first = mid + 1;
		}
		else if (num < arr[mid])
		{
			last = mid - 1;
		}
		
		mid = (first + last)/2;
	}

	if (first > last)
	{
		printf("\n Element not found :(");
	}

	printf("\n\n");
}


