using namespace std;
using LL = long long;

LL N,K;
const LL MOD = 1000000007ll;

LL m_pow(LL a,LL x)
{
    if(x == 0)return 1;
    LL half = m_pow(a,x/2);
    half *= half;
    half %= MOD;
    return (half * (x % 2 ? a : 1))%MOD;
}

map<LL,LL>memo;
LL dp(LL d)
{
    if(memo.count(d))return memo[d];
    LL res = m_pow(K,(d+1)/2);
    vector<int>div;
    for(int i = 1;i * i <= d;++i)
    {
        if(d % i == 0)
        {
            div.push_back(i);
            if(d/i != i)div.push_back(d/i);
        }
    }
    for(int dash : div)
    {
        if(dash == d)continue;
        res -= dp(dash);
        res += MOD;
        res %= MOD;
    }
    return memo[d] = res;
}

int main()
{
    cin >> N >> K;
    dp(N);
    LL ans = 0;
    for(auto p : memo)
    {
        LL index = p.first;
        LL value = p.second;
        if(index % 2 == 0)
        {
            value *= index / 2;
        }
        else
        {
            value *= index;
        }
        /*
        cerr << index << endl;
        cerr << value << endl;
        //*/
        value %= MOD;
        ans += value;
        ans %= MOD;
    }
    cout << ans << endl;
    return 0;
}

