function result(v, w, ts) {
  //console.log(v, w, ts);
  if (ts.length === 0) {
    return [v, w];
  }
  var s = ts.concat();
  var a = s.shift();
  if (a[1] > w) {
    return result(v, w, s);
  }
  return comp(result(v + a[0], w - a[1], s), result(v, w, s))
}

function comp(a, b) {
  if (a[0] > b[0]) {
    return a;
  } else if (a[0] < b[0]) {
    return b;
  } else if (a[1] > b[1]) {
    return a;
  } else {
    return b;
  }
}

# Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def binaryTreePaths(self, root: Optional[TreeNode]) -> List[str]:
      ans = []
      def dfs(root, path):

        if not root.left and not root.right:
          path = "".join(path) + str(root.val)
          ans.append(path)
          return 
        path.append(str(root.val) + "->")
        if root.left:
          dfs(root.left,path)
        if root.right:
          dfs(root.right,path)
        path.pop()
          
      if root.left:
        dfs(root.left, [str(root.val) + "->"])
      if root.right:
        dfs(root.right, [str(root.val) + "->"])
      
      if not root.left and not root.right:
        ans.append(str(root.val))
      return ans

