    result = 0
    
    for i in arr:
        idx = pos_lsd(i)
        if idx not in my_dict:
            my_dict[idx] = [i]
        else: my_dict[idx] += [i]

    for x in my_dict.values():
        if len(x) > 1:
            result += (len(x)*(len(x)-1)//2)
    
