import java.util.Arrays;

public class QuickSort {

	static int[] arr = {5, 1, 1, 2, 1, 4, 4, 4, 5, 5};

	public static void main(String[] args) throws Exception {

		quickSort(arr, 0, arr.length-1);

		System.out.println(Arrays.toString(arr));

	}

	public static void quickSort(int[] arr, int start, int end) {

		if(start >= end) return;

		if(start < end) {

			int i = start-1;
			int j = end+1;
			int pivot = arr[(start+end)/2];

			while(i < j) {

				while(arr[++i] < pivot) {}
				while(arr[--j] > pivot) {}

				if (i >= j) break;

				int temp = arr[i];
				arr[i] = arr[j];
				arr[j] = temp;
			}

			quickSort(arr, start, i-1);
			quickSort(arr, j+1, end);
		}

	}
}

#include <cstdio>
#include <cstring>

#define NIL 0

using namespace std;

struct node
{
	int info;
	node *next[26];
};

node root;

void insert(char *s)
{
	int l = strlen(s);
	node *cur = &root;
	for (int i = 0; i < l; i++)
	{
		if (cur->next[s[i] - 'a'] == NIL)
		{
			node *o = new node;
			o->info = 0;
			cur->next[s[i] - 'a'] = o;
		}
		cur = cur->next[s[i] - 'a'];
	}
	cur->info++;
}

int find(char *s)
{
	int l = strlen(s);
	node *cur = &root;
	for (int i = 0; i < l; i++)
	{
		if (cur->next[s[i] - 'a'] == NIL)
		{
			return -1;
		}
		else
		{
			cur = cur->next[s[i] - 'a'];
		}
	}
	return cur->info;
}

int main()
{
	int in;
	char str[100];
	while (true)
	{
		scanf("%d", &in);
		if (in == 1)
		{
			scanf("%s", str);
			insert(str);
		}
		else if (in == 2)
		{
			scanf("%s", str);
			printf("%d\n", find(str));
		}
		else if (in == 0)
		{
			return 0;
		}
		else
		{
			printf("No such command!\n");
		}
	}
	return 0;
}

