#include <stdio.h>
#include <stdlib.h>

// Define structure for circular doubly linked list node
struct node {
    int data;
    struct node *next;
    struct node *prev;
};

struct node *head = NULL;

// Function to insert at the end
void insertion_last() {
    struct node *ptr, *temp;
    int item;

    ptr = (struct node *)malloc(sizeof(struct node));
    if (ptr == NULL) {
        printf("\nOVERFLOW\n");
        return;
    }

    printf("\nEnter value: ");
    scanf("%d", &item);
    ptr->data = item;

    if (head == NULL) {
        head = ptr;
        ptr->next = head;
        ptr->prev = head;
    } else {
        temp = head;
        while (temp->next != head)
            temp = temp->next;

        temp->next = ptr;
        ptr->prev = temp;
        ptr->next = head;
        head->prev = ptr;
    }

    printf("\nNode inserted at the end.\n");
}

// Function to delete from beginning
void deletion_beginning() {
    struct node *temp;

    if (head == NULL) {
        printf("\nUNDERFLOW\n");
    } else if (head->next == head) {
        temp = head;
        head = NULL;
        free(temp);
        printf("\nOnly node deleted.\n");
    } else {
        temp = head;
        while (temp->next != head)
            temp = temp->next;

        temp->next = head->next;
        head->next->prev = temp;

        struct node *toDelete = head;
        head = head->next;
        free(toDelete);

        printf("\nFirst node deleted.\n");
    }
}

// Function to display the list
void display() {
    struct node *temp;
    if (head == NULL) {
        printf("\nList is empty.\n");
        return;
    }

    temp = head;
    printf("\nCircular Doubly Linked List: ");
    do {
        printf("%d <-> ", temp->data);
        temp = temp->next;
    } while (temp != head);
    printf("(head)\n");
}

