int binarySearch(int array[], int low, int high, int item)
{
    while (low <= high)
    {
        int mid = low + (high - low) / 2;
        if (array[mid] == item){
            return mid;
        }
        else if (array[mid] < item){
            low = mid + 1;
        }
        else{
            high = mid - 1;
        }
    }
    return -1;
}

