	}

	private static int getLongestChain(Pair[] pairs, int[] dp) {
		// TODO Auto-generated method stub
		for(int i = 1 ; i < pairs.length; i++){
			int maxValue = 1;
			for(int j = 0; j < i ; j++){
				if(pairs[j].y < pairs[i].x){
					maxValue = Utils.max(maxValue, dp[j] + 1);
				}
			}
			dp[i] = maxValue;
		}
		Utils.printArray(dp);
		return Utils.maxArray(dp);
	}

