class qList {
  constructor() {
    this.head = null
    this.tail = null
    this.size = 0
  }

  enqueue(data) {
    const nodeData = new Node(data)
    if (this.head == null) {
      this.head = nodeData
      this.tail = nodeData
    } else {
      this.tail.next = nodeData
      this.tail = nodeData
    }
    this.size++
  }

  dequeue() {
    this.head = this.head.next
    this.size--
  }

  isEmpty() {
    return this.size === 0
  }

  getSize() {
    return this.size
  }

  print() {
    let curr = this.head
    while (curr) {
      console.log(curr.data);
      curr = curr.next
    }
  }
  peek() {
    return this.head.data
  }

}

