class Queue {
  constructor() {
    this.items = []
  }

  enqueue(val) {
    this.items.push(val)
  }

  dequeue() {
    return this.items.shift()
  }

  isEmpty() {
    return this.items.length === 0
  }

  size() {
    return this.items.length
  }

  print() {
    console.log(this.items);
  }

  reverse() {
    if (this.size() === 0) {
      return
    }

    let frontElement = this.dequeue()

    this.reverse()
    this.enqueue(frontElement)
  }
}

