function gcd(a, b) {
	while (a !== b) {
		if (a < b) {
			var tmp = a;
			a = b;
			b = tmp;
		}
		if (a % b === 0) return b;
		a -= b;
	}
	return a;
}

function lcm(a, b) {
	var g = gcd(a, b);
	return g * (a / g) * (b / g);
}

