function calc(map,h,w){
    if(map[h][w] == "."){
        return w + " "+ h;
    }
    if(map[h][w] == "1"){
        return "LOOP";
    }
    switch(map[h][w]){
    case '>':
        map[h][w] = "1";
        return calc(map,h,w+1);
    case '<':
        map[h][w] = "1";
        return calc(map,h,w-1);
    case 'v':
        map[h][w] = "1";
        return calc(map,h+1,w);
    case '^':
        map[h][w] = "1";
        return calc(map,h-1,w);
    }
}

