 public static int cut_rod_Aux(int p[],int n,int arr[])
 {
	 int max;
	if(arr[n]>=0)
		return arr[n];
	if(n==0)
		max=0;
	else
	{
		max=Integer.MIN_VALUE;
		for(int i=0;i<n;i++)
			max=Math.max(max,p[i]+cut_rod_Aux(p,n-i-1,arr));
		arr[n]=max;
	}
	return max;
 }
