function perm(xs, n, s, callback) {
  var
  x, i, len = xs.length;
  s = s || [];
  if(n === 0) {
    callback(s);
  }else{
    for(i = 0; i < len; i++){
      x = xs.shift();
      s.push(x);
      perm(xs, n - 1, s, callback);
      s.pop();
      xs.push(x);
    }
  }
}

