int a[51][51];
int book[51][51],n,m,sum;
void dfs(int x,int y)
{
	/*定义一个方向数组*/
	int next[4][2]={
	{0,1},  //向右走
	{1,0},  //向下走
	{0,-1},  //向左走
	{-1,0},  //向上走 
	};
	int k,tx,ty;
	/*枚举4个方向*/
	for(k=0;k<=3;k++)
	{
		tx=x+next[k][0];  //计算下一个点的坐标
		ty=y+next[k][1];
		if(tx<1 || tx>n || ty<1 || ty>m)  //判断是否越界
			continue;
		/*判断是否是陆地或者曾经是否走过*/
		if(a[tx][ty]>0 && book[tx][ty]==0)
		{
			sum++;
			book[tx][ty]=1;  //标记这个点已走过
			dfs(tx,ty);  //开始尝试下一个点
		}
	}
	return ;
}

