      else
	ms1=m1*100/(100+x)+1;
      
      if((m2*100)%(100+x)==0)
	ms2=m2*100/(100+x);
      else
	ms2=m2*100/(100+x)+1;

      if((ms1*(100+x)/100 + ms2*(100+x)/100)==s){
	
	total=ms1*(100+y)/100 + ms2*(100+y)/100;
	
	if(max<total)
	  max=total;
      }
      m1++;
      m2--;
    }  
      cout<<max<<endl;
