struct node{

    char value;
    float freq;
    node* right;
    node* left;
};

struct compare{
    bool operator()(const node &n1, const node &n2) const{
        return n1.freq>n2.freq;
    }
};


//IS CORRECT
node * mergeNodes(node *n1, node *n2){

    node *n=new node;
    n->freq=n1->freq+n2->freq;
    n->right=n2;
    n->left=n1;
    n->value='~';

    return n;
}
