#include<stdio.h>
#define MAX 50

int check_palindrome(int arr[MAX][MAX],int r,int c)
{
    int i,j,k,flag=0;
    for(i=0,j=r-1;i<r && j>=0;i++,j--)
    {
        for(k=0;k<c;k++)
        {
            // printf("%d %d\n",arr[i][k],arr[j][k]);
            if(arr[i][k] == arr[j][k])
                flag++;
        }
    }
    for(i=0,j=c-1;i<c && j>=0;i++,j--)
    {
        for(k=0;k<r;k++)
        {
            if(arr[k][i] == arr[k][j])
                flag++;
        }
    }
    return flag == (2*r*c);
}

int main(void)
{
    int i,j,r,c,arr[MAX][MAX];
    scanf("%d %d",&r,&c);
    for(i=0;i<r;i++)
    {
        for(j=0;j<c;j++)
        {
            scanf("%d",&arr[i][j]);
        }
    }
    (check_palindrome(arr,r,c) != 0)? printf("YES") : printf("NO");
    return 0;
}

#include <stdio.h>

void swap(int *a, int *b)
{
    int temp = *a;
    *a = *b;
    *b = temp;
}

void heapify(int array[], int size, int root)
{
    int largest = root;
    int left = 2 * root + 1;
    int right = 2 * root + 2;

    if (left < size && array[left] > array[largest])
        largest = left;

    if (right < size && array[right] > array[largest])
        largest = right;

    if (largest != root)
    {
        swap(&array[root], &array[largest]);
        heapify(array, size, largest);
    }
}

void heapSort(int array[], int size)
{
    for (int i = size / 2 - 1; i >= 0; i--)
        heapify(array, size, i);

    for (int i = size - 1; i > 0; i--)
    {
        swap(&array[0], &array[i]);
        heapify(array, i, 0);
    }
}

int main(void)
{
    int array[] = {12, 11, 13, 5, 6, 7};
    int size = sizeof(array) / sizeof(array[0]);

    heapSort(array, size);

    for (int i = 0; i < size; i++)
        printf("%d ", array[i]);

    return 0;
}

import math


class WeightedGraph:

    def __init__(self,
                 undirected=True,
                 ) -> None:
        super().__init__()
        self.nodes = {}
        self.edges = {}
        self.undirected = undirected

    def get_nodes(self):
        return list(self.nodes.keys())

    def add_node(self, *args):
        for node in args:
            self.nodes[node] = []

    def remove_node(self, node):
        del self.nodes[node]
        edges = list(self.edges.keys())
        for key in edges:
            if key[0] == node or key[1] == node:
                del self.edges[key]

    def add_edge(self, i, j, c):
        self.edges[(i, j)] = c
        if not self.undirected:
            self.edges[(j, i)] = c

    def preprocess(self):

        # for each edge add the neighbors
        for (i, j), c in self.edges.items():
            if i in self.nodes and j in self.nodes:
                self.nodes[i].append(j)
                if not self.undirected:
                    self.nodes[j].append(i)
            else:
                raise Exception("Can not an edge to an unknown node!")

        # filter out duplicates in the neighbor list
        for node in list(self.nodes.keys()):
            H = set()
            entry = []
            for elem in self.nodes[node]:
                if elem not in H:
                    entry.append(elem)
                    H.add(elem)
            self.nodes[node] = entry

    def get_neighbors(self, node):
        for n in self.nodes[node]:
            yield n

    def get_distance(self, i, j):
        if (i, j) in self.edges:
            return self.edges[(i, j)]
        else:
            return math.inf

    def costs_as_list(self):
        for node in list(self.edges.keys()):
            self.edges[node] = [self.edges[node]]
        return self

