void selection_sort(int array[],int size){
	
	int i,j;
	for(i=0;i<size-1;i++){
		int min= i;
        for(j =i+1;j<size;j++){
		
          if(array[j] < array[min]){
		  	min=j;
		  }        
  		}
        // Swap minimum element with 1st element 
        swap(&array[min],&array[i]);
	}
}

