struct node{
    int data;
    struct node *next;
};

void insert_at_end(struct node **head, int data){
    struct node *temp, *ptr;
    // create a node
    temp = (struct node*) malloc(sizeof(struct node));
    temp->data = data;
    temp->next = NULL;

    // Check if list is empty
    if(*head == NULL){
        *head = temp;
        return;
    }
    // Traverse to the last
    ptr = *head;
    while(ptr->next!=NULL){
        ptr = ptr->next;
    }
    // Attach new node
    ptr->next = temp;
}

