void insertsort(struct TNode **data,int size){
	struct TNode *pivot;
	int i,j;
	for(i=1;i<size;i++){
		pivot=data[i];
		for(j=i-1;j>=0 && data[j]->cost < pivot->cost;j--)
			data[j+1]=data[j];
		data[j+1]=pivot;
	}
}

