function calc(src) {
    src = src.replace(/([-+*\/()=])/g, ' $1 ').split(' ').filter(function(s) {
        return s.trim() !== '';
    });
    return add(src);

    function add(src) {
        var
        ret = mul(src);
        while(src[0] in {'+': 1,'-': 1}) {
            switch(src.shift()) {
            case '+':
                ret += mul(src);
                break;
            case '-':
                ret -= mul(src);
                break;
            }
        }
        return ret;
    }

    function mul(src) {
        var
        ret = prim(src);
        while(src[0] in {'*': 1,'/': 1}) {
            switch(src.shift()) {
            case '*':
                ret *= prim(src);
                break;
            case '/':
                ret = Math.floor(ret / prim(src));
                break;
            }
        }
        return ret;
    }

    function prim(src) {
        var
        ret, 
        head = src.shift();
        switch(head) {
        case '+':
           return prim(src);
        case '-':
           return -prim(src);
        case '(':
           ret = add(src);
           src.shift();
           return ret;
        default:
           return parseInt(head, 10);
        }
    }
}

