#define REP2(i, m, n) for(int i = (int)(m); i < (int)(n); i++)
#define REP(i, n) REP2(i, 0, n)
#define ALL(c) (c).begin(), (c).end()
#define ITER(c) __typeof((c).begin())
#define PB(e) push_back(e)
#define FOREACH(i, c) for(ITER(c) i = (c).begin(); i != (c).end(); ++i)
#define MP(a, b) make_pair(a, b)
#define PARITY(n) ((n) & 1)



const int h = 4;
const int w = 8;
typedef vector<int> vec;
typedef vector<vec> mat;

bool done(const mat &board){
  REP(i, h)REP(j, w - 1){
    if(board[i][j] != i * 10 + j + 1) return false;
  }
  return true;
}


int main(){
  int T;
  cin >> T;
  
  while(T--){
    mat board(h, vec(w, 0));
    
    REP(i, h)REP2(j, 1, w){
      cin >> board[i][j];
      board[i][j] -= 10;
      int &b = board[i][j];
      if(b % 10 == 1) swap(board[b / 10][0], b);
    }

    int ans = -1;
    set<mat> memo;
    queue<pair<int, mat> > que;
    memo.insert(board);
    que.push(MP(0, board));
    
    while(!que.empty()){
      int d = que.front().first;
      mat board = que.front().second;
      que.pop();

      if(done(board)){
        ans = d;
        break;
      }
      
      REP(r, h)REP2(c, 1, w){
        int b = board[r][c-1];
        if(board[r][c] == 0 && b > 0 && b % 10 < 7){
          int n = b + 1;
          REP(i, h)REP2(j, 1, w){
            if(board[i][j] == n){
              swap(board[i][j], board[r][c]);
              if(memo.count(board) == 0){
                memo.insert(board);
                que.push(MP(d + 1, board));
              }
              swap(board[i][j], board[r][c]);
            }
          }
        }
      }
    }
    cout << ans << endl;
  }
  
  return 0;
}

