int frequency(char *paragraph, char *from, char *to)
{
    int freq = 0, sub_len = to - from + 1;
    int p = 0;
    while (paragraph[p] != '\0')
    {
        if (paragraph[p] != *from)
        {
            p++;
            continue;
        }
        int t = 0;
        while (paragraph[p + t] == *(from + t) && t < sub_len && paragraph[p + t] != '\0')
            t++;
        if (t == sub_len)
            freq++;
        p++;
    }
    return freq;
}

