/* Recursion Approach */
// -> 2 and 5 GCD
// 2    5
// 5    2
// 2    1
// 1    0

// -> 20 and 12 GCD
// 20   12
// 12   8
// 8    4
// 4    0

// -> 20 and 15 GCD
// 20   15
// 15   5
// 5    0
int gcd(int a, int b)
{
    if (b == 0)
    {
        return a;
    }
    else
    {
        return gcd(b, a % b);
    }
}

