    cin >> n >> x;
    dp[0][0] = 1;
    for(int i=0;i<n;i++){
        for(int j=0;j<=2*i;j++){
            dp[i+1][j+1] += dp[i][j];
            dp[i+1][j+1] %= mod;
            dp[i+1][j+2] += dp[i][j];
            dp[i+1][j+2] %= mod;
        }
    }
    ll ans = 0;
    for(int i=0;i<=n;i++){
        for(int j=0;j<x;j++){
            ans += dp[i][j]*comb(n,i)%mod;
            ans %= mod;
        }
    }
