    for(int k=1;k<=(n)/2;k++){
        for(int p = 0;p<=n-2*k;p++){
            if(x-1-2*k<=0)continue;
            ans += dp[p][x-1-2*k]*comb(n,p+2*k)%mod;
            ans %= mod;
            if(2*p==x-1-2*k){
                ans += mod-comb(n,p+2*k);
                ans %= mod;
            }
        }
        
    }
    cerr << ans << endl;
    if(x%2==0){
        
    }else{
        for(int k = (x+1)/2;k<=n;k++){
            
            ans += comb(n,k);
