            added = 0
            for (x,y) in directions:

                row, col = i+x,j+y
                if not (0 <= row < len(grid) and 0 <= col < len(grid)) or grid[row][col] or (row,col) in visited:
                    continue
                if row == col == len(grid)-1:
                    return path_length+1
                visited.add((row,col))
                temp.append((row,col))
            if not queue:
                queue = temp
