char* intToBinary(long long int n)
{
    char *binary = (char*)malloc(sizeof(char)*32);
    long long int i = 0;
    while(n > 0)
    {
        binary[i] = (n % 2) + '0';
        n /= 2;
        i += 1;
    }
    binary[i] = '\0';
    return binary;
}

