        printf("Not able to push the element (Memory allocation failed).\n");
    } else {
        printf("Enter the value: ");
        scanf("%d", &val);

        ptr->val = val;
        ptr->next = head;
        head = ptr;

        printf("Item pushed.\n");
    }
}

