from collections import deque

from algorithms.collections.graph import Graph


def bfs(graph: Graph, root):
    dq = deque([root])
    visited = set()
    scanned = []
    while len(dq) > 0:
        node = dq.pop()
        if id(node) in visited:
            continue
        visited.add(id(node))
        for child in graph.get_children(node):
            if id(child) not in visited:
                dq.appendleft(child)
        scanned.append(node)
    return scanned


