d = {}
def isprime(n):
    if n in d:
        return d[n]
    if n == 2 or n == 3:
        d[n] = True
        return True
    if n % 2 == 0 or n < 2:
        d[n] = False
        return False
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            d[n] = False
            return False
    d[n] = True
    return True


