{
    
    int arr[] = {10, 25, 5, 50, 20};
    int end = sizeof(arr)/sizeof(arr[0]);
    
    printArray(arr, end);
    quickSort(arr, 0, end);
    printArray(arr, end);
    
    return (0);
}

