// Swap Kth node from beginning with Kth node from end in a Linked List

// Given a singly linked list, swap kth node from beginning with kth node from end. Swapping of data is not allowed, 
// only pointers should be changed. This requirement may be logical in many situations where the linked list data part 
// is huge (For example student details line Name, RollNo, Address, ..etc). The pointers are always fixed 
// (4 bytes for most of the compilers).

// Let X be the kth node from beginning and Y be the kth node from end. 
// Following are the interesting cases that must be handled.
// 1) Y is next to X
// 2) X is next to Y
// 3) X and Y are same
// 4) X and Y don't exist (k is more than number of nodes in linked list)

class Node { 
    int data; 
    Node next; 
    Node(int d) { 
        data = d; 
        next = null; 
    } 
} 

class LinkedList { 
    Node head;   
    void push(int new_data) { 
        Node new_node = new Node(new_data); 
        new_node.next = head; 
        head = new_node; 
    } 
    void printList() { 
        Node node = head; 
        while (node != null) { 
            System.out.print(node.data + " "); 
            node = node.next; 
        } 
        System.out.println(""); 
    } 

    int countNodes() { 
        int count = 0; 
        Node s = head; 
        while (s != null) { 
            count++; 
            s = s.next; 
        } 
        return count; 
    } 

    void swapKth(int k) { 
        // Count nodes in linked list 
        int n = countNodes(); 
        // Check if k is valid 
        if (n < k) 
            return;   
        // If x (kth node from start) and y(kth node from end) are same 
        if (2*k - 1 == n) 
            return;   
        // Find the kth node from beginning of linked list. 
        // We also find previous of kth node because we need 
        // to update next pointer of the previous. 
        Node x = head; 
        Node x_prev = null; 
        for (int i = 1; i < k; i++) { 
            x_prev = x; 
            x = x.next; 
        } 

        // Similarly, find the kth node from end and its  
        // previous. kth node from end is (n-k+1)th node 
        // from beginning 
        Node y = head; 
        Node y_prev = null; 
        for (int i = 1; i < n - k + 1; i++) { 
            y_prev = y; 
            y = y.next; 
        } 

        // If x_prev exists, then new next of it will be y. 
        // Consider the case when y->next is x, in this case, 
        // x_prev and y are same. So the statement  
        // "x_prev->next = y" creates a self loop. This self 
        // loop will be broken when we change y->next. 
        if (x_prev != null) 
            x_prev.next = y; 

        // Same thing applies to y_prev 
        if (y_prev != null) 
            y_prev.next = x; 

        // Swap next pointers of x and y. These statements 
        // also break self loop if x->next is y or y->next 
        // is x 
        Node temp = x.next; 
        x.next = y.next; 
        y.next = temp; 

        // Change head pointers when k is 1 or n 
        if (k == 1) 
            head = y; 

        if (k == n) 
            head = x; 
    } 

    public static void main(String[] args) { 
        LinkedList llist = new LinkedList(); 
        for (int i = 8; i >= 1; i--) 
            llist.push(i); 

        System.out.print("Original linked list: "); 
        llist.printList(); 
        System.out.println(""); 

        for (int i = 1; i < 9; i++) { 
            llist.swapKth(i); 
            System.out.println("Modified List for k = " + i); 
            llist.printList(); 
            System.out.println(""); 
        } 
    } 
}

/*
MERGE SORT

Space complexity: stack O(logn) + space for merge procedure O(n)
Therefore total = O(n)

Time complexity: time taken to merge O(n) + time taken to sort by masters theorem O(nlogn)
Therefore: O(nlogn) 

*/
#include <stdio.h>
#include <stdlib.h>
#include <limits.h>


void merge(int *arr, int start, int mid, int end) {

    int len1 = mid - start + 2;
    int len2 = end - mid + 1;

    int left[len1], right[len2];

    int i;
    for(i=0; i<len1-1; i++) {
        left[i] = arr[start + i];
    }

    for(i=0; i<len2-1; i++) {
        right[i] = arr[mid + i + 1];
    }
    
    left[len1-1] = INT_MAX;
    right[len2-1] = INT_MAX;

    int k;
    int j;
    i=0,j=0;
    for(k=start; k<=end; k++) {
        if(left[i] < right[j]) {
            arr[k] = left[i];
            i++;
        }else{
            arr[k] = right[j];
            j++;
        }
    }

}

void mergeSort(int *arr, int start, int end) {
    int mid;
    if(start < end) {
        mid = (start + end)/2;
        mergeSort(arr, start, mid);
        mergeSort(arr, mid + 1, end);

        merge(arr, start, mid, end);
    }
}

void display(int *arr, int size) {
    int i;
    for(i=0;i<size;i++) {
        printf("%d ", arr[i]);
    }
    printf("\n");
}   

int main() {
    int arr[] = {9,6,5,0,8,2};
    int size = sizeof(arr)/sizeof(arr[0]);

    mergeSort(arr,0,size-1);

    display(arr, size);
    return 0;
}

