void backtrack(int *number){
    int record[N];
    int answer[N];
    int step=0;
    record[step]=-1;
    while(step>=0){
        record[step]++;
        if(record[step]>=size[number[step]])
            step--;
        else if(step==N-1){
            answer[step]=record[step];
            display_outcome(number,answer);
        }else{
             answer[step]=record[step];
             step++;
             record[step]=-1;
        }
    }
}

