{
    int number[10]={4,8,6,9,4,6,8,6,6,4};
    backtrack(number);
    return 0;
}

/*
 * Level : Easy
 * Given a grid, calculate the maximum number of unique paths
 * from source (0,0) to destination (m, n). You can only move
 * either in down or in right direction.
 * 
 *  S . . . . . . . .
 *  . . . . . . . . .
 *  . . . . . . . . .
 *  . . . . . . . . .
 *  . . . . . . . . .
 *  . . . . . . . . D
 * 
 * In this 6 x 9 grid, 
 * unique paths from source origin to destination are 1287.
 * 
 */

#include <iostream>
#include <vector>

int unique_paths(int m, int n)
{
    std::vector<std::vector<int>> paths(m, std::vector<int>(n));
    for (int i = 0; i < m; ++i) {
        paths[i][0] = 1;
    }

    for (int j = 0; j < n; ++j) {
        paths[0][j] = 1;
    }

    for (int i = 1; i < m; ++i) {
        for (int j = 1; j < n; ++j) {
            paths[i][j] = paths[i-1][j] + paths[i][j-1];
        }
    }
    return paths[m-1][n-1];
}

int main()
{
    std::cout << "Number of unique paths for 6 x 9 grid: " <<
        unique_paths(6, 9) << std::endl;
    return 0;
}

class Solution {
    public int findRepeatNumber(int[] nums) {
        int len = nums.length;
        for (int i = 0; i < len; i++) {
            while (nums[i] != i) {//保证交换过来的新元素位置也要正确，即令：a[i]=i
                if (nums[i] == nums[nums[i]]) {//将每个位置的数交换映射到其对应的数组下标下面，当出现新的元素与其对应的下标中的数字相等时，即为重复数字
                    return nums[i];
                }
                int temp = nums[i]; //交换，使对应下标的数组值与其下标值相等，即令 a[i]=i
                nums[i] = nums[temp];
                nums[temp] = temp;
            }
        }
        return -1;
    }
}

