typedef struct{
  int to,cost;
}Edge;

const int N = 100;
vector<Edge> edge[N];
int f[N];
int findMax(int n,int src,int maxhp){
  for(int i=0;i<n;i++){
    f[i] = 0;
  }
  for(int i=0;i<edge[src].size();i++){
    int next = edge[src][i].to;
    f[next] = max(f[next],maxhp+edge[src][i].cost);
    f[next] = min(f[next],maxhp);
  }
  //O(VE)
  for(int loop=0;loop<n-1;loop++){
    for(int i=0;i<n;i++){
      int now = i;
      if (f[now] == 0)continue;
      for(int j=0;j<edge[i].size();j++){
	int next = edge[now][j].to;
	f[next] = max(f[next],f[now]+edge[now][j].cost);
	f[next] = min(f[next],maxhp);
      }
    }
  }
  return f[src];
}

int cost[N];
int prevCost[N];
bool haveInfLoop[N];
int solve(int n,int src,int dst,int maxhp){
  edge[dst].clear();
  for(int i=0;i<n;i++){
    int tmp = findMax(n,i,maxhp);
    haveInfLoop[i] = tmp == maxhp;
  }


  for(int i=0;i<n;i++){
    cost[i] = 0;
    prevCost[i] = 0;
  }
  cost[src] = maxhp;
  prevCost[src] = maxhp;
  for(int loop=0;loop<n;loop++){
    for(int now=0;now<n;now++){
      if (cost[now] == 0)continue;
      for(int j=0;j<edge[now].size();j++){
	int next = edge[now][j].to;
	cost[next] = max(cost[next],cost[now]+edge[now][j].cost);
	cost[next] = min(cost[next],maxhp);
      }
    }

    for(int now=0;now<n;now++){
      if (cost[now] == 0)continue;
      for(int j=0;j<edge[now].size();j++){
	int next = edge[now][j].to;
	if (min(maxhp,cost[now] + edge[now][j].to)  != cost[next]){
	  //if (findMax(n,next,maxhp) == maxhp){
	  if (haveInfLoop[next]){
	    cost[next] = maxhp;
	  }
	}
      }
    }
  end:;
  }
  return cost[dst];
}

