/**
 The Hamming distance between two integers is the number of positions at which
 the corresponding bits are different.
 Given two integers x and y, calculate the Hamming distance.

 Input: x = 1, y = 4

Output: 2

Explanation:
1   (0 0 0 1)
4   (0 1 0 0)
       ↑   ↑

The above arrows point to positions where the corresponding bits are different
*/

#include <iostream>

int hamming_distance(int x, int y)
{
    // XOR will set only those bits in z which are different in x and y
    int z = x ^ y;

    // Now just count set bits in z.
    int count = 0;
    while (z)
    {
        count += (z % 2);
        z >>= 2;
    }
    return count;
}


int main()
{
    int x = 4;
    int y = 1;
    std::cout << "Hamming distance between " << x << " and " << y << " is : "
        <<  hamming_distance(x, y) << std::endl;
}

from __future__ import annotations

from dataclasses import dataclass
from typing import TYPE_CHECKING, Dict, List, Optional

if TYPE_CHECKING:

    @dataclass
    class TreeNode:
        val: int
        left: Optional[TreeNode]
        right: Optional[TreeNode]


class Solution:
    def allPossibleFBT(self, n: int) -> List[TreeNode]:
        # FBT - Full Binary Tree
        fbts_by_size: Dict[int, List[TreeNode]] = {
            0: [],
            1: [TreeNode(0, None, None)],
        }

        for size in range(1, n):
            # size without the root node, as tree of size 1 is trivial
            # so it is not considered here
            fbts_by_size[size + 1] = []

            for left_size in range(size + 1):
                for left_fbt in fbts_by_size[left_size]:
                    for right_fbt in fbts_by_size[size - left_size]:
                        node = TreeNode(0, left_fbt, right_fbt)
                        fbts_by_size[size + 1].append(node)

        return fbts_by_size[n]

