    struct node* next;
};

struct node* last = NULL;

void addatlast(int data) {
    struct node* temp;
    temp = (struct node*)malloc(sizeof(struct node));
    if (last == NULL) {
        temp->info = data;
        temp->next = temp;
        last = temp;
    } else {
        temp->info = data;
        temp->next = last->next;
        last->next = temp;
        last = temp;
    }
}

void deletefirst() {
    struct node* temp;
    if (last == NULL)
        printf("\nList is empty.\n");
    else {
        temp = last->next;
        last->next = temp->next;
        free(temp);
    }
}

void viewList() {
    if (last == NULL)
        printf("\nList is empty\n");
    else {
        struct node* temp;
        temp = last->next;
        do {
            printf("\nData = %d", temp->info);
            temp = temp->next;
        } while (temp != last->next);
    }
}

