class Solution:
    def sortArray(self, arr: List[int]) -> List[int]:
        if len(arr) <= 1:
            return arr

        def merge_sort(arr):
            if len(arr) > 1:
                mid = len(arr) // 2
                left_arr = arr[:mid]
                right_arr = arr[mid:]

             
                merge_sort(left_arr)
                merge_sort(right_arr)

               
                merge(left_arr, right_arr, arr)

       
        def merge(left_arr, right_arr, arr):
            i = j = k = 0

           
            while i < len(left_arr) and j < len(right_arr):
                if left_arr[i] < right_arr[j]:
                    arr[k] = left_arr[i]
                    i += 1
                else:
                    arr[k] = right_arr[j]
                    j += 1
                k += 1

            
            while i < len(left_arr):
                arr[k] = left_arr[i]
                i += 1
                k += 1
            while j < len(right_arr):
                arr[k] = right_arr[j]
                j += 1
                k += 1

        
        merge_sort(arr)
        return arr

class Solution:
    def search(self, nums: List[int], target: int) -> int:
        if not nums:
            return -1

        rotation_point = self.find_rotation_point(nums)
        start, end = 0, rotation_point - 1

        # checking in which bucket target is found
        if target < nums[0]:
            start, end = rotation_point, len(nums) - 1

        while start <= end:
            mid = (start + end) // 2
            if nums[mid] == target:
                return mid
            elif nums[mid] > target:
                end = mid - 1
            else:
                start = mid + 1

        return -1

    def find_rotation_point(self, nums):
        start = 0
        end = len(nums) - 1

        while start < end:
            mid = (start + end) // 2
            if nums[mid] > nums[end]:
                start = mid + 1
            else:
                end = mid

        return start if start else len(nums)

