typedef long long ll;
typedef pair<int, int> P;

int gcd(int a, int b) {
    a = abs(a); b = abs(b);
    if (a == 0) return b;
    return gcd(b%a, a);
}

struct K {
    int x, y, z;
    K() {}
    K(int x, int y, int z) : x(x), y(y), z(z) {}
    bool operator== (const K &r) const {
        return (x==r.x && y==r.y && z==r.z);
    }
};

struct T {
    double x, y, z;
    int i;
    T() {}
    T(int x, int y, int z, int i) : x(x), y(y), z(z), i(i) {}
    inline K key(double r) {
        return K(x/r, y/r, z/r);
    }
    double abs() {
        return sqrt(x*x+y*y+z*z);
    }
};

double dist(const T &l, const T &r) {
    double x = l.x-r.x;
    double y = l.y-r.y;
    double z = l.z-r.z;
    return sqrt(x*x + y*y + z*z);
}

const int MN = 100100;
const int MD = 1007;

int n;
int x[MN], y[MN], z[MN];
T p[MN];

auto khash = [](const K &x){
    return x.x^(x.y<<10)^(x.z<<20);
};
unordered_map<K, vector<int>, decltype(khash)> mp(0, khash);

P solve() {
    for (int i = 0; i < n; i++) {
        int g = gcd(gcd(x[i], y[i]), z[i]);
        p[i] = T(x[i]/g, y[i]/g, z[i]/g, i);
    }
    sort(p, p+n, [](const T &l, const T &r) {
        if (l.x != r.x) return l.x < r.x;
        if (l.y != r.y) return l.y < r.y;
        return l.z < r.z;
    });
    n = unique(p, p+n, [](const T &l, const T &r){
        return dist(l, r) < 1e-9;
    })-p;
    shuffle(p, p+n, mt19937());
    for (int i = 0; i < n; i++) {
        double u = p[i].abs();
        p[i].x /= u;
        p[i].y /= u;
        p[i].z /= u;
    }
    double res = dist(p[1], p[0]);
    P resp = P(p[0].i, p[1].i);
    if (resp.first > resp.second) swap(resp.first, resp.second);
    mp.clear();
    mp[p[0].key(res)].push_back(0);
    mp[p[1].key(res)].push_back(1);
    for (int i = 2; i < n; i++) {
        double r = res;
        P rp = resp;
        K k = p[i].key(res);
        bool f = false;
        for (int x = -1; x <= 1; x++) {
            for (int y = -1; y <= 1; y++) {
                for (int z = -1; z <= 1; z++) {
                    auto it = mp.find(K(k.x+x, k.y+y, k.z+z));
                    if (it == mp.end()) continue;
                    for (int t: it->second) {
                        double u = dist(p[i],p[t]);
                        P up = P(p[t].i, p[i].i);
                        if (up.first > up.second) swap(up.first, up.second);
                        if (u < r || (u == r && up < rp)) {
                            f = true;
                            r = u;
                            rp = up;
                        }
                    }
                }
            }
        }
        if (f) {
            res = r;
            resp = rp;
            mp.clear();
            for (int j = 0; j <= i; j++) {
                mp[p[j].key(res)].push_back(j);
            }
        } else {
            mp[p[i].key(res)].push_back(i);
        }
    }
    return resp;
}

