struct Node
{
    int data;
    struct Node *link;
};

struct Node *Top = NULL;

struct Node *CreateNode()
{
    struct Node *newNode;
    newNode = (struct Node *)malloc(sizeof(struct Node));

    if (newNode == NULL)
    {
        printf("Allocation Failed\n");
    }
    else
    {
        printf("Node Created\n");
        return newNode;
    }
}

void push(int key)
{
    struct Node *newNode = CreateNode();

    newNode->data = key;
    newNode->link = NULL;

    if (Top == NULL)
    {
        Top = newNode;
    }
    else
    {
        newNode->link = Top;
        Top = newNode;
    }
}

int pop()
{
    if (Top == NULL)
    {
        return -1;
    }
    else
    {
        int key;
        struct Node *temp;
        temp = Top;
        Top = temp->link;
        key = temp->data;
        free(temp);
        return key;
    }
}

int peek()
{
    if (Top == NULL)
    {
        return -1;
    }
    else
    {
        int key;
        key = Top->data;
        return key;
    }
}

int main()
{
