            {
                printf("\nStack is Empty\n");
            }
            else
            printf("\n%d is pop from the stack.\n", key);
            break;
        }

        case 3:
        {
            int key = peek();
            if(key==-1)
            {
                printf("\n Stack is Empty\n");
            }
            else
            printf("\nTop of Stack is : %d\n",  key);
            break;
        }

        case 4:
        {
            exit(1);
            break;
        }

        default:
            break;
        }
