int knapsack(int v[],int w[], int c,int n)
{
		if(n==0 || c ==0)
			return 0;

		else if(w[n-1] > c)
			return knapsack(v,w,c,n-1);

		else
			return max(v[n-1] + knapsack(v,w,c-w[n-1],n-1), knapsack(v,w,c,n-1));
}

