void ordena_por_selecao(int x[], int n);
void mostra_vetor(int a[], int n);

void troca(int v[], int i, int j){
    int aux;
    aux = v[i];
    v[i]=v[j];
    v[j]=aux;
}

void ordena_por_selecao(int x[], int n){
    int menor, pos;
    int i,k;
    k=0;

    while(k<n){
        menor=INFINITO;
        for(i=k;i<n;i++)
            if(x[i]<menor)
            {
                menor = x[i];
                pos = i;
            }
            troca(x,k,pos);
            printf("Passo %d\n", k+1);
            mostra_vetor(x,n); printf("\n");
            k++;
    }
}

