    }
  }

  insert(root, data) {
    let newNode = new BNode(data)

    if (!root) {
      this.root = newNode
      return root
    }

    if (data < root.data) {
      if (!root.left) root.left = newNode
      else this.insert(root.left, data)
    } else {
      if (!root.right) root.right = newNode
      else this.insert(root.right, data)
    }

    return root
  }


