using namespace std;
int h[N],nex[N*2],to[N*2],dep[N],fa[N],fav[N],M;
void add(int a,int b){
    M++;
    to[M]=b;
    nex[M]=h[a];
    h[a]=M;
}
void dfs(int x){
    dep[x]=dep[fa[x]]+1;
    for(int i=h[x];i;i=nex[i]){
        if(to[i]!=fa[x]){
            fa[to[i]]=x;
            dfs(to[i]);
        }
    }
}
void col(int x,int y){
    if(dep[x]<dep[y])swap(x,y);
    while(dep[x]>dep[y]){
        fav[x]++;
        x=fa[x];
    }
    while(x!=y){
        fav[x]++;
        fav[y]++;
        x=fa[x];
        y=fa[y];
    }
}
struct rt{
    int x,y;
    rt(int a=0,int b=0){x=a;y=b;}
};
bool operator==(rt a,rt b){return a.x==b.x&&a.y==b.y;}
int d[2010],n;
vector<rt>solve(vector<rt>v){
    if(v.size()==0)return v;
    int x,u,i;
    for(x=1;x<=n;x++){
        if(d[x]==1)break;
    }
    if(x>n)return v;
    for(i=h[x];i;i=nex[i]){
        if(d[to[i]]){
            u=to[i];
            break;
        }
    }
    d[x]--;
    d[u]--;
    vector<rt>lx,nv;
    vector<int>id;
    int pos[2010];
    memset(pos,-1,sizeof(pos));
    for(i=0;i<(int)v.size();i++){
        if(v[i].x==x||v[i].y==x){
            lx.push_back(v[i]);
            id.push_back(i);
        }else{
            nv.push_back(v[i]);
            pos[i]=nv.size()-1;
        }
    }
    if(lx.size()==0)return solve(v);
    for(i=0;i+1<(int)lx.size();i+=2){
        if(lx[i].y==x)swap(lx[i].x,lx[i].y);
        if(lx[i+1].y==x)swap(lx[i+1].x,lx[i+1].y);
        if(lx[i]==lx[i+1]){
            if(v[id[i]]==v[id[i+1]])swap(v[id[i]].x,v[id[i]].y);
            continue;
        }
        nv.push_back(rt(lx[i].y,lx[i+1].y));
        pos[id[i]]=pos[id[i+1]]=nv.size()-1;
    }
    if(lx.size()&1){
        if(lx[lx.size()-1].y==x)swap(lx[lx.size()-1].x,lx[lx.size()-1].y);
        if(lx[lx.size()-1].y!=u){
            nv.push_back(rt(u,lx[lx.size()-1].y));
            pos[id[lx.size()-1]]=nv.size()-1;
        }
    }
    nv=solve(nv);
    for(i=0;i<(int)v.size();i++){
        if(pos[i]!=-1&&!(v[i].x==nv[pos[i]].x||v[i].y==nv[pos[i]].y))swap(v[i].x,v[i].y);
    }
    return v;
}
