    MakeSet(1);
    MakeSet(2);
    MakeSet(3);
    MakeSet(4);

    Union(1, 2);
    Union(2, 1);
    Union(2, 3);
    Union(1, 3);

    printf("%d\n",numComponents);

    return 0;
}

