void Shell_sort()
{
	for (int gc = n >> 1; gc >= 1; gc >>= 1)
	{
		for (int s = 0; s < gc; s++)
		{
			for (int i = s; i < n; i += gc)
			{
				for (int j = i - gc; j >= 0 && d[j] > d[j + gc]; j -= gc)
				{
					int temp = d[j];
					d[j] = d[j + gc];
					d[j + gc] = temp;
				}
			}
		}
	}
}

