void add_at_beginning(struct node **head, int value){
    // create a new node
    struct node *newNode = (struct node*) malloc(sizeof(struct node));
    // assign data
    newNode->data = value;
    // link new node to current node
    newNode->next = *head;
    // update head to new node
    *head = newNode;
}

