#include<bits/stdc++.h>
using namespace std;

int node[1 << 21] = {};
int SIZE;
void segtree(int size) {
  SIZE = 1;
  while(SIZE <= size) SIZE <<= 1;
}
inline int parent(int i) {return i ? (i - 1) >> 1 : 0;}
inline int lchild(int i) {return (i << 1) + 1;}
inline int rchild(int i) {return (i << 1) + 2;}
int add(int i, int v) {
  i += SIZE - 1;
  node[i] += v;
  while(i = parent(i)) node[i] = max(node[lchild(i)], node[rchild(i)]);
}
int find(int a, int b, int i = 0, int l = 0, int r = SIZE) {
  if(b <= l || r <= a) return 0;
  if(a <= l && r <= b) return node[i];
  return max(find(a, b, lchild(i), l, (l+r)/2), find(a, b, rchild(i), (l+r)/2, r));
}

int N, M;
int C[1000000];

int L[2000000];
int be[1000000];
int en[1000000];
void migrant(auto flag) {
  for(auto i = 0; i < 2 * N; ++i) L[i] = 0;
  for(auto i = 0; i < M; ++i) en[i] = be[i];
  if(flag) L[en[C[0]]++] = C[0];
  for(auto i = 1 + flag; i < N; i += 2) {
    L[en[C[i-1]]++] = C[i-1];
    L[en[C[i-1]]++] = C[i];
    if(C[i] == C[i-1]) continue;
    L[en[C[i]]++] = C[i-1];
    L[en[C[i]]++] = C[i];
  }
  if((N - flag) & 1) L[en[C[N-1]]++] = C[N-1];
}

vector<int> solve() {
  vector<int> res(M, 1e9);

  segtree(M);
  for(auto i = 0; i < N; ++i) add(C[i], 1);
  for(auto i = 1; i < M; ++i) be[i] = be[i-1] + 2 * find(i-1, i);

  for(auto i: {0, 1}) {
    migrant(i);
    for(auto c = 0; c < M; ++c) {
      int cost = (en[c] - be[c]) - find(c, c+1);
      for(auto i = be[c]; i < en[c]; ++i) add(L[i], -1);
      cost += N - (en[c] - be[c]) - find(0, M);
      for(auto i = be[c]; i < en[c]; ++i) add(L[i], 1);
      res[c] = min(res[c], cost);
    }
  }

  return res;
}

int main() {
  cin >> N >> M;
  for(auto i = 0; i < N; ++i) cin >> C[i];
  for(auto i = 0; i < N; ++i) --C[i];

  for(auto i: solve()) cout << i << "\n";
}

