vector<int> bfs(vector<vector<int>> graph, int sv)
{
    int n = graph.size();
    vector<int> dist(n, -1);
    queue<int> que;
    dist[sv] = 0;
    que.push(sv);
    while (!que.empty())
    {
        int v = que.front();
        que.pop();
        for (int nv : graph[v])
        {
            if (dist[nv] != -1)
                continue;
            dist[nv] = dist[v] + 1;
            que.push(nv);
        }
    }
    return dist;
}

