/**Problem statement:
 You have a long flowerbed in which some of the plots are planted, and some are not. However, flowers cannot be planted in adjacent plots.

 Given an integer array flowerbed containing 0's and 1's, where 0 means empty and 1 means not empty, and an integer n, return true if n new flowers can be planted in the flowerbed without violating the no-adjacent-flowers rule and false otherwise.

 Example 1:
 Input: flowerbed = [1,0,0,0,1], n = 1
 Output: true

 Example 2:
 Input: flowerbed = [1,0,0,0,1], n = 2
 Output: false

 Constraints:
 1 <= flowerbed.length <= 2 * 104
 flowerbed[i] is 0 or 1.
 There are no two adjacent flowers in flowerbed.
 0 <= n <= flowerbed.length
 Leetcode link: https://leetcode.com/problems/can-place-flowers/description/
 **/
public class CanPlaceFlowers {
    public boolean canPlaceFlowers(int[] flowerbed, int n) {
        int availableSlots = 0;
        for (int i = 0; i < flowerbed.length; i++) {
            if (flowerbed[i] == 0 && leftIsAvailable(flowerbed, i) && rightIsAvailable(flowerbed, i)) {
                flowerbed[i] = 1;
                availableSlots++;
                if (availableSlots == n) {
                    return true;
                }
            }
        }
        return availableSlots >= n;
    }
    public static boolean leftIsAvailable(int[] flowerbed, int i) {
        return i - 1 == -1 || flowerbed[i - 1] == 0;
    }
    public static boolean rightIsAvailable(int[] flowerbed, int i) {
        return i + 1 == flowerbed.length || flowerbed[i + 1] == 0;
    }
}

import collections
import heapq


class QueueFIFO:
    """
    Class: QueueFIFO
    Description: QueueFIFO is designed for First-in-First-out rule.
    """

    def __init__(self):
        self.queue = collections.deque()

    def empty(self):
        return len(self.queue) == 0

    def put(self, node):
        self.queue.append(node)  # enter from back

    def get(self):
        return self.queue.popleft()  # leave from front


class QueueLIFO:
    """
    Class: QueueLIFO
    Description: QueueLIFO is designed for Last-in-First-out rule.
    """

    def __init__(self):
        self.queue = collections.deque()

    def empty(self):
        return len(self.queue) == 0

    def put(self, node):
        self.queue.append(node)  # enter from back

    def get(self):
        return self.queue.pop()  # leave from back


class QueuePrior:
    """
    Class: QueuePrior
    Description: QueuePrior reorders elements using value [priority]
    """

    def __init__(self):
        self.queue = []

    def empty(self):
        return len(self.queue) == 0

    def put(self, item, priority):
        heapq.heappush(self.queue, (priority, item))  # reorder s using priority

    def get(self):
        return heapq.heappop(self.queue)[1]  # pop out the smallest item

    def enumerate(self):
        return self.queue

