bool bfs(int st,int tp)
{
	queue<int> q;
	int now,i,u,v;
	memset(dis,-1,sizeof(dis));
	dis[st]=0;
	q.push(st);
	while(!q.empty())
	{
		u=q.front();
		q.pop();
		for(i=head[u];i!=-1;i=edge[i].next)
		{
			v=edge[i].to;
			if(dis[v]==-1&&edge[i].cap>0)
			{
				dis[v]=dis[u]+1;
				q.push(v);
			}
		}
	}
	return (dis[tp]!=-1);
}
int dfs(int a,int b,int tp)
{
	int res=0,v,i;
	if(a==tp)return b;
	for(i=head[a];i!=-1&&res<b;i=edge[i].next)
	{
		v=edge[i].to;
		if(edge[i].cap>0&&dis[v]==dis[a]+1)
		{
			int x=min(edge[i].cap,b-res);
			x=dfs(v,x,tp);
			res+=x;
			edge[i].cap-=x;
			edge[i^1].cap+=x;
		}
	}
	if(!res)dis[a]=-2;
	return res;
}
