def rescue_mission(map, start_vlg, target_vlg):
    queue = deque([(start_vlg, [start_vlg])])

    visited = {start_vlg}

    while queue:
        cur, path = queue.popleft()

        if cur == target_vlg:
            return path
        
        for i in map.get(cur, []):
            if i not in visited:
                visited.add(i)
            
            new_path = path + [i]
            queue.append((i,new_path))

    return 'Path Not Found !!!!'


