  std::cout << "Enter num 1 :" ;
  std::cin >> x;
  std::cout << "Enter num 2 :" ;
  std::cin >> y;
  std::cout << "Iterative version - Addition of " << x << " and " << y
            << " is " << sum(x, y) << std::endl;
  std::cout << "Recursive version - Addition of " << x << " and " << y
            << " is " << sum2(x, y) << std::endl;
  return 0;
}

