struct node *getnode()
{
	struct node *newnode = (struct node*)malloc(sizeof(struct node));
	newnode -> prev = newnode ->next = NULL;
	return newnode;
}

struct node *insert(struct node *head, int r, int c, int d)
{
	struct node *newnode = getnode();
	newnode -> row = r;
	newnode -> col = c;
	newnode -> data = d;
	if(head == NULL)
	{
		head = newnode;
	}
	else
	{
		newnode -> next = head;
		head -> prev = newnode;
		head = newnode;
	}
	return head;
}

