function checkPair(obj){
	var paircnt = 0;
	for(var i=1;i<=9;i++){
		if(obj[i] >= 3){
			obj[i] -= 3;
			paircnt++;
		}
	}
	for(var i=1;i<=9;i++){
		if(obj[i] >= 1 && obj[i+1] >= 1 && obj[i+2] >= 1){
			obj[i] -= 1;
			obj[i+1] -= 1;
			obj[i+2] -= 1;
			i--;
			paircnt++;
