#define NUM 3005


enum Type{
	UNDEFINED,
	MUST_MEDICAL,
};

struct Info{
	Info(){
		node_index = 0;
		edge_num = 0;
	}
	Info(int arg_node_index,int arg_edge_num){
		node_index = arg_node_index;
		edge_num = arg_edge_num;
	}
	bool operator<(const struct Info &arg) const{
		return edge_num > arg.edge_num;
	}
	int node_index,edge_num;
};

int V,E,K,num_nodes;
int edge_num[NUM];
bool edge[NUM][NUM];
int ans,minimum;
Info first_info[NUM],info[NUM];
vector<int> first_G[NUM],G[NUM];
Type type[NUM];
map<int,int> MAP;

int total_index;


void recursive(int index){

	if(ans >= minimum || ans > K){
		return;
	}

	if(index == num_nodes){
		if(E == 0){
			minimum = ans;
		}else{
			printf("BUGG!!\n");
		}
		return;
	}

	int node_id = info[index].node_index;

	if(ans+(min(K-ans,num_nodes-index)*info[index].edge_num) < E){
		return;
	}

	if(edge_num[node_id] == 0){
		recursive(index+1);
		return;
	}

	if(type[node_id] == MUST_MEDICAL || edge_num[node_id] >= 2){

		if(type[node_id] == UNDEFINED){
			ans++;
		}
		E -= edge_num[node_id];
		for(int i = 0; i < G[node_id].size(); i++){
			if(!edge[node_id][G[node_id][i]])continue;
			edge_num[G[node_id][i]]--;
			edge[G[node_id][i]][node_id] = false;
		}

		recursive(index+1);

		if(type[node_id] == UNDEFINED){
			ans--;
		}
		E += edge_num[node_id];
		for(int i = 0; i < G[node_id].size(); i++){
			if(!edge[node_id][G[node_id][i]])continue;
			edge_num[G[node_id][i]]++;
			edge[G[node_id][i]][node_id] = true;
		}

		if(type[node_id] == MUST_MEDICAL)return;
	}

	if(ans+edge_num[node_id] >= min(minimum,K+1))return;

	ans += edge_num[node_id];
	E -= edge_num[node_id];

	for(int i = 0; i < G[node_id].size(); i++){
		if(!edge[node_id][G[node_id][i]])continue;
		edge_num[G[node_id][i]]--;
		type[G[node_id][i]] = MUST_MEDICAL;
		edge[G[node_id][i]][node_id] = false;
	}

	recursive(index+1);

	ans -= edge_num[node_id];
	E += edge_num[node_id];

	for(int i = 0; i < G[node_id].size(); i++){
		if(!edge[node_id][G[node_id][i]])continue;
		edge_num[G[node_id][i]]++;
		type[G[node_id][i]] = UNDEFINED;
		edge[G[node_id][i]][node_id] = true;
	}
}

int get_index(int node_id){

	auto at = MAP.find(node_id);
	if(at == MAP.end()){
		MAP[node_id] = total_index++;
	}
	return MAP[node_id];
}

