		first_G[from].push_back(to);
		first_G[to].push_back(from);

		edge[from][to] = true;
		edge[to][from] = true;
	}

	sort(first_info,first_info+V);

	ans = 0;

	for(int i = 0; i < V; i++){
		if(first_info[i].edge_num <= K)break;

		ans++;
		type[i] = MUST_MEDICAL;

		E -= first_G[first_info[i].node_index].size();

		for(int k = 0; k < first_G[first_info[i].node_index].size(); k++){

			edge[first_info[i].node_index][first_G[first_info[i].node_index][k]] = false;
			edge[first_G[first_info[i].node_index][k]][first_info[i].node_index] = false;
		}
	}

	if(ans > K){
		printf("Impossible\n");
		return 0;
	}

	int index = 0,node_id;

	for(int i = 0; i < V; i++){
		if(type[i] == MUST_MEDICAL)continue;

		info[index].node_index = first_info[i].node_index;
		node_id = info[index].node_index;

		for(int k = 0; k < first_G[node_id].size(); k++){
			if(edge[node_id][first_G[node_id][k]] == false)continue;

			edge_num[node_id]++;

			G[node_id].push_back(first_G[node_id][k]);
		}
		info[index].edge_num = edge_num[node_id];
		index++;
	}

	sort(info,info+index);

	minimum = BIG_NUM;

	for(int i = 0; i < V; i++){
		type[i] = UNDEFINED;
	}

	num_nodes = index;

	recursive(0);

	if(minimum > K){

		printf("Impossible\n");

	}else{

		printf("%d\n",minimum);
	}

	return 0;
}

