struct node {
    char book[101];
    struct node *next;
};

struct node *top = NULL;
int count = 0;

void push(char name[]) {

    struct node *newNode = (struct node*)malloc(sizeof(struct node));

    if (newNode == NULL) {
        printf("Stack Overflow\n");
        return;
    }

    strcpy(newNode->book, name);
    newNode->next = top;
    top = newNode;
    count++;
}

void pop() {

    if (top == NULL) {
        printf("Stack Underflow\n");
        return;
    }

    struct node *temp = top;
    top = top->next;
    free(temp);
    count--;
}

void peek() {

    if (top == NULL) {
        printf("Stack Underflow\n");
        return;
    }

    printf("%s\n", top->book);
}

void isEmpty() {

    if (top == NULL)
        printf("true\n");
    else
        printf("false\n");
}

void size() {

    printf("%d\n", count);
}

