            int a;
            scanf("%d", &a);
            lose[a] = 1;
        }
        for(int i = 0; i < B; i++){
            int a;
            scanf("%d", &a);
            back[a] = 1;
        }
        vector< dvec > dp(T + 1, dvec(N + 1, 0));
        dp[0][0] = 1;
        for(int i = 0; i < T; i++){
            for(int j = 0; j < N; j++){
                for(int s = 1; s <= 6; s++){
                    int nxt = j + s;
                    if(j + s > N){
                        nxt = N - (j + s - N);
                    }
                    if(lose[nxt]){
                        if(i > T - 2) continue;
                        dp[i + 2][nxt] += dp[i][j] / 6;
                    }else if(back[nxt]){
                        dp[i + 1][0] += dp[i][j] / 6;
                    }else{
                        dp[i + 1][nxt] += dp[i][j] / 6;
                    }
                }
            }
            dp[i + 1][N] += dp[i][N];
        }
        printf("%.12f\n", dp[T][N]);
    }
    
    return 0;
}

