/* constant */

const int MAX_N = 10000;
const int INF = 1 << 29;

/* typedef */

typedef pair<int,int> pii;
typedef vector<pii> vpii;

struct Edge {
  int i, d, c;
  Edge() {}
  Edge(int _i, int _d, int _c): i(_i), d(_d), c(_c) {}
};

typedef vector<Edge> ve;

/* global variables */

int n, m;
ve nbrs[MAX_N];
pii dists[MAX_N];

/* subroutines */

/* main */

int main() {
  for (;;) {
    cin >> n >> m;
    if (n == 0) break;

    for (int i = 0; i < n; i++)
      nbrs[i].clear(), dists[i] = pii(INF, INF);
    
    for (int i = 0; i < m; i++) {
      int u, v, d, c;
      cin >> u >> v >> d >> c;
      u--, v--;

      nbrs[u].push_back(Edge(v, d, c));
      nbrs[v].push_back(Edge(u, d, c));
    }

    dists[0] = pii(0, 0);

    priority_queue<pii,vpii,greater<pii> > q;
    q.push(pii(0, 0));

    while (! q.empty()) {
      pii u = q.top(); q.pop();

      int& ud = u.first;
      int& ui = u.second;
      if (ud > dists[ui].first) continue;

      ve& nbru = nbrs[ui];
      for (ve::iterator vit = nbru.begin(); vit != nbru.end(); vit++) {
	int& vi = vit->i;
	int& vd = vit->d;
	int nvd = ud + vd;
	pii vdist(nvd, vit->c);

	if (dists[vi] > vdist) {
	  if (dists[vi].first > nvd) q.push(pii(nvd, vi));
	  dists[vi] = vdist;
	}
      }
    }

    int sum = 0;

    for (int i = 1; i < n; i++)
      sum += dists[i].second;

    cout << sum << endl;
  }
  
  return 0;
}

//LeetCode 22. Generate Parentheses
//Question - https://leetcode.com/problems/generate-parentheses/

class Solution {
    public List<String> generateParenthesis(int n) {
        List<String> res = new ArrayList<>();
        helper("", res, 0, 0, n);
        return res;
    }
    
    public void helper(String str, List<String> l, int open, int close, int n){
        if(str.length() == n*2){
            l.add(str);
            return;
        }
        
        //each valid parentheses must have n open braces and not more.
        if(open < n) helper(str + '(', l, open + 1, close, n);
        //To maintain a valid parentheses, the closed brackets can only be added when 
        //we have corresponding open brackets available.
        if(close < open) helper(str + ')', l, open, close + 1, n);
    }
}

