P crosspoint(P a,P b,P c,P d){
  double A = cross(b - a, d - c);
  double B = cross(b - a, b - c);
  if (abs(A) < EPS && abs(B) < EPS) return c; // same line
  if (abs(A) < EPS) assert(false); // !!!PRECONDITION NOT SATISFIED!!!
  return c + B / A * (d - c);
