int binarySearch_recursive(int a[],int key,int low ,int high){
	int mid;
	if(low<=high){
		mid=(low+high)/2;
		if(a[mid]==key){
			return mid;
		}
		else if(a[mid]<key)
			return binarySearch_recursive(a,key,mid+1,high);
		else 
			return binarySearch_recursive(a,key,low,mid-1);

	}
	return -1;
}

