}

void decrypt(int rows, int cols, char str[])
{
    int i;
    for(i=0;str[i] != '\0';i++)
    {
        switch (str[i])
        {
        case '*': str[i] = 'A';
            break;
        case '+': str[i] = 'E';
            break;
        case 'Q': str[i] = 'I';
            break;
        case '-': str[i] = 'O';
            break;
        case '?': str[i] = 'U';
            break;
        default:
            break;
        }
    }
}


