//Bubble sort algoritam za sortiranje niza
//Slozenost: O(n^2)

inline void bubbleSort()
{
    bool swapped;
    int it = 0;
    do
    {
        swapped = false;
        for (int i=0;i<n-it-1;i++)
        {
            if (niz[i] > niz[i+1])
            {
                swap(niz[i], niz[i+1]);
                swapped = true;
            } 
        }
        it++;
    } while (swapped);
}

