void _counting_sort_for_radix_sort(int arr[], int digit, int n)
{
    int aux[n];
    int freq[10] = {0};
    for(int i=0;i<n;i++) freq[(arr[i]/(int)pow(10.,digit-1))%10]++;
    for(int i=1;i<10;i++) freq[i] += freq[i-1];
    for(int i=0;i<n;i++)
    {
        int ind = (arr[i]/(int)pow(10.,digit-1))%10;
        aux[freq[ind]-1] = arr[i];
        freq[ind]--;
