int binary_search_rec(int* arr, int low, int high, int x) {
    if (high >= low) {
        int mid = low + (high - low) / 2;
        if (arr[mid] == x) {
            return mid;
        }
        if (arr[mid] > x) {
            return binary_search_rec(arr, low, mid - 1, x);
        }
        return binary_search_rec(arr, mid + 1, high, x);
    }
    return -1;
}

