const int N = 100003;
int n, fa[N], f, r;
set<int> S[N];
map<pii, int> M;
pii q[N];
inline int getfa(int x){
	while(x != fa[x]) x = fa[x] = fa[fa[x]];
	return x;
}
int main(){
	read(n);
	for(Rint i = 1;i <= n;++ i) fa[i] = i;
	for(Rint i = 1, u, v;i <= 2 * (n - 1);++ i){
		read(u); read(v);
		S[u].insert(v); S[v].insert(u);
		++ M[MP(u, v)]; ++ M[MP(v, u)];
		if(M[MP(u, v)] == 2) q[r ++] = MP(u, v);
	}
	while(f < r){
		int u = q[f].fi, v = q[f].se; ++ f;
		u = getfa(u); v = getfa(v);
		if(S[u].size() < S[v].size()) swap(u, v);
		fa[v] = u; S[u].erase(v); S[v].erase(u);
		for(Rint x : S[v]){
			S[x].erase(v); S[x].insert(u); S[u].insert(x);
			M[MP(x, v)] = M[MP(v, x)] = 0;
			++ M[MP(x, u)]; ++ M[MP(u, x)];
			if(M[MP(x, u)] == 2) q[r ++] = MP(x, u);
		}
		S[v].clear();
	}
	puts(r == n - 1 ? "YES" : "NO");
}

