int solve(int bit, int H, int W, int K, vector<string> &S){
    int cnt = __builtin_popcount(bit);
    vector<vector<int>> tot(cnt+1, vector<int>(W));
    int pos = 0;
    for(int i=0; i<H; i++){
        for(int j=0; j<W; j++){
            if(S[i][j] == '1')
                tot[pos][j]++;
        }
        if(bit&(1<<i)) pos++;
    }

    int ans = cnt;
    vector<int> cumsum(cnt+1);
    for(int i=0; i<W; i++){
        for(int pos=0; pos<cnt+1; pos++){
            if(tot[pos][i] > K) return 1<<30;
            cumsum[pos] += tot[pos][i];
        }
        bool over = false;
        for(int pos=0; pos<cnt+1; pos++){
            if(cumsum[pos] > K){
                over=true;
            }
        }
        if(over){
            ans++;
            for(int pos=0; pos<cnt+1; pos++){
                cumsum[pos] = tot[pos][i];
            }
        }
    }
    return ans;
}

