		//2_ð~üãÉÂ~ðè
		for (int i = 0; i < n; i++) {
			for (int j = i + 1; j < n; j++) {
				double d = hypot(p[i].first - p[j].first, p[i].second - p[j].second);
				if (d > 2.0 + EPS) continue;	//£ê·¬
				
				//_(»ê¼êÌÀWÌ½Ï)
				pair<double, double> m((p[i].first + p[j].first) / 2.0, (p[i].second + p[j].second) / 2.0);
