class SecretOfChocolatePoles {
public:
    SecretOfChocolatePoles(int l, int k) : l(l), k(k), dp(l + 1) {};

    long long Count() {
        dp[1] = 1;
        if (k <= l) dp[k] = 1;
        for (int h = 2; h <= l; ++h) {
            if (0 <= h - 2) dp[h] += dp[h - 2];
            if (0 <= h - k - 1) dp[h] += dp[h - k - 1];
        }

        return accumulate(dp.begin(), dp.end(), 0LL);
    }
private:
    int l, k;
    vector<long long> dp;
};

