void dfs(int u, int p) {
	for (auto &e : g[u]) {
		int v = e.first, id = e.second;
		if (v != p) {
			depth[v] = depth[u] + 1;
			par[v] = u;
			up[v] = id;
			dfs(v, u);
		}
	}
}

