		d[i][mn[i]] = P(0,mn[i]);
		que.push(mn[i]);
		while(!que.empty()){
			int p = que.front();
			que.pop();
			each(v,G[p]){
				if(d[i][p].fi+1 < d[i][v].fi){
					d[i][v] = P(d[i][p].fi+1,min(d[i][p].se,v));
					que.push(v);
				}else if(d[i][p].fi+1 == d[i][v].fi && d[i][v].se > d[i][p].se){
					d[i][v].se = d[i][p].se;
					que.push(v);
				}
			}
		}
	}
	P ans = P(INF,INF);
	rep(i,n){
		cmn(ans,P(d[0][i].fi+d[1][i].fi+d[2][i].fi,min({d[0][i].se,d[1][i].se,d[2][i].se})));
	}
	cout << ans.fi << " " << ans.se+1 << "\n";
	return 0;
}

