char *search(char *s, char *t)
{
    char *p = s;
    char *q = t;
    while (*p != '\0')
    {
        if (*p == *q)
        {
            char *temp = p;
            while (*q != '\0')
            {
                if (*temp != *q)
                    break;
                temp++;
                q++;
            }
            if (*q == '\0')
                return p;
            else
            {
                q = t;
                p++;
            }
        }
        else
            p++;
    }
    return NULL;
}

