int dp[410][410];
int N,C,A[410],B[410];
int sum[410][410];

int main(){
	for(int j = 1; j <= 400; ++j) sum[0][j] = 1;
	for(int j = 1; j <= 400; ++j){
		sum[1][j] = j;
		for(int i = 2; i <= 400; ++i){
			sum[i][j] = 1ll * sum[i - 1][j] * j % mod;
		}
	}
	for(int i = 0; i <= 400; ++i){
		for(int j = 1; j <= 400; ++j){
			sum[i][j] = (sum[i][j] + sum[i][j - 1]) % mod;
		}
	}
	scanf("%d%d",&N,&C);
	for(int i = 1; i <= N; ++i){
		scanf("%d",&A[i]);
	}
	for(int i = 1; i <= N; ++i){
		scanf("%d",&B[i]);
	}
	dp[0][0] = 1;
	for(int i = 1; i <= N; ++i){
		for(int j = 0; j <= C; ++j){
			for(int k = 0; k <= j; ++k){
				// dp[i - 1][k] --> dp[i][j]
				dp[i][j] = (dp[i][j] + 1ll * dp[i - 1][k] * (sum[j - k][B[i]] - sum[j - k][A[i] - 1]) % mod) % mod;
				if(dp[i][j] < 0) dp[i][j] += mod;
			}
		}
	}
	printf("%d\n",dp[N][C]);
	return 0;
}

