	}
	std::cout << std::endl;
}

void insert(ListNode* &  head, int data ) {

	ListNode * newNode = new ListNode(data);
	if ( head == nullptr ) {
		head = newNode;
	} else {
		ListNode * curr = head;
		while ( curr->next != nullptr ) {
			curr = curr->next;
		}
		curr->next = newNode;
	}
}

int length(ListNode * head) {
	int count = 0;
	while( head ) {
		head = head->next;
		++count;
	}
	return count;
}


ListNode* rotateRight(ListNode* head, int k) {
	if ( head == nullptr ||  head->next == nullptr) {
		return head;
	}
	int len = length(head);
	k = k % len;
	if ( k == 0) {
		return head;
	}
	ListNode * ptr1 = head;
	ListNode * ptr2 = head;
	int c = 0;
	while( ptr1 && c < k ) {
		ptr1 = ptr1->next;
		c++;
	}
	if (!ptr1) {
		return nullptr;
	}
	while( ptr1 && ptr1->next != nullptr ) {
		ptr1 = ptr1->next;
		ptr2 = ptr2->next;
	}
	ListNode * newHead = ptr2->next;
	ptr2->next = nullptr;
	ptr1->next = head;
	return newHead;
}


