#define N 50
int queue[N];
int front = -1;
int rear = -1;

void enqueue()
{
    int x;
    printf("Enter the Element to be inserted:\n");
    scanf("%d", &x);
    if (rear == N - 1)
    {
        printf("Queue is Full!\n");
    }
    else if (front == -1 && rear == -1)
    {
        rear = front = 0;
        queue[rear] = x;
    }
    else
    {
        rear++;
        queue[rear] = x;
    }
}

void dequeue()
{
    if (front == -1 && rear == -1)
    {
        printf("Queue is Empty!\n");
    }
    else if (front == rear)
    {
        front = rear = -1;
    }
    else
    {
        front++;
    }
}

void display()
{
    if (front == -1 && rear == -1)
    {
        printf("Queue is Empty\n");
    }
    else
    {
        for (int i = front; i < rear + 1; i++)
        {
            printf("%d ", queue[i]);
        }
    }
    printf("\n");
}

void peek()
{
    if (front == -1 && rear == -1)
    {
        printf("Queue is Empty\n");
    }
    else
    {
        printf("Front Element: %d", queue[front]);
    }
}

