		long ans=0;
		int N=a.length;
		dp[N][1][0]=1;dp[N][0][0]=1;

		for(int i=N-1;i>=0;i--) 
			for(int tight=0;tight<2;tight++)
				for(int sum=0;sum<180;sum++) {

					if(tight==0) {
						for(int d=0;d<=9;d++) {
							if(sum-d>=0)
							dp[i][0][sum]+=dp[i+1][0][sum-d];
						}
					}
					else {
						for(int d=0;d<=a[i];d++) {
							if(sum-d>=0)
							dp[i][1][sum]+=(d==a[i])?dp[i+1][1][sum-d] : dp[i+1][0][sum-d];
						}
					}

				}//sum

