public class rod_cutDP1 {
//top down recursive function Time complexity O(n^2);

	public static int cut_rod(int p[],int n)
	{
		int max=Integer.MIN_VALUE;
		if(n==0)
			return 0;
		else
		{
			for(int j=0;j<n;j++)
			{
				max=Math.max(max, p[j]+cut_rod(p,n-j-1));
			}
		}
		return max;
	}


