{
	//freopen("233.txt","r",stdin);
    memset(Next, -1, sizeof(Next));
    int a, b, c;
    scanf("%d",&n);
    for(int i=1; i<n; ++i)
    {
        scanf("%d%d%d",&a,&b,&c);
        add_edge(a, b, c);
    }
    dfs(1, 0, 0);
    int com = 0x3f3f3f3f;
    for(int i=Next[mid]; i!=-1; i=edge[i].next)
    {
        int v = edge[i].e;
        com = min(com, edge[i].w);
        if(zhong[v] == zhong[mid])
        {
            ans -= edge[i].w;
            return 0*printf("%lld\n",ans);
        }
    }
    printf("%lld\n",ans-com);
    return 0;
}

