void Forward(const string &text, unsigned &cursor, bool is_char) {
	if(is_char) {
		if(cursor < text.size()) ++cursor;
	}
	else {
		while(cursor < text.size() && isblank(text[cursor])) ++cursor;
		while(cursor < text.size() && !isblank(text[cursor])) ++cursor;
	}
}

void Backward(const string &text, unsigned &cursor, bool is_char) {
	if(is_char) {
		if(cursor > 0) --cursor;
	}
	else {
		while(cursor > 0 && isblank(text[cursor - 1])) --cursor;
		while(cursor > 0 && !isblank(text[cursor - 1])) --cursor;
	}
}

void Insert(string &text, unsigned &cursor, const string &target) {
	const string insert_text = target.substr(1, target.size() - 2);
	text.insert(cursor, insert_text);
	cursor += insert_text.size();
}

void Delete(string &text, unsigned cursor, bool is_char) {
	if(is_char) {
		if(cursor < text.size()) text.erase(text.begin() + cursor);
	}
	else {
		unsigned idx = cursor;
		Forward(text, idx, false);
		if(idx == 0 || isblank(text[idx - 1])) return;
		text.erase(text.begin() + cursor, text.begin() + idx);
	}
}

