    // MÃ©todo para calcular la distancia total recorrida a partir de una cadena de puntos
    public int calculateTotalDistance(String[] points) {
        int totalDistance = 0;

        // Iterar sobre el array de puntos para sumar las distancias entre ellos
        for (int i = 0; i < points.length - 1; i++) {
            String point1 = points[i];
            String point2 = points[i + 1];

            // Verificar si la distancia entre los puntos estÃ¡ definida
            int distance = getDistance(point1, point2);
            if (distance == -1) {
                // La distancia entre los puntos no estÃ¡ definida, por lo que la ruta no es vÃ¡lida
                System.out.println("La ruta especificada no es vÃ¡lida debido a que la distancia entre " + point1 + " y " + point2 + " no estÃ¡ definida.");
                return -1;
            }

            // Sumar la distancia al total
            totalDistance += distance;
        }

        return totalDistance;
    }
