        while(!que.empty())
        {
            P p = que.top(); que.pop();
            int v = p.second;
            if(dist[v] < p.first) continue;
            rep(i, G[v].size())
            {
                Edge &e = G[v][i];
                if(e.cap > 0 && dist[e.to] > dist[v] + e.cost + h[v] - h[e.to]) {
                    dist[e.to] = dist[v] + e.cost + h[v] - h[e.to];
                    prevv[e.to] = v; preve[e.to] = i;
                    que.push(P(dist[e.to], e.to));
                }
            }
        }
        
        if(!first) rep(v, MAX_V) h[v] += dist[v];
        first = false;
        if(h[sink] >= 0) return res;
        
        int f = INF;
        for(int v = sink; v != src; v = prevv[v])
            f = min(f, G[prevv[v]][preve[v]].cap);
        res -= f * h[sink];
        for(int v = sink; v != src; v = prevv[v]) {
            Edge &e = G[prevv[v]][preve[v]];
            e.cap -= f;
            G[v][e.rev].cap += f;
        }
    }
}

int main()
{
    int Nn, Np, Kn[N], Kp[N], M, P, L, In, Ip, NJ;
    string A, J;
    
    while(cin >> Nn >> Np && Nn)
    {
        map<string, int> table;
        fill_n(h, MAX_V, 0);
        rep(i, MAX_V) G[i].clear();
        
        rep(i, Nn) cin >> Kn[i], add_edge(src, i, Kn[i], 0);
        rep(i, Np) cin >> Kp[i], add_edge(Nn+i, sink, Kp[i], 0);
        cin >> M;
        rep(i, M) cin >> A >> P, table[A] = P;
        cin >> L; int vmax = 0;
        rep(i, L) {
            int v = 0;
            cin >> In >> Ip >> NJ;
            rep(j, NJ) cin >> J, v += table[J];
            add_edge(In-1, Nn+Ip-1, INF, -v);   // reverse sign of cost
            h[Nn+Ip-1] = min(h[Nn+Ip-1], -v);
            vmax = max(vmax, v);
        }
        
        h[sink] = -vmax;
        cout << min_cost_flow() << endl;
    }
}

// C++ implementation of search and insert 
// operations on Trie 
#include <bits/stdc++.h> 
using namespace std; 

const int ALPHABET_SIZE = 26; 

// trie node 
struct TrieNode 
{ 
    struct TrieNode *children[ALPHABET_SIZE]; 

    // isEndOfWord is true if the node represents 
    // end of a word 
    bool isEndOfWord; 
}; 

// Returns new trie node (initialized to NULLs) 
struct TrieNode *getNode(void) 
{ 
    struct TrieNode *pNode =  new TrieNode; 

    pNode->isEndOfWord = false; 

    for (int i = 0; i < ALPHABET_SIZE; i++) 
        pNode->children[i] = NULL; 

    return pNode; 
} 

// If not present, inserts key into trie 
// If the key is prefix of trie node, just 
// marks leaf node 
void insert(struct TrieNode *root, string key) 
{ 
    struct TrieNode *pCrawl = root; 

    for (int i = 0; i < key.length(); i++) 
    { 
        int index = key[i] - 'a'; 
        if (!pCrawl->children[index]) 
            pCrawl->children[index] = getNode(); 

        pCrawl = pCrawl->children[index]; 
    } 

    // mark last node as leaf 
    pCrawl->isEndOfWord = true; 
} 

// Returns true if key presents in trie, else 
// false 
bool search(struct TrieNode *root, string key) 
{ 
    struct TrieNode *pCrawl = root; 

    for (int i = 0; i < key.length(); i++) 
    { 
        int index = key[i] - 'a'; 
        if (!pCrawl->children[index]) 
            return false; 

        pCrawl = pCrawl->children[index]; 
    } 

    return (pCrawl != NULL && pCrawl->isEndOfWord); 
} 

// Driver 
int main() 
{ 
    // Input keys (use only 'a' through 'z' 
    // and lower case) 
    string keys[] = {"the", "a", "there", 
                    "answer", "any", "by", 
                     "bye", "their" }; 
    int n = sizeof(keys)/sizeof(keys[0]); 

    struct TrieNode *root = getNode(); 

    // Construct trie 
    for (int i = 0; i < n; i++) 
        insert(root, keys[i]); 

    // Search for different keys 
    search(root, "the")? cout << "Yes\n" : 
                         cout << "No\n"; 
    search(root, "these")? cout << "Yes\n" : 
                           cout << "No\n"; 
    return 0; 
}

# Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def insert(self, root: TreeNode, num: int) -> TreeNode:
        if not root: return TreeNode(num)

        if root.val > num:
            root.left = self.insert(root.left, num)
        else:
            root.right = self.insert(root.right, num)

        return root

    def bstFromPreorder(self, preorder: List[int]) -> TreeNode:
        root = TreeNode(preorder[0])

        for i in range(1, len(preorder)):
            root = self.insert(root, preorder[i])

        return root

# 0/1 knapsack
# O(N*Capacity) time |  # O(N*Capacity) space
# My solution, Passes
def knapsackProblem(items, capacity):
    dp = [[0 for _ in range(capacity + 1)] for _ in range(len(items))]

    # Populate the first row for first item
    for cap in range(capacity + 1):
        val, wei = items[0]  # first item
        if cap >= wei:
            dp[0][cap] = val

    for itemIdx in range(1, len(items)):
        for cap in range(1, capacity + 1):
            val, wei = items[itemIdx]
            cValue1, cValue2 = 0, 0
            if wei <= cap:
                cValue1 = val + dp[itemIdx - 1][cap - wei]
            cValue2 = dp[itemIdx - 1][cap]
            dp[itemIdx][cap] = max(cValue1, cValue2)
    return [dp[-1][-1], buildItemSequence(dp, items, capacity)]


def buildItemSequence(dp, items, capacity):
    sequence = []
    currentItemIdx, currentCapacity = len(items) - 1, capacity
    while currentItemIdx >= 0:
        if dp[currentItemIdx][currentCapacity] == dp[currentItemIdx - 1][currentCapacity]:
            currentItemIdx -= 1
        else:
            sequence.append(currentItemIdx)
            currentCapacity -= items[currentItemIdx][1]
            currentItemIdx -= 1
        if currentCapacity == 0:
            break
    return list(reversed(sequence))


