			int cost = next_item.second;

			if (!visited[next]) {
				Q.push(next);
				x[next] = x[current] + cost;
				visited[next] = true;
			}
			else if (x[next] != x[current] + cost) {
				ret = false;
			}
		}
	}

	return ret;
}

