		void rot_f(){ rotation(f,u,b,d);}
		void rot_b(){ rotation(b,u,f,d);}
		void rot_l(){ rotation(l,u,r,d);}
		void rot_r(){ rotation(r,u,l,d);}

		inline bool valid(){
			if(l<0||r<0||f<0||b<0||d<0||u<0) return false;
			int na=u+d,nb=l+r,nc=f+b;
			if(na>nb+nc) return false;
			if(nb>na+nc+1) return false;
			if(nc>na+nb+1) return false;
			return true;
		}
};



