void calc() {
	int NG = 0;
	
	rep(i, HN) rep(j, WN) {
		int a = HP[i].first;
		int b = HP[i].second;
		int c = WP[j].first;
		int d = WP[j].second;
		if (S[a][c] != S[b][d]) NG = 1;
		if (S[a][d] != S[b][c]) NG = 1;
	}

	if (H % 2) {
		rep(i, WN) {
			int c = WP[i].first;
			int d = WP[i].second;
			if (S[areH][c] != S[areH][d]) NG = 1;
		}
	}
	if (W % 2) {
		rep(i, HN) {
			int a = HP[i].first;
			int b = HP[i].second;
			if (S[a][areW] != S[b][areW]) NG = 1;
		}
	}
	if (NG == 0) OK = 1;
}

void SWP(int A) {
	if (A == -1) {
		rep(i, W) {
			areW = i;
			usedW[i] = 1;
			SWP(0);
			usedW[i] = 0;
		}
		return;
	}
	if (A == WN) {
		calc();
		return;
	}
	rep(i, W) if (usedW[i] == 0) {
		usedW[i] = 1;
		rep(j, W) {
			if (usedW[j] == 0) {
				usedW[j] = 1;
				WP[A] = mp(i, j);
				SWP(A + 1);
				usedW[j] = 0;
			}
		}
		usedW[i] = 0;
		return;
	}
}

void SHP(int A) {
	if (A == -1) {
		rep(i, H) {
			areH = i;
			usedH[i] = 1;
			SHP(0);
			usedH[i] = 0;
		}
		return;
	}
	if (A == HN) {
		if (W % 2) SWP(-1);
		else SWP(0);
		return;
	}
	rep(i, H) if (usedH[i] == 0) {
		usedH[i] = 1;
		rep(j, H) {
			if (usedH[j] == 0) {
				if (OK) return;
				if (S2[i] == S2[j]) {
					usedH[j] = 1;
					HP[A] = mp(i, j);
					SHP(A + 1);
					usedH[j] = 0;
				}
			}
		}
		usedH[i] = 0;
		return;
	}
}

