typedef vector<int> vi;
typedef vector<ii> vii;

using namespace std;

int n, m, S, T, w;

vector<vii> AdjList;
vi dist;
priority_queue<ii, vector<ii>, greater<ii>> pq;

void dijkstra(int s)
{

    dist.assign(n, 1e9);
    dist[s] = 0;

    pq.push(ii(0, s));

    while (!pq.empty())
    {
        ii front = pq.top(); pq.pop();
        int d = front.first, u = front.second;
        if (d > dist[u])
            continue;
        for (int j = 0; j < (int)AdjList[u].size(); j++)
        {
            ii v = AdjList[u][j];
            if (dist[u] + v.second < dist[v.first])
            {
                dist[v.first] = dist[u] + v.second;
                pq.push(ii(dist[v.first], v.first));
            }
        }
    }

    if (dist[T] == 1e9)
        cout << "unreachable" << endl;
    else
        cout << dist[T] << endl;
}

int main()
{
    int numCases;
    cin >> numCases;
    while (numCases--)
    {
        scanf("%d %d %d %d", &n, &m, &S, &T);

        AdjList.assign(n, vii());

        int n1, n2;
        for (int i = 0; i < m; i++)
        {
            scanf("%d %d %d", &n1, &n2, &w);
            AdjList[n1].push_back(ii(n2, w));
            AdjList[n2].push_back(ii(n1, w));
        }
        dijkstra(S);
    }

    return 0;
}

// Write a menu driven program to implement of Circular queue operations using linked list. The operation are such as :- 
//         1. Insert 
//         2. Delete 
//         3. Display
//         4. Exit

#include <stdio.h>
#include <stdlib.h>

struct Node
{
    int data;
    struct Node *next;
};

typedef struct Node Node;

Node *front = NULL;
Node *rear = NULL;

void enqueue(int value);
int dequeue();
void display();
int isEmpty();

int main()
{
    int choice, value;

    while (1)
    {
        printf("\n1. Insert\n");
        printf("2. Delete\n");
        printf("3. Display\n");
        printf("4. Exit\n");
        printf("Enter your choice: ");
        scanf("%d", &choice);

        switch (choice)
        {
        case 1:
            printf("Enter the value to insert: ");
            scanf("%d", &value);
            enqueue(value);
            break;
        case 2:
            if (!isEmpty())
            {
                printf("Deleted element: %d\n", dequeue());
            }
            else
            {
                printf("Queue is empty. Cannot delete.\n");
            }
            break;
        case 3:
            display();
            break;
        case 4:
            printf("Exiting the program.\n");
            // return 0;
            exit(0);
            break;
        default:
            printf("Invalid option. Please enter a valid choice.\n");
        }
    };

    return 0;
}

void enqueue(int value)
{
    Node *newNode = (Node *)malloc(sizeof(Node));
    if (newNode == NULL)
    {
        printf("Memory allocation failed. Cannot insert element %d.\n", value);
        return;
    }

    newNode->data = value;
    newNode->next = NULL;

    if (isEmpty())
    {
        front = rear = newNode;
    }
    else
    {
        rear->next = newNode;
        rear = newNode;
    }

    rear->next = front;

    printf("Inserted %d into the queue.\n", value);
}

int dequeue()
{
    if (isEmpty())
    {
        printf("Queue is empty. Cannot delete.\n");
        return -1;
    }

    int deletedValue = front->data;
    Node *temp = front;

    if (front == rear)
    {
        front = rear = NULL;
    }
    else
    {
        front = front->next;
        rear->next = front;
    }

    free(temp);
    return deletedValue;
}

void display()
{
    if (isEmpty())
    {
        printf("Queue is empty.\n");
        return;
    }

    Node *temp = front;
    printf("Queue elements: ");
    do
    {
        printf("%d ", temp->data);
        temp = temp->next;
    } while (temp != front);

    printf("\n");
}

int isEmpty()
{
    return front == NULL;
}

