#include <stdlib.h>
#define SIZE 5

void scanData(int a[])
{
    for (int i = 0; i < SIZE; i++)
    {
        printf("Enter the value of a[%d]: ", i);
        scanf("%d", &a[i]);
    }
}

void dispData(int a[])
{
    for (int i = 0; i < SIZE; i++)
    {
        printf("%d\t", a[i]);
    }
}

int LinearSearch(int a[], int key)
{
    int index = -1;

    for (int i = 0; i < SIZE; i++)
    {
        if (a[i] == key)
        {
            index = i;
            break;
        }
    }
    return index;
}

int BinarySearch(int a[], int key)
{
    int index = -1;
    int min = 0, mid, max = SIZE - 1;

    while (min <= max)
    {
        mid = (min + max) / 2;
        if (a[mid] == key)
        {
            index = mid;
            break;
        }
        else if (key > a[mid])
        {
            min = mid + 1;
        }
        else
        {
            max = mid - 1;
        }
    }
}

