// My approach, not completely correct
function pivot(arr) {
    // Let's choose the pivot to be the arr[0] element
    let pivotIndex = 0;
    for (let i = 0; i < arr.length; i++) {
        // If current element is lesser than our pivot element
        if (arr[i] < arr[0]) {
            // Increment the pivot index
            pivotIndex++;
            // Swap current element with the element at the new pivot index
            [arr[i], arr[pivotIndex]] = [arr[pivotIndex], arr[i]];
        }
    }
    // Swap the pivot element with the element at the pivotIndex index
    [arr[0], arr[pivotIndex]] = [arr[pivotIndex], arr[0]];
    // Return the index of the pivot element after swapping
    return pivotIndex;
}

// Colt's solution
function pivot(arr, start = 0, end = arr.length - 1) {
    let pivot = arr[start];
    let swapIdx = start;

    for (let i = start + 1; i <= end; i++) {
        if (arr[i] < pivot) {
            swapIdx++;
            [arr[i], arr[swapIdx]] = [arr[swapIdx], arr[i]];
        }
    }
    [arr[swapIdx], arr[start]] = [arr[start], arr[swapIdx]];
    return swapIdx;
}

// --------------------------------------------------------------------
// Actual quick sort function
function quickSort(arr, left = 0, right = arr.length - 1) {
    // Base case is that the left and right pointers don't overlap, after which we'll be left with an array of 1 item
    if (left < right) {
        let pivotIndex = pivot(arr, left, right);
        // For left subarray, which is everything to the left of the pivot element
        quickSort(arr, left, pivotIndex - 1);
        // For the right sub array, which is everything to the right of the pivot element
        quickSort(arr, pivotIndex + 1, right);
    }
    // Return the array, when it's of length 1 i.e, left === right
    return arr;
}

class Heap {
    constructor() {
        this.arr = []
    }

    getParent(i) {
        return Math.floor((i - 1) / 2)
    }

    getLeftChild(i) {
        return i * 2 + 1
    }

    getRightChild(i) {
        return i * 2 + 2
    }

    swap(i, j) {
        let temp = this.arr[i]
        this.arr[i] = this.arr[j]
        this.arr[j] = temp
    }

    insert(data) {
        this.arr[this.arr.length] = data
        this.heapfyUp()
    }

    heapfyUp() {
        let index = this.arr.length - 1
        while (this.arr[index] > this.arr[this.getParent(index)]) {
            this.swap(index, this.getParent(index))

            index = this.getParent(index)
        }
    }

    removeRoot() {
        let root = this.arr[0]
        let last = this.arr.pop()

        if (this.arr.length > 0) {
            this.arr[0] = last
            this.heapfyDown(0, this.arr.length)
        }

        return root
    }

    heapfyDown(index, arrLength) {

        let largest = index
        let left = this.getLeftChild(index)
        let right = this.getRightChild(index)

        if (left < arrLength && this.arr[left] < this.arr[largest]) {
            largest = left
        }

        if (right < arrLength && this.arr[right] < this.arr[largest]) {
            largest = right
        }

        if (largest != index) {
            this.swap(index, largest)
            this.heapfyDown(largest, arrLength)
        }
    }

    buildHeap() {
        let length = this.arr.length
        for (let i = Math.floor(length / 2) - 1; i >= 0; i--) {
            this.heapfyDown(i, length)
        }
    }

    heapSort() {
        this.buildHeap()
        for (let i = this.arr.length - 1; i >= 0; i--) {
            this.swap(0, i)
            this.heapfyDown(0, i)
        }
    }

}

