using Graph = vector< vector<int> >;

bool exist_edge[710][710], dp[710];
int used[710];

long long int edges(long long int A) {
    return A * (A - 1) / 2;
}

int na = 0, nb = 0;
bool check_bipartite(Graph &G, int cur, int col=0) {
    bool res = true;
    used[cur] = col;
    (col == 0 ? na : nb)++;
    for(auto to : G[cur]) {
        if(used[to] >= 0) {
            if(used[to] == used[cur]) res = false;
        }
        else {
            res &= check_bipartite(G, to, 1-col);
        }
    }
    return res;
}

int main() {
    int N, M; cin >> N >> M;
    for(int i=0; i<M; i++) {
        int u, v; cin >> u >> v;
        u--; v--;
        exist_edge[u][v] = exist_edge[v][u] = true;
    }

    Graph G(N);
    for(int i=0; i<N; i++) {
        for(int j=0; j<N; j++) {
            if(i == j) continue;
            if(!exist_edge[i][j]) G[i].push_back(j);
        }
    }

    bool ok = true;
    vector< pair<int, int> > vtxs;
    fill(used, used + N, -1);
    for(int i=0; i<N; i++) {
        if(used[i] >= 0) continue;
        int pa = na, pb = nb;
        ok &= check_bipartite(G, i);
        vtxs.emplace_back(na - pa, nb - pb);
    }

    if(ok) {
        dp[0] = true;
        for(auto x : vtxs) {
            int A = x.first, B = x.second;
            for(int i=N; i>=0; i--) {
                if(dp[i]) {
                    dp[i] = false;
                    dp[i+A] = dp[i+B] = true;
                }
            }
        }

        long long int ans = 1LL << 60;
        for(int i=0; i<=N; i++) {
            if(dp[i]) {
                int A = i, B = N-i;
                ans = min(ans, edges(A) + edges(B));
            }
        }
        cout << ans << endl;
    }
    else {
        cout << -1 << endl;
    }
    return 0;
}

package com.hellokoding.algorithm;

public class AnagramsByBruteForce {
    static boolean areAnagrams(String s, String t) {
        if (s.length() != t.length()) {
            return false;
        }

        return areAnagramsByBackTracking(0, s, t);
    }

    static boolean areAnagramsByBackTracking(int i, String s1, String s2) {
        if (i == s1.length()-1) {
            return s1.equals(s2);
        }

        for(int j=i; j<s1.length(); j++) {
            s1 = swap(s1, i, j);

            if (areAnagramsByBackTracking(i+1, s1, s2)) {
                return true;
            }

            s1 = swap(s1, i, j); // backtracking
        }

        return false;
    }

    static String swap(String str, int i, int j) {
        char[] arr = str.toCharArray();

        char temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;

        return String.valueOf(arr);
    }

    public static void main(String[] args) {
        System.out.println(areAnagrams("listen", "silent"));
        System.out.println(areAnagrams("rat", "car"));
    }
}

