using namespace std;

struct Graph {
	vector<vector<int> > edges;
	vector<int> dst;
	int size;
	Graph(int n) {
		size = n;
		edges.resize(n);
		dst.resize(n);
	}
	
	int deg(int i) {
		return edges[i].size();
	}
	
	void bfs(vector<int> s) {
		fill(dst.begin(), dst.end(), -1);
		queue<int> q;
		for (int i = 0; i < s.size(); i++) {
			q.push(s[i]);
			dst[s[i]] = 0;
		}
		while (!q.empty()) {
			int v = q.front();
			q.pop();
			for (int i = 0; i < edges[v].size(); i++) {
				int new_dst = dst[v] + 1;
				if (dst[edges[v][i]] == -1) {
					dst[edges[v][i]] = new_dst;
					q.push(edges[v][i]);
				}
			}
		}
		return;
	}
	
	void bfs(int s) {
		fill(dst.begin(), dst.end(), -1);
		queue<int> q;
		q.push(s);
		dst[s] = 0;
		while (!q.empty()) {
			int v = q.front();
			q.pop();
			for (int i = 0; i < edges[v].size(); i++) {
				int new_dst = dst[v] + 1;
				if (dst[edges[v][i]] == -1) {
					dst[edges[v][i]] = new_dst;
					q.push(edges[v][i]);
				}
			}
		}
		return;
	}
	void add_edge(int u, int v) {
		edges[u].push_back(v);
		edges[v].push_back(u);
	}
};

int main() {
	int n;
	cin >> n;
	if (n == 2) {
		cout << "1 2\n";
		return 0;
	}
	Graph g(n);
	int u[n], v[n];
	for (int i = 1; i < n; i++) {
		cin >> u[i] >> v[i];
		g.add_edge(--u[i], --v[i]);
	}
	pair<int, ll> ans(n, n);
	for (int i = 0; i < n; i++) {
		g.bfs(i);
		int m[n], d = 0;
		fill(m, m+n, 0);
		for (int j = 0; j < n; j++) {
			d = max(d, g.dst[j]);
			m[g.dst[j]] = max(m[g.dst[j]], g.deg(j));
		}
		pair<int, ll> temp(d + 1, m[0]);
		for (int j = 1; j < d; j++) {
			temp.second *= m[j] - 1;
		}
		ans = min(ans, temp);
	}
	for (int i = 1; i < n; i++) {
		vector<int> s;
		s.push_back(u[i]);
		s.push_back(v[i]);
		g.bfs(s);
		int m[n], d = 0;
		fill(m, m+n, 0);
		for (int j = 0; j < n; j++) {
			d = max(d, g.dst[j]);
			m[g.dst[j]] = max(m[g.dst[j]], g.deg(j));
		}
		pair<int, ll> temp(d + 1, 2 * m[0] - 2);
		for (int j = 1; j < d; j++) {
			temp.second *= m[j] - 1;
		}
		ans = min(ans, temp);
	}
	cout << ans.first << " " << ans.second << endl;
	return 0;
}

