	vector<long long int>rev_by(N + K + 1, 1);
	vector<long long int>rev_two_by(N + K + 1, 1);
	for (int i = 1; i <= N + K; i++) {
		two_by[i] = two_by[i - 1] * 2;
		two_by[i] %= MOD;
		rev_two_by[i] = power(two_by[i], MOD - 2, MOD);
		by[i] = by[i - 1] * i;
		by[i] %= MOD;
		rev_by[i] = power(by[i], MOD - 2, MOD);
	}
	long long int nap = 0, nbp = 0;
	for (int i = 1; i <= N + K; i++) {
		if (i > 1) {
			if (N < i) {
				long long int add = by[i - 2];
				add *= rev_by[N - 1];
				add %= MOD;
				add *= rev_by[i - N - 1];
				add %= MOD;
				add *= rev_two_by[i - 1];
				add %= MOD;
				nap += add;
				nap %= MOD;
			}
			if (K < i) {
				long long int add = by[i - 2];
				add *= rev_by[K - 1];
				add %= MOD;
				add *= rev_by[i - K - 1];
				add %= MOD;
				add *= rev_two_by[i - 1];
				add %= MOD;
				nbp += add;
				nbp %= MOD;
			}
		}
		//cout << i << " " << nap << " " << nbp << endl;
		long long int ret = 1 + MOD * 2;
		ret -= nap;
		ret += nbp;
		ret %= MOD;
		ret *= rev_two_by[1];
		ret %= MOD;
