///===========================================  template  =======================================================

inline ll add(ll x, ll y){
    x += y;
    if(x >= mod) x -= mod;
    return x;
}

inline ll sub(ll x, ll y){
    x -= y;
    if(x < 0) x += mod;
    return x;
}

ll modexpo(ll x, ll n, ll m = mod){
	x %= m;
	ll ret = 1;
    while(n){
        if(n & 1LL) ret = (ret*x) % m;
        x = (x*x) % m;
        n >>= 1;
    }
    return ret;
}

int N;	//N is size
int bit1[nmax];
ll bit2[nmax];

pair<int, ll> prefix(int i)
{
    pair<int, ll> ret = {0, 0ll};	//identity
    while(i >= 1) {
        ret.first += bit1[i];
        ret.second = add(ret.second, bit2[i]);
        i -= i&-i;
    }
    return ret;
}

void update(int i, ll x)
{
    while(i<=N && i) {
        bit1[i] += 1;
        bit2[i] = add(bit2[i], x);
        i += i&-i;
    }
}

pair<int, ll> query(int l, int r){
    if(l > r) return {0, 0ll};

    pair<int, ll> ret;
    ret = prefix(r);
    if(l != 1){
        auto tmp = prefix(l-1);
        ret.first -= tmp.first;
        ret.second = sub(ret.second, tmp.second);
    }
    return ret;
}

