#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

struct Solution {
  int *A;
  bool *H;
  int n;
};

typedef struct Solution Solution;

bool isSolution(Solution *sol, int k) {
  return (sol->n == k);
}

void printSolution(Solution *sol) {
  for (int i = 1; i <= sol->n; ++i) {
    printf("%d ", sol->A[i]);
  }
  printf("\n");
}

void initSolution(Solution *sol) {
  for (int i = 0; i <= sol->n; ++i) {
    sol->A[i] = -1;
    sol->H[i] = false;
  }
}

void makeMove(Solution *sol, int k, int cand) {
  sol->A[k] = cand;
  sol->H[cand] = true;
}

void undoMove(Solution *sol, int k, int cand) {
  sol->A[k] = -1;
  sol->H[cand] = false;
}

void backtrack(Solution *sol, int k) {
  if (isSolution(sol, k)) {
    printSolution(sol);
  } else {
    k = k + 1;

    /* Scan through candidates */
    for (int i = 1; i <= sol->n; i++) {
      if (!sol->H[i]) {
        makeMove(sol, k, i);
        backtrack(sol, k);
        undoMove(sol, k, i);
      }
    }
  }
}

int main(int argc, char *argv[]) {
  Solution sol;

  if (argc != 2) {
    printf("Usage: %s [n] - Will print permutations of numbers 1 - n\n",
        argv[0]);
    return 1;
  }

  int n = atoi(argv[1]);
  int A[n + 1];   // Need to store A[1] ... A[k]
  bool H[n + 1];
  sol.A = A;
  sol.H = H;
  sol.n = n;

  backtrack(&sol, 0);
}

