int saiki(int a,int b,int c,int d){
    if(a<0||a>=n||c<0||c>=n||b<0||b>=m||d<0||d>=m)return -inf;
    if(s[a][b]=='#'||s[c][d]=='#')return -inf;
    if(a==c&&b==d)return 0;
    if(ok[a][b][c][d])return dp[a][b][c][d]; 
    ok[a][b][c][d] = 1;
    if(a>c||b>d){
        return dp[a][b][c][d] = -inf;
    }
    if(s[a][b]>='a'&&s[a][b]<='z'&&s[c][d]==s[a][b]+('A'-'a')){
        if(c==a+1&&b==d)return dp[a][b][c][d]=1;
        if(c==a&&d==b+1)return dp[a][b][c][d]=1;
        int tmp = -inf;
        tmp = max(tmp,saiki(a+1,b,c-1,d)+1);
        tmp = max(tmp,saiki(a+1,b,c,d-1)+1);
        tmp = max(tmp,saiki(a,b+1,c-1,d)+1);
        tmp = max(tmp,saiki(a,b+1,c,d-1)+1);
        srep(i,a,c){
            srep(j,b,d){
                if(i==c&&j==d)continue;
                if(s[i][j]!=s[a][b]+('A'-'a'))continue;
                tmp = max(tmp,saiki(a,b,i,j)+saiki(i+1,j,c,d));
                tmp = max(tmp,saiki(a,b,i,j)+saiki(i,j+1,c,d));
            }
        }
        
        if(tmp<0)tmp = -inf;
        return dp[a][b][c][d] = tmp;
    }else{
        if(c==a+1&&b==d)return dp[a][b][c][d]=0;
        if(c==a&&d==b+1)return dp[a][b][c][d]=0;
        int tmp = -inf;
        tmp = max(tmp,saiki(a+1,b,c,d));
        tmp = max(tmp,saiki(a,b,c-1,d));
        tmp = max(tmp,saiki(a,b+1,c,d));
        tmp = max(tmp,saiki(a,b,c,d-1));
        if(s[a][b]>='a'&&s[a][b]<='z'&&s[c][d]>='A'&&s[c][d]<='Z'){
            srep(i,a,c){
                srep(j,b,d){
                    if(i==c&&j==d)continue;
                    if(s[i][j]!=s[a][b]+('A'-'a'))continue;
                    tmp = max(tmp,saiki(a,b,i,j)+saiki(i+1,j,c,d));
                    tmp = max(tmp,saiki(a,b,i,j)+saiki(i,j+1,c,d));
                }
            }
        }
        if(tmp<0)tmp = -inf;
        return dp[a][b][c][d] = tmp;
    }
}


