long long f(int i, int pos, long long k) {
  //if (k <= 30 || pos > 12) return F[i][pos][min(k, 30LL)];
  if (k == 0 || pos > 12) return F[i][pos][min(k, 30LL)];
  long long s = A[i][pos], p = 1;
  long long n = k, r = 1;
  for (int x=pos-1; x>=0; x--) {
    assert((p*n)%r == 0);
    p = (p*n)/r;
    n++, r++;
    s += 1LL*p*A[i][x];
    if (p >= INF || s >= INF) return INF;
  }
  if (k <= 30) assert(s == F[i][pos][k]);
  return s;
}

signed main() {
