    bool ok = true;
    rep(i, N-1) if (A[i][0] >= A[i+1][0]) ok = false;
    cout << (ok?0:-1) << "\n";
    return 0;
  }
  rep(i, N) {
    rep(j, M) F[i][j][0] = A[i][j];
    rep(f, 30) rep(j, M) F[i][j][f+1] = min(F[i][j][f] + (j>0?F[i][j-1][f+1]:0), INF);
  }
  rep(i, N-1) {
    if (A[i][0] != A[i+1][0]) continue;
    int a = A[i][0];
    long long cur_sec = 1LL*K[i]*A[i][0]+A[i][1];
    if (A[i+1][1] < cur_sec) {
      long long X = (cur_sec-A[i+1][1]+a-1)/a;
      K[i+1] += X;
    }
    if (cur_sec == 1LL*K[i+1]*A[i+1][0]+A[i+1][1]) {
      // if a[i] >= a[i+1]: do +1
      bool ord = false;
      for (int pos=2; pos<M; pos++) {
        long long k1 = K[i], k2 = K[i+1];
        long long a = -1, b = -1;
        if (k1 <= k2) {
          // <=> A[i]^0[pos] < A[i+1]^(k2-k1)[pos]
          a = A[i][pos];
          b = f(i+1, pos, k2-k1);
        }
        else {
          // <=> A[i]^(k1-k2)[pos] < A[i+1]^0[pos]
          a = f(i, pos, k1-k2);
          b = A[i+1][pos];
        }
        if (a < b) {
          ord = true;
          break;
        }
        if (a > b) break;
      }
      //cout<<"i="<<i<<"-"<<i+1<<": ord="<<ord<<"\n";
      if (!ord) K[i+1]++;
    }
  }
  /*
  rep(i, N) {
