var reversePolishNotationCalc = function (arr) {
    var checking = 0;
    while(checking < arr.length) {
        switch(arr[checking]) {
            case "+":
                var ans = arr[checking - 1] + arr[checking - 2];
                arr.splice(checking - 2, 3, ans);
                checking = checking - 2;
                break;
            case "-":
                var ans = arr[checking - 1] - arr[checking - 2];
                arr.splice(checking - 2, 3, ans);
                checking = checking - 2;
                break;
            case "*":
                var ans = arr[checking - 1] * arr[checking - 2];
                arr.splice(checking - 2, 3, ans);
                checking = checking - 2;
                break;
            case "/":
                var ans = arr[checking - 1] / arr[checking - 2];
                arr.splice(checking - 2, 3, ans);
                checking = checking - 2;
                break;
            default:
                arr[checking] = parseFloat(arr[checking]);
                checking++;
                console.log(arr);
