struct ListNode *create_list(int *nums, int len)
{
    int i;
    struct ListNode *head, *node, *tmp_head;

    head = (struct ListNode*)malloc(sizeof(struct ListNode));
    head->val = nums[0];
    head->next = NULL;
    tmp_head = head;

    for (i = 1; i < len; ++i) {
        node = (struct ListNode*)malloc(sizeof(struct ListNode));
        node->val = nums[i];
        node->next = NULL;
        tmp_head->next = node;
        tmp_head = tmp_head->next;
    }

    return head;
}

bool is_palindrome(struct ListNode *head)
{
    struct ListNode *mid, *end, *tmp_head, *left, *right, *tail;

    if (head == NULL) {
        return true;
    }

    // Find the middle of the linked list.
    mid = head;
    right = head;
    end = head;
    for (; end != NULL && end->next != NULL;) {
        mid = right;
        right = right->next;
        end = end->next->next;
    }

    if (right == end) {
        return true;
    }

    // Reverse the left side of linked list;
    // BIG HOLE AT HERE...
    tmp_head = head;
    left = NULL;
    tail = NULL;
    for (;left != mid;) {
        left = tmp_head;
        tmp_head = tmp_head->next;
        left->next = tail;
        tail = left;
    }

    // Compare.
    if (end != NULL) {
        right = right->next;
    }
    for (; right != NULL; right = right->next, left = left->next) {
        if (left == NULL || right->val != left->val) {
            return false;
        }
    }

    return (left == NULL);
}

/**
 * Say you have an array for which the ith element is the price of a given stock on day i.
 * If you were only permitted to complete at most one transaction (ie, buy one and sell one share of the stock),
 * Design an algorithm to find the maximum profit.
 */

#include <iostream>
#include <vector>

int maxProfit(std::vector<int>& prices) {
	if (prices.size() == 0 ) {
		return 0;
	}
	std::vector<int> dp(prices.size());
	dp[0] = 0;
	int buyPrice = prices[0];
	int mostProfit = 0;
	for ( size_t i = 1; i < prices.size(); ++i ) {
		if ( prices[i] >= buyPrice ) {
			dp[i] = dp[i-1] + prices[i] - prices[i-1];
		} else {
			dp[i] = 0;
			buyPrice = prices[i];
		}
		if (mostProfit < dp[i]) {
			mostProfit = dp[i];
		}
	}
	return mostProfit;
}

