void rankSort(int A[], int n)
{
	int U[n],R[n];
	for(int i=0;i<n;i++)
	{
		R[i]=0;
	}
	for(int i=1;i<n;i++)
	{
		for(int j=0;j<i;j++)
		{
			if(A[j]<=A[i])
			R[i]=R[i]+1;
			else
			R[j]=R[j]+1;
		}
	}
	for(int j=0;j<n;j++)
	{
		U[R[j]]=A[j];
	}
	for(int j=0;j<n;j++)
	{
		A[j]=U[j];
	}
}

