#define INF std::numeric_limits<int>::max()
#define N_MAX 8

using ll = long long;

int N;
int A, B, C;
int takes[N_MAX];

int dfs(int cnt, int a, int b, int c) {
    if(cnt == N) {
        if(std::min({a, b, c}) > 0) {
            return std::abs(a - A) + std::abs(b - B) + std::abs(c - C) - 30;
        }
        else {
            return INF - 10;
        }
    }

    int ret0 = dfs(cnt + 1, a, b, c);
    int ret1 = dfs(cnt + 1, a + takes[cnt], b, c) + 10;
    int ret2 = dfs(cnt + 1, a, b + takes[cnt], c) + 10;
    int ret3 = dfs(cnt + 1, a, b, c + takes[cnt]) + 10;
    return std::min({ret0, ret1, ret2, ret3});
}

int main() {
    std::cin.tie(0);
    std::ios::sync_with_stdio(false);

    std::cin >> N >> A >> B >> C;
    REP(i, N) {
        std::cin >> takes[i];
    }

    std::cout << dfs(0, 0, 0, 0) << std::endl;

    return 0;
}

