inline double cross(const Point& a, const Point& b){
  return imag(conj(a) * b);
}
Point crosspoint(const Line &l, const Line &m) {
  double A = cross(l[1] - l[0], m[1] - m[0]);
  double B = cross(l[1] - l[0], l[1] - m[0]);
  if (abs(A) < EPS && abs(B) < EPS) return m[0]; // same line
  if (abs(A) < EPS) assert(false); // !!!PRECONDITION NOT SATISFIED!!!
  return m[0] + B / A * (m[1] - m[0]);
}
double polygonArea(const Polygon& P) {
  double A = 0;
  for (int i = 0; i < P.size(); ++i) 
    A += cross(CURR(P, i), NEXT(P, i));
  return abs(A) / 2.0;
}
double area(Line lx1, Line lx2, Line ly1, Line ly2){
  Polygon pol;
  pol.push_back(crosspoint(lx1, ly1));
  pol.push_back(crosspoint(lx2, ly1));
  pol.push_back(crosspoint(lx2, ly2));
  pol.push_back(crosspoint(lx1, ly2));
  return polygonArea(pol);
}

