// Find the range of a particular element occuring in a given sorted array.
// If the element doesn't exist, return 1.

#include <bits/stdc++.h>

using namespace std;

int findleft(const vector<int>& A, int B, int low, int high){
    int res = -1;
    while(low <= high){
        int mid = low + (high - low)/2;
        if(A[mid] == B){
            res = mid;
            high = mid-1;
        }else if(A[mid] < B){
            low = mid+1;
        }else high = mid-1;
    }
    if(res == -1)
        return res;
    return low;
}

int findright(const vector<int>& A, int B, int low, int high){
    int res = -1;
    while(low <= high){
        int mid = low + (high - low)/2;
        if(A[mid] == B){
            res = mid;
            low = mid+1;
        }else if(A[mid] > B){
            high = mid-1;
        }else low = mid+1;
    }
    if(res == -1)return -1;
    return low-1;
}

