    static class firstlast
    {
        int firstcnt = 0;
        int lastcnt = 0;
    }
    public static void solution(int num) throws IOException
    {
        // given arraylist of strings, generate output
        // num = test case number
        TreeMap<String, firstlast> ans = new TreeMap<>();
        StringBuilder output_name = new StringBuilder();
        output_name.append("C:\\Users\\vishn\\OneDrive\\Documents\\IntelliJ\\competitivestandrews\\src\\frequency_of_names_data\\output\\output");
        if (num < 10)
            output_name.append("0");
        output_name.append(num);
        output_name.append(".txt");
        FileWriter fw = new FileWriter(output_name.toString());
        for (String s:namelist)
        {
            // split
            String split[] = s.split("_");
            // consider each entity separately
            firstlast f1 = ans.get(split[0]);
            if (f1 == null)
                f1 = new firstlast();
            f1.firstcnt++;
            ans.put(split[0], f1);
            firstlast f2 = ans.get(split[1]);
            if (f2 == null)
                f2 = new firstlast();
            f2.lastcnt++;
            ans.put(split[1], f2);
        }
        // now output
        for (String str:ans.keySet())
        {
        firstlast f = ans.get(str);
        fw.write(str + " " + Integer.toString(f.firstcnt) + " " + Integer.toString(f.lastcnt));
        fw.write('\n');
    //    System.out.println (str + " " + f.firstcnt + " " + f.lastcnt);
        }
        fw.close();
    }
