class Node:
    def __init__(self, name):
        self.children = []
        self.name = name

    def addChild(self, name):
        self.children.append(Node(name))
        return self

    def breadthFirstSearch(self, array):
        queue = [self] # step 1 > add root node to the queue, the node on which we are calling BFS
        while len(queue) > 0:
            current = queue.pop(0) # step 2 > pop the root/current node
            array.append(current.name) # step 3 > add the current node to the final array
            for child in current.children: # step 4 > add the children of the current node to the queue
                queue.append(child)
        return array

package ds.rangequeryandpointupdate;

public class BITree {

    private final int n;
    private long[] tree;

    public BITree(int n) {
        this.n = n;
        this.tree = new long[n + 1];
    }

    public BITree(long[] values) {

        if (values == null) {
            throw new IllegalArgumentException("Values array cannot be null");
        }

        values[0] = 0L;

        this.n = values.length;

        tree = values.clone();

        for (int i = 1; i < n; i++) {
            int parent = i + lsb(i);
            
            if (parent < n) {
                tree[parent] += tree[i];
            }
        }
    }            

    public long sum(int left, int right) {
    
        if (right < left) {
            throw new IllegalArgumentException("Right should be greater or equal to left");
        }
        
        return prefixSum(right) - prefixSum(left - 1);
    }

    public long get(int i) {
        return sum(i, i);
    }

    public void add(int i, long v) {
        while (i < n) {
            tree[i] += v;
            i += lsb(i);
        }
    }

    public void set(int i, long v) {
        add(i, v - sum(i, i));
    }

    @Override
    public String toString() {
        return java.util.Arrays.toString(tree);
    }
    
    private long prefixSum(int i) {
        long sum = 0L;
        
        while (i != 0) {
            sum += tree[i];
            i &= ~lsb(i); // or, i -= lsb(i);
        }
        
        return sum;
    }
    
    private static int lsb(int i) {

        return i & -i;

        // or
        // return Integer.lowestOneBit(i);
    }
}

