void dfs(int x,vector<int> G){
  
  if(x>=2){

    int sum=0;

    for(int i=0;i<G.size();i++){
      
      int mincost=INF;
      
      for(int j=0;j<G.size();j++){
      
	if(G[i]!=G[j])
	  mincost=min(mincost,d[G[i]][G[j]]);
      
      }

      if(mincost!=INF) sum+=mincost;
    
    }
  
    ans=max(ans,sum);

  }
  
  sort(G.begin(),G.end());
  
  if(memo.count(G)) return ;
  memo.insert(G);
  
  for(int i=0;i<n;i++){

    if(used[idx[i].S]) continue;

    used[idx[i].S]=1;
    
    int mincost=INF;

    vector<int> nG=G;

    nG.push_back(idx[i].S);
    
    for(int j=0;j<nG.size();j++)
      
      if(idx[i].S!=nG[j]&&used[nG[j]])
	mincost=min(mincost,d[idx[i].S][nG[j]]);
    
    if(!x||(mincost&&mincost!=INF)) dfs(x+1,nG);
    
    used[idx[i].S]=0;
    
  }
  
}

