def get_fibo(n):
    if n<=1:
        return n
    rem=n%60
    a,b = 0,1
    for _ in range(rem-1):
        a,b=b,(a+b)

    return b%10
    
def fibonacci_partial_sum_fast(from_, to):
    if from_ == to:
        return get_fibo(from_%60)
    else:
        from_ %=60
        to %=60
        from_last = get_fibo(from_+1)-1
        to_last = get_fibo(to+2)-1

    return (to_last-from_last)%10



