class Solution:
    def pairSum(self, head: Optional[ListNode]) -> int:
        values=[]
        while head:
            values.append(head.val)
            head=head.next
        max_=0
        for i in range(len(values)):
            sum_=values[i]+values[-1-i]
            if(sum_>max_):
                max_=sum_
        return max_

#include<bits/stdc++.h>
typedef long long int ll;
