#define BIG_NUM 2000000000
#define HUGE_NUM 99999999999999999
#define MOD 1000000007
#define EPS 0.000000001
using namespace std;



#define SIZE 505

int V,E;
int root = 0;
int POW[20],pow_max = 0;
bool can_visit[20][SIZE][SIZE],check[2][SIZE];


bool isOK(int count){

	int CURRENT = 0,NEXT = 1;
	for(int i = 0; i < V; i++){
		check[CURRENT][i] = false;
		check[NEXT][i] = false;
	}

	bool FLG;

	check[CURRENT][root] = true;

	for(int i = pow_max; i >= 0; i--){
		if(POW[i] > count)continue;
		count -= POW[i];

		for(int k = 0; k < V; k++){
			if(!check[CURRENT][k])continue;


			for(int p = 0; p < V; p++){
				if(can_visit[i][k][p]){

					check[NEXT][p] = true;
				}
			}
		}

		FLG = true;
		for(int k = 0; k < V; k++){
			if(!check[NEXT][k]){
				FLG = false;
				break;
			}
		}

		if(FLG)return true;

		swap(CURRENT,NEXT);
		for(int k = 0; k < V; k++){

			check[NEXT][k] = false;
		}
	}

	return false;
}


int main(){

	scanf("%d %d",&V,&E);

	POW[0] = 1;
	for(int i = 1; i <= 19; i++){

		POW[i] = POW[i-1]*2;
	}

	for(int i = 0; i <= 19; i++){
		if(POW[i] > V*V+(V+5)){
			pow_max = i;
			break;
		}
	}

	for(int i = 0; i <= pow_max; i++){
		for(int from = 0; from < V; from++){
			for(int to = 0; to < V; to++){

				can_visit[i][from][to] = false;
			}
		}
	}

	int from,to;
	for(int loop = 0; loop < E; loop++){

		scanf("%d %d",&from,&to);
		from--;
		to--;
		can_visit[0][from][to] = true;
	}

	for(int i = 1; i <= pow_max; i++){
		for(int a = 0; a < V; a++){
			for(int b = 0; b < V; b++){
				if(!can_visit[i-1][a][b])continue;
				for(int c = 0; c < V; c++){
					if(!can_visit[i-1][b][c])continue;
					can_visit[i][a][c] = true;
				}
			}
		}
	}

	int left = 0,right = V*V+V+5,mid = (left+right)/2;
	int ans = BIG_NUM;

	while(left <= right){

		if(isOK(mid)){

			ans = mid;
			right = mid-1;
		}else{

			left = mid+1;
		}
		mid = (left+right)/2;
	}

	if(ans == BIG_NUM){

		printf("-1\n");
	}else{

		printf("%d\n",ans);
	}

	return 0;
}

