	for(int i=1;i<=n;++i) if(X[i]<S) ID=i;
	while((l<=ID)^(r<=ID)) {
		if(P[l]>=P[r]) P[l]+=P[r],tmp[++cnt]=X[r--];
		else P[r]+=P[l],tmp[++cnt]=X[l++];
	}
