	for (int i = 0; i <= n0; i++)
	{
		a0[i] = read();
	}
	for (int i = 0; i <= n1; i++)
	{
		a1[i] = read();
	}
	n = n0 + n1;
	while (n > 0)
	{
		k++;
		n >>= 1;
	}
	n = 1 << k;
	pre(a0);
	pre(a1);
	dft(a0, 1);
	dft(a1, 1);
	for (int i = 0; i < n; i++)
	{
		a0[i] = a0[i] * a1[i] % MOD;
	}
	pre(a0);
	dft(a0, -1);
	ll inv = qpow(n, MOD - 2);
	for (int i = 0; i <= n0 + n1; i++)
	{
