int K;
int A[111];

int l[111];//label


/*
floor((m+1-l[i])/2)>A[i]
(m-l[i])/2>A[i]
m-l[i]>2*A[i]
m>2*A[i]+l[i]
*/
bool check(){
	int m=0;
	rep(i,K)chmax(m,A[i]+l[i]);
	rep(i,K)if(m>2*A[i]+l[i])return false;
	return true;
}

bool ex[111];
int pos[111];
signed main(){
	cin>>K;
	rep(i,K)cin>>A[i];

	if(!check()){
		cout<<-1<<endl;
		return 0;
	}

	vint ans;
	int rem=0;

	while(*max_element(A,A+K)){
		int len=ans.size();
		for(int i=0;i<K;i++){
			if(A[i]==0)continue;

			if(find(ans.end()-rem,ans.end(),i)!=ans.end())continue;
			ans.pb(i);
			A[i]--;
			int memrem=rem;
			rem++;

			if(ans.size()>=K){
				bool isperm=true;
				memset(ex,0,sizeof(ex));
				for(int j=0;j<K;j++){
					int a=ans[ans.size()-1-j];
					if(ex[a])isperm=false;
					ex[a]=true;
				}
				if(isperm)rem=0;
			}



			memset(l,0,sizeof(l));
			rep(j,rem){
				int a=ans[ans.size()-1-j];
				l[a]=1;
			}

			int ma=-1001001001,mi=1001001001;
			rep(j,K){
				chmax(ma,A[j]-1+l[j]);
				chmin(mi,2*(A[j]-1+l[j]));
			}

			int argma=1001001001,argmi=-2;
			rep(j,rem){
				int a=ans[ans.size()-1-j];
				if(ma==A[a])chmin(argma,j);
				if(mi==2*A[a])chmax(argmi,j);
			}
			rep(j,K)if(!l[j]&&A[j]-1==ma)argma=-1;


			if(ma<=mi)break;
			if(ma-mi==1&&argma>argmi)break;


			for(int j=rem;j<K&&j<ans.size();j++){
				int a=ans[ans.size()-1-j];
				if(l[a])break;
				if(ma==A[a]-1)break;
				l[a]=1;
			}
			if(check())break;


			A[i]++;
			rem=memrem;
			ans.pop_back();			
		}
		if(len==ans.size())break;
	}

	rep(i,ans.size()){
		if(i)cout<<" ";
		cout<<ans[i]+1;
	}cout<<endl;

	return 0;
}

class Node {
    constructor(data) {
        this.data = data;
        this.next = null;
    }
}

class SinglyLinkedList {
    constructor() {
        this.head = null;
        this.length = 0;
    }

    add(data) {
        let node = new Node(data),
            currentNode = this.head;

        if (!currentNode) {
            this.head = node;
            this.length++;

            return node;
        }

        while(currentNode.next) {
            currentNode = currentNode.next;
        }

        currentNode.next = node;
        this.length++;

        return node;
    }


    findNodeAt(position) {
        let currentNode = this.head,
            count = 1;

        /* invaid position */
        if (this.length === 0 || position > this.length || position < 0) {
            throw new Error("Not Found");
        }

        /* valid position */
        while(count < position) {
            currentNode = currentNode.next;
            count++;
        }

        return currentNode;
    }

    remove(position) {
        let currentNode = this.head,
            count = 0,
            previousNode = null,
            nodeToDelete = null,
            deletedNode = null;

        /* invalid position */
        if (position > this.length || position < 0) {
            throw new Error("Not Found");
        }

        /* remove 1st node */
        if (position === 1) {
            deletedNode = currentNode;
            this.head = currentNode.next;
            currentNode = null;
            this.length--;

            return deletedNode;
        }

        /* valid position */
        while(count < position) {
            previousNode = currentNode;
            nodeToDelete = currentNode.next;
            count++;
        }

        previousNode.next = nodeToDelete.next;
        deletedNode = nodeToDelete;
        this.length--;

        return deletedNode;
    }

    /* extra operations */
    traverse() {
        var currentNode = this.head,
            result = [];

        while(currentNode) {
            result.push(currentNode.data);
            currentNode = currentNode.next;
        }

        return result;
    }

    reverse(head) {
        var prev = null,
            next = null,
            currentNode = head || this.head;

        while (currentNode) {
            next = currentNode.next;
            currentNode.next = prev;
            prev = currentNode;
            currentNode = next;
        }

        return prev;
    }

    findMiddlePoint() {
        var fastPointer = this.head,
            slowPointer = this.head,
            currentNode = this.head;

        /* when fastPointer will reach at the end, slowPointer will reach at mid point that time */
        while (fastPointer && fastPointer.next) {
            fastPointer = fastPointer.next.next;
            slowPointer = slowPointer.next;
        }

        return slowPointer.data;
    }
}


