            if not root:
                return

            if not root.left and not root.right:

                path += str(root.val)
                pathlist.append(path)

                path = ""
            path += str(root.val) + "->"

            helper(root.left,path,pathlist)
            helper(root.right,path,pathlist)
            return pathlist
            
        return helper(root,"",[])

