#define MAX_N 5001
using namespace std;
typedef long long lld;

int n;

struct Node
{
    vector<int> adj;
};
Node graf[MAX_N];
bool mark[MAX_N];

int indegree[MAX_N];
int toposort[MAX_N];

//Algoritam za topolosko sortiranje usmerenog grafa; moze se koristiti i za otkrivanje ciklusa
//Slozenost: O(V + E)

inline int TopoSort()
{
    queue<int> S;
    for (int i=0;i<n;i++) if (indegree[i] == 0) S.push(i);
    int idx = 0;
    while (!S.empty())
    {
        int idd = S.front();
        S.pop();
        toposort[idx++] = idd;
        for (int i=0;i<graf[idd].adj.size();i++)
        {
            if (--indegree[graf[idd].adj[i]] == 0) S.push(graf[idd].adj[i]);
        }
    }
    if (idx < n) return -1; // Cycle detected!
    else return 0;
}

int main()
{
