    indegree[3] = 0;
    indegree[4] = 2;
    indegree[5] = 2;
    indegree[6] = 2;
    indegree[7] = 2;

    TopoSort();
    for (int i=0;i<n;i++) printf("%d ",toposort[i]);
    printf("\n");

    return 0;
}

