#include <bits/stdc++.h>
#define F first
#define S second
#define mp make_pair
#define pb push_back
#define ll long long
#define LEFT(a) ((a)<<1)
#define RIGHT(a) (LEFT(a) + 1)
#define MID(a,b) ((a+b)>>1)
#define MAX(a,b) ((a)>(b)?(a):(b))
#define MIN(a,b) ((a)<(b)?(a):(b))
using namespace std;

const int N = 210000;

int n, m;
pair < int, pair < int, int > > P[N];
ll sum[N];
int p[N];
int ans;

int parent (int x){
    if (p[x] == x)
        return x;
    return p[x] = parent (p[x]);
}

bool F[N];

vector < pair < int, int > > G[N];
vector < int > g[N];

void dfs (int k, int x){
    int I = -1;
    for (int i = 19; i >= 0; i--){
        if (I + (1 << i) >= (int)G[k].size())
            continue;
        if (G[k][I + (1 << i)].F <= x)
            I += (1 << i);
    }
    while (I >= 0 && g[k][I] == 0){
        g[k][I] = 1;
        dfs (G[k][I].S, x);
        I--;
    }
}

map < pair < int, pair < int, int > >, bool > M;

int main()
{
    ios_base::sync_with_stdio(false);
    cin >> n >> m;
    for (int i = 1; i <= n; i++){
        cin >> sum[i];
        p[i] = i;
    }
    for (int i = 1; i <= m; i++)
        cin >> P[i].S.F >> P[i].S.S >> P[i].F;
    sort (P + 1, P + m + 1);
    for (int i = 1; i <= m; i++){
        int u = P[i].S.F, v = P[i].S.S, x = P[i].F;
        G[u].pb ({x, v});
        G[v].pb ({x, u});
        u = parent (u);
        v = parent (v);
        //cout << u << " " << v << endl;
        if (u == v){
            if (sum[u] >= x){
                F[i] = 1;
                //cout << i << " " << P[i].S.F << " " << P[i].S.S << endl;
            }
        }
        else {
            if (sum[u] + sum[v] >= x){
                F[i] = 1;
                //cout << i << " " << P[i].S.F << " " << P[i].S.S << endl;
            }
            p[u] = v;
            sum[v] += sum[u];
        }
    }
    for (int i = 1; i <= n; i++){
        sort (G[i].begin(), G[i].end());
        for (int j = 0; j < (int)G[i].size(); j++)
            g[i].pb (0);
    }
    for (int i = m; i >= 1; i--)
        if (F[i] == 1)
            dfs (P[i].S.F, P[i].F);
    for (int i = 1; i <= n; i++)
        for (int j = 0; j < (int)G[i].size(); j++)
            if (g[i][j])
                M[{G[i][j].F, {i, G[i][j].S}}] = 1;
    for (int i = 1; i <= m; i++)
        if (M[{P[i].F, {P[i].S.F, P[i].S.S}}] == 0)
            ans++;
    cout << ans << endl;
    return 0;
}

package chaos.tree.binaryMap;

import java.util.Comparator;
import java.util.Map;
import java.util.SortedMap;

public final class AvlTreeMap<K, V> extends AbstractBinaryTreeMap<K, V, AvlMapNode<K, V>> {

    public AvlTreeMap() {
        super();
    }

    public AvlTreeMap(Comparator<? super K> comparator) {
        super(comparator);
    }

    public AvlTreeMap(Map<? extends K, ? extends V> m) {
        super();
        putAll(m);
    }

    public AvlTreeMap(SortedMap<K, ? extends V> m) {
        buildFromSorted(m.size(), m.entrySet().iterator());
    }

    @Override
    void afterNodeBuiltFromSorted(AvlMapNode<K, V> node, int level, int redLevel) {
        int leftHeight = nodeHeight(node.left);
        int rightHeight = nodeHeight(node.right);
        node.height = Math.max(leftHeight, rightHeight) + 1;
    }

    @Override
    AvlMapNode<K, V> createNode(K key, V value) {
        return new AvlMapNode<>(key, value);
    }

    @Override
    void afterInsert(AvlMapNode<K, V> node) {
        if (node != null) {
            node = node.parent;
        }
        balanceNode(node);
    }

    private void balanceNode(AvlMapNode<K, V> node) {
        while (node != null) {
            int oldHeight = node.height;
            updateHeight(node);
            int balance = nodeHeight(node.left) - nodeHeight(node.right);
            if (balance > 1) {
                if (nodeHeight(node.left.left) >= nodeHeight(node.left.right)) {
                    node = rotateRightAVL(node);
                } else {
                    rotateLeftAVL(node.left);
                    node = rotateRightAVL(node);
                }
            } else if (balance < -1) {
                if (nodeHeight(node.right.right) >= nodeHeight(node.right.left)) {
                    node = rotateLeftAVL(node);
                } else {
                    rotateRightAVL(node.right);
                    node = rotateLeftAVL(node);
                }
            }
            if (oldHeight == node.height) {
                break;
            }
            node = node.parent;
        }
    }

    private AvlMapNode<K, V> rotateRightAVL(AvlMapNode<K, V> p) {
        AvlMapNode<K, V> newRoot = p.left;
        super.rotateRight(p);
        updateHeight(p);
        updateHeight(newRoot);
        return newRoot;
    }

    private AvlMapNode<K, V> rotateLeftAVL(AvlMapNode<K, V> p) {
        AvlMapNode<K, V> newRoot = p.right;
        super.rotateLeft(p);
        updateHeight(p);
        updateHeight(newRoot);
        return newRoot;
    }

    private void updateHeight(AvlMapNode<K, V> root) {
        root.height = 1 + Math.max(nodeHeight(root.left), nodeHeight(root.right));
    }

    private int nodeHeight(AvlMapNode<K, V> node) {
        return node == null ? -1 : node.height;
    }

    @Override
    public V remove(Object o) {
        if (isEmpty()) {
            @SuppressWarnings("unchecked") K key = (K) o;
            compare(key, key);
            return null;
        }
        @SuppressWarnings("unchecked")
        K key = (K) o;
        AvlMapNode<K, V> x = nodeFinder(key);
        if (x == null) return null;
        V oldValue = x.getValue();
        if (x.left != null && x.right != null) {
            AvlMapNode<K, V> successor = x.right;
            while (successor.left != null) {
                successor = successor.left;
            }
            x.setPair(successor.getKey(), successor.getValue());
            x = successor;
        }

        AvlMapNode<K, V> nodeReplacer = x.left != null ? x.left : x.right;
        AvlMapNode<K, V> parentOfDeleted = x.parent;

        if (nodeReplacer != null) {
            nodeReplacer.parent = parentOfDeleted;
            if (parentOfDeleted == null) {
                root = nodeReplacer;
            } else if (x == parentOfDeleted.left) {
                parentOfDeleted.left = nodeReplacer;
            } else {
                parentOfDeleted.right = nodeReplacer;
            }
        } else if (parentOfDeleted == null) {
            root = null;
        } else {
            if (x == parentOfDeleted.left) {
                parentOfDeleted.left = null;
            } else {
                parentOfDeleted.right = null;
            }
        }
        if (parentOfDeleted != null) {
            fixUpFromBottom(parentOfDeleted);
        }

        x.left = null;
        x.right = null;
        x.parent = null;

        size--;
        modCount++;
        return oldValue;
    }

    private void fixUpFromBottom(AvlMapNode<K, V> parentOfDeleted) {
        balanceNode(parentOfDeleted);
    }
}

package org.lionsoul.jcseg.analyzer;

import java.io.IOException;

import org.apache.lucene.analysis.Tokenizer;
import org.apache.lucene.analysis.tokenattributes.CharTermAttribute;
import org.apache.lucene.analysis.tokenattributes.OffsetAttribute;
import org.apache.lucene.analysis.tokenattributes.TypeAttribute;
import org.lionsoul.jcseg.ISegment;
import org.lionsoul.jcseg.IWord;
import org.lionsoul.jcseg.dic.ADictionary;
import org.lionsoul.jcseg.segmenter.SegmenterConfig;


/**
 * <p>
 * here is the documentation from {@link org.apache.lucene.analysis.Tokenizer}
 * A Tokenizer is a TokenStream whose input is a Reader.
 * </p>
 * 
 * <p>
 * This is an abstract class; subclasses must override {@link #incrementToken()}
 * <p>
 * 
 * <p>
 * NOTE: Subclasses overriding {@link #incrementToken()} must
 * call {@link #clearAttributes()} before setting attributes
 * </p>
 *
 * <p>
 * lucene invoke Tokenizer#setReader(Reader input) to set the inputPending
 * after invoke the reset, global object input will be available
 * </p>
 * 
 * <p>Jcseg tokenizer for lucene on or after 5.1.0</p>
 * 
 * @author    chenxin<chenxin619315@gmail.com>
 */
public class JcsegTokenizer extends Tokenizer 
{
    // The default Jcseg segmentor
    private final ISegment segmentor;

    private final CharTermAttribute termAtt = addAttribute(CharTermAttribute.class);
    private final OffsetAttribute offsetAtt = addAttribute(OffsetAttribute.class);
    private final TypeAttribute typeAtt = addAttribute(TypeAttribute.class);
    
    /**
     * field level offset tracker for multiple-value field
     * like the Array field in Elasticsearch or Solr
    */
    private int fieldOffset = 0;
    
    public JcsegTokenizer(
        ISegment.Type type,
        SegmenterConfig config,
        ADictionary dic )
    {
        segmentor = type.factory.create(config, dic);
    }

    @Override
    final public boolean incrementToken() throws IOException 
    {
    	/* Clear the attributes */
    	clearAttributes();
    	
        final IWord word = segmentor.next();
        if ( word == null ) {
            fieldOffset = offsetAtt.endOffset();
            return false;
        }
        
        /// char[] token = word.getValue().toCharArray();
        /// termAtt.copyBuffer(token, 0, token.length);
        termAtt.append(word.getValue());
        termAtt.setLength(word.getLength());
        offsetAtt.setOffset(
        	correctOffset(fieldOffset + word.getPosition()), 
        	correctOffset(fieldOffset + word.getPosition() + word.getLength())
        );
        typeAtt.setType("word");
        
        return true;
    }
    
    @Override
    public void end() throws IOException
    {
        super.end();
        final int finalOffset = correctOffset(fieldOffset);
        offsetAtt.setOffset(finalOffset, finalOffset);
        this.fieldOffset = 0;
    }
    
    @Override
    public void reset() throws IOException 
    {
        super.reset();
        segmentor.reset(input);
    }
    
}

