/**
 * Given a Binary Tree and a key, write a function that returns level of the key.
 * 				3
 * 			/		\
 * 			2		5
 * 		/		\
 * 		1		4
 *
 * 	Here 3 is on level 1
 * 	2 and 5 have level 2
 * 	1 and 4 have level 3
 * 	If key not in tree, return 0
 *
 */
#include <iostream>
struct Node {
	int data;
	Node * left;
	Node * right;
	Node( int d ) : data{ d }, left{ nullptr }, right{ nullptr } { }
};

int get_node_level_util( Node * root, int key, int level ) {
	if ( root == nullptr ) {
		return 0;
	}
	if ( root->data == key ) {
		return level;
	}
	int downlevel = get_node_level_util( root->left, key, level + 1);
	if ( downlevel != 0 ) {
		return downlevel;
	}
	downlevel = get_node_level_util( root->right, key, level + 1);
	return downlevel;
}

int get_node_level( Node * root, int key ) {
	return get_node_level_util( root, key, 1 );
}

void printLevels(Node * root) {
	for ( int i = 1; i <= 6; ++i ) {
		std::cout << "Level of node with key as " << i << " is " << get_node_level( root, i ) << std::endl;
	}
}

int main() {
	Node * root = new Node(3);
	root->left = new Node(2);
	root->right = new Node(5);
	root->left->left = new Node(1);
	root->left->right = new Node(4);
	printLevels(root);
	return 0;
}

import java.util.*;

//binary search in a sorted array
public class BinarySearch {

	int search(int arr[], int l, int r, int x) 
    { 
        if (r >= l) { 
            int mid = l + (r - l) / 2; 

            if (arr[mid] == x) 
                return mid; 

            if (arr[mid] > x) 
                return search(arr, l, mid - 1, x); 

            return search(arr, mid + 1, r, x); 
        } 

        return -1; 
    } 
	public static void main(String[] args) {
		// TODO Auto-generated method stub
		Scanner s = new Scanner(System.in);
		System.out.print("Enter size of array: ");
		int size = s.nextInt();
		int[] arr = new int[size];
		System.out.print("Enter the elements of array: ");
		for(int i = 0; i < size; i++)
		{
			arr[i] = s.nextInt();
		}

		System.out.println("Enter the element you want to search: ");
		int element = s.nextInt();
		//Arrays.sort(arr);
		BinarySearch obj = new BinarySearch();
		int index = obj.search(arr, 0, size-1, element);

		if(index == -1)
		{
			System.out.println(element + " not found.");
		}
		else
		{
			System.out.println(element + " found.");
		}

	}

}

