void reverseCLL() {
    struct node *current, *prev, *nextnode;
    current = tail->next;

    if(tail == NULL) {
        printf("\nLinkedlist is empty.");
    } else {
        while(current != tail) {
            prev = current;
            current = nextnode;
            nextnode = current->next;
            current->next = prev;
        }

        nextnode->next = tail;
        tail = nextnode;
    }
}

