#         self.right = right
class Solution:
    def tree2str(self, root: Optional[TreeNode]) -> str:
        if not root:
            return ")"
        s = str(root.val)
        if root.left:
            s += "(" + self.tree2str(root.left) + ")"
        if root.right:
            s += ("" if root.left else "()") + "(" + self.tree2str(root.right) + ")"
