#include <iostream>
#include <algorithm>
using namespace std;

struct Card {char suit; char value;};

void trace(struct Card C[], int N) {
    for (int i = 0; i < N; i++){
        if (i > 0) cout << " ";
        cout << C[i].suit << C[i].value;
    }
    cout << endl;
}

void bubbleSort(struct Card A[], int N){
    int flag = 1;
    for(int i=0;flag;i++){
        flag = 0;
        for(int j= N-1; j >= i+1; j--){
            if (A[j].value < A[j-1].value) {
                swap(A[j], A[j-1]);
                flag = 1;
            }
        }
    }
}

void selectionSort(struct Card A[], int N) {
    for(int i=0; i<N; i++) {
        int minj = i;
        for(int j=i+1; j<N; j++) {
            if(A[j].value < A[minj].value) {
                minj = j;
            }
        }
        if(i != minj) {
            swap(A[i], A[minj]);
        }
    }
} 

bool judgeStable(Card C1[], Card C2[], int N) {
    for(int i=0; i<N; i++) {
        if(C1[i].suit != C2[i].suit) return false;
    }
    return true;
}

int main(){
    int N;
    cin >> N;
    Card C1[100],C2[100];
    for (int i=0; i < N; i++) {
        cin >> C1[i].suit >> C1[i].value;
        C2[i] = C1[i]; 
    }

    bubbleSort(C1, N);
    selectionSort(C2, N);

    trace(C1, N);
    cout << "Stable" << endl;
    trace(C2, N);
    if(judgeStable(C1, C2, N)){
        cout << "Stable" << endl;;
    }
    else {
        cout << "Not stable" << endl;
    }
    return 0;
}

