    {
        L = add_to_front (rand() % 1000, L);    //taking a random number and adding it to the list
    }
    print_list(L, "\n\nList Before sorting : \n");

    sort_list(L);

    print_list(L, "\n\nList After Sorting : \n");

    return 0;    
}

