#define N 8

// Possible moves for the knight
int xMoves[8] = { 2, 1, -1, -2, -2, -1, 1, 2 };
int yMoves[8] = { 1, 2, 2, 1, -1, -2, -2, -1 };

// Function to print the chessboard
void printSolution(int board[N][N]) {
    for (int x = 0; x < N; x++) {
        for (int y = 0; y < N; y++) {
            printf(" %2d ", board[x][y]);
        }
        printf("\n");
    }
}

// Check if the move is valid (within bounds and not yet visited)
int isValidMove(int x, int y, int board[N][N]) {
    return (x >= 0 && x < N && y >= 0 && y < N && board[x][y] == -1);
}

// Solve the Knight's Tour problem using backtracking
int solveKnightTour(int x, int y, int moveCount, int board[N][N], int xMoves[N], int yMoves[N]) {
    if (moveCount == N * N)
        return 1;

    // Try all possible moves for the knight
    for (int i = 0; i < 8; i++) {
        int nextX = x + xMoves[i];
        int nextY = y + yMoves[i];
        if (isValidMove(nextX, nextY, board)) {
            board[nextX][nextY] = moveCount;
            if (solveKnightTour(nextX, nextY, moveCount + 1, board, xMoves, yMoves))
                return 1;
            else
                board[nextX][nextY] = -1; // Backtrack
        }
    }

    return 0;
}

// Main function to initialize the chessboard and start the tour
int main() {
    int board[N][N];

    // Initialize the chessboard with -1 (unvisited)
    for (int x = 0; x < N; x++)
        for (int y = 0; y < N; y++)
            board[x][y] = -1;

    // Starting position of the knight
    int startX = 0;
    int startY = 0;
    board[startX][startY] = 0;

    // Solve the Knight's Tour
    if (solveKnightTour(startX, startY, 1, board, xMoves, yMoves))
        printSolution(board);
    else
        printf("No solution exists.\n");

    return 0;
}

// Write a function to delete a given node in a doubly linked list.

class LinkedList {   
    static Node head = null;   
    class Node {   
        int data; 
        Node next, prev;   
        Node(int d) { 
            data = d; 
            next = prev = null; 
        } 
    } 

    /*Function to delete a node in a Doubly Linked List. 
    head_ref --> pointer to head node pointer. 
    del  -->  pointer to node to be deleted. */
    void deleteNode(Node head_ref, Node del) {   
        /* base case */
        if (head == null || del == null) { 
            return; 
        }   
        /* If node to be deleted is head node */
        if (head == del) { 
            head = del.next; 
        }   
        /* Change next only if node to be deleted is NOT the last node */
        if (del.next != null) { 
            del.next.prev = del.prev; 
        }   
        /* Change prev only if node to be deleted is NOT the first node */
        if (del.prev != null) { 
            del.prev.next = del.next; 
        }   
        /* Finally, free the memory occupied by del*/
        return; 
    } 

    /* Function to insert a node at the beginning of the Doubly Linked List */
    void push(Node head_ref, int new_data) {   
        /* allocate node */
        Node new_node = new Node(new_data);   
        /* since we are adding at the begining, 
         prev is always NULL */
        new_node.prev = null;   
        /* link the old list off the new node */
        new_node.next = (head);   
        /* change prev of head node to new node */
        if ((head) != null) { 
            (head).prev = new_node; 
        }   
        /* move the head to point to the new node */
        (head) = new_node; 
    } 

    void printList(Node node) { 
        while (node != null) { 
            System.out.print(node.data + " "); 
            node = node.next; 
        } 
    } 

    public static void main(String[] args) { 
        LinkedList list = new LinkedList();   
        /* Let us create the doubly linked list 10<->8<->4<->2 */
        list.push(head, 2); 
        list.push(head, 4); 
        list.push(head, 8); 
        list.push(head, 10);   
        System.out.println("Original Linked list "); 
        list.printList(head); 

        /* delete nodes from the doubly linked list */
        list.deleteNode(head, head);  /*delete first node*/

        list.deleteNode(head, head.next);  /*delete middle node*/

        list.deleteNode(head, head.next);  /*delete last node*/
        System.out.println(""); 

        /* Modified linked list will be NULL<-8->NULL */
        System.out.println("Modified Linked List"); 
        list.printList(head); 
    } 
}

