using namespace std;
struct state{int x,y;};
 
bool f[50][50][2];
int H,W,N;
int six,siy,tix,tiy;
 
int d[50][50];
state prev[50][50];
 
int dfs(){
  for(int i=0;i<50;i++)
    for(int j=0;j<50;j++)
      d[i][j]=-1;
 
  d[six][siy]=0;
  queue<state> Q;
  Q.push((state){six,siy});
 
  while(!Q.empty()){
    state s=Q.front();Q.pop();
    int y=s.y,x=s.x;
    int cost=d[x][y];
    // cout<<x<<' '<<y<<' '<<cost<<endl;
 
    if(y+1<H && d[x][y+1]==-1 && !f[x][y][0]){
      d[x][y+1]=cost+1;
      prev[x][y+1]=s;
      Q.push((state){x,y+1});
    }
     
    if(x+1<W && d[x+1][y]==-1 && !f[x][y][1]){
      d[x+1][y]=cost+1;
      prev[x+1][y]=s;
      Q.push((state){x+1,y});
    }
 
    if(y>0 && d[x][y-1]==-1 && !f[x][y-1][0]){
      d[x][y-1]=cost+1;
      prev[x][y-1]=s;
      Q.push((state){x,y-1});
    }
 
    if(x>0 && d[x-1][y]==-1 && !f[x-1][y][1]){
      d[x-1][y]=cost+1;
      prev[x-1][y]=s;
      Q.push((state){x-1,y});
    }
  }
 
  return d[tix][tiy];
}
 
void init(){
  for(int i=0;i<50;i++)
    for(int j=0;j<50;j++)
      f[i][j][0]=f[i][j][1]=false;
}
 
 
int main(){
  while(cin>>W>>H>>N){
    init();
    for(int i=0;i<N;i++){
      int ax,ay,bx,by;
      cin>>ax>>ay>>bx>>by;
      if(ax==bx){// |
    if(ay>by)swap(ay,by);
    for(int y=ay;y<by;y++){
      if(ax)f[ax-1][y][1]=true;
    }
      }else if(ay==by){// -
    if(ax>bx)swap(ax,bx);
    for(int x=ax;x<bx;x++){
      if(ay)f[x][ay-1][0]=true;
    }
      }
    }
    cin>>six>>siy>>tix>>tiy;
    int A=dfs();
    if(A==-1){
      cout<<0<<endl;
      continue;
    }
    vector<state> vec;
    state s=(state){tix,tiy};
    while(1){
      vec.push_back(s);
      if(s.x==six&&s.y==siy)break;
      s=prev[s.x][s.y];
    }
    reverse(vec.begin(),vec.end());
    int B=A;
    for(int i=0;i+1<(int)vec.size();i++){
      int ax=vec[i].x;
      int ay=vec[i].y;
      int bx=vec[i+1].x;
      int by=vec[i+1].y;
 
      if(ax==bx){
    if(ay>by)swap(ay,by);
    f[ax][ay][0]=true;
      }else if(ay==by){
    if(ax>bx)swap(ax,bx);
    f[ax][ay][1]=true;
      }
 
      B=max(B,dfs());
      if(ax==bx){
    if(ay>by)swap(ay,by);
    f[ax][ay][0]=false;
      }else if(ay==by){
    if(ax>bx)swap(ax,bx);
    f[ax][ay][1]=false;
      }
    }
    cout<<B-A<<endl;
  }
  return 0;
}

