#include <stdio.h>
#include <stdlib.h>

struct node{
	int data;
	struct node *prev;
	struct node *next;
} *rear = NULL, *front = NULL;

struct node *newNode(int data){
	struct node *temp = (struct node *)malloc(sizeof(struct node));
	temp->data = data;
	temp->prev = NULL;
	temp->next = NULL;
	return temp;
}

void enqueue(int data){
	struct node *temp;
	if(!rear){
		temp = newNode(data);
		front = rear = temp;
	}else{
		while(rear->data < data){
			struct node *temp = rear;
			rear = rear->prev;
			free(temp);
			if(!rear){
				front = rear;
				break;
			}
		}
		temp = newNode(data);
		if(!rear){
			front = rear = temp;
		}else{
			rear->next = temp;
			temp->prev = rear;
			if(!front->next){
				front->next = temp;
			}
			rear = rear->next;
		}
	}
}

void printList(){
	struct node *temp = front;
	while(temp){
		printf("%d\n", temp->data);
		temp=temp->next;
	}
	// printf("=======================\n");
}

void printMaxInK(int *arr, int size, int k){
	int i;
	for(i=0; i<k;i++){
		enqueue(arr[i]);
	}
	// printList();
	printf("%d\n", front->data);
	int last=i-k;
	for(;i<size;i++){
		// printf("enqueuing %d\n", arr[i]);
		enqueue(arr[i]);
		if(arr[last] == front->data){
			front=front->next;
			// printf("front now pointing to %d\n", front->data);
			front->prev = NULL;
		}
		printf("%d\n", front->data);
		// printList();
		last++;
	}
}

