  printf( "栈顶为：%d\n", s->top_pointer );
  // 出栈
  int temp = pop( s );
  printf( "栈顶为：%d , 弹出元素为：%d\n", s->top_pointer, temp );
  temp = pop( s );
  printf( "栈顶为：%d , 弹出元素为：%d\n", s->top_pointer, temp );
  temp = pop( s );
  printf( "栈顶为：%d , 弹出元素为：%d\n", s->top_pointer, temp );
