function term() {
    var n = factor();

    while(true) {
        if ( line[idx] == "*" ) {
            idx++;
            n *= factor();
        } else if ( line[idx] == "/" ) {
            idx++;
            n = ~~(n / factor());
        } else {
            break;
        }
    }
    return n;
}

