#define  _CRT_SECURE_NO_WARNINGS
#include<stdio.h>
#include<stdlib.h>

#define SUCCESS 0
#define E_EXIST -1
#define MAX_COUNT 512

typedef struct Node{
    int item;
    struct Node* lchild;
    struct Node* rchild;
}Node;

int bst_insert(Node* node, int num) {
	Node **next_node = NULL;
	if (node->item == num) {
		return E_EXIST;
	}

	if (num < node->item) 
		next_node = &node->lchild;
	else
		next_node = &node->rchild;

	if (*next_node == NULL) {
		*next_node = (Node*)calloc(1, sizeof(Node));
		(*next_node)->item = num;
		return SUCCESS;
	} else {
		return bst_insert(*next_node, num);
	}
		
}

Node * create_bst_tree(int* num, int len) {
	int i = 1;
	Node * root = (Node*)calloc(1, sizeof(Node));
	if (root == NULL)
		return NULL;
	root->item = num[0];
	for (;i < len; i++) {
		bst_insert(root, num[i]);
	}
	return root;
}

Node* bst_search(Node * node , int item) {
	if (node == NULL)
		return NULL;

	if (node->item == item)
		return node;

	if( item > node->item)
		return bst_search(node->rchild, item);
	else
		return bst_search(node->lchild, item);
}

