  for(int i=0;i<n;i++) {

   if(positiveSlope(packages[i].y,packages[i].x,packages[i+1].y,packages[i+1].x)){
    ans.append(move(packages[i].y,packages[i].x,packages[i+1].y,packages[i+1].x));
