class Solution:
    def sortedListToBST(self, head: Optional[ListNode]) -> Optional[TreeNode]:
        
        
        def dc(head):
            
            if not head:
                return None
            
            if not head.next:
                return TreeNode(head.val)
            
            prev = None
            slow = head
            fast = head
            while fast and fast.next:
                fast = fast.next.next
                prev = slow
                slow = slow.next
        
            prev.next = None
            
            return TreeNode(slow.val, dc(head), dc(slow.next))
        
        return dc(head)

