                for (int k = j + 1; k < aa.length; k++) {
                    int current1 = Integer.parseInt(aa[k]);
                    if (Math.max(current, current1) % Math.min(current, current1) == 0) {
                        sum += (Math.max(current, current1) / Math.min(current, current1));
                        break;
                    }
                }
            }
        }
        return sum;
    }
