long long seg_find(int now,int n_l,int n_r,int w_l,int w_r){
    if(updates[now] != -1){
        seg_tree[now] = updates[now];
        updates[now*2] = updates[now];
        updates[now*2+1] = updates[now];
        updates[now] = -1;
    }
    if(w_l <= n_l&&n_r <= w_r) return seg_tree[now];
    if(n_r <= w_l||w_r <= n_l) return (1LL << 31LL) - 1;
    return min(seg_find(now*2,n_l,(n_l+n_r)/2,w_l,w_r),seg_find(now*2+1,(n_l+n_r)/2,n_r,w_l,w_r));
