        updates[now*2] = updates[now];
        updates[now*2+1] = updates[now];
        updates[now] = -1;
    }
    if(w_l <= n_l&&n_r <= w_r){
        updates[now] = settings;
        seg_tree[now] = settings;
        return seg_tree[now];
    }
    if(n_r <= w_l||w_r <= n_l) return (1LL << 31LL) - 1;
