def fib_period_of_cycle(m):

    if n<=1:
        return n
    
    a,b = 0,1
    for i in range((m*m)+1):
        a,b = b,(a+b)%m
        if a==0 and b==1:
            return i+1

def get_fibonacci_huge_fast(n,m):
    if n<=1:
        return n
    rem=n%fib_period_of_cycle(m)
    if rem<=1:
        return rem
    a,b = 0,1
    for _ in range(rem-1):
        a,b=b,(a+b)

    return b%m


