using namespace std;

const int N = 2e3 + 11;
int a[N][N];
int b[N][N];

int f(int *a, int x) {
	for(int i = 0; i < N; i ++)
		if(a[i] == x) return i;
}
int rf(int *a, int x) {
	for(int i = N - 1; i >= 0; i --)
		if(a[i] == x) return i;
}

bool check(int n, int m, int limit) {
	int mi = 1e9L, ma = 0;
	memset(b, -1, sizeof(b));
	for(int i = 1; i <= n; i ++)
		for(int j = 1; j <= m; j ++) {
			mi = min(mi, a[i][j]);
			ma = max(ma, a[i][j]);
		}
	for(int i = 1; i <= n; i ++)
		for(int j = 1; j <= m; j ++) {
			if(a[i][j] < ma - limit && a[i][j] > mi + limit)
				return false;
			else if(a[i][j] < ma - limit)
				b[i][j] = 0;
			else if(a[i][j] > mi + limit)
				b[i][j] = 1;
		}
	for(int t = 0; t < 2; t ++) {
		vector <pair <int, int>> v;
		for(int i = 1; i <= n; i ++) {
			int c[2] = {(int)count(b[i] + 1, b[i] + m + 1, t),
				(int)count(b[i] + 1, b[i] + m + 1, 1 - t)};
			if(c[0] && c[1]) {
				int l = rf(b[i], t);
				int r = f(b[i], 1 - t) - 1;
				if(l > r) goto end;
				v.push_back({l, r});
			} else if(c[0]) {
				int l = rf(b[i], t);
				v.push_back({l, m});
			} else if(c[1]) {
				int r = f(b[i], 1 - t) - 1;
				v.push_back({0, r});
			} else
				v.push_back({0, m});
		}

		for(int _ = 0; _ < 2; _ ++) {
			bool f = true;
			int s = -1;
			for(auto p : v) {
				if(s == -1)
					s = p.first;
				else {
					while(s < p.first)
						s ++;
					if(s > p.second)
						f = false;
				}
			}
			if(f) return true;
			for(auto &p : v)
				p = {m - p.second, m - p.first};
		}

		end: ;
	}
	return false;
}

int main() {
	int n, m; cin >> n >> m;
	for(int i = 1; i <= n; i ++)
		for(int j = 1; j <= m; j ++)
			scanf("%d", &a[i][j]);
	int l = 0, r = 1e9L + 11;
	while(l + 1 < r) {
		int mid = (l + r) / 2;
		if(check(n, m, mid - 1))
			r = mid;
		else
			l = mid;
	}
	cout << l << '\n';
	return 0;
}

