	for(i=1; i<size;i++){
		c[i]=c[i-1]+c[i];
	}
	for(j=length-1;j>=0;j--){
		b[c[a[j]-min]-1]=a[j]; //-1 is done to match with 0 index
		c[a[j]-min]--;
	}
	//printing the array
	for(i=0; i<length;i++){
		printf("%d ", b[i]);
	}
}

