ll comb(ll N_, ll C_) {
	const int NUM_=400001;
	static ll fact[NUM_+1],factr[NUM_+1],inv[NUM_+1];
	if (fact[0]==0) {
		inv[1]=fact[0]=factr[0]=1;
		for (int i=2;i<=NUM_;++i) inv[i] = inv[mo % i] * (mo - mo / i) % mo;
		for (int i=1;i<=NUM_;++i) fact[i]=fact[i-1]*i%mo, factr[i]=factr[i-1]*inv[i]%mo;
	}
	if(C_<0 || C_>N_) return 0;
	return factr[C_]*fact[N_]%mo*factr[N_-C_]%mo;
}
ll p2[2020];

struct res {
	ll V[2][404];
};


res hoge(int L,int R,int B) {
	while(L<R&&H[L]<=B) L++;
	res ret={};
	if(L==R) {
		ret.V[0][0]=ret.V[1][0]=1;
		return ret;
	}
	int i;
	int add=0;
	for(i=L;i<R;i++) {
		if(H[i]<=B) {
			res X=hoge(L,i,B);
			res Y=hoge(i+1,R,B);
			int a1,a2;
			int W=R-L-1;
			for(a1=0;a1<=i-L;a1++) for(a2=0;a1+a2<=W;a2++) {
				(ret.V[0][a1+a2]+=1LL*X.V[0][a1]*Y.V[0][a2])%=mo;
				(ret.V[1][a1+a2]+=1LL*X.V[1][a1]*Y.V[1][a2])%=mo;
			}
			return ret;
		}
		if(H[i]==B+1) add++;
	}
	res X = hoge(L,R,B+1);
	int a1,a2,u1,u2;
	int W=R-L;
	// no rook
	FOR(u1,W-add+1) ret.V[0][u1+add]=ret.V[1][u1+add]=X.V[0][u1];
	
	FOR(u1,W+1) if(X.V[0][u1] || X.V[1][u1]) {
		int x,y;
		if(X.V[0][u1]) {
			FOR(x,u1+add+1) {
				if(x+y==0) (ret.V[0][u1+add]+=X.V[0][u1]*(p2[W-(u1+add)]-1))%=mo;
				else (ret.V[0][u1+add-x-y]+=X.V[0][u1]*comb(u1+add,x)%mo*p2[W-(u1+add)])%=mo;
			}
		}
		if(X.V[1][u1]) {
			FOR(x,u1+1) {
				if(x==0) (ret.V[1][u1]+=X.V[1][u1]*(p2[W-u1]-1))%=mo;
				else (ret.V[1][u1-x]+=X.V[1][u1]*comb(u1,x)%mo*p2[W-u1])%=mo;
			}
		}
	}
		
	return ret;
	
}

