/**
 * Finds the minimum amount of change that cannot be created using the given coins.
 *
 * @param {number[]} coins - An array of positive integers representing coin values.
 * @returns {number} - The minimum amount of change that cannot be created.
 */
function nonConstructibleChange(coins) {
  // Start with the smallest possible change, which is 1.
  let minChange = 1;

  // Sort the coins in ascending order. Sorting takes O(n log n) time.
  coins.sort((a, b) => a - b);

  // Iterate through the sorted coins to update the minimum change. This takes O(n) time.
  for (const coin of coins) {
    // If the current coin value is greater than minChange, we've found the minimum
    // non-constructible value, and we can break from the loop.
    if (coin > minChange) break;

    // Otherwise, we can increment minChange by the current coin value.
    minChange += coin;
  }

  return minChange;
}

// Complexity Analysis:
// - Time Complexity: O(n log n) for sorting + O(n) for iteration = O(n log n)
// - Space Complexity: O(1) (constant space used, not dependent on input size)

export { nonConstructibleChange };

// Time: (n^2) || Space: (1)
export function insertionSort(array) {
  let step_fast = 1;
  let step_slow = 0;
  while (step_fast < array.length) {
    if (array[step_slow] > array[step_fast]) {
      swap(array, step_fast)
    }
    step_fast++
    step_slow++
  }
  return array
}

function swap(array, idx) {
  let slow = idx - 1;
  let current = idx;
  while (slow >= 0) {
    if (array[slow] > array[current]) {
      let store = array[slow];
      array[slow] = array[current];
      array[current] = store
    }
    current = current - 1;
    slow = slow - 1
  }
}

export function insertionSortRefactor(array) {
  let step_fast = 1;
  let step_slow = 0;
  while (step_fast < array.length) {
    if (array[step_slow] > array[step_fast]) {
      swapRefactor(array, step_fast)
    }
    step_fast++
    step_slow++
  }
  return array
}

function swapRefactor(array, idx) {
  let step_after = idx - 1;
  let step_current = idx;
  while (step_after >= 0) {
    if (array[step_after] > array[step_current]) {
      let store = array[step_after];
      array[step_after] = array[step_current];
      array[step_current] = store
    }
    step_current = step_current - 1;
    step_after = step_after - 1
  }
}

