#define int long long
#define MAX 200005

vector<int> seg(4*MAX, 0), adj[MAX];
int arr[MAX], brr[MAX], ans[MAX];
map<int, int> mp;
int ps = 0;

int query(int idx, int l, int r, int sl, int sr){
	if( l > sr || r < sl )
		return 0;
	if( sl <= l && sr >= r )
		return seg[idx];

	int md = (l+r)/2;
	return max(query(2*idx, l, md, sl, sr), query(2*idx+1, md+1, r, sl, sr));
}

int get(int idx, int l, int r, int pos){
	if( l == r )
		return seg[idx];
	int md = (l+r)/2;
	if( pos <= md )
		return get(2*idx, l, md, pos);
	else
		return get(2*idx+1, md+1, r, pos);
}

void update(int idx, int l, int r, int pos, int val){
	if( l == r ){
		seg[idx] = val;
		return;
	}
	int md = (l+r)/2;
	if( pos <= md )
		update(2*idx, l, md, pos, val);
	else
		update(2*idx+1, md+1, r, pos, val);
	seg[idx] = max(seg[2*idx], seg[2*idx+1]);
}

void dfs(int u, int p){
	int mpos = mp[arr[u]];
	ans[u] = mpos > 0 ? query(1, 0, ps-1, 0, mpos-1)+1 : 1;
	int prev = get(1, 0, ps-1, mpos);
	update(1, 0, ps-1, mpos, ans[u]);
	ans[u] = seg[1];
	for(int v : adj[u])
		if( v != p )
			dfs(v, u);

	update(1, 0, ps-1, mpos, prev);
}

