/*
 * Given an array of n integers where n > 1, nums, return an array output
 * such that output[i] is equal to the product of all the elements of nums except nums[i].
 * Example: [1, 2, 3, 4] ==> [24, 12, 8, 6]
 * 
 * Try to use constant space. (excluding result array)
 */

#include <iostream>
#include <vector>


/*
 * Idea is to maintain two product variables, one from beginning and 
 * one from the end.
 * Each result variable in result array
 * would be touched twice, one from the left to right
 * and other right to left, thus producing desired result.
 */
std::vector<int> product_except_self(const std::vector<int>& nums)
{
    int product_from_beginning = 1;
    int product_from_end = 1;
    unsigned int n = nums.size();
    std::vector<int> result(n, 1);
    for (unsigned int i = 0; i < n; ++i) {
        result[i] *= product_from_beginning;
        product_from_beginning *= nums[i];
        result[n-1-i] *= product_from_end;
        product_from_end *= nums[n-1-i];
    }
    return result;
}
void print_vector(const std::vector<int>& vec)
{
    for (auto n : vec) {
        std::cout << n << " ";
    }
    std::cout << std::endl;
}

int main()
{
    std::vector<int> vec{1, 2, 3, 4};
    std::cout << "Input Vector: ";
    print_vector(vec);
    std::vector<int> result = product_except_self(vec);
    std::cout << "Output Vector: ";
    print_vector(result);
}

/*
Given the head of a singly linked list, return true if it is a palindrome or false otherwise.

Example 1:

Input: head = [1,2,2,1]
Output: true
Example 2:

Input: head = [1,2]
Output: false 

Constraints:

The number of nodes in the list is in the range [1, 105].
0 <= Node.val <= 9
*/
class Solution {
    public boolean isPalindrome(ListNode head) {
        if(head==null || head.next==null)return true;
        ListNode mid = middle(head);
        ListNode rev = reverse(mid);
        while(rev!=null){
            if(head.val!=rev.val){
                return false;
            }
            head=head.next;
            rev=rev.next;

        }
        return true;

    }
    public static ListNode middle(ListNode head){
        ListNode slow=head;
        ListNode fast=head;
        while(fast!=null && fast.next!=null){
            slow=slow.next;
            fast=fast.next.next;
        }
        return slow;

    }
    public static ListNode reverse (ListNode head){
        if(head==null)return head;
        ListNode prev=null;
        while(head!=null){
            ListNode temp = head.next;
            head.next=prev;
            prev=head;
            head=temp;
        }
        return prev;
    }
}

class Solution {

    Map<Integer, Integer> memo = new HashMap<>();

    public int numDecodings(String s) {
        return numDecoding(s, 0);
    }

    private int numDecoding(String s, int start) {

        if (memo.containsKey(start)) {
            return memo.get(start);
        }

        if (start == s.length()) {
            return 1;
        }

        if (s.charAt(start) == '0') {
                return 0;
        }

        if (start == s.length() - 1) {
            return 1;
        }

        int count = numDecoding(s, start + 1);

        if (start + 1 < s.length()) {
            Integer val = Integer.valueOf(s.substring(start, start + 2));
            if (val <= 26) {
                count += numDecoding(s, start + 2);
            }
        }

        memo.put(start, count);

        return count;
    }
}

/*
 Petar 'PetarV' Velickovic
 Algorithm: Ford-Fulkerson Algorithm
*/

#include <stdio.h>
