namespace TYC
{
	typedef long long ll;
	typedef pair<ll, int> pa;
	const int N = 2010, INF = 0x3f3f3f3f;
	const ll INFLL = 0x3f3f3f3f3f3f3f3fLL;

	int n, S, T, Head[N], Pre[N], Vis[N];
	ll H[N], Dis[N];
	struct edge { int to, next, w, c; } E[N * 20];

	inline int read()
	{
		int x = 0, f = 0, ch = getchar();
		while (!isdigit(ch))
			f |= (ch == '-'), ch = getchar();
		while (isdigit(ch))
			x = x * 10 + ch - '0', ch = getchar();
		return f ? -x : x;
	}

	void add(const int u, const int v, const int w, const int c)
	{
		static int ecnt = 1;
		E[++ecnt] = (edge){v, Head[u], w, c};
		Head[u] = ecnt;
		E[++ecnt] = (edge){u, Head[v], 0, -c};
		Head[v] = ecnt;
	}

	void spfa()
	{
		static queue<int> Q;
		Q.push(S);
		fill(H + 1, H + T + 1, -INFLL);
		H[S] = 0;
		while (!Q.empty())
		{
			int u = Q.front();
			Q.pop();
			Vis[u] = 0;
			for (int i = Head[u]; i; i = E[i].next)
			{
				int v = E[i].to;
				if (E[i].w && H[v] < H[u] + E[i].c)
				{
					H[v] = H[u] + E[i].c;
					if (!Vis[v])
						Q.push(v), Vis[v] = 1;
				}
			}
		}
	}

	bool Dijkstra()
	{
		static priority_queue<pa> Q;
		memset(Vis, 0, sizeof(int[T + 1]));
		fill(Dis + 1, Dis + T + 1, -INFLL);
		Q.push(pa(Dis[S] = 0, S));
		while (!Q.empty())
		{
			int u = Q.top().second; 
			Q.pop();
			if (Vis[u])
				continue;
			Vis[u] = 1;
			for (int i = Head[u]; i; i = E[i].next)
			{
				int v = E[i].to;
				ll w = E[i].c + H[u] - H[v];
				if (E[i].w && Dis[v] < Dis[u] + w)
				{
					Pre[v] = i;
					Dis[v] = Dis[u] + w;
					Q.push(pa(Dis[v], v));
				}
			}
		}
		return Dis[T] != -INFLL;
	}

	ll mcmf()
	{
		spfa();
		ll ans = 0;
		while (Dijkstra())
		{
			int flow = INF;
			for (int i = Pre[T]; i; i = Pre[E[i ^ 1].to])
				flow = min(flow, E[i].w);
			for (int i = Pre[T]; i; i = Pre[E[i ^ 1].to])
				E[i].w -= flow, E[i ^ 1].w += flow;
			ans += (ll)flow * (Dis[T] - H[S] + H[T]);
			for (int i = 1; i <= T; i++)
				H[i] += Dis[i];
		}
		return ans;
	}

	void work()
	{
		n = read();
		S = (n << 1) + 1, T = S + 5;
		for (int i = 1; i <= n; i++)
		{
			int x = read(), y = read();
			add(S, i, read(), 0);
			add(i, S + 1, INF, +x + y);
			add(i, S + 2, INF, +x - y);
			add(i, S + 3, INF, -x + y);
			add(i, S + 4, INF, -x - y);
		}
		for (int i = n + 1; i <= (n << 1); i++)
		{
			int x = read(), y = read();
			add(i, T, read(), 0);
			add(S + 1, i, INF, -x - y);
			add(S + 2, i, INF, -x + y);
			add(S + 3, i, INF, +x - y);
			add(S + 4, i, INF, +x + y);
		}
		printf("%lld\n", mcmf());
	}
}

