//Insertion Sort
void sort(int A[],int n)
{
	int i,value,h;

	for(i=1;i<n;i++)
	{
		value = A[i];
		h = i;

		while(h>0 && A[h-1] > value)
		{
			A[h] = A[h-1];
			h = h-1;
		}

		A[h] = value;
	}

}

