const int INF = 1000000000;
int value[] = {500, 100, 50, 10, 5, 1};

int opt(int p, int num[])
{
  int ret = 0;
  REP(i, 6) {
    int use = min(num[i], p / value[i]);
    p -= value[i] * use;
    ret += use;
  }
  return p ? INF : ret;
}

int main()
{
  int p;
  while (scanf("%d", &p), p) {
    int num[6], sum = 0;
    REP(i, 6) {
      scanf("%d", &num[5-i]);
      sum += num[5-i] * value[5-i];
    }
    int big[] = {INF, INF, INF, INF, INF, INF};
    int ans = INF;
    FOREQ(i, p, min(sum, p + 10000)) {
      ans = min(ans, opt(i, num) + opt(i - p, big));
    }
    printf("%d\n", ans);
  }
}

import java.lang.StringBuffer;

public class LinkedList {

    public LLNode head;

    public LinkedList() {
        this.head = null;
    }

    public LinkedList(LLNode head) {
        this.head = head;
    }

    public LinkedList(Object obj) {
        this.head = new LLNode(obj);
    }

    public void add(LLNode nd) {
        if(head == null) {
            head = nd;
            return;
        }
        LLNode cur = head;
        while(cur.next != null) {
            cur = cur.next;
        }
        cur.next = nd;
    }

    public void reverse() {
        if(head == null || head.next == null) return;
        head = reverse(head);
    }

    public LLNode reverse(LLNode nd) {
        if(nd.next == null) return nd;

        //reverse the linked list starting from the second node
        LLNode second = reverse(nd.next);

        //Add first node to end of reversed sub list
        LLNode tmp = second;
        while(tmp.next != null) {
            tmp = tmp.next;
        }
        nd.next = null;
        tmp.next = nd;
        return second;
    }

    public String toString() {
        LLNode cur = head;
        StringBuffer retSB = new StringBuffer();
        while(cur != null) {
            retSB.append("(" + cur.val + ")->");
            cur = cur.next;
        }
        return retSB.toString();
    }

    public static void main(String[] args) {
        LinkedList list = new LinkedList();
        System.out.println("List: " + list);
        list.add(new LLNode(1));
        list.add(new LLNode(2));
        list.add(new LLNode(3));
        list.add(new LLNode(4));
        System.out.println("List: " + list);
        list.reverse();
        System.out.println("List: " + list);
    }
}

def binSearch(arr, val):
    def search(arr, val, l, r):
        # Base case
        ## 1. Negative
        if l > r:
            return None

        ## 2. Positive case
        mid = (l + r) // 2
        if arr[mid] == val:
            return mid

        # Recursive step, rules to reduce all other cases to base case
        if val < arr[mid]:
            # Search in the left side of the array
            return search(arr, val, l, mid)

        return search(arr, val, mid+1, r)

    return search(arr, val, 0, len(arr)-1)

