function calcPrimeNumbers(){
  var max = 49999;
  var primeNumbers = new Int8Array(max + 1);
  var primeCounts = new Int16Array(100001);
   
  // 除外
  primeNumbers[0] = primeNumbers[1] = 1;
  for(var i = 2, maxI = ~~Math.sqrt(max); i <= maxI; i++){
    if(primeNumbers[i]){
      continue;
    }
       
    for(var j = (i<<1); j <= max; j+=i){
      primeNumbers[j] = 1;
    }
  }
   
  var primeNums = new Int16Array(5134);
  var c = 0;
  for(var i = 1; i <= max; i++){
    if(primeNumbers[i])
      continue;
    
    primeNums[++c] = i;
    for(var j = 1; j <= c; j++){
      var sum = i + primeNums[j];
      
      primeCounts[sum]++;
    }
      
  }
     
  return primeCounts;
}

