int fa[N], sz[N], out[N], ini[N], vis[N];
int find(int x){return x==fa[x]?x:fa[x]=find(fa[x]);}
void merge(int x, int y) {
	int xx = find(x), yy = find(y);
	if (xx == yy) ++ sz[xx];
	else fa[xx] = yy, sz[yy] += sz[xx] + 1;
}
int main(int argc, char const *argv[]) {
