struct Node
{
	int data;
	struct Node* next;

};
struct Node* head;

//Linked List

void insertatbeg(int x)
{
	struct Node* temp;
	temp = (struct Node*)malloc(sizeof(struct Node));

	temp->data = x;
	temp->next = head;
	head = temp;
}

void insertatend(int x)
{
	struct Node *temp,*p;
	temp = (struct Node*)malloc(sizeof(struct Node));
	p = (struct Node*)malloc(sizeof(struct Node));

	temp->data = x;
	temp->next = NULL;
	p = head;

	while(p->next!=NULL)
	{
		p = p->next;
	}
	p->next = temp;
}

void printlist(struct Node* temp)
{
	if(temp==NULL)
		return;

	printf("%d ",temp->data);
	printlist(temp->next);
}

void inseratn(int x , int n)
{
	int i;
	struct Node *temp,*p,*temp1;

	if(n==1)
	{
		insertatbeg(x);
		return;
	}

	temp = (struct Node*)malloc(sizeof(struct Node));
	p = (struct Node*)malloc(sizeof(struct Node));
	temp1 = (struct Node*)malloc(sizeof(struct Node));

	temp1->data = x;

	p = head;
	temp = head;

	for(i=0;i<n;i++)
		temp = temp->next;

	for(i=0;i<n-2;i++)
		p = p->next;

	p->next = temp1;
	temp1->next = temp;

}
void deleteatn(int n)
{
	struct Node *temp,*p;
	int i;
	temp = (struct Node*)malloc(sizeof(struct Node));
	p = (struct Node*)malloc(sizeof(struct Node));

	p = head;
	temp = head;
    if(n==1)
    {
    	head = temp->next;
    	return;
    }
	for(i=0;i<n;i++)
		temp= temp->next;
	
	for(i=0;i<n-2;i++)
		p = p->next;

	p->next = temp;
}

void reverse(struct Node* temp)
{
	if(temp->next==NULL)
	{
		head = temp;
		return;
	}

	reverse(temp->next);
	struct Node *q;
	q = temp->next;
	q->next = temp;
	temp->next = NULL;


}

void printrev(struct Node* temp)
{
	if(temp==NULL)
		return;

	printrev(temp->next);
	printf("%d ",temp->data);
}

