// Circular Queue using array
#include <stdio.h>
#include <stdlib.h>

#define N 50
int queue[N];
int front = -1;
int rear = -1;

void enqueue()
{
    int x;
    printf("Enter data to be enqueued: ");
    scanf("%d", &x);
    if (front == -1 && rear == -1)
    {
        front = rear = 0;
        queue[rear] = x;
    }
    else if ((rear + 1) % N == front)
    {
        printf("Queue is full\n");
    }
    else
    {
        rear = (rear + 1) % N;
        queue[rear] = x;
    }
}

void dequeue()
{
    if ((front == -1) && (rear == -1))
    {
        printf("\nQueue is underflow..\n");
    }
    else if (front == rear)
    {
        printf("\nThe Dequeued element is %d\n", queue[front]);
        front = -1;
        rear = -1;
    }
    else
    {
        printf("\nThe Dequeued element is %d\n", queue[front]);
        front = (front + 1) % N;
    }
}

void display()
{
    int i = front;
    if (front == -1 && rear == -1)
    {
        printf("Queue is Empty\n");
    }
    else
    {
        printf("Queue is: ");
        while (i != rear)
        {
            printf("%d ", queue[i]);
            i = (i + 1) % N;
        }
        printf("%d ", queue[rear]);
    }
    printf("\n");
}

void peek()
{
    if (front == -1 && rear == -1)
    {
        printf("Queue is Empty\n");
    }
    else
    {
        printf("Front Element: %d", queue[front]);
    }
}
int main()
{
    int ch;
    int x;

    while (1)
    {
        printf("\n*** Queue Menu ***");
        printf("\n1.Insert\n2.Delete\n3.Display\n4.Peek\n5.Exit");
