#include <set>
#include <cstdio>
#include <queue>
#define REP(i,n) for(int i=0; i<(int)(n); i++)

inline int getInt(){ int s; scanf("%d", &s); return s; }

using namespace std;

typedef pair<int, int> Edge;

vector<vector<Edge> > g;
vector<vector<bool> > u;

int bfs(int s, int t){
  int n = g.size();

  vector<int> ans(n, -1);
  queue<int> q;
  ans[s] = 0; q.push(s);

  while(q.size()){
    int pos = q.front(); q.pop();
    int cost = ans[pos];
    REP(i,g[pos].size()){
      int next = g[pos][i].first;
      if(u[pos][i] && ans[next] == -1){
        if(next == t) return cost + 1;
        ans[next] = cost + 1;
        q.push(next);
      }
    }
  }

  return n + 1;
}

int main(){
  while(const int n = getInt()){
    const int s = getInt() - 1;
    const int t = getInt() - 1;
    const int m = getInt();
    vector<vector<int> > id(n);

    g = vector<vector<Edge> >(n);
    u = vector<vector<bool> >(n);

    REP(i,m){
      const int a = getInt() - 1;
      const int b = getInt() - 1;

      const size_t v1 = g[a].size();
      const size_t v2 = g[b].size();

      g[a].push_back(Edge(b, v2));
      g[b].push_back(Edge(a, v1));

      u[a].push_back(true);
      u[b].push_back(false);

      id[a].push_back(i + 1);
      id[b].push_back(i + 1);
    }

    pair<int, int> ans = make_pair(bfs(s, t), 0);

    REP(i,n) REP(j,g[i].size())
      if(u[i][j]){
        int to  = g[i][j].first;
        int rev = g[i][j].second;
        u[i][j] = false;
        u[to][rev] = true;
        ans = min(ans, make_pair(bfs(s, t), id[i][j]));
        u[i][j] = true;
        u[to][rev] = false;
      }

    printf("%d %d\n", ans.first, ans.second);
  }
  return 0;
}

