	}
	for(int i=0;i<N;i++) for(int j=0;j<2;j++){
		for(int k=0;k<=Sum;k++){
			f[i][j][k]=inf;
		}
	}
	f[N-1][0][s[N-1]]=-inf;
	f[N-1][1][0]=-inf;
	for(int i=N-2;i>=0;i--){
		for(int j=0;j<=1;j++){
			for(int s=0;s<=Sum;s++){
				long long lb=-inf/2,ub=inf/2;
				while(ub-lb>1){
					long long x=(ub+lb)/2;
					int val=simulate(i,j,x);
					if(val>=s){
						ub=x;
					}else{
						lb=x;
					}
				}
				if(ub==(-inf/2)+1) f[i][j][s]=-inf;
				else if(ub==(inf/2)) f[i][j][s]=inf;
				else f[i][j][s]=ub;
			}
		}
	}
	int ans=0;
	for(int i=0;i<=Sum;i++){
		if(f[0][0][i]<=A-B){
			ans=i;
		}
	}
	printf("%d %d\n",ans,Sum-ans);
	return 0;
}

