map<int,int>calc(int a,int b){
    if(a+b>=L){
        map<int,int>ret;
        ret[L]++;
        return ret;
    }

    auto m=calc(a+b,a);
    map<int,int>ret;

    for(auto p:m){
        if(p.fi>a+b){
            ret[a+b]+=p.se;
            ret[p.fi-a-b]+=p.se;
        }
        else{
            ret[p.fi]+=p.se;
        }
    }
    return ret;
