	int i;
	first=(struct Node *)malloc(sizeof(struct Node));

	first->Data=a[0];
	first->next=NULL;
	last=first;

	for(i=1;i<elements;i++){
		current=(struct Node *)malloc(sizeof(struct Node ));
		current->Data=a[i];
		current->next=NULL;
		last->next=current;
		last=current;
	}
}

int count_of_node(struct Node *node)
{
	int count=0;
	while(node!=NULL){
		count++;
		node=node->next;
	}
	return count;
}


