	for (int i = 0; i < M; ++i) {
		cin >> valve[i].x >> valve[i].y;
	}
	point2d src, dst;
	cin >> src.x >> src.y >> dst.x >> dst.y;
	vector<vector<int> > cardinals(N);
	vector<point2d> pts;
	vector<int> ptstype;
	function<int(point2d)> next_ptr = [&](point2d p) {
		for (int i = 0; i < pts.size(); ++i) {
			if ((p - pts[i]).abs() < 1.0e-8) return i;
		}
		return int(pts.size());
	};
	for (int i = 0; i < N; ++i) {
		int p1ptr = next_ptr(seg[i].p1);
		if (p1ptr == pts.size()) pts.push_back(seg[i].p1), ptstype.push_back(0);
		cardinals[i].push_back(p1ptr);
		ptstype[p1ptr] |= 1;
		int p2ptr = next_ptr(seg[i].p2);
		if (p2ptr == pts.size()) pts.push_back(seg[i].p2), ptstype.push_back(0);
		cardinals[i].push_back(p2ptr);
		ptstype[p1ptr] |= 1;
	}
	for (int i = 0; i < M; ++i) {
		int ptr = next_ptr(valve[i]);
		if (ptr == pts.size()) pts.push_back(valve[i]), ptstype.push_back(0);
		ptstype[ptr] |= 2;
		for (int j = 0; j < N; ++j) {
			if (distance(valve[i], seg[j]) < 1.0e-8) {
				cardinals[j].push_back(ptr);
			}
		}
	}
	int srcptr = next_ptr(src);
	if (srcptr == pts.size()) pts.push_back(src), ptstype.push_back(0);
	ptstype[srcptr] |= 4;
	int dstptr = next_ptr(dst);
	if (dstptr == pts.size()) pts.push_back(dst), ptstype.push_back(0);
	ptstype[dstptr] |= 8;
	for (int i = 0; i < N; ++i) {
		if (distance(src, seg[i]) < 1.0e-8) {
			cardinals[i].push_back(srcptr);
		}
		if (distance(dst, seg[i]) < 1.0e-8) {
			cardinals[i].push_back(dstptr);
		}
	}
	for (int i = 0; i < N; ++i) {
		for (int j = i + 1; j < N; ++j) {
			if (intersect(seg[i], seg[j])) {
				point2d crp = intersect_point(seg[i], seg[j]);
				int ptr = next_ptr(crp);
				if (ptr == pts.size()) pts.push_back(crp), ptstype.push_back(0);
				ptstype[ptr] |= 16;
				cardinals[i].push_back(ptr);
				cardinals[j].push_back(ptr);
			}
		}
	}
	vector<vector<edge> > G(pts.size());
	int cnt = 0;
	for (int i = 0; i < N; ++i) {
		sort(cardinals[i].begin(), cardinals[i].end(), [&](int j, int k) { return abs(pts[j].x - pts[k].x) > 1.0e-8 ? pts[j].x < pts[k].x : pts[j].y < pts[k].y; });
		cardinals[i].erase(unique(cardinals[i].begin(), cardinals[i].end()), cardinals[i].end());
		for (int j = 1; j < cardinals[i].size(); ++j) {
			G[cardinals[i][j]].push_back(edge{ cardinals[i][j - 1], cnt });
			G[cardinals[i][j - 1]].push_back(edge{ cardinals[i][j], cnt });
			++cnt;
		}
	}
	queue<int> que;
	que.push(dstptr);
	vector<bool> used(pts.size());
	used[dstptr] = true;
	while (!que.empty()) {
		int u = que.front(); que.pop();
		if (ptstype[u] & 2) continue;
		for (edge &e : G[u]) {
			if (!used[e.to]) {
				used[e.to] = true;
				que.push(e.to);
			}
		}
	}
	vector<bool> pass(pts.size());
	vector<bool> usededge(cnt);
	que.push(srcptr);
	pass[srcptr] = true;
	while (!que.empty()) {
		int u = que.front(); que.pop();
		if ((ptstype[u] & 2) && used[u]) continue;
		for (edge& e : G[u]) {
			usededge[e.id] = true;
			if (!pass[e.to]) {
				pass[e.to] = true;
				que.push(e.to);
			}
		}
	}
	if (pass[dstptr]) cout << -1 << endl;
	else {
		double sum = 0.0;
		for (int i = 0; i < pts.size(); ++i) {
			for (edge e : G[i]) {
				if (!usededge[e.id]) {
					sum += (pts[i] - pts[e.to]).abs();
					usededge[e.id] = true;
				}
			}
		}
		cout.precision(15);
		cout << fixed << sum << endl;
	}
	return 0;
}

