#include <stdio.h>
#include <stdlib.h>

typedef int ElemType;

typedef struct DNode {
    ElemType data;
    struct DNode *prior, *next;
} DNode, *DLinkList;

// 初始化方式一：因为带头节点， LinkList 声明后需要先初始化
int InitDLinkList(DLinkList *L) {
    *L = (DNode *)malloc(sizeof(DNode));
    if (L == NULL) {
        printf("申请L失败\n");
        exit(1);
        return 0;
    }
    (*L)->data = 0;
    (*L)->next = NULL;

    (*L)->prior = NULL; // 头节点的prior永远指向NULL
    (*L)->next = NULL;  // 刚初始化之后暂时还没next节点
    return 1;
}

// 初始化方式二：直接生成一个 LinkList
DLinkList NewList() {
    DLinkList L = (DNode *)malloc(sizeof(DNode));
    if (L == NULL) {
        printf("申请L失败\n");
        exit(1);
        return 0;
    }

    L->data = 0;
    L->next = NULL;

    L->prior = NULL; // 头节点的prior永远指向NULL
    L->next = NULL;  // 刚初始化之后暂时还没next节点
    return L;
}

void Dsiplay(DLinkList L) {
    if (L == NULL) {
        printf("数据结构为NULL\n");
        return;
    }

    printf("{ ");

    DNode *p = L;
    int j = 0;
    while (p != NULL) {
        p = p->next;
        if (p != NULL) {
            printf("%d ", p->data);
        }
        j++;
    }
    printf("}\n");
}

int IsEmpty(DLinkList L) {
    if (L->next == NULL) {
        printf("为空链表\n");
        return 1;
    }
    printf("链表不为空\n");
    return 0;
}

// 删除p的后继节点
int DeleteNextNode(DNode *p) {
    if (p == NULL) {
        printf("节点参数为空\n");
        return 0;
    }

    DNode *q = p->next; // 找到p的后继节点
    if (q == NULL) {
        printf("p没有后继节点\n");
        return 0;
    }
    p->next = q->next;
    if (q->next != NULL) {
        q->next->prior = p;
    }
    free(q);
    return 1;
}

void DestroyList(DLinkList *L) {
    while ((*L)->next != NULL) {
        DeleteNextNode(*L);
    }
    free(*L);
    L = NULL; // 头指针指向NULL
}

// 后插操作：在节点p之后插入节点s
// 通过后插操作，可以轻松实现按位序插入，前插操作
int InsertNextDNode(DNode *p, DNode *s) {
    if (p == NULL || s == NULL) {
        printf("传入节点参数为空\n");
        return 0;
    }

    s->next = p->next;
    if (p->next != NULL) {
        p->next->prior = s;
    }

    s->prior = p;
    p->next = s;
    return 1;
}

