/**
 * Convert binary string to decimal number.
 * @param binary the binary string.
 * @return decimal number.
 */
int toBinary(char *binary) {
    int sum = 0;
    bool isNegative = binary[0] == '-';
    int k = isNegative ? (int) strlen(binary) - 1 : (int) strlen(binary);
    for (int i = isNegative ? 1 : 0; binary[i] != '\0'; ++i) {
        --k;
        int power = 1;
        for (int j = 1; j <= k; j++) {
            power *= 2;
        }
        sum += (binary[i] - '0') * power;
    }
    return isNegative ? -sum : sum;
}

void test() {
    assert(0 == toBinary("0"));
    assert(1 == toBinary("1"));
    assert(10 == toBinary("1010"));
    assert(-29 == toBinary("-11101"));
}

int main() {
    test();
    return 0;
}

class Solution:
    def removeDuplicates(self, nums: List[int]) -> int:
        length = len(nums)
        if length < 2: return length
        slow = 2
        for fast in range(2, length):
            if nums[slow - 2] != nums[fast]:
                nums[slow] = nums[fast]
                slow += 1
        return slow

class Solution {
    static ArrayList<Integer> topologicalSort(ArrayList<ArrayList<Integer>> adj) {
        int n = adj.size();
        Queue<Integer> q = new LinkedList<>();
        int indegree[] = new int[n];
        ArrayList<Integer> list = new ArrayList<>(n);

        for(int i=0;i<n;i++) {
            for(Integer idx : adj.get(i)) indegree[idx]++;
        }

        for(int i=0;i<n;i++) if(indegree[i] == 0) q.add(i);

        while(!q.isEmpty()) {
            int idx = q.poll();
            list.add(idx);
            for(Integer i2 : adj.get(idx)) {
                indegree[i2]--;
                if(indegree[i2] == 0) q.add(i2);
            }
        }

        return list;
    }
}

