#define repeat_from(i,m,n) for (int i = (m); (i) < (n); ++(i))
#define repeat(i,n) repeat_from(i,0,n)
using namespace std;
uint64_t pack(vector<deque<char> > const & s) {
    uint64_t t = 0;
    repeat (i, s.size()) {
        t *= 27;
        for (char c : s[i]) {
            t *= 27;
            t += c - 'a' + 1;
        }
    }
    return t;
}
enum we_t { W, E };
template <typename It>
void step(vector<deque<char> > const & s, map<pair<int,we_t>,vector<pair<int,we_t> > > const & g, It it) {
    int x = s.size();
    repeat (i,x) {
        repeat_from (n,1,s[i].size()+1) {
            for (we_t p : { W, E }) {
                auto v = make_pair(i,p);
                for (auto w : g.at(v)) {
                    int j = w.first;
                    vector<deque<char> > t = s;
                    queue<char> u;
                    repeat (k,n) {
                        if (v.second == W) {
                            u.push(t[i].front());
                            t[i].pop_front();
                        } else {
                            u.push(t[i].back());
                            t[i].pop_back();
                        }
                    }
                    repeat (k,n) {
                        if (w.second == W) {
                            t[j].push_front(u.front());
                        } else {
                            t[j].push_back(u.front());
                        }
                        u.pop();
                    }
                    *(it ++) = t;
                }
            }
        }
    }
}
map<vector<deque<char> >,int> steps(vector<deque<char> > const & s, map<pair<int,we_t>,vector<pair<int,we_t> > > const & g, int n) {
    map<vector<deque<char> >,int> ms;
    ms[s] = 0;
    vector<vector<deque<char> > > vs;
    vs.push_back(s);
    repeat (i,n) {
        vector<vector<deque<char> > > ws;
        for (auto it : vs) {
            step(it, g, back_inserter(ws));
        }
        vs.clear();
        for (auto it : ws) {
            if (not ms.count(it)) {
                ms[it] = i+1;
                vs.push_back(it);
            }
        }
    }
    return ms;
}
int main() {
    while (true) {
        int x, y; cin >> x >> y;
        if (x == 0 and y == 0) break;
        map<pair<int,we_t>,vector<pair<int,we_t> > > g;
        repeat (i,x) for (we_t j : { W, E }) g[make_pair(i,j)];
        repeat (i,y) {
            char p, P, q, Q; cin >> p >> P >> q >> Q;
            auto a = make_pair(p - '0', P == 'W' ? W : E);
            auto b = make_pair(q - '0', Q == 'W' ? W : E);
            g[a].push_back(b);
            g[b].push_back(a);
        }
        vector<deque<char> > s(x); repeat (i,x) { string a; cin >> a; if (a == "-") a.clear(); s[i] = deque<char>(a.begin(), a.end()); }
        vector<deque<char> > t(x); repeat (i,x) { string a; cin >> a; if (a == "-") a.clear(); t[i] = deque<char>(a.begin(), a.end()); }
        map<vector<deque<char> >,int> s2 = steps(s, g, 2);
        map<vector<deque<char> >,int> t2 = steps(t, g, 2);
        unordered_map<uint64_t,int> t2h;
        for (auto it : t2) t2h[pack(it.first)] = it.second;
        int result = 6;
        for (auto it : s2) {
            uint64_t ha = pack(it.first);
            if (t2h.count(ha)) {
                result = min(result, it.second + t2h[ha]);
            }
            if (it.second == 2) {
                vector<vector<deque<char> > > s3;
                step(it.first, g, back_inserter(s3));
                for (auto that : s3) {
                    uint64_t hb = pack(that);
                    if (t2h.count(hb)) {
                        result = min(result, 1 + it.second + t2h[hb]);
                    }
                }
            }
        }
        cout << result << endl;
    }
    return 0;
}

public class FibonacciNumber {

    // fibonacci function return the nth fibonacci no for all n>0
    public static int fibonacci(int n) {
        if (n == 1 || n == 2) {
            return (n - 1);
        } else {
            // Store second last fibonacci number
            int a = 0;
            // Store last fibonacci number
            int b = 1;
            // Store current fibonacci number which is sum of last and second last fibonacci no
            int fib = 0;
            for (int i = 2; i < n; i++) {
                fib = a + b;
                a = b;
                b = fib;
            }
            return (fib);
        }
    }

    public static void main(String[] args) {
        // n>0
        int n = 5;
        if (n <= 0) {
            System.out.println("n must be greater than 0");
            return;
        }
        System.out.println(fibonacci(n));
    }
}

#include <bits/stdc++.h>
 
using namespace std;
 
#define MAX_H 61
#define MAX_W 31
#define INF 1e9
#define Fi first
#define Se second
typedef pair<int,int> pii;
 
struct State{
    int d,lx,ly,rx,ry;
    bool f;
    State(){}
    State(int d,int lx,int ly,int rx,int ry,bool f) :
	d(d),lx(lx),ly(ly),rx(rx),ry(ry),f(f) {}
    bool operator > (const State &s)const{
	return d > s.d;
    }
};
 
int W,H;
int ps,pt;
pii S[MAX_W],T[MAX_W];
char field[MAX_H][MAX_W];
int dist[MAX_H][MAX_W][MAX_H][MAX_W][2];
 
const int dx[9] = {1,1,1,1,1,2,2,2,3};
const int dy[9] = {-2,-1,0,1,2,-1,0,1,0};
 
bool inField(int x,int y){
    return 0 <= x && x < W && 0 <= y && y < H;
}
 
int dijkstra(){
    priority_queue<State,vector<State>,greater<State> > Q;
    fill(dist[0][0][0][0],dist[0][0][0][0]+MAX_H*MAX_W*MAX_H*MAX_W*2,INF);
    for(int i = 0 ; i < ps ; i++){
	Q.push(State(0,S[i].Fi,S[i].Se,W,H,0)); 
	Q.push(State(0,W,H,S[i].Fi,S[i].Se,1));
	dist[S[i].Se][S[i].Fi][H][W][0] = 0;
	dist[H][W][S[i].Se][S[i].Fi][1] = 0;
    }
 
    while(!Q.empty()){
	State s = Q.top(); Q.pop();
	int lx = s.lx, ly = s.ly;
	int rx = s.rx, ry = s.ry;
 
	if(dist[ly][lx][ry][rx][s.f] < s.d) continue;
	for(int i = 0 ; i < pt ; i++){
	    if(lx == T[i].Fi && ly == T[i].Se ||
	       rx == T[i].Fi && ry == T[i].Se){
		return s.d;
	    }
	}
	if(s.f){
	    for(int i = 0 ; i < 9 ; i++){
		int nlx = rx - dx[i];
		int nly = ry + dy[i];
		if(!inField(nlx,nly)) continue;
		if(field[nly][nlx] == 'X') continue;
		int t = field[nly][nlx] - '0';
		if(s.d + t < dist[nly][nlx][ry][rx][0]){
		    dist[nly][nlx][ry][rx][0] = s.d + t;
		    Q.push(State(dist[nly][nlx][ry][rx][0],nlx,nly,rx,ry,0));
		}
	    }
	}else{
	    for(int i = 0 ; i < 9 ; i++){
		int nrx = lx + dx[i];
		int nry = ly + dy[i];
		if(!inField(nrx,nry)) continue;
		if(field[nry][nrx] == 'X') continue;
		int t = field[nry][nrx] - '0';
		if(s.d + t < dist[ly][lx][nry][nrx][1]){
		    dist[ly][lx][nry][nrx][1] = s.d + t;
		    Q.push(State(dist[ly][lx][nry][nrx][1],lx,ly,nrx,nry,1));
		}
	    }
	}
    }
    return -1;
}
 
int main(){
    dijkstra();
    while(cin >> W >> H, W){
	ps = pt = 0;
	for(int i = 0 ; i < H ; i++){
	    for(int j = 0 ; j < W ; j++){
		cin >> field[i][j];
		if(field[i][j] == 'S'){
		    S[ps++] = pii(j,i);
		    field[i][j] = '0';
		}else if(field[i][j] == 'T'){
		    T[pt++] = pii(j,i);
		    field[i][j] = '0';      
		}
	    }
	}
	cout << dijkstra() << endl;
    }
    return 0;
}

