#include <iostream>

using namespace std;

typedef long long ll;

const int MOD = 1e9 + 7; // change if needed

struct Modint {
  ll val;
  
  Modint (ll _val = 0)
    : val(_val % MOD) {}

  Modint operator+ (Modint other) const {
    return Modint(val + other.val);
  }

  void operator+= (Modint other) {
    val += other.val;
    val %= MOD;
  }

  Modint operator- () const {
    return Modint(MOD - val);
  }

  Modint operator- (Modint other) const {
    return Modint(val + MOD - other.val);
  }

  void operator-= (Modint other) {
    val += MOD - other.val;
    val %= MOD;
  }

  Modint operator* (Modint other) const {
    return Modint(val * other.val);
  }

  void operator*= (Modint other) {
    val *= other.val;
    val %= MOD;
  }

  bool operator== (Modint other) const {
    return val == other.val;
  }

  bool operator!= (Modint other) const {
    return val != other.val;
  }
};

Modint exp (Modint a, ll k) {
  if (k == 0) {
    return Modint(1);
  } else if (k % 2 == 0) {
    Modint half = exp(a, k / 2);
    return half * half;
  } else {
    return a * exp(a, k - 1);
  }
}

Modint inv (Modint a) {
  return exp(a, MOD - 2);
}

ostream& operator<< (ostream& out, Modint p) {
  out << p.val;
  return out;
}

typedef long long ll;

ll gcd (ll p, ll q) {
  if (q == 0) return p;
  return gcd(q, p % q);
}

int main () {
  ll h, w, t;
  cin >> h >> w >> t;

  ll ex = gcd(t, h) * gcd(t, w); // # of independent cases
  h /= gcd(t, h);
  w /= gcd(t, w);

  ll clc = gcd(h, w);
  Modint ans = exp(Modint(2), clc) - Modint(2); // in these cases only one possibility
  ans += exp(Modint(2), h);
  ans += exp(Modint(2), w);
  ans -= Modint(1);

  ans = exp(ans, ex);
  cout << ans << endl;
}

#include <stdio.h>

void printArray(int *array, int size) {
    for (int i = 0; i < size; i++) {
        printf("%d ", array[i]);
    }
    printf("\n");
}

int partition(int array[], int low, int high) {
    int pivot = array[low];  
    int left = low + 1;      
    int right = high;        
    int temp;

    do {
        // Move left pointer rightward until an element greater than pivot is found
        while (array[left] <= pivot && left <= high) {
            left++;
        }

        // Move right pointer leftward until an element less than or equal to pivot is found
        while (array[right] > pivot && right >= low) {
            right--;
        }

        // If left is still less than right, swap the elements
        if (left < right) {
            temp = array[left];
            array[left] = array[right];
            array[right] = temp;
        }
    } while (left < right);

    // Swap the pivot element with the element at the right pointer
    temp = array[low];
    array[low] = array[right];
    array[right] = temp;

    // Return the index where the pivot is located after partition
    return right;
}

void quickSort(int array[], int low, int high) {
    if (low < high) {
        int partitionIndex = partition(array, low, high); 

        // Recursively sort the left and right subarrays
        quickSort(array, low, partitionIndex - 1);  
        quickSort(array, partitionIndex + 1, high); 
    }
}

int main() {
    int array[] = {78, 45, 90, 12, 34, 70, 43, 56, 88, 9};
    int size = 10;

    printArray(array, size);
    quickSort(array, 0, size - 1);  
    printArray(array, size);

    return 0;
}

