        if (arr[j] < pivot){
            i++;    // increment index of smaller element
            
            int tmp = arr[i];
            arr[i] = arr[j];
            arr[j] = tmp;
        }
    }
    int tmp = arr[i+1];
    arr[i+1] = arr[high];
    arr[high] = tmp;
    
    return (i + 1);
}

void quickSort(int arr[],int low,int high){
    int pi;
    
    if (low < high){

        pi = partition(arr, low, high);

        quickSort(arr, low, pi - 1);
        quickSort(arr, pi + 1, high);
    }
}

