void quicksort (int a[], int low, int high){
    int x, y, p, temp ;
    x = low ;
    y = high ;
    p = a[(x+y)/2] ;
    do{
        while (a[x] < p) x++ ;
        while (a[y] > p) y-- ;
        if (x <= y){
            temp = a[x] ;
            a[x] = a[y] ;
            a[y] = temp ;
            x++ ;
            y-- ;
        }
    }while (x <= y) ;
    if (low < y) quicksort (a, low, y) ;
    if (x < high) quicksort (a, x, high) ;
}
