class Solution:
    def deleteDuplicates(self, head: Optional[ListNode]) -> Optional[ListNode]:
        dummyNode = ListNode("$", head)
        sortedNode = dummyNode
        while sortedNode.next:
            if sortedNode.val == sortedNode.next.val:
                sortedNode.next = sortedNode.next.next
