/* THUẬT TOÁN: -> ĐỆ QUY: O(log(min(a, b))) | O(1)
 | - Công thức: gcd(a, b) = gcd(b, a % b).
 | - Nếu b = 0, trả về a.
 */

int gcd(int a, int b)
{
    if (b == 0)
    {
        return a;
    }
    return gcd(b, a % b);
}

int main()
{
