#define MAX 100
char stack[MAX];
int top = -1;

void push(char ch){
    if(top == MAX - 1){
        return;
    }
    top = top + 1;
    stack[top] = ch;
}

char pop(){
    if(top == -1){
        return '\0';
    }
    char ch = stack[top];
    top = top - 1;
    return ch;
}

