int reduction( int A[] , int BEG , int END )
{
	int LEFT , RIGHT , TEMP , LOC;
	LEFT = LOC = BEG;
	RIGHT = END;
	while( 1 )
	{
		while( A[LOC] <= A[RIGHT] && LOC != RIGHT )
		{
			RIGHT = RIGHT - 1 ;
		}
		if( LOC == RIGHT )
		{
			break;
		}		
		if( A[LOC] > A[RIGHT] )
		{
			TEMP = A[LOC];
			A[LOC] = A[RIGHT];
			A[RIGHT] = TEMP;
			LOC = RIGHT;
		}
		while( A[LEFT] <= A[LOC] && LOC != LEFT )
		{
			LEFT = LEFT + 1 ;
		}
		if( LOC == LEFT )
		{
			break;
		}		
		if( A[LEFT] > A[LOC] )
		{
			TEMP = A[LOC];
			A[LOC] = A[LEFT];
			A[LEFT] = TEMP;
			LOC = LEFT;
		}
	}
	return LOC;
}
void quick_sort( int A[] , int BEG , int END )
{
	int  LOC;
	LOC = reduction( A , BEG , END );
	if( BEG < LOC - 1 )
	{
		quick_sort( A , BEG , LOC - 1);
	}
	if( LOC + 1 < END )
	{
		quick_sort( A , LOC + 1 , END );
	}		
}
