        int next = G[i][j].dst;
        int cost = G[i][j].area;
        double length = G[i][j].length;
        if( area + cost < LIMIT && LT(dp[i][area]+length,dp[next][area+cost]) ) {
          dp[next][area+cost] = dp[i][area]+length;
        }
      }
