Vec dijkstra(int v){

    Vec ret_val(n,INF);
    ret_val[v] = 0;
    priority_queue<Edge,Edges,Compare> pq;
    pq.push(Edge(0,v));

    while(!pq.empty()){
        Edge e = pq.top();
        pq.pop();
        int to = e.to;
        int w = e.w;

        if(ret_val[to] < w) continue;

        for(auto a = G[to].begin();a != G[to].end();++a){
            if(w + a->w < ret_val[a->to]){
                ret_val[a->to] = w + a->w;
                pq.push(Edge(w + a->w,a->to));
            }
        }
    }

    return ret_val;
}

