LL dfs(int f, LL num){
    if(num <= 0) return 0;
    LL ans = 0;
    if(dp[f] <= num) return dp2[f];

    ans += dfs(f - 1, min(num, dp[f] / 2 + 1) - 1);
    if(num > dp[f] / 2) {
        ans += 1;
        ans += dfs(f - 1, num - (dp[f] / 2) - 1);
    }
    return ans;
}

