void main()
{
    int choice, value; // choice for menu, value for push
    printf("\n:: Stack using Linked List ::\n");
    while (1)
    {
        printf("\n****** MENU ******\n");
        printf("1. Push\n2. Pop\n3. Display\n4. Exit\n");
        printf("Enter your choice: ");
        scanf("%d", &choice);
        switch (choice)
        {
        case 1: // Push
            printf("Enter the value to be insert: ");
            scanf("%d", &value);
            push(value);
            break;
        case 2: // Pop
            pop();
            break;
        case 3: // Display
            display();
            break;
        case 4:
            exit(0);
        default:
            printf("\nWrong selection!!! Please try again!!!\n");
        }
    }
}
void push(int value)
{
    struct Node *newNode;                                 // New node for linked list
    newNode = (struct Node *)malloc(sizeof(struct Node)); // Allocate memory for new node
    newNode->data = value;                                // Assign value to new node
    if (top == NULL)
        newNode->next = NULL;
    else
        newNode->next = top;
    top = newNode;
    printf("\nInsertion is Success!!!\n");
}
void pop()
{
    if (top == NULL)
        printf("\nStack is Empty!!!\n");
    else
    {
        struct Node *temp = top;
        printf("\nDeleted element: %d", temp->data);
        top = temp->next;
        free(temp);
    }
}
void display()
{
    if (top == NULL)
        printf("\nStack is Empty!!!\n");
    else
    {
        struct Node *temp = top;
        while (temp->next != NULL)
        {
            printf("%d--->", temp->data);
            temp = temp->next;
        }
        printf("%d--->NULL", temp->data);
    }
}

// Given a singly linked list and a position, delete a linked list node with the given key

class LinkedList
{
    Node head;  // head of list

    /* Linked list Node*/
    class Node
    {
        int data;
        Node next;

        // Constructor to create a new node
        // Next is by default initialized
        // as null
        Node(int d) {
            data = d;
            next=null;
        }
    }
    // Insert a new node at front
    public void insertNode(int item){
        Node node = new Node(item);
        node.next = head;
        head = node; // move the head to point the next node
    }
    public void print(){
        Node node = head;
        while(node!=null){
            System.out.print(node.data + " -> ");
            node = node.next;
        }
        System.out.println("null");
    }
    public void deleteNode(int key){
        Node temp = head;
        Node prev = null;
        if(temp != null && temp.data == key){
            head = temp.next;
            return;
        }
        //keep track of prev node inorder to delete temp.next
        while(temp != null && temp.data != key){
            prev = temp;
            temp = temp.next;
        }
        if(temp == null) return; //key not present :(
        prev.next = temp.next; //unlink the node
    }
    public static void main(String args[]){
        LinkedList llist = new LinkedList();
        for(int i=5;i>0;--i){
            llist.insertNode(i);
        }
        System.out.println("Linked list - ");
        llist.print();
        llist.deleteNode(3); //Delete node at position 3
        System.out.println("After deletion - ");
        llist.print();
    }
}

