constexpr ll INF = (1LL << 30) - 1LL;
constexpr ll LINF = (1LL << 60) - 1LL;
constexpr ll MOD = 1e9 + 7;
template <typename T> void chmin(T &a, T b) { a = min(a, b); }
template <typename T> void chmax(T &a, T b) { a = max(a, b); }
int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    int n, m;
    cin >> n >> m;
    vector<int> a(n), r(m), b(m);
    int asum = 0;
    for (int i = 0; i < n; i++) {
        cin >> a[i];
        asum += a[i];
    }
    int rsum = 0, bsum = 0;
    for (int i = 0; i < m; i++) {
        cin >> r[i];
        rsum += r[i];
    }
    for (int i = 0; i < m; i++) {
        cin >> b[i];
        bsum += b[i];
    }
    sort(all(a));
    sort(all(r));
    sort(all(b));
    reverse(all(a));
    reverse(all(r));
    reverse(all(b));
    vector<vector<vector<int>>> dp(
        n + 1, vector<vector<int>>(m + 1, vector<int>(50 * (n + 1), INF)));
    dp[0][0][0] = 0;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j <= m; j++) {
            for (int k = 0; k <= 50 * (i + 1); k++) {
                if (i >= j && i - j < m) {
                    chmin(dp[i + 1][j][k],
                          dp[i][j][k] + max(0, a[i] - b[i - j]));
                }
                if (j > 0 && k >= a[i]) {
                    chmin(dp[i + 1][j][k],
                          dp[i][j - 1][k - a[i]] + max(0, a[i] - r[j - 1]));
                }
            }
        }
    }
    int res = INF;
    for (int j = 0; j <= m; j++) {
        for (int k = 0; k <= 50 * n; k++) {
            if (k <= rsum && asum - k <= bsum) {
                chmin(res, dp[n][j][k]);
            }
        }
    }
    if (res == INF) {
        cout << -1 << endl;
        return 0;
    }
    cout << res << endl;
}

function generateTrianglesFromInput(input) {
  var maxLines = 1000;
  var offset = 1;

  var lines = getInputAsLines(input, "\n");
  var vertices = lines.map(processLineToVertices);
  var limit = (vertices.length < maxLines) ? vertices.length : maxLines;

  for(var i = offset; i <= limit; i++) {
    var vertexLine = vertices[i];
    if(vertexLine && vertexLine.length === 3) {
      var tri = new Triangle({
        constraints: {
          min: 1,
          max: 1000
        },
        vertices: {
          a: vertexLine[0],
          b: vertexLine[1],
          c: vertexLine[2]
        }
      });

      var isRightAngleTriangle = tri.isRightAngleTriangle();
      var logValue = (isRightAngleTriangle) ? 'YES' : 'NO';
      console.log(logValue);
    }
  }
}

function getInputAsLines(input, delimeter) {
  return input.split(delimeter);
}

function processLineToVertices(line) {
  var vertices = line.split(' ');
  return vertices;
}


//Triangle
function Triangle(options) {

  this.constraints = {};
  this.vertices = {};

  //Set up triangle constraints.
  this.constraints.min = options.constraints.min || 1;
  this.constraints.max = options.constraints.max || 1000;

  //Set up triangle vertices
  this.vertices.a = (this.vertexIsWithinConstraints(options.vertices.a)) ? options.vertices.a : null;
  this.vertices.b = (this.vertexIsWithinConstraints(options.vertices.b)) ? options.vertices.b : null;
  this.vertices.c = (this.vertexIsWithinConstraints(options.vertices.c)) ? options.vertices.c : null;

}

Triangle.prototype.vertexIsWithinConstraints = function(vertex) {
  return (vertex >= this.constraints.min && vertex <= this.constraints.max);
}

Triangle.prototype.isRightAngleTriangle = function() {
  var value = false;
  if(this.vertices.a && this.vertices.b && this.vertices.c) {
    var vertexArray = [];
    vertexArray.push(this.vertices.a);
    vertexArray.push(this.vertices.b);
    vertexArray.push(this.vertices.c);

    vertexArray.sort();

    var squares = vertexArray.map((vertex) => Math.pow(vertex, 2));
    value = (squares[2] === (squares[0] + squares[1]));
  }

  return value;
}

