void ins(int a[], int n)
{

    int i, j, x;

    for (i = 1; i < n; i++)
    {
        j = i - 1;
        x = a[i];

        while (j > -1 && a[j] > x)
        {
            a[j + 1] = a[j];

            j--;
        }

        a[j + 1] = x;
    }
}
