parsed fact(const string& s,int i,vector<parsed>& memo)
{
	if(memo[i]!=parsed(-1,-1,-1)) return memo[i];
	auto& res=memo[i];
	int t,f;
	if(s[i]=='~'){
		tie(t,f,i)=fact(s,i+1,memo);
		swap(t,f);
	}
	else if(s[i]=='('){
		tie(t,f,i)=expr(s,i+1,memo);
		i++;
	}
	else{
