parsed term(const string& s,int i,vector<parsed>& memo)
{
	//if(memo[i]!=parsed(-1,-1,-1)) return memo[i];
	auto& res=memo[i];
	int t,f; tie(t,f,i)=fact(s,i,memo);
	while(i<s.size() && s[i]=='&'){
		int t2,f2; tie(t2,f2,i)=fact(s,i+1,memo);
		ll sum=ll(t+f)*ll(t2+f2);
		tie(t,f)=mp(ll(t)*t2%MOD,(sum-ll(t)*t2)%MOD);
	}
	return res=parsed(t,f,i);
}

parsed expr(const string& s,int i,vector<parsed>& memo)
{
