inline void merge(int left, int mid, int right)
{
    int h,i,j,k;
    h = left;
    i = left;
    j = mid+1;
    while (h <= mid && j <= right)
    {
        if (niz[h] <= niz[j])
        {
            tmp[i] = niz[h];
            h++;
        }
        else
        {
            tmp[i] = niz[j];
            j++;
        }
        i++;
    }
    if (h > mid)
    {
        for(k=j;k<=right;k++)
        {
            tmp[i] = niz[k];
            i++;
        }    
    }
    else
    {
        for(k=h;k<=mid;k++)
        {
            tmp[i] = niz[k];
            i++;
        }
    }
    for(k=left;k<=right;k++) niz[k] = tmp[k];
}

void mergeSort(int left, int right)
{
    if (left == right) return;
    int MID = (left+right)/2;
    mergeSort(left, MID);
    mergeSort(MID+1, right);
    merge(left, MID, right);
}

