const int N=2e5+10;
const int M=1e7;
typedef long long ll;
struct edge{
	int u,v;ll val;
	inline bool operator <(const edge B)const{
		return val<B.val;
	}
}E[M];int cur=0;
int fa[N];
ll w[N];
int n,m;
struct Edge{
	int to,next;ll w;
}a[N<<1];
int head[N],cnt=0;
inline void add(int x,int y,ll w){a[++cnt]=(Edge){y,head[x],w};head[x]=cnt;}
int size[N],f[N];
bool vis[N];
int RT,SZ;
void Find(int u,int fa){
	size[u]=1,f[u]=0;
	for(int v,i=head[u];i;i=a[i].next){
		v=a[i].to;if(v==fa||vis[v]) continue;
		Find(v,u);
		f[u]=max(f[u],size[v]);size[u]+=size[v];
	}
	f[u]=max(f[u],SZ-size[u]);
	if((!RT)||f[RT]>f[u]) RT=u;
	return;
}
typedef pair<ll,int> PA;
PA Dis[N];int top=0;
PA Mi;
void Dfs(int u,int fa,ll dis){
	Dis[++top]=PA(dis+w[u],u);
	if(Mi>Dis[top]) Mi=Dis[top];
	for(int v,i=head[u];i;i=a[i].next){
		v=a[i].to;if(vis[v]||v==fa) continue;
		Dfs(v,u,dis+a[i].w);
	}
	return;
}
int dep=0,mx=0;
void Divide(int u){
	vis[u]=1;top=0;Mi=PA(w[u],u);
	++dep;mx=max(dep,mx);
	int L=0,R=0;
	for(int v,i=head[u];i;i=a[i].next){
		v=a[i].to;if(vis[v]) continue;
		L=top;PA now=Mi;
		Dfs(v,u,a[i].w);if(now!=Mi) R=top;
	}
	if(!R) {
		int U=Mi.second;ll val=Mi.first;
		for(int i=1;i<=top;++i) {
			int V=Dis[i].second;
			E[++cur]=(edge){U,V,val+Dis[i].first};
		}
	}
	else {
		E[++cur]=(edge){u,Mi.second,Mi.first+w[u]};
		int U=Mi.second;ll val=Mi.first;
		for(int i=1;i<=top;++i) {
			if(i>L&&i<=R) continue;
			int V=Dis[i].second;
			E[++cur]=(edge){U,V,val+Dis[i].first};
		}
	}
	for(int v,i=head[u];i;i=a[i].next){
		v=a[i].to;if(vis[v]) continue;
		RT=0;SZ=size[v];Find(v,u);
		Divide(RT);
	}
	--dep;
	return;
}
int find(int x){return fa[x]==x? x:fa[x]=find(fa[x]);}
