string rec(int A, int L) {
    if (L <= 0) {
        assert(A == 0);
        return "";
    }

    int D;
    for (D = 0; D * (D + 1) / 2 < A; ++D) {}

    string ret;
    for (int i = 0; i < L - D; ++i) ret += "()";
    return ret + ')' + rec(A - D, D - 1) + '(';
}

