int64 rec(int sy, int sx)
{
  if(sy >= H && sx >= W) return (-INF);
  if(~dp[sy][sx]) return (dp[sy][sx]);
  int64 ret = rec2(sy, sx, H - 1, W - 1);
  for(int i = sy; i < H; i++) {
    for(int j = sx; j < W; j++) {
      if((isdigit(S[i][j]))) {
        if(i + 2 < H && S[i + 1][j] == '+') {
          auto x = rec2(sy, sx, i, j);
          auto y = rec(i + 2, j);
          if(x >= 0 && y >= 0) ret = max(ret, x + y);
        }
 
        if(j + 2 < W && S[i][j + 1] == '+') {
          auto x = rec2(sy, sx, i, j);
          auto y = rec(i, j + 2);
          if(x >= 0 && y >= 0) ret = max(ret, x + y);
        }
 
        if((i + 1 < H && S[i + 1][j] == '+') &&
           (j + 1 < W && S[i][j + 1] == '+')) {
          if(i + 1 < H && j + 1 < W) {
            auto x = rec2(sy, sx, i, j);
            auto y = rec(i + 1, j + 1);
            if(x >= 0 && y >= 0) ret = max(ret, x + y);
          }
        }
      }
    }
  }
  return (dp[sy][sx] = min(INF, ret));
}
 
