inline int b_search(int left, int right, int x)
{
    int i = left;
    int j = right;
    while (i < j)
    {
        int mid = (i+j)/2;
        if (niz[mid] == x) return mid;
        if (niz[mid] < x) i = mid+1;
        else j = mid-1;
    }
    if (niz[i] == x) return i;
    return -1;
}

