                bool fd = false;
                string ans(m, '^');
                for (int j = m - 1; j >= 0; --j) {
                    fd |= (ed[j].first == i || ed[j].second == i);
                    if (!fd) continue;
                    if (!ok[ed[j].first] && !ok[ed[j].second]) continue;
                    if (ok[ed[j].first] && ok[ed[j].second]) continue;
                    if (ok[ed[j].second]) ans[j] = 'v';
