        vector<int> dest(n), cnt(n);
        for (int i = 0; i < n; ++i) dest[i] = i, cnt[i] = 1;
        string ans(m, '^');
        for (int i = m - 1; i >= 0; --i) {
            if (dest[ed[i].first] == dest[ed[i].second]) continue;
            if (cnt[dest[ed[i].second]] == n - 1) {
                --cnt[dest[ed[i].second]];
                dest[ed[i].second] = dest[ed[i].first];
                ++cnt[dest[ed[i].second]];
