bool is_tree_empty(tree *t)
{
    return t->size == 0;
}

tree* init_tree()
{
    tree *t = (tree*)malloc(sizeof(tree));
    t->root = NULL;
    t->size = 0;
    return t;
}

void insert(tree *t,int val,int node_id)
{
    tree_node *tn = (tree_node*)malloc(sizeof(tree_node));
    tn->data = val;
    tn->node_id = node_id;
    tn->lchild = tn->rchild = NULL;
    if(is_tree_empty(t))
    {
        t->root = tn;
        t->size++;
        return ;
    }
    tree_node *root = t->root;
    while(1)
    {
        if(node_id > root->node_id)
        {
            if(root->rchild == NULL)
            {
                root->rchild = tn;
                t->size++;
                break;
            }else
                root =  root->rchild;
        }else if(node_id < root->node_id)
        {
            if(root->lchild == NULL)
            {
                root->lchild = tn;
                t->size++;
                break;
            }else
                root = root->lchild;
        }else
            break;
    }
}

// Depth First Traversal 
void traverse_tree(tree_node *root, char s)
{
    if(root == NULL)
        return ;
    if(s == 'f' || s == 'f')
    {
        printf("%d->",root->data);
        traverse_tree(root->lchild,'f');
        traverse_tree(root->rchild,'f');
    }else if(s == 'i' || s == 'I')
    {
        traverse_tree(root->lchild,'i');
        printf("%d->",root->data);
        traverse_tree(root->rchild,'i');
    }else if(s == 'p' || s == 'P')
    {
        traverse_tree(root->lchild,'p');
        traverse_tree(root->rchild,'p');
        printf("%d->",root->data);
    }else
        printf("Invalid Traversal Schema");
}

// Search
int search(tree_node *root,int node_id)
{
    if(node_id == root->node_id)
        return root->data;
    else if(node_id < root->node_id)
        return search(root->lchild,node_id);
    else if(node_id > root->node_id)
        return search(root->rchild,node_id);
    return 0;
}

int main(void)
{
    tree *t = init_tree();
    insert(t,80,8);
    insert(t,20,10);
    insert(t,10,2);
    insert(t,10,1);
    insert(t,90,5);
    insert(t,30,4);
    insert(t,11,6);
    insert(t,40,3);
    traverse_tree(t->root,'f');
    printf("\n%d",search(t->root,4));
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

int n;
/*
堆是完全二叉树，有最大堆和最小堆，其中最大堆是父结点的值比子结点大，
相应的最小堆就是父结点的值比子节点小。

堆排序就是利用了最大堆（或最小堆）堆顶记录的关键字最大（或最小）这一特征，
使得在当前无序区中选取最大（或最小）关键字变得简单。以最大堆为例，它的基本思想就是：

先将初始文件R[1..n]建成一个最大堆，此堆为初始的无序区；
再将关键字最大的记录R[1]（即堆顶）和无序区的最后一个记录R[n]交换，
由此得到新的无序区R[1..n-1]和有序区R[n]，且满足R[1..n-1].keys≤R[n].key；
由于交换后新的根R[1]可能违反堆性质，故应将当前无序区R[1..n-1]调整为堆。
然后再次将R[1..n-1]中关键字最大的记录R[1]和该区间的最后一个记录R[n-1]交换，
由此得到新的无序区R[1..n-2]和有序区R[n-1..n]，且仍满足关系R[1..n-2].keys≤R[n1..n].keys，
同样要将R[1..n-2]调整为堆； 重复此操作直到全部有序。


*/ 
/*
 * 生成堆
 */
void HeapAdjust(int *array, int s, int m)
{
    int i;
    array[0] = array[s];
    for (i = s * 2; i <= m; i *= 2)
    {
        if (i < m && array[i] < array[i + 1])
        {
            i++;
        }
        if (!(array[0] < array[i]))
        {
            break;
        }
        array[s] = array[i];
        s = i;
    }
    array[s] = array[0];
}

/*
 * 堆排序
 */
void HeapSort(int *array)
{
    int i;
    for (i = n / 2; i > 0; i--)
    {
        HeapAdjust(array, i, n);
    }
    for (i = n; i > 1; i--)
    {
        array[0] = array[1];
        array[1] = array[i];
        array[i] = array[0];
        HeapAdjust(array, 1, i - 1);
    }
}

int main()
{
    int i;
    int *array;
    printf("请输入数组的大小：");
    scanf("%d", &n);
    array = (int*) malloc(sizeof(int) * (n + 1));
    printf("请输入数据（用空格分隔）：");
    for (i = 1; i <= n; i++)
    {
        scanf("%d", &array[i]);
    }
    HeapSort(array);
    printf("排序后为：");
    for (i = 1; i <= n; i++)
    {
        printf("%d ", array[i]);
    }
    printf("\n");
}

