{
	int endp, next;
}E[EDGE_COUNT];

int nl, nr, iec, ec = 2;
bool vis[VERTEX_COUNT];

inline void add_edge(int u, int v)
{
	E[ec].next = V[u].first;
	V[u].first = ec;
	E[ec].endp = v;
	ec++;
}

bool dfs(int u)
{
	if (vis[u] == true) return false;
	vis[u] = true;
	for (int cur = V[u].first; cur != 0; cur = E[cur].next)
	{
		if (V[u].mv != E[cur].endp && (V[E[cur].endp].mv == 0 || dfs(V[E[cur].endp].mv) == true))
		{
			V[u].mv = E[cur].endp;
			V[E[cur].endp].mv = u;
			return true;
		}
	}
	return false;
}

int match()
{
	int res = 0;
	for (int i = 1; i <= nl; i++)
	{
		memset(vis, false, sizeof(vis));
		res += (int)dfs(i);
	}
	return res;
}

