      a.push_back(bit ^ bit >> 1);
    }
    for (int bit = 0; bit < 1 << m; ++bit) {
      for (int i = 2; i < m; i += 2) if (bit + (1 << i) >= 1 << m) {
        int x = a[bit] & 1 << i - 2;
        int y = a[bit] & 1 << i - 1;
        a[bit] -= x + y;
        a[bit] += x << 1;
        a[bit] += y >> 1;
        a[bit] ^= (1 << i) - (1 << i - 2);
      }
    }
    return a;
  };
  V<> res;
  bool tg = true;
  if (n - m) for (int e : f(m)) {
    if (tg) {
      for (int bit = 0; bit < 1 << n - m; ++bit) {
        int x = bit ^ bit >> 1;
        res.push_back(e | x << m);
      }
    } else {
      for (int bit = (1 << n - m) - 1; bit >= 0; --bit) {
        int x = bit ^ bit >> 1;
        res.push_back(e | x << m);
      }
    }
    tg ^= true;
  } else res = f(m);
  V<> idx(n);
  iota(begin(idx), end(idx), 0);
  sort(begin(idx), end(idx), [&](int i, int j) { return ((a ^ b) & 1 << i) > ((a ^ b) & 1 << j); });
  for (int i = 0; i < 1 << n; ++i) {
