    res[i] = 0;
    for (int j = 0; j < n; ++j) if (x & 1 << j) {
      res[i] |= 1 << idx[j];
    }
    if (i) assert(__builtin_popcount(res[i] ^ res[i - 1]) == 1);
    // cout << bitset<5>(res[i]) << '\n';
    cout << (a ^ res[i]) << " \n"[i == (1 << n) - 1];
  }
}

