    long long sx = 0;
    long long sy = 0;
    long long cnt = 0;
    for (long long x = 0; x * p <= bound; x++) {
      long long y = (bound - x * p) / q;
      sx += x * (y + 1);
      sy += y * (y + 1) / 2;
      cnt += y + 1;
    }
    return make_tuple(sx, sy, cnt);
  };
  auto Test = [&](long long p, long long q) {
    bool inv = false;
    if (p < q) {
      swap(p, q);
      swap(r, b);
      inv = true;
    }
    long long low = 0, high = 1;
    while (true) {
      auto got = Count(p, q, high);
      if (get<0>(got) * p + get<1>(got) * q > r * p + b * q) {
        break;
      }
      low = high;
      high <<= 1;
    }
    while (low + 1 < high) {
      long long mid = (low + high) >> 1;
      auto got = Count(p, q, mid);
      if (get<0>(got) * p + get<1>(got) * q > r * p + b * q) {
        high = mid;
      } else { 
        low = mid;
      }
    }
    auto got = Count(p, q, low);
    long long sx = get<0>(got);
    long long sy = get<1>(got);
    long long cnt = get<2>(got);
    long long s = sx * p + sy * q;
    long long add = (r * p + b * q - s) / high;
    long long x = 0;
    while ((high - x * p) % q != 0) {
      ++x;
    }
    sx += x * add + q * (add * (add - 1) / 2);
    long long y = (high - x * p) / q;
    while (y >= p) {
      x += q;
      y -= p;
    }
    sy += y * add + p * (add * (add - 1) / 2);
    cnt += add;
    if (sx <= r && sy <= b) {
      cout << cnt - 1 << '\n';
      exit(0);
    }
    bool ret = (sx > r) ^ inv;
    if (inv) {
      swap(r, b);
    }
    return ret;
  };
  long long p0 = 0, q0 = 1;
  long long p1 = 1, q1 = 0;
  while (true) {
    long long low = 0, high = 1;
    while (true) {
      if (!Test(p0 + high * p1, q0 + high * q1)) {
        break;
      }
      low = high;
      high <<= 1;
    }
    while (low + 1 < high) {
      long long mid = (low + high) >> 1;
      if (!Test(p0 + mid * p1, q0 + mid * q1)) {
        high = mid;
      } else {
        low = mid;
      }
    }
    p0 += low * p1;
    q0 += low * q1;
    p1 += p0;
    q1 += q0;
  }
  return 0;
}

