void radix_sort()
{
	static int c[10], _d[ELEMENT_COUNT];
	for (int k = 0; k < 8; k++)
	{
		for (int i = 0; i < 10; i++)
		{
			c[i] = 0;
		}
		for (int i = 0; i < n; i++)
		{
			c[d[i] / pow10[k] % 10]++;
		}
		for (int i = 1; i < 10; i++)
		{
			c[i] += c[i - 1];
		}
		for (int i = n - 1; i >= 0; i--)
		{
			_d[--c[d[i] / pow10[k] % 10]] = d[i];
		}
		for (int i = 0; i < n; i++)
		{
			d[i] = _d[i];
		}
	}
}

