using Graph = vector<vector<int>>;
int N;
Graph G;
Graph CC;
Graph dp;
vector<int> fac(200010);
int count0(int now, int p = -1) {
    int s = G[now].size();
    CC[now].assign(s, -1);
    int res = 0;
    rep(i, s) {
        int to = G[now][i];
        if(to == p) continue;
        CC[now][i] = count0(to, now);
        res += CC[now][i];
    }
    return res + 1;
}
void count1(int now, int pval = 0, int p = -1) {
    int s = G[now].size();
    rep(i, s) {
        if(G[now][i] == p) CC[now][i] = pval;
    }
    int sum = pval + 1;
    rep(i, s) {
        if(G[now][i] == p) continue;
        sum += CC[now][i];
    }
    rep(i, s) {
        int to = G[now][i];
        if(to == p) continue;
        count1(to, sum - CC[now][i], now);
    }
}

int rec(int now, int p = -1) {
    int s = G[now].size();
    dp[now].assign(s, -1);
    int res = 1;
    int c = 0;
    rep(i, s) {
        int to = G[now][i];
        if(to == p) continue;
        dp[now][i] = rec(to, now);
        res = (res * dp[now][i]) % mod;
        res = (res * mod_inverse(fac[CC[now][i]], mod)) % mod;
        c += CC[now][i];
    }
    res = (res * fac[c]) % mod;
    return res;
}
void rerec(int now, int pval = 1, int p = -1) {
    int s = G[now].size();
    rep(i, s) {
        if(G[now][i] == p) dp[now][i] = pval;
    }
    int res = 1;
    int c = 0;
    rep(i, s) {
        res = (res * dp[now][i]) % mod;
        res = (res * mod_inverse(fac[CC[now][i]], mod)) % mod;
        c += CC[now][i];
    }
    rep(i, s) {
        int to = G[now][i];
        if(to == p) continue;
        rerec(to, res * fac[CC[now][i]] % mod * mod_inverse(dp[now][i], mod) % mod * fac[c - CC[now][i]] % mod, now);
    }
}
int solve(int now) {
    int s = G[now].size();
    int res = 1, c = 0;
    rep(i, s) {
        res = (res * mod_inverse(fac[CC[now][i]], mod)) % mod;
        res = (res * dp[now][i]) % mod;
        c += CC[now][i];
    }
    return res * fac[c] % mod;
}
