    {
        this.wordSeg = wordSeg;
    }

    public SentenceSeg getSentenceSeg()
    {
        return sentenceSeg;
    }

    public void setSentenceSeg(SentenceSeg sentenceSeg)
    {
        this.sentenceSeg = sentenceSeg;
    }

}

