Author: nbro

Created: 21/01/2017

Updated: 19/09/2017

# Description

is_sorted checks if a list or tuple contains elements in sorted order by using
recursion. This algorithm can potentially be modified to work with other
collections. The other versions are here just for comparison.
"""

import operator

__all__ = ["is_sorted", "iterative_is_sorted", "pythonic_is_sorted"]


def _is_sorted(a: list, i: int, op) -> bool:
    """i is used to index the two adjacent elements of a.

    op can either be >, if a should be in ascending order, or <, if a should be
    in descending order."""
    # If i is the last index, there's nothing more to check, thus the list is
    # sorted.
    if i == len(a) - 1:
        return True
    if op(a[i], a[i + 1]):
        return False
    return _is_sorted(a, i + 1, op)


def is_sorted(a: list, rev=False) -> bool:
    """Checks recursively if a is sorted.

    If rev is true, this function checks if a is sorted in descending order,
    else if it's sorted in ascending order."""
    if len(a) < 2:
        return True

    op = operator.gt
    if rev:
        op = operator.lt

    return _is_sorted(a, 0, op)


def iterative_is_sorted(a, rev=False) -> bool:
    """Iterative alternative to is_sorted.

    Time complexity: O(n)."""
    if len(a) < 2:
        return True

    op = operator.gt
    if rev:
        op = operator.lt

    for i in range(len(a) - 1):
        if op(a[i], a[i + 1]):
            return False

    return True


def pythonic_is_sorted(a, rev=False) -> bool:
    """Checking if a is sorted in a shorter way by using the all function."""
    op = operator.le
    if rev:
        op = operator.ge
    return all(op(a[i], a[i + 1]) for i in range(len(a) - 1))

/* 
 Title: Counting Nodes in Linked List
 Author: Inam Ul Haq

 Description:
    This program demonstrates how to count the number of nodes in a 
    singly linked list. To count the nodes, we traverse the linked list 
    starting from the head node and increment a counter for each node 
    encountered.

    The program performs the following operations:
    1. Creates a linked list by inserting nodes at the beginning.
    2. Accepts user input to populate the list.
    3. Traverses the list to count the total number of nodes.
    4. Displays the total count of nodes.
    5. Frees the allocated memory to avoid memory leaks.

    The traversal continues until the end of the list is reached 
    (i.e., when the next pointer becomes NULL).
*/

#include <stdio.h>
#include <stdlib.h>

struct Node{
	int data;
	struct Node* next;
};

void initNode(struct Node *newNode,int value){
	newNode->data=value;
	newNode->next=NULL;
}

struct Node* insertAtBeginning(struct Node *head,int value){
	struct Node *newNode=malloc(sizeof(struct Node));
	if(!newNode){
		printf("Memory allocation failed.\n");
		exit(1);
	}
	initNode(newNode,value);
	if(head!=NULL)
	newNode->next=head;
	return newNode;
}

int countNodes(struct Node *head){
	int counts=0;
	while(head!=NULL){
		counts++;
		head=head->next;
	}
	return counts;
}

void freeNodes(struct Node *head){
	if(head!=NULL){
		freeNodes(head->next);
		free(head);
	}
}
int main(){
	struct Node *head=NULL;
	printf("Enter data for nodes:\n");
	for(int i=0;i<10;i++){
		int value;
		printf("Enter value: ");
		scanf("%d",&value);
		head=insertAtBeginning(head,value);
	}
	
	int totalNodes=countNodes(head);
	printf("Total Nodes: %d\n",totalNodes);
	
	freeNodes(head);
	return 0;
}

// I shall be using an adjacencyList along with the other instance methods defined in the 'Graphs' section, to implement DFS
class Graph {
    constructor() {
        this.adjacencyList = {};
    }

    // To add a new vertex
    addVertex(vertex) {
        // check if there is already a key of the same name
        if (!this.adjacencyList[vertex]) {
            this.adjacencyList[vertex] = [];
            return true;
        }
    }

    // To add an undirected edge between two vertices
    addEdge(vertex1, vertex2) {
        // Search the adjacencyList for the keys of vertex1 and vertex2
        if (this.adjacencyList[vertex1] && this.adjacencyList[vertex2]) {
            // push 'vertex2' to vertex1's value array
            this.adjacencyList[vertex1].push(vertex2);
            // push 'vertex1' to vertex2's value array
            this.adjacencyList[vertex2].push(vertex1);
        }
        return this.adjacencyList;
    }

    // To remove an edge between two vertices
    removeEdge(vertex1, vertex2) {
        if (this.adjacencyList[vertex1] && this.adjacencyList[vertex2]) {
            // filter out the unwanted vertex
            this.adjacencyList[vertex1] = this.adjacencyList[vertex1].filter(
                (vertex) => vertex !== vertex2
            );
            this.adjacencyList[vertex2] = this.adjacencyList[vertex2].filter(
                (vertex) => vertex !== vertex1
            );

            // return the new adjacenecyList
            return this.adjacencyList;
        }
    }

    // To remove a vertex;
    removeVertex(vertex) {
        // loop through all the elements stored in the value of key 'vertex' and call the removeEdge() method for all the pairs of vertices
        this.adjacencyList[vertex].map((v) => this.removeEdge(vertex, v));

        // delete the key of the 'vertex'
        delete this.adjacencyList[vertex];

        // return the new adjacencyList
        return this.adjacencyList;
    }

    // -----------------------
    // DFS Starts Here Onwards
    // -----------------------

    // My approach, does work, and is very similar to Colt's solution
    DFS(startVertex) {
        // Create a stack
        const stack = [];

        // Create an object to keep track of visited nodes
        const visited = {};

        // Create an array to store the results
        const result = [];

        // push() the startVertex to the stack
        stack.push(startVertex);

        // Loop until stack becomes empty
        while (stack.length) {
            // Pop() a node from the stack
            const currentNode = stack.pop();

            // Check if the currentNode has not been visited yet
            if (!visited[currentNode]) {
                // mark it as visited
                visited[currentNode] = true;

                // add it to the result array
                result.push(currentNode);

                // push() currentNode's neighbour nodes to the stack
                this.adjacencyList[currentNode].forEach((neighbor) => {
                    stack.push(neighbor);
                });
            }
        }

        // return the result
        return result;
    }

    // Colt's solution
    DFS(start) {
        const stack = [start];
        const result = [];
        const visited = {};
        visited[start] = true;
        let currentVertex;

        while (stack.length) {
            currentVertex = stack.pop();
            result.push(currentVertex);

            this.adjacencyList[currentVertex].forEach((neighbor) => {
                // Now check if the neighbor node has been visited
                if (!visited[neighbor]) {
                    // Mark it as being visited
                    visited[neighbor] = true;
                    stack.push(neighbor);
                }
            });
        }
        return result;
    }
}

