  // Requirement: Build a Trie from todo names and support prefix-based lookup without scanning every todo.
  class TodoApp {
    constructor() {
      this.todos = [];
      this.trie = {
        children: new Map(),
        indexes: new Set(),
      };
    }

    addTodo(name, category, time) {
      const todo = {
        name,
        category,
        time,
        completed: false,
      };

      const index = this.todos.push(todo) - 1;
      let node = this.trie;

      for (const char of name.toLowerCase()) {
        if (!node.children.has(char)) {
          node.children.set(char, {
            children: new Map(),
            indexes: new Set(),
          });
        }

        node = node.children.get(char);
        node.indexes.add(index);
      }
    }

    searchByPrefix(prefix) {
      let node = this.trie;

      for (const char of prefix.toLowerCase()) {
        node = node.children.get(char);

        if (!node) {
          return [];
        }
      }

      return [...node.indexes].map((index) => this.todos[index]);
    }
  }

