  // createMinHeapScheduler
  // Requirement: Schedule incomplete todos by minimum execution time using a binary min-heap.
  class TodoApp {
    constructor() {
      this.todos = [];
    }

    addTodo(name, category, time) {
      this.todos.push({
        name,
        category,
        time: Number(time),
        completed: false,
      });
    }

    createMinHeapScheduler() {
      const heap = [];

      const push = (todo) => {
        heap.push(todo);

        let index = heap.length - 1;

        while (index > 0) {
          const parent = Math.floor((index - 1) / 2);

          if (heap[parent].time <= heap[index].time) {
            break;
          }

          [heap[parent], heap[index]] = [heap[index], heap[parent]];

          index = parent;
        }
      };

      const pop = () => {
        if (!heap.length) {
          return undefined;
        }

        const root = heap[0];
        const last = heap.pop();

        if (heap.length) {
          heap[0] = last;

          let index = 0;

          while (true) {
            const left = index * 2 + 1;
            const right = index * 2 + 2;
            let smallest = index;

            if (left < heap.length && heap[left].time < heap[smallest].time) {
              smallest = left;
            }

            if (right < heap.length && heap[right].time < heap[smallest].time) {
              smallest = right;
            }

            if (smallest === index) {
              break;
            }

            [heap[index], heap[smallest]] = [heap[smallest], heap[index]];

            index = smallest;
          }
        }

        return root;
      };

      this.todos.filter((todo) => !todo.completed).forEach(push);

      const result = [];

      while (heap.length) {
        result.push(pop());
      }

      return result;
    }
  }

  // Example
  const myTodos = new TodoApp();

  myTodos.addTodo("Long Project", "Learning", 8);

  myTodos.addTodo("Quick Fix", "Personal", 1);

  myTodos.addTodo("Documentation", "Learning", 3);

  console.log(myTodos.createMinHeapScheduler());

  //
}

