package datastructures.dynamicarray;

import java.util.Iterator;
import java.util.List;
import java.lang.StringBuilder;
import java.util.Arrays;

public class DynamicArray<T> implements Iterable<T>{

	private int capacity;
	private int size;
	private T[] arr;

	public DynamicArray(){
		this(4);
	}

	public DynamicArray(int capacity){
		this.capacity = capacity;
		this.size = 0;
		this.arr = (T[]) new Object[capacity];
	}

	public T get(int index){
		//Checking bounds
		if (index<0 || index >= size)
			throw new ArrayIndexOutOfBoundsException("Index " + index + " out of range!");
		return arr[index];
	}

	public int size() {return this.size;}

    public boolean isEmpty() {return size == 0;}

    public boolean contains(Object o) {return indexOf(o)!=-1;}

    @Override public Iterator<T> iterator() {return new ArrayIterator<T>(this);}

    public Object[] toArray() {
    	Object[] arr = new Object[size];
    	for(int i = 0; i < size; i++)
    		arr[i] = this.arr[i];
        return arr;
    }

    public <E> E[] toArray(E[] a) {
    	//if a has not enough space return new array
    	if(a.length < size)
    		return (E[]) Arrays.copyOf(arr, size, a.getClass());
    	//filling a if a has enough space
		System.arraycopy(arr,0,a,0,size);
		if(a.length>size)
			a[size] = null;
		return a;
	}

    public boolean add(T t) {
    	//Checking if resize is required. Resize is required when the array is full. each resize doubles the size of the array.
        if (size == capacity)
        	addCapacity();
        //Putting object in array
        arr[size] = t;
        size++;
        return true;
    }

    public void add(int index, T element) {
    	//checking if index is in range
    	if (index<0 || index>=size)
    		throw new ArrayIndexOutOfBoundsException("Index " + index + " out of range!");
    	//Checking if resize is required. Resize is required when the array is full. each resize doubles the size of the array.
    	if (size==capacity)
    		addCapacity();
    	for(int i = size; i > index; i--)
    		arr[i] = arr[i-1];
    	arr[index] = element;
    	size++;
    }

    private void addCapacity(){
    	if (size == 0)
    		capacity = 1;
    	else
        	capacity *= 2;
    	T[] arr = (T[]) new Object[capacity];
    	System.arraycopy(this.arr,0,arr,0,size);	
    	this.arr = arr;
    }

    public boolean remove(Object o) {
        int index = indexOf(o);
        if (index == -1)
        	return false;
        remove(index);
        return true;
    }

    public void clear() {
    	capacity = 4;
    	arr = (T[]) new Object[capacity];
    	size = 0;
    }

    public T set(int index, T element) {
    	if (index<=0 || index>=size)
    		throw new ArrayIndexOutOfBoundsException("Index " + index + " out of range!");
    	T prevElement = arr[index];
    	arr[index] = element;
    	return prevElement;
    }



    public T remove(int index) {
    	//Checking bound
    	if (index<0 || index>=size)
    		throw new ArrayIndexOutOfBoundsException("Index " + index + " out of range!");
    	//Checking if resize is needed. Resize happens when array size is 1/4 of the capacity.
    	T[] arr = this.arr;
        if (size-1 == capacity/4){
        	capacity /= 2;
        	this.arr = (T[]) new Object[capacity];
        }
        //Deleting and shifting
        T result = null;
        for (int i = 0, j = 0; i < size; i++, j++){
        	if (i == index){
        		j--;
        		result = arr[i];
        	}
        	else
        		this.arr[j] = arr[i];
        }
        size--;
        return result;
    }

    public int indexOf(Object o) {
        for(int i = 0; i < size; i++){
        	if (o == null && arr[i]==null)
        		return i;
       		if(o.equals(arr[i]))
       			return i;
       }
    	return -1;
    }

    public int lastIndexOf(Object o) {
    	if (size == 0)
    		return -1;
        for(int i = size-1; i >= 0; i++){
        	if (o == null && arr[i]==null)
        		return i;
       		if(o.equals(arr[i]))
       			return i;
       }
    	return -1;
    }

    @Override public String toString(){
    	if (size == 0)
    		return new String("[]");
    	StringBuilder sb = new StringBuilder("Array(" + size + ")[");
    	for (int i = 0; i < size-1; i++)
    		sb.append(arr[i] + ", ");
    	return sb.append(arr[size-1] + "]").toString();
    }


    private class ArrayIterator<T> implements Iterator<T>{

    	private DynamicArray<T> arr;
    	private int index;

    	public ArrayIterator(DynamicArray<T> arr){
    		this.arr = arr;
    		index = 0;
    	}

    	@Override public boolean hasNext() {return index!=arr.size;}

    	@Override public T next() {
    		if (!hasNext())
    			throw new ArrayIndexOutOfBoundsException("Index " + index + " out of range!");
    		T result = arr.get(index);
    		index++;
    		return result;
    	}

    	@Override public void remove() {
    		if (index == size)
    			throw new ArrayIndexOutOfBoundsException("Index " + index + " out of range!");	
    		arr.remove(index);
    	}
    }

}

package ds.queueviaarrayblockingqueueproducerconsumer;

import com.google.common.util.concurrent.ThreadFactoryBuilder;
import java.util.concurrent.ArrayBlockingQueue;
import java.util.concurrent.BlockingQueue;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.ThreadLocalRandom;
import java.util.concurrent.TimeUnit;

public class Main {

    private static final int QUEUE_MAX_SIZE = 20;
    private static final int PRODUCER_THREADS = 3;
    private static final int CONSUMER_THREADS = 2;
    private static final String PRODUCER_THREAD_NAME = "producer-stack-%d";
    private static final String CONSUMER_THREAD_NAME = "consumer-stack-%d";

    private static BlockingQueue<Integer> queue = new ArrayBlockingQueue<>(QUEUE_MAX_SIZE);

    private static ExecutorService producerPool
            = Executors.newFixedThreadPool(
                    PRODUCER_THREADS,
                    new ThreadFactoryBuilder().setNameFormat(PRODUCER_THREAD_NAME).build()
            );

    private static ExecutorService consumerPool
            = Executors.newFixedThreadPool(
                    CONSUMER_THREADS,
                    new ThreadFactoryBuilder().setNameFormat(CONSUMER_THREAD_NAME).build()
            );

    private static class Producer implements Runnable {

        private final BlockingQueue<Integer> queue;

        public Producer(BlockingQueue<Integer> queue) {
            this.queue = queue;
        }

        @Override
        public void run() {
            while (true) {
                int randomInt = produce();

                try {
                    queue.put(randomInt);

                    TimeUnit.MILLISECONDS.sleep(randomInt);
                } catch (InterruptedException ex) {
                    Thread.currentThread().interrupt();
                }
            }
        }

        public Integer produce() {
            String threadName = Thread.currentThread().getName();
            int randomInt = ThreadLocalRandom.current().nextInt(1, 1001);

            System.out.printf("[%s] produced: %s\n", threadName, randomInt);

            return randomInt;
        }

    }

    private static class Consumer implements Runnable {

        private final BlockingQueue<Integer> queue;

        public Consumer(BlockingQueue<Integer> queue) {
            this.queue = queue;
        }

        @Override
        public void run() {
            while (true) {
                try {
                    Integer randomInt = queue.take();
                    consume(randomInt);

                    TimeUnit.MILLISECONDS.sleep(randomInt / 10);
                } catch (InterruptedException ex) {
                    Thread.currentThread().interrupt();
                }
            }
        }

        public void consume(Integer value) {

            String threadName = Thread.currentThread().getName();
            System.out.printf("[%s] produced: %s\n", threadName, value);
        }
    }

    public static void main(String[] args) throws InterruptedException {

        System.out.println("Starting producers ...");
        Producer p1 = new Producer(queue);
        Producer p2 = new Producer(queue);
        Producer p3 = new Producer(queue);
        Producer p4 = new Producer(queue);

        producerPool.execute(p1);
        producerPool.execute(p2);
        producerPool.execute(p3);
        producerPool.execute(p4);

        System.out.println("Starting consumers ...");
        Consumer c1 = new Consumer(queue);
        Consumer c2 = new Consumer(queue);
        Consumer c3 = new Consumer(queue);
        Consumer c4 = new Consumer(queue);

        consumerPool.execute(c1);
        consumerPool.execute(c2);
        consumerPool.execute(c3);
        consumerPool.execute(c4);

        consumerPool.shutdown();
        producerPool.shutdown();
        producerPool.awaitTermination(Long.MAX_VALUE, TimeUnit.NANOSECONDS);
        consumerPool.awaitTermination(Long.MAX_VALUE, TimeUnit.NANOSECONDS);
    }

}

