inline int power(int a,int b){
	int ret=1;
	for (;b;b>>=1,a=1ll*a*a%mod) if (b&1) ret=1ll*ret*a%mod;
	return ret;
}

const int N = 6e5;
int fac[N+10],ifac[N+10];
inline void init(){
	fac[0]=1;
	For(i,1,N) fac[i]=1ll*fac[i-1]*i%mod;
	ifac[N]=power(fac[N],mod-2);
	Dow(i,N-1,0) ifac[i]=1ll*ifac[i+1]*(i+1)%mod;
}
inline int C(int n,int m){
	if (n<m||m<0) return 0;
	return 1ll*fac[n]*ifac[m]%mod*ifac[n-m]%mod;
}

int n,m,l,r;
inline int calc2(int s,int lim){
	if (s<0) return 0;
	int ret=0;
	For(i,0,n-m){
		if (C(s-(lim+1)*i+n,n)==0) break;
		int tmp=1ll*C(n-m,i)*C(s-(lim+1)*i+n,n)%mod;
		if (i&1) ret=Mod(ret+mod-tmp);
			else ret=Mod(ret+tmp);
	}
	return ret;
}
inline int calc(int n,int m,int s){
	int ret=0;
	for (int i=0;(i+1)*m<=s;i++) ret=Mod(ret+Mod(calc2(s-(i+1)*m,i)+mod-calc2(s-(i+2)*m,i)));
	return Mod(C(n+s,n)+mod-1ll*ret*C(n,m)%mod);
}

