struct S {
  ll c0, c1, in;
};

S op(S s, S t) {
  return {s.c0 + t.c0, s.c1 + t.c1, s.in + t.in + s.c1*t.c0};
}

S e() {
  return {0, 0, 0};
}

struct F {
  int k;
};

ll chs(ll n) {
  return n * (n-1) / 2;
}

S mapping(F f, S s) {
  if (f.k) return {s.c1, s.c0, chs(s.c0 + s.c1) - chs(s.c0) - chs(s.c1) - s.in};
  else return s;
}

F composition(F f, F g) {
  return {(f.k + g.k)&1};
}

F id() {
  return {0};
}


