//Selection sort algoritam za sortiranje niza
//Slozenost: O(n^2)

inline void selectionSort()
{
    for (int i=0;i<n-1;i++)
    {
        int minPos = i;
        for (int j=i+1;j<n;j++)
        {
            if (niz[j] < niz[minPos])
            {
               minPos = j;
            }
        }
        swap(niz[i], niz[minPos]);
    }
}

