function order(a) {
  var r = [];
  var x;
  var c = a.shift();
  while (x = a.shift()) {
    if (x > c) {
      c = x;
      continue;
    }
    r.push(x);
  }
  var m = - Infinity;
  while (x = r.shift()) {
    if (x > m) {
      m = x;
      continue;
    }
    return 'NO';
  }
  return 'YES';
}

