void knapsackDP(ll v,ll lim,ll clim,const vector<ll>& pre,vector<ll>& ret){
  deque<ll> deq,deqv;
  rep(i,clim+1){
    ll val=pre[i]-i*v;
    while(deq.size()&&deqv.back()<=val){
      deq.pop_back(); deqv.pop_back();
    }
    deq.push_back(i);
    deqv.push_back(val);
    ret[i]=deqv.front()+i*v;
    if(deq.front()==i-lim){
      deq.pop_front();
      deqv.pop_front();
    }
  }
}

void dfs(int v,int clim,vector<ll>& ret){
  knapsackDP(s[v],h[v],clim,ret,dp[v]);
