    ret=dp[nv];
    knapsackDP(s[v],h[v]-l[nv],clim,ret,update);
    rep(i,clim+1-l[nv])maxch(dp[v][i+l[nv]],update[i]+(ll)l[nv]*s[v]);
  }
}

