// a / b
struct frac {
    Int a, b;
    frac() : a(0), b(1) {}
    frac(Int _a, Int _b) : a(_a), b(_b) {
        if (b < 0) a *= -1, b *= -1;
        const Int g = gcd(mabs(a), mabs(b));
        a /= g; b /= g;
    }
};

frac operator+(const frac& x, const frac& y) {
    return frac(x.a*y.b+x.b*y.a, x.b*y.b);
}

frac operator-(const frac& x, const frac& y) {
    return frac(x.a*y.b-x.b*y.a, x.b*y.b);
}

frac operator*(const frac& x, const frac& y) {
    return frac(x.a*y.a, x.b*y.b);
}

frac operator/(const frac& x, const frac& y) {
    return frac(x.a*y.b, x.b*y.a);
}

