function thief(n, ws, vs, m) {
  var
  i, j, v, w,
  _back,
  back = {};
  for(i = 0; i < n; i++) {
    w = ws[i];
    v = vs[i];
    _back = [];
    for(j = 0; j <= m; j++) {
      if(j < w) {
        _back[j] = back[j]||0;
      } else {
        _back[j] = max(back[j]||0, (back[j - w]||0) + v);
      }
    }
    back = _back;
  }
  w = v = 0;
  for(j = 0; j <= m; j++) {
    if(v < back[j]) {
      w = j;
      v = back[j];
    }
  }
  return [v, w];
}

