void backtrace(int *set,int size){
    int answer[size],record[size];
    #define N 2
    int step=0;
    record[step]=-1;
    int summary;
    while(step>=0){
        summary=sum(answer,step,set);
        record[step]++;
        if(record[step])
            summary+=set[step];
        if(record[step]>=N || summary>9)
            step--;
        else if(summary==9){
            answer[step]=record[step];
            displayoutcome(answer,set,step+1);
        }
        else if(step!=size-1){
            answer[step]=record[step];
            step++;
            record[step]=-1;
        }
    }
}

