int main() {
	int H, N;
	cin >> N >> H;
	vector<pair<long, long>> a(N);
	vector<pair<long, long>> b(N);

	long c, d;
	for (int i=0; i<N; i++) {
		cin >> c >> d;
		a[i] = make_pair(c, d);
		b[i] = make_pair(d, c);
	}

	sort(a.begin(), a.end(), greater<pair<long,long>>());
	sort(b.begin(), b.end(), greater<pair<long,long>>());

	long res = H/a[0].first + 1;
	long res_v = res * a[0].first;
	int a_c = res;


	int m_c = 0;
	for (int i=0; i < b.size(); i++) {
		if (a[0].first > b[i].first) break;
		res_v += b[i].first;
		res++;
		m_c = i;
	}

	while(res_v >= H) {
		if (a_c > 0) {
			res_v -= a[0].first;
			res--;
			a_c--;
		} else {
			for (int i=m_c; res_v>=H; i--) {
				res--;
				res_v -= b[i].first;
			}

		}
	}


	cout << (res+1) << endl;
}

