#include <bits/stdc++.h>
#define int long long
using namespace std;

int N, p[105];
string words[105];
string s;
int dp1[500], dp2[3000];

bool same(int x, int idx){
  
  if( (int)s.size() - x < (int)words[idx].size() ) return false;
  
  for(int i=0;i<(int)words[idx].size();i++){
    
    if( s[x+i] != words[idx][i] ) return false;
    
  }

  return true;
}

void solve(){
  
  memset(dp1,-1,sizeof(dp1));
  
  dp1[0] = 0;
  
  for(int i=0;i<(int)s.size();i++){
    
    if( dp1[i] == -1 ) continue;
    
    for(int j=0;j<N;j++){
      
      if( same( i, j ) == true ){
	
	int len = (int)words[j].size();
	
	dp1[i+len] = max( dp1[i+len], dp1[i] + p[j] );
	
      }
      
    }
    
  }
  
  int P = dp1[(int)s.size()];
  
  const int INF = 1e9;
  
  for(int i=0;i<=P;i++) dp2[i] = INF;
  
  dp2[0] = 0;
  
  int cnt = 2005;
  
  while(cnt--){
    
    for(int i=0;i<N;i++){
      
      int len = (int)words[i].size();
      
      for(int j=P;j>=0;j--){
	
	if( dp2[j] == INF ) continue;
	
	dp2[j+p[i]] = min( dp2[j+p[i]], dp2[j] + len );
	
      }
      
