using ld = long double;

const ld INF = 1e100;

template <class T>
T Vec(T v) { return v; }

template <class T, class... Ts>
auto Vec(size_t l, Ts... ts) {
    return std::vector<decltype(Vec<T>(ts...))>(l, Vec<T>(ts...));
}

template <class T>
inline T sq(T a) { return a * a; }

inline ld dist(std::pair<ld, ld> a, std::pair<ld, ld> b) {
    return sqrtl(sq(a.first - b.first) + sq(a.second - b.second));
}

int main() {
    int N;
    std::cin >> N;

    std::vector<std::pair<ld, ld>> vp(N);
    for (auto& p : vp) std::cin >> p.first >> p.second;
    std::sort(vp.begin(), vp.end());

    auto dp = Vec<ld>(N, N, INF);
    dp[0][0] = 0;
    for (int i = 0; i < N - 1; ++i) {
        for (int j = 0; j < N - 1; ++j) {
            int n = std::max(i, j) + 1;
            dp[n][j] = std::min(dp[n][j], dp[i][j] + dist(vp[i], vp[n]));
            dp[i][n] = std::min(dp[i][n], dp[i][j] + dist(vp[j], vp[n]));
        }
    }

    ld ans = INF;
    for (int i = 0; i < N - 1; ++i) {
        ans = std::min(ans, std::min(dp[N - 1][i], dp[i][N - 1]) + dist(vp[i], vp[N - 1]));
    }

    std::cout << std::fixed << std::setprecision(10) << ans << std::endl;
    return 0;
}

