package dp;

public class DominoFill {
    /**
     * .....
     * ..234
     * 01
     */
    public static int method1(int R, int C) {
        int[] prev = new int[1 << C];
        prev[(1 << C) - 1] = 1;

        for (int r = 0; r < R; r++) {
            for (int c = 0; c < C; c++) {
                int[] cur = new int[1 << C];
                for (int mask = 0; mask < 1 << C; mask++) {
                    if ((mask & (1 << c)) != 0) {
                        cur[mask ^ (1 << c)] += prev[mask]; // do nothing

                        if (c > 0 && (mask & (1 << (c - 1))) == 0) {
                            cur[mask | (1 << (c - 1))] += prev[mask]; // horizontal
                        }
                    } else {
                        cur[mask | (1 << c)] += prev[mask]; // vertical
                    }
                }
                prev = cur;
            }
        }

        return prev[(1 << C) - 1];
    }

    /**
     * .....
     * ..012
     * 34
     */
    public static int method2(int R, int C) {
        int[] prev = new int[1 << C];
        prev[(1 << C) - 1] = 1;

        for (int r = 0; r < R; r++) {
            for (int c = 0; c < C; c++) {
                int[] cur = new int[1 << C];
                for (int mask = 0; mask < 1 << C; mask++) {
                    int nmask = (mask << 1) & ((1 << C) - 1);
                    if ((mask & (1 << (C - 1))) != 0) {
                        cur[nmask] += prev[mask]; // do nothing

                        if (c > 0 && ((mask & 1) == 0)) {
                            cur[nmask | 3] += prev[mask]; // horizontal
                        }
                    } else {
                        cur[nmask | 1] += prev[mask]; // vertical
                    }
                }
                prev = cur;
            }
        }

        return prev[(1 << C) - 1];
    }

    // random test
    public static void main(String[] args) {
        for (int r = 1; r < 10; r++) {
            for (int c = 1; c < 10; c++) {
                int res1 = method1(r, c);
                int res2 = method2(r, c);
                if (res1 != res2)
                    throw new RuntimeException();
            }
        }
    }

    public static int method0(int R, int C) {
        int[][][] dp = new int[R + 1][C][1 << C];
        dp[0][C - 1][(1 << C) - 1] = 1;

        for (int r = 1; r <= R; r++) {
            for (int c = 0; c < C; c++) {
                int[] prev = c > 0 ? dp[r][c - 1] : dp[r - 1][C - 1];
                for (int mask = 0; mask < 1 << C; mask++) {
                    if ((mask & (1 << c)) != 0) {
                        dp[r][c][mask ^ (1 << c)] += prev[mask]; // do nothing

                        if (c > 0 && (mask & (1 << (c - 1))) == 0) {
                            dp[r][c][mask | (1 << (c - 1))] += prev[mask]; // horizontal
                        }
                    } else {
                        dp[r][c][mask | (1 << c)] += prev[mask]; // vertical
                    }
                }
            }
        }

        return dp[R][C - 1][(1 << C) - 1];
    }
}

import java.util.Arrays;

class GfG {

    // Partition function
    static int partition(int[] arr, int low, int high) {

        // Choose the pivot
        int pivot = arr[high];

        // Index of smaller element and indicates 
        // the right position of pivot found so far
        int i = low - 1;

        // Traverse arr[low..high] and move all smaller
        // elements to the left side. Elements from low to 
        // i are smaller after every iteration
        for (int j = low; j <= high - 1; j++) {
            if (arr[j] < pivot) {
                i++;
                swap(arr, i, j);
            }
        }

        // Move pivot after smaller elements and
        // return its position
        swap(arr, i + 1, high);  
        return i + 1;
    }

    // Swap function
    static void swap(int[] arr, int i, int j) {
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }

    // The QuickSort function implementation
    static void quickSort(int[] arr, int low, int high) {
        if (low < high) {

            // pi is the partition return index of pivot
            int pi = partition(arr, low, high);

            // Recursion calls for smaller elements
            // and greater or equals elements
            quickSort(arr, low, pi - 1);
            quickSort(arr, pi + 1, high);
        }
    }

    public static void main(String[] args) {
        int[] arr = {10, 7, 8, 9, 1, 5};
        int n = arr.length;

        quickSort(arr, 0, n - 1);

        for (int val : arr) {
            System.out.print(val + " ");  
        }
    }
}

function big_multiply(A, B)
{
    var m, n, mn, i, j, carry, tmp;
    var buf, a1, a2;
    
    if(A.length > B.length){
        m = A.length;
        n = B.length;
        a1 = A.split(/(?!$)/);
        a2 = B.split(/(?!$)/);
    }
    else{
        m = B.length;
        n = A.length;
        a1 = B.split(/(?!$)/);
        a2 = A.split(/(?!$)/);
    }
    
    mn = m + n;
    if(mn < 7) return 0;
    buf = new Array(mn+1);
    for(j=0;j<=mn;++j) buf[j] = 0;
    
    for(j=m-1;j>=0;--j){
        for(carry = 0,i=n-1;i>=0;--i){
            tmp = parseInt(a1[j]) * parseInt(a2[i]) + buf[i+j+1] + carry;
            buf[i+j+1] = tmp % 10;
            carry = parseInt(tmp / 10);
        }
        buf[j] = carry;
    }
    
    for(j=0;j<=mn;++j){
        if(buf[j] > 0) break;
    }
    
    return (mn - j >= 7) ? 1 : 0;
}

