#include <stdio.h>
#include <stdlib.h>

/* CÀI ĐẶT THUẬT TOÁN DFS (Depth First Search) TRÊN ĐỒ THỊ VÔ HƯỚNG:
 | - Đồ thị sử dụng danh sách kề.
 | - Sử dụng đệ quy.
 | - Độ phức tạp: O(V + E), V là số đỉnh, E là số cạnh.
 */

#define MAX 100 // Số đỉnh tối đa

typedef struct Node
{
    int data;
    struct Node *next;
} Node;

typedef struct Graph
{
    int numVertices;
    Node *adjLists[MAX];
    int visited[MAX];
} Graph;

// Hàm tạo một Node mới
Node *createNode(int data)
{
    Node *newNode = (Node *)malloc(sizeof(Node));
    newNode->data = data;
    newNode->next = NULL;
    return newNode;
}

// Hàm khởi tạo đồ thị
Graph *createGraph(int numVertices)
{
    Graph *graph = (Graph *)malloc(sizeof(Graph));
    graph->numVertices = numVertices;

    for (int i = 0; i < numVertices; i++)
    {
        graph->adjLists[i] = NULL;
        graph->visited[i] = 0;
    }

    return graph;
}

// Hàm thêm cạnh vào đồ thị
void addEdge(Graph *graph, int u, int v)
{
    // Thêm cạnh từ u đến v
    Node *newNode = createNode(v);
    newNode->next = graph->adjLists[u];
    graph->adjLists[u] = newNode;

    // Thêm cạnh từ v đến u
    newNode = createNode(u);
    newNode->next = graph->adjLists[v];
    graph->adjLists[v] = newNode;
}

// Khai báo stack
Node *head = NULL;

// Hàm push một đỉnh vào stack
void push(int data)
{
    Node *newNode = createNode(data);
    newNode->next = head;
    head = newNode;
}

// Hàm pop một đỉnh ra khỏi stack
int pop()
{
    if (head == NULL)
        return -1;

    Node *temp = head;
    head = head->next;
    int popped = temp->data;
    free(temp);

    return popped;
}

// Hàm DFS sử dụng đệ quy
void DFS(Graph *graph, int vertex)
{
    Node *adjList = graph->adjLists[vertex];
    Node *temp = adjList;

    graph->visited[vertex] = 1;
    printf("%d ", vertex);

    while (temp != NULL)
    {
        int connectedVertex = temp->data;

        if (graph->visited[connectedVertex] == 0)
        {
            DFS(graph, connectedVertex);
        }

        temp = temp->next;
