	F[0]=1;
	for(int i=1;i<=n;i++) F[i]=int(1LL*F[i-1]*i%P);
	iF[n]=powq(F[n],P-2);
	for(int i=n;--i>=0;) iF[i]=int(1LL*iF[i+1]*(i+1)%P);

	pow2[0]=1;
	for(int i=1;i<=n;i++) pow2[i]=pow2[i-1]*2%P;

