function hms(x){
   var S=x%60;
   var M=(x%3600-S)/60;
   var H=(x-(M*60)-S)/3600;
   if(S<10)S="0"+S;
   if(M<10)M="0"+M;
   if(H<10)H="0"+H;
   return [H,M,S].join(":");
}

