function perm(xs, n) {
 var
 x, i, len = xs.length,
 ret = [];
 if(n === 0) return [[]];
 for(i = 0; i < len; i++){
  x = xs.shift();
  ret = ret.concat(perm(xs, n - 1).map(function(ys){
   return (ys.unshift(x), ys);
  }));
  xs.push(x);
 }
 return ret;
}

