#define MAXLIMIT 100

struct queue
{
	int front, rear;
	int data[MAXLIMIT];
};

void create(struct queue *q)
{
	q->front=-1;
	q->rear=-1;
}

bool isEmpty(struct queue *q)
{
	if (q->front==-1)
		return true;
	else
		return false;
}

void enqueue(struct queue *q,int d)
{
	if (isEmpty(q))
	{
		q->front++;
		q->rear++;
		q->data[q->rear]=d;
	}
	else
	{
		if (q->rear==MAXLIMIT-1)
			return;
		else
		{
			q->rear++;
			q->data[q->rear]=d;
		}
	}
}
int dequeue(struct queue *q)
{
	int temp = q->data[q->front];
	if(q->front==-1)
	return 0;
	if (q->front == q->rear)
	{
		q->front=q->rear=-1;
	}
	else
	{
		q->front++;
	}
	return temp;
}

