def longest_increasing_subsequence(nums):
    if len(nums) == 0:
        return 0

    OPT = [1 for i in range(len(nums))]

    for i in range(1, len(nums)):
        for j in range(0, i):
            if nums[j] < nums[i] and OPT[j] + 1 > OPT[i]:
                OPT[i] = OPT[j] + 1

    return max(OPT)


