import java.io.*; 
import java.util.*; 
import java.util.LinkedList; 

// This class represents a undirected graph using adjacency list 
// representation 
class Graph 
{ 
    private int V;   // No. of vertices 

    // Array  of lists for Adjacency List Representation 
    private LinkedList<Integer> adj[]; 
    int time = 0; 
    static final int NIL = -1; 

    // Constructor 
    Graph(int v) 
    { 
        V = v; 
        adj = new LinkedList[v]; 
        for (int i=0; i<v; ++i) 
            adj[i] = new LinkedList(); 
    } 

    // Function to add an edge into the graph 
    void addEdge(int v, int w) 
    { 
        adj[v].add(w);  // Add w to v's list. 
        adj[w].add(v);    //Add v to w's list 
    } 

    // A recursive function that finds and prints bridges 
    // using DFS traversal 
    // u --> The vertex to be visited next 
    // visited[] --> keeps tract of visited vertices 
    // disc[] --> Stores discovery times of visited vertices 
    // parent[] --> Stores parent vertices in DFS tree 
    void bridgeUtil(int u, boolean visited[], int disc[], 
                    int low[], int parent[]) 
    { 

        // Mark the current node as visited 
        visited[u] = true; 

        // Initialize discovery time and low value 
        disc[u] = low[u] = ++time; 

        // Go through all vertices aadjacent to this 
        Iterator<Integer> i = adj[u].iterator(); 
        while (i.hasNext()) 
        { 
            int v = i.next();  // v is current adjacent of u 

            // If v is not visited yet, then make it a child 
            // of u in DFS tree and recur for it. 
            // If v is not visited yet, then recur for it 
            if (!visited[v]) 
            { 
                parent[v] = u; 
                bridgeUtil(v, visited, disc, low, parent); 

                // Check if the subtree rooted with v has a 
                // connection to one of the ancestors of u 
                low[u]  = Math.min(low[u], low[v]); 

                // If the lowest vertex reachable from subtree 
                // under v is below u in DFS tree, then u-v is 
                // a bridge 
                if (low[v] > disc[u]) 
                    System.out.println(u+" "+v); 
            } 

            // Update low value of u for parent function calls. 
            else if (v != parent[u]) 
                low[u]  = Math.min(low[u], disc[v]); 
        } 
    } 


    // DFS based function to find all bridges. It uses recursive 
    // function bridgeUtil() 
    void bridge() 
    { 
        // Mark all the vertices as not visited 
        boolean visited[] = new boolean[V]; 
        int disc[] = new int[V]; 
        int low[] = new int[V]; 
        int parent[] = new int[V]; 


        // Initialize parent and visited, and ap(articulation point) 
        // arrays 
        for (int i = 0; i < V; i++) 
        { 
            parent[i] = NIL; 
            visited[i] = false; 
        } 

        // Call the recursive helper function to find Bridges 
        // in DFS tree rooted with vertex 'i' 
        for (int i = 0; i < V; i++) 
            if (visited[i] == false) 
                bridgeUtil(i, visited, disc, low, parent); 
    } 

    public static void main(String args[]) 
    { 
        // Create graphs given in above diagrams 
        System.out.println("Bridges in first graph "); 
        Graph g1 = new Graph(5); 
        g1.addEdge(1, 0); 
        g1.addEdge(0, 2); 
        g1.addEdge(2, 1); 
        g1.addEdge(0, 3); 
        g1.addEdge(3, 4); 
        g1.bridge(); 
        System.out.println(); 

        System.out.println("Bridges in Second graph"); 
        Graph g2 = new Graph(4); 
        g2.addEdge(0, 1); 
        g2.addEdge(1, 2); 
        g2.addEdge(2, 3); 
        g2.bridge(); 
        System.out.println(); 

        System.out.println("Bridges in Third graph "); 
        Graph g3 = new Graph(7); 
        g3.addEdge(0, 1); 
        g3.addEdge(1, 2); 
        g3.addEdge(2, 0); 
        g3.addEdge(1, 3); 
        g3.addEdge(1, 4); 
        g3.addEdge(1, 6); 
        g3.addEdge(3, 5); 
        g3.addEdge(4, 5); 
        g3.bridge(); 
    } 
}

import java.util.Scanner;
public class DisjointSet {
	public static void main(String[]args) {
		Scanner sc = new Scanner(System.in);
		DUS tree = new DUS(10);
		sc.close();
	}
	static class DUS{
  		int rank[];
  		int parent[];
  		int n;
  		public DUS(int n) {
  			rank = new int[n];
  			parent = new int[n];
  			this.n = n;
  			makeSet();
  		}
  		public void makeSet() {
  			for(int i = 0; i < n; i++)
  				parent[i] = i;
  		}
  		public int find(int x) { // path compression
  			if(parent[x] != x)
  				parent[x] = find(parent[x]);
  			return parent[x];
  		}
  		public void union(int x, int y) { // rank compression
  			int xRoot = find(x);
  			int yRoot = find(y);

  			if(xRoot == yRoot) return;

  			if(rank[xRoot] < rank[yRoot]) parent[xRoot] = yRoot;

  			else if(rank[yRoot] < rank[xRoot]) parent[yRoot] = xRoot;

  			else {
  				parent[yRoot] = xRoot;
  				rank[xRoot]++;
  			}
  		}
  	}
}

package com.jwetherell.algorithms.data_structures;

/**
 * In computer science, a disjoint-set data structure, also called a union–find data structure or merge–find set, is a data structure that keeps track of a set of 
 * elements partitioned into a number of disjoint (non-overlapping) subsets. 
 * <p>
 * It supports two useful operations:<br>
 *     Find: Determine which subset a particular element is in. Find typically returns an item from this set that serves as its "representative"; by comparing the 
 *           result of two Find operations, one can determine whether two elements are in the same subset.<br>
 *     Union: Join two subsets into a single subset.<br>
 * <p>
 * @see <a href="https://en.wikipedia.org/wiki/Disjoint-set_data_structure">Disjoint Set (Wikipedia)</a>
 * <br>
 * @author Justin Wetherell <phishman3579@gmail.com>
 */
@SuppressWarnings("unchecked")
public class DisjointSet<T extends Object> {

    private DisjointSet() { }

    /**
     * Creates a set of one element.
     * 
     * @param v Value to use when creating the set
     * @return Item representing the value
     */
    public static final <T extends Object> Item<T> makeSet(T v) {
        final Item<T> item = new Item<T>(null,v);
        item.parent = item;
        return item;
    }

    /**
     * Determine which subset a particular element is in. Find returns an item from this set that serves as its "representative"; by comparing the result 
     * of two Find operations, one can determine whether two elements are in the same subset. This method uses path compression which is a way of flattening 
     * the structure of the tree whenever Find is used on it.
     * 
     * @param x Find the "representative" of this Item
     * @return "Representative" of this Item
     */
    public static final <T extends Object> Item<T> find(Item<T> x) {
        if (x == null)
            return null;

        if ((x.parent!=null) && !(x.parent.equals(x)))
            return x.parent = find(x.parent);
        return x.parent;
    }

    /**
     * Join two subsets into a single subset. This method uses 'union by rank' which always attaches the smaller tree to the root of the larger tree. 
     * 
     * @param x Subset 1 to join
     * @param y Subset 2 to join
     * @return Resulting Set of joining Subset 1 and Subset 2 
     */
    public static final <T extends Object> Item<T> union(Item<T> x, Item<T> y) {
        final Item<T> xRoot = find(x);
        final Item<T> yRoot = find(y);
        if (xRoot==null && yRoot==null)
            return null;
        if (xRoot==null && yRoot!=null)
            return yRoot;
        if (yRoot==null && xRoot!=null)
            return xRoot;

        // x and y are in the same set
        if (xRoot.equals(yRoot))
            return xRoot;

        if (xRoot.rank < yRoot.rank) {
            xRoot.parent = yRoot;
            return yRoot;
        } else if (xRoot.rank > yRoot.rank) {
            yRoot.parent = xRoot;
            return xRoot;
        }
        // else
        yRoot.parent = xRoot;
        xRoot.rank = xRoot.rank + 1;
        return xRoot;
    }

    /**
     * {@inheritDoc}
     */
    @Override
    public String toString() {
        return "Nothing here to see, yet.";
    }

    public static final class Item<T> {

        private Item<T> parent;
        private T value;
        /** Rank is not the actual depth of the tree rather it is an upper bound. As such, on a find operation, the rank is allowed to get out of sync with the depth. **/
        private long rank;

        public Item(Item<T> parent, T value) {
            this.parent = parent;
            this.value = value;
            this.rank = 0;
        }

        public T getValue() {
            return value;
        }
        public long getRank() {
            return rank;
        }

        /**
         * {@inheritDoc}
         */
        @Override
        public boolean equals(Object o) {
            if (!(o instanceof Item))
                return false;

            final Item<T> i = (Item<T>) o;
            if ((i.parent!=null && parent!=null) && !(i.parent.value.equals(parent.value)))
                return false;
            if ((i.value!=null && value!=null) && !(i.value.equals(value)))
                return false;
            return true;
        }

        /**
         * {@inheritDoc}
         */
        @Override
        public String toString() {
            return "parent="+(parent!=null?parent.value:null)+" "+
                   (rank>0?"rank="+rank +" " : "") +
                   "value="+(value!=null?value:null);
        }
    }
}

package com.yomahub.liteflow.agent.a2a;

import io.agentscope.core.a2a.agent.A2aAgent;
import io.agentscope.core.a2a.agent.A2aAgentConfig;
import io.agentscope.core.a2a.agent.card.AgentCardResolver;
import io.agentscope.core.message.Msg;
import io.agentscope.core.message.UserMessage;
import reactor.core.publisher.Mono;

import java.util.List;
import java.util.Objects;
import java.util.concurrent.atomic.AtomicBoolean;

/** Creates component-owned A2A runtimes without retaining invocation-scoped agents. */
@FunctionalInterface
public interface A2aClientRuntimeFactory {

    A2aClientRuntime create(AgentCardResolver resolver, A2aAgentConfig config);

    static A2aClientRuntimeFactory defaultFactory() {
        return A2aClientRuntimeFactories.perCall(request -> {
            A2aAgent agent = A2aAgent.builder()
                    .name(request.remoteAgentName())
                    .agentCardResolver(request.resolver())
                    .a2aAgentConfig(request.config())
                    .build();
            return new A2aAgentHandle() {
                @Override
                public Mono<Msg> call(UserMessage message) {
                    return agent.call(List.of(message));
                }

                @Override
                public void interrupt() {
                    agent.interrupt();
                }
            };
        });
    }
}

/** Internal injectable construction path used by package-local contract tests. */
final class A2aClientRuntimeFactories {

    private A2aClientRuntimeFactories() {
    }

    static A2aClientRuntimeFactory perCall(A2aAgentFactory agentFactory) {
        Objects.requireNonNull(agentFactory, "agentFactory");
        return (resolver, config) -> {
            Objects.requireNonNull(resolver, "resolver");
            Objects.requireNonNull(config, "config");
            return request -> Mono.defer(() -> {
                if (request.resolver() != resolver || request.config() != config) {
                    return Mono.error(new IllegalArgumentException(
                            "A2A request resolver/config must match its runtime binding"));
                }
                A2aAgentHandle agent = Objects.requireNonNull(
                        agentFactory.create(request), "agentFactory returned null");
                AtomicBoolean active = new AtomicBoolean(true);
                Mono<Msg> invocation = Mono.defer(() -> Objects.requireNonNull(
                                agent.call(request.message()), "A2A agent call returned null"))
                        .doOnSuccess(ignored -> active.set(false))
                        .doOnError(ignored -> active.set(false))
                        .doOnCancel(() -> interruptOnce(agent, active));
                // AbstractAgentComponent owns the logical deadline; cancellation identifies this agent.
                return invocation;
            });
        };
    }

    private static void interruptOnce(A2aAgentHandle agent, AtomicBoolean active) {
        if (!active.compareAndSet(true, false)) {
            return;
        }
        try {
            agent.interrupt();
        }
        catch (RuntimeException failure) {
            // Cancellation/timeout remains the primary signal; upstream interrupt is best effort.
        }
    }
}

@FunctionalInterface
interface A2aAgentFactory {
    A2aAgentHandle create(A2aClientRequest request);
}

interface A2aAgentHandle {
    Mono<Msg> call(UserMessage message);

    void interrupt();
}

