#define REP(i,n)  FOR(i,0,n)

//constant
//--------------------------------------------
const double EPS = 1e-9;
const double PI  = acos(-1.0);
const double INF = 1e9;

struct P{
  double x;
  double y;

  P(){
	x=INF,y=INF;
  }

  P(const double &s , const double &e)
  { x=s; y=e;}

  P operator - (const P &t) const
  { return P(x-t.x , y-t.y); }

  P operator + (const P &t) const
  { return P(x+t.x , y+t.y); }

  P operator * (const double &d) const
  { return P(x*d , y*d); }
  P operator / (const double &d) const
  { return P(x/d , y/d); }
};
double dis(P t){
  return sqrt(t.x*t.x+t.y*t.y);
}

P unit_vector(P t){
  double u=fabs(dis(t));
  return P(t.x/u , t.y/u);
}
P rotate(P p,double angle){
  return P(p.x*cos(angle) - p.y*sin(angle),
			   p.x*sin(angle) + p.y*cos(angle));
}
struct Circle{
  P c;
  double r;
};

pair<P, P> getCrossPoints(const Circle& c1, const Circle& c2){
  double d = dis(c2.c - c1.c);
  double a = (c1.r*c1.r + d*d - c2.r*c2.r) / (2*d);
  P e = (c2.c - c1.c) / d;
  P h = rotate(e, PI/2) * sqrt(max(c1.r*c1.r - a*a, 0.));
  if(d + min(c1.r, c2.r) <= max(c1.r, c2.r))
	return MP(c1.c + e*c1.r, c1.c + e*c1.r);

  return MP(c1.c + e*a + h, c1.c + e*a - h);
}

