struct BIT {
  vector<int> data;
  BIT(){}
  void init(int n) {
    data.resize(n+1, 0);
  }
  int sum(int k) {
    int ret = 0;
    while(k > 0) {
      ret += data[k];
      k -= k & -k;
    }
    return ret;
  }
  void add(int k, int x) {
    while(k < (int)data.size()) {
      data[k] += x;
      k += k & -k;
    }
  }
};

