constexpr int md = (int) 1e9 + 7;
using Mint = Modular<std::integral_constant<decay<decltype(md)>::type, md>>;

class dsu {
 public:
  vector<int> p;
  int n;

  dsu(int _n) : n(_n) {
    p.resize(n);
    iota(p.begin(), p.end(), 0);
  }

  inline int get(int x) {
    return (x == p[x] ? x : (p[x] = get(p[x])));
  }

  inline bool unite(int x, int y) {
    x = get(x);
    y = get(y);
    if (x != y) {
      p[x] = y;
      return true;
    }
    return false;
  }
};

int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);
  int n, q;
  cin >> n >> q;
  vector<int> l(q), r(q);
  for (int i = 0; i < q; i++) {
    cin >> l[i] >> r[i];
    --l[i];
  }
  set<int> s;
  for (int i = 0; i < q; i++) {
    s.insert(l[i]);
    s.insert(r[i]);
  }
  vector<int> xs(s.begin(), s.end());
  int sz = (int) xs.size();
  dsu d(sz);
  for (int i = 0; i < q; i++) {
    int x = (int) (lower_bound(xs.begin(), xs.end(), l[i]) - xs.begin());
    int y = (int) (lower_bound(xs.begin(), xs.end(), r[i]) - xs.begin());
    d.unite(x, y);
  }
  vector<int> comp(sz, -1);
  int cnt = 0;
  for (int i = 0; i < sz; i++) {
    for (int j = 0; j < i; j++) {
      if (d.get(i) == d.get(j)) {
        comp[i] = comp[j];
        break;
      }
    }
    if (comp[i] == -1) {
      comp[i] = cnt++;
    }
  }
  Mint ans = 1;
  vector<Mint> modifier(1 << cnt, 1);
  for (int i = 0; i < sz - 1; i++) {
    Mint cur = (power(Mint(10), xs[i + 1] - xs[i]) - 1) / 9;
    ans *= cur;
    int x = comp[i];
    int y = comp[i + 1];
    for (int t = 0; t < (1 << cnt); t++) {
      if ((t & (1 << x)) && (t & (1 << y))) {
        modifier[t] *= (cur + 1) / cur;
      }
    }
  }
  vector<vector<Mint>> dp(1 << cnt, vector<Mint>(9, 0));
  for (int t = 1; t < (1 << cnt); t += 2) {
    dp[t][0] = modifier[t];
  }
  for (int t = 0; t < (1 << cnt) - 1; t++) {
    for (int dig = 0; dig < 8; dig++) {
      if (dp[t][dig] == 0) {
        continue;
      }
      Mint ft = dp[t][dig] * (8 - dig);
      int ct = (1 << cnt) - 1 - t;
      int lowest = 1 << __builtin_ctz(ct);
      ct ^= lowest;
      int u = ct;
      while (true) {
        dp[t | u | lowest][dig + 1] += ft * modifier[u | lowest];
        if (u == 0) {
          break;
        }
        u = (u - 1) & ct;
      }
    }
  }
  ans *= accumulate(dp.back().begin(), dp.back().end(), Mint(0));
  ans *= power(Mint(10), n - (xs.back() - xs[0]));
  cout << ans << '\n';
  return 0;
}

