template <typename T>
void swap(T& a, T& b)
{
    T c(std::move(a));
    a = std::move(b);
    b = std::move(c);
}

unsigned int remove_duplicates(std::vector<int>& nums)
{
    unsigned int i = 0;
    for (unsigned int j = 0; j < nums.size(); ++j) {
        if (nums[i] != nums[j]) {
            swap(nums[++i], nums[j]);
        }
    }
    return i+1;
}

