using namespace std;

const int dx[4] = {0,1,0,-1};
const int dy[4] = {1,0,-1,0};

int w,h,n,sx,sy,gx,gy,d;
bool G[202][202];

void initG(){
  fill(G[0],G[202],false);
  for(int i=0;i<2*h+1;i++) G[i][0] = G[i][2*w] = true;
  for(int i=0;i<2*w+1;i++) G[0][i] = G[2*h][i] = true;
}

void displayG(int x, int y){
    for(int i=0;i<2*h+1;i++){
      for(int j=0;j<2*w+1;j++){
	if(i == y && x == j) cout << '*' << ' ';
	else cout << G[i][j] << ' ';
      }
      cout << endl;
    }
    cout << endl;
}

void solve(){
  int x = sx, y = sy, ans = 1;
  bool f[202][202][4];

  if(sx == gx && sy == gy){
    cout << 1 << endl;
    return;
  }


  for(int i=0;i<202;i++) for(int j=0;j<202;j++) for(int k=0;k<4;k++) f[i][j][k] = false;
  f[x][y][d] = true;

  while(1){
    bool f2 = false;
    for(int i=-1;i<=2;i++){
      int nd = (d + i + 4) % 4;
      int nx = x + dx[nd];
      int ny = y + dy[nd];

      if(G[ny][nx]) continue;

      nx += dx[nd];
      ny += dy[nd];
      if(f[nx][ny][nd]) break;

      x = nx;
      y = ny;
      d = nd;
      ans++;
      f[x][y][nd] = true;
      f2 = true;

      //displayG(x,y);

      if(x == gx && y == gy){
	cout << ans << endl;
	return;
      }

      break;
    }
    if(!f2) break;
  }
  cout << "Impossible" << endl;
}

int main(){
  int x1,y1,x2,y2;
  while(cin >> w >> h >> n && (w|h|n)){
    initG();

    for(int i=0;i<n;i++){
      cin >> x1 >> y1 >> x2 >> y2;
      if(x1 > x2) swap(x1,x2);
      if(y1 > y2) swap(y1,y2);
      if(x1 == x2) for(int j=2*y1;j<=2*y2;j++) G[j][2*x1] = true;
      if(y1 == y2) for(int j=2*x1;j<=2*x2;j++) G[2*y1][j] = true;
      //displayG();
    }

    cin >> x1 >> y1 >> x2 >> y2 >> gx >> gy;
    if(x1 > x2) swap(x1,x2);
    if(y1 > y2) swap(y1,y2);
    sx = x1 * 2 + 1;
    sy = y1 * 2 + 1;
    if(x1 == x2){
      if(x1 == 0) d = 1;
      else{
	d = 3;
	sx -= 2;
      }
    } else {
      if(y1 == 0) d = 0;
      else {
	d = 2;
	sy -= 2;
      }
    }

    gx = gx * 2 + 1;
    gy = gy * 2 + 1;
    //cout << sx << ' ' << sy << ' ' << d << endl;
    solve();
  }
}

#include <stdio.h>
