            logger.debug("Response from redis for (setex: [key: {}, value: {}, expiration: {}]): {}", key, value, expirationSeconds, response);
        }
    }

    // Close the pool when the bot shuts down
    public static void shutdown() {
        if (pool != null) {
            pool.close();
        }
    }
