import java.util.*;

public class RarMazeProblem {
    public static void main(String[] args) {
        int[][] arr =  {{1, 0, 0, 0},
                        {1, 1, 0, 1},
                        {1, 1, 0, 0},
                        {0, 1, 1, 1},};
        System.out.println(findPath(arr));
    }

    public static ArrayList<String> findPath(int[][] arr) {
        ArrayList<String> ans = new ArrayList<>();
        if (arr[0][0] == 0) return ans;
        int n = arr.length;
        int vis[][] = new int[n][n];
        solve(0, 0, arr, vis, n, ans, "");
        return ans;
    }

    static boolean isSafe(int x, int y, int[][] arr, int[][] visited, int n) {
        return ((x >= 0 && x < n) && (y >= 0 && y < n) && arr[x][y] == 1 && visited[x][y] == 0);
    }

    static void solve(int i, int j, int arr[][], int vis[][], int n, ArrayList<String> ans, String move) {
        if (i == n - 1 && j == n - 1) {
            ans.add(move);
            return;
        }
        vis[i][j] = 1;
        // down
        if (isSafe(i + 1, j, arr, vis, n)) {
            solve(i + 1, j, arr, vis, n, ans, move + 'D');
        }
        // left
        if (isSafe(i, j - 1, arr, vis, n)) {
            solve(i, j - 1, arr, vis, n, ans, move + 'L');
        }

        if (isSafe(i, j + 1, arr, vis, n)) {
            solve(i, j + 1, arr, vis, n, ans, move + 'R');
        }
        // upward
        if (isSafe(i - 1, j, arr, vis, n)) {
            solve(i - 1, j, arr, vis, n, ans, move + 'U');
        }
        vis[i][j] = 0;
    }

}

// Longest Icreasing Subsequence with BIT
// O(NloN) complexity

#include <bits/stdc++.h>
#define MAXN 100005
using namespace std;

void update(int index, int val, int (&bit)[MAXN]) {
    int size = sizeof(bit) / sizeof(*bit);
    for (int i = index; i <= size; i += (i & -i)) {
        bit[i] = max(bit[i], val);
    }
}

int getMax(int index, int (&bit)[MAXN]) {
    int res = 0;
    for (int i = index; i; i -= (i & -i)) {
        res = max(res, bit[i]);
    }

    return res;
}

int findLISBit(int arr[],int length) {
    int bit[MAXN];
    memset(bit, 0, sizeof bit);

    int res = 0;

    for (int i = 0; i < length; i++) {
        int current = getMax(arr[i], bit); 
        update(arr[i], current + 1, bit);
    }

    return getMax(MAXN - 5, bit);
}

int main() {
    int arr[] = { 1, 4, 2, 10, 8 };
    int lisLength = findLISBit(arr,5);
    cout << "Longest Increasing Subsequence Length is : " << lisLength << endl;
}

