function primeNumbersIn(x) {
    var a = {};
    for (var i = 2; i <= x; i++) {
        if (i % 2 === 0 || i % 3 === 0 || i % 5 === 0) {
            continue;
        }
        a[i] = 1;
    }

    var n = 2;
    do {
        for (var i = n * 2; i <= x; i += n) {
            if (i in a) {
                delete a[i];
            }
        }
        var m = x;
        for (i in a) {
            i = Number(i);
            if (n < i && i < m) {
                m = i;
            }
        }
        n = m;
    } while (n <= Math.sqrt(x))
    var numbers = Object.keys(a).map(Number);
    numbers.unshift(2, 3, 5);
    return numbers;
}

