from collections import deque
class Solution:
    def getImportance(self, employees: List['Employee'], id: int) -> int:
        id_employee = {}
        for e in employees:
            id_employee[e.id] = e

        res = 0
        queue = deque([id_employee[id]])
        while queue:
            node = queue.popleft()
            res += node.importance
            for subordinate in node.subordinates:
                queue.append(id_employee[subordinate])
        return res

