typedef struct node {
    int data;
    struct node *next;
} *Stack;

// Top, Pop, Push, and other utility functions such as initStack, isEmpty, and isFull
void init(Stack *S);
void read(Stack S);
bool isEmpty(Stack S);
bool isFull(Stack S);
int top(Stack S);
void pop(Stack *S);
void push(Stack *S, int data);

void freeAll(Stack S);

int main() {
    Stack S;

    printf("\033[H\033[J"); // clear screen
    
    init(&S);
    read(S);

    push(&S, 1);
    read(S);

    push(&S, 2);
    push(&S, 3);
    read(S);

    int temp = top(S);
    printf("Top: %d\n", temp);

    pop(&S);
    read(S);

    freeAll(S);

    return 0;
}

void init(Stack *S) {
    *S = NULL;
}

void read(Stack S) {
    Stack temp;
    init(&temp);

    printf("Stack: ");

    if(isEmpty(S)) {
        printf("EMPTY");
    }

    while(!isEmpty(S)) {
        printf("%d ", top(S));

        Stack t = S;
        S = S->next;

        t->next = temp;
        temp = t;
    }

    while(!isEmpty(temp)) {
        Stack t = temp;
        temp = temp->next;

        t->next = S;
        S = t;
    }

    printf("\n");
}

bool isEmpty(Stack S) {
    return (S == NULL) ? true : false;
}

int top(Stack S) {
    return (!isEmpty(S)) ? S->data : -1;
}

void pop(Stack *S) {
    if(!isEmpty(*S)) {
        Stack temp = (*S);
        (*S) = temp->next;
        free(temp);
    }
}

void push(Stack *S, int data) {
    Stack temp = (Stack)malloc(sizeof(struct node));
    if(temp != NULL) {
        temp->data = data;
        temp->next = *S;
        (*S) = temp;
    }
}

void freeAll(Stack S) {
    Stack temp;

    while(S != NULL) {
        temp = S;
        S = S->next;
        free(temp);
    }
}

//Note this need to be sorted
function binarySearch(arr, target) {
    let left = 0;
    let right = arr.length - 1;

    while (left <= right) {  // <= because left and right could point to the same element, < would miss it
        let mid = left + Math.floor((right - left) / 2);  // use `(right - left) /2` to prevent `left + right` potential overflow
        if (arr[mid] === target) return mid;  // found target, return its index
        if (arr[mid] < target) {
            // middle less than target, discard left half by making left search boundary `mid + 1`
            left = mid + 1;
        } else {
            // middle greater than target, discard right half by making right search boundary `mid - 1`
            right = mid - 1;
        }
    }
    // if we get here we didn't hit above return so we didn't find target
    return -1;
}

