void calc(int nd, int an) {
	szs[nd] = 1;
	for(auto sn: adj[nd]) {
		if(sn != an) {
			calc(sn, nd);
			szs[nd] += szs[sn];
		}
	}
}

void dfs(int nd, int an) {
	sstc.push_back(nd);
	if(stcs[col[nd]].empty()) {
		ans[col[nd]] -= szs[nd];
	} else {
		int bue = sstc[stcs[col[nd]].back() + 1];
		otr[bue].push_back(nd);
		LOG << nd + 1 << ' ' << bue + 1 << '\n';
	}
	stcs[col[nd]].push_back(sstc.size() - 1);
	for(auto sn: adj[nd])
		if(sn != an)
			dfs(sn, nd);
	stcs[col[nd]].pop_back();
	sstc.pop_back();
}

void lst(int nd, int an) {
	for(auto sn: adj[nd]) {
		if(sn == an) continue;
		ll cr = szs[sn];
		for(auto grn: otr[sn])
			cr -= szs[grn];
		ans[col[nd]] += F(cr);
		lst(sn, nd);
	}
}

