			if (!adj[_i][j] || b[j] != _i || vis[_i]) continue;
			if (dfs(N, M, adj, a, b, _i, vis)) {
				b[j] = i;
				a[i] = j;
				return true;
			}
		}
	}
	return false;
}

int match(int N, int M, vector< vector<bool> >& adj) {
	vector<int> a(N, -1), b(M, -1);
	int cnt = 0;
	for (int i = 0; i < N; i++) {
		if (a[i] != -1) continue;
		vector<bool> vis(N);
		if (dfs(N, M, adj, a, b, i, vis))
			cnt++;
	}
	return cnt;
}

int main() {
