int n, m , R;
int r[10];
ll d[205][205];
ll cache[205][1<<8];

ll solve(int here, int visited) {
	if(visited == ((1<<R)-1)) {
		return 0;
	}

	ll& ret = cache[here][visited];
	if(ret != -1) return ret;
	ret = INF;

	rep(i,0,R) {
		if(visited & (1 << i)) {
			continue;
		}
		int there = r[i];
		ret = min(ret, solve(there, visited | (1<<i)) + d[here][there]);
	}

	return ret;
}

