import java.util.*;

public class ArrayRotation {

	public void rotate(int arr[], int rs, int n)
	{
		int j = 0;
		int temp[] = new int[n];
		for(int i = rs; i < n ; i++)
		{
			temp[j] = arr[i];
			j++;
		}
		for(int i = 0; i < rs; i++)
		{
			temp[j] = arr[i];
			j++;
		}
		for(int i  = 0; i < n; i++)
		{
			arr[i] = temp[i];
		}
	}

