ll solve(string a,string b,ll H){
  for(int i=H-1;i>=0;i--){
    for(int j=H-1;j>=0;j--){
      dp1[i][j]=dp1[i+1][j+1]+(a[i]==b[j]?1:0);
    }
  }
  for(auto &I:dp2){
    for(auto &J:I){J=MOD;}
  }
  dp2[0][0]=0;
  for(int i=0;i<=2*H;i++){
    for(int j=0;j<=H;j++){
      int x=j,y=i-j;
      if(x<0 || y<0 || x>H || y>H){continue;}
      if(x<H){
	dp2[x+1][y]=min(dp2[x+1][y],dp2[x][y]+dp1[x][y]);
      }
      if(y<H){
	dp2[x][y+1]=min(dp2[x][y+1],dp2[x][y]+dp1[x][y]);
      }
    }
  }
  return dp2[H][H];
}

