typedef pair<int,int> pii;
typedef pair<double,pii> pp;

int main(void){
    int n,m,p,a,b;
    while (cin>>n>>m>>p>>a>>b && n) {
        a--, b--;
        vector<int> t(n);
        for (int i = 0; i < n; i++) cin >> t[i];
        vector<vector<pii> > g(m, vector<pii>());
        for (int i = 0; i < p; i++) {
            int x,y,z;
            cin>>x>>y>>z;
            x--, y--;
            g[x].push_back(make_pair(y,z));
            g[y].push_back(make_pair(x,z));
        }
        sort(t.begin(), t.end());
        
        vector<vector<double> > d(m, vector<double>(1<<n, inf));
        priority_queue<pp, vector<pp>, greater<pp> > que;
        que.push(make_pair(0.0, make_pair(a, (1<<n)-1)));
        
        double ans = inf;
        while (!que.empty()) {
            pp p = que.top(); que.pop();
            double cost = p.first;
            int cur = p.second.first, bit = p.second.second;
            if (cur == b) {
                ans = cost;
                break;
            }
            if (cost > d[cur][bit]) continue;
            
            for (int i = 0; i < g[cur].size(); i++) {
                int to = g[cur][i].first, len = g[cur][i].second;
                for (int j = 0; j < n; j++) {
                    if (bit & 1<<j) {
                        double x = len / (double)t[j];
                        int nbit = bit & ~(1<<j);
                        if (cost+x >= d[to][nbit]) continue;
