void quick_sort(int array[], int l, int r) {
    int i, j, k, x;
    i = l;
    j = r;
    x = array[(l + r) / 2];
    do {
        while (array[i] < x)
            i++;
        while (array[j] > x)
            j--;
        if (i <= j) {
            k = array[i];
            array[i] = array[j];
            array[j] = k;
            i++;
            j--;
        }
    } while (i < j);
    if (l < j)
        quick_sort(array, l, j);
    if (i < r)
        quick_sort(array, i, r);
}

