class ListNode:
    def __init__(self, key, val):
        self.key = key
        self.val = val
        self.nex = None


class LinkedList:
    def __init__(self, key, val):
        self.head = ListNode(key, val)

    def get(self, key):
        node = self.head
        while node:
            if node.key == key:
                return node.val
            node = node.nex
        return -1

    def put(self, key, val):
        dummy = ListNode(None, None)
        dummy.nex = self.head
        pre, cur = dummy, self.head
        while cur:
            if cur.key == key:
                cur.val = val
                self.head = dummy.nex
                return
            pre, cur = pre.nex, cur.nex
        pre.nex = ListNode(key, val)
        self.head = dummy.nex
        return

    def remove(self, key):
        dummy = ListNode(None, None)
        dummy.nex = self.head
        pre, cur = dummy, self.head
        while cur:
            if cur.key == key:
                pre.nex = cur.nex
                break
            pre = pre.nex
            cur = cur.nex
        self.head = dummy.nex

    def isNone(self):
        return self.head is None

    def __repr__(self):
        res = []
        node = self.head
        while node:
            res.append("key:{}, val:{}".format(node.key, node.val))
            node = node.nex
        return ' '.join(res)

