{
	V[u].dfn = V[u].low = dfn++;
	for (int cur = V[u].first; cur != 0; cur = E[cur].next)
	{
		if (V[E[cur].endp].dfn == 0)
		{
			DFS(E[cur].endp, u);
			V[u].low = min(V[u].low, V[E[cur].endp].low);
			if (V[E[cur].endp].low >= V[u].dfn)
			{
				V[u].iscv = true;
			}
		}
		else if (E[cur].endp != p)
		{
