function gcd(a, b){
  var x = max(a, b);
  var y = min(a, b);
  var mod
  while(mod = x % y){
    x = y;
    y = mod;
  }
  return y;
}

function max(a, b) {
  var t = a - b;
  return a - (t & (t >> 31));
}

function min(a, b){
  var t = a - b;
  return b + (t & (t >> 31));
