const long long INF = 1LL << 60;

ll k;

P calc(ll x, ll y) {
  if (x < 0) {
    P ans = calc(-x, y);
    ans.first *= -1;
    return ans;
  }
  if (y < 0) {
    P ans = calc(x, -y);
    ans.second *= -1;
    return ans;
  }
  if (y > x) {
    P ans = calc(y, x);
    swap(ans.first, ans.second);
    return ans;
  }

  ll d = abs(x) + abs(y);
  ll nx = x, ny = y;

  ll sp = d % k;
  if (sp == 0) {
    ny = max(0ll, y - k);
    ll kk = k - abs(ny - y);
    nx -= kk;
  } else if (k % 2 == 0 || sp % 2 == 1) {
    if (d < k) {
      if (sp % 2 == 1) {
        nx += k;
      } else {
        sp = k - sp;
        ny += sp;
        nx -= (k - sp) / 2;
        ny += (k - sp) / 2;
      }
    } else {
      nx -= sp;
      nx -= (k - sp) / 2;
      ny += (k - sp) / 2;
    }
  } else {
    sp = k - sp;
    ny += sp;
    nx -= (k - sp) / 2;
    ny += (k - sp) / 2;
  }
  return make_pair(nx, ny);
}

signed main() {
  cin.tie(0);
  ios::sync_with_stdio(false);
  cout << fixed << setprecision(20);

  ll x, y;
  cin >> k >> x >> y;

  if ((abs(x) + abs(y)) % 2 == 1 && k % 2 == 0) {
    cout << -1 << endl;
    return 0;
  }

  vector<P> ans;
  ans.emplace_back(x, y);
  while (x || y) {
    auto np = calc(x, y);
    // update
    x = np.first;
    y = np.second;
    ans.emplace_back(x, y);
  }

  reverse(all(ans));
  cout << ans.size() - 1 << endl;
  for (auto it : ans) {
    if (it.first == 0 && it.second == 0)
      continue;
    cout << it.first << " " << it.second << endl;
  }

  return 0;
}

