#include <stdio.h>
#include <stdbool.h>
#include <stdlib.h>

/**
 * All sets / Combinations
 *
 * Backtrack Algorithm
 *
 */
void getCandidates(bool *candidates, int *c) {
  candidates[0] = true;
  candidates[1] = false;
  *c = 2;
}

bool isSolution(int k, int n) {
  return k == n;
}

void printSolution(bool *a, int k) {
  int i;

  printf("{ ");
  for (i = 1; i <= k; i++) {
    if (a[i] == true)
      printf("%d ", i);
  }
  printf("}");
}

void backtrack(bool *a, int k, int n) {
  bool candidates[2];
  int c;
  int i;

  if (isSolution(k, n)) {
    printSolution(a, k);
    printf("\n");
  } else {
    k = k + 1;
    getCandidates(candidates, &c);
    for (i = 0; i < c; i++) {
      a[k] = candidates[i];
      backtrack(a, k, n);
    }
  }
}

int main(int argc, char *argv[]) {
  if (argc != 2) {
    printf("Usage: %s [n]\n", argv[0]);
    return 1;
  }

  int n = atoi(argv[1]);
  int kSolSize = n + 1;
  bool a[kSolSize];
  int i;

  backtrack(a, 0, n);
  return 0;
}

