using namespace std;
typedef long long ll;

ll gcd(ll m, ll n){
	if(m < n){ return gcd(n, m); }
	if(n == 0){ return m; }
	if(m % n == 0){ return n; }
	return gcd(n, m % n);
}

int main(){
	while(true){
		int N;
		cin >> N;
		if(N == 0){ break; }
		int cnt = N * (N + 1) / 2;
		vector<ll> b(cnt);
		ll smallestOdd = 0x7fffffffffffffffll;
		for(int i = 0; i < cnt; ++i){
			cin >> b[i];
			if(b[i] % 2 == 1){ smallestOdd = min(smallestOdd, b[i]); }
		}
		ll a0 = 0;
		for(int i = 0; i < cnt; ++i){
			if(b[i] % 2 == 0){ a0 = ((a0 == 0) ? b[i] : gcd(a0, b[i])); }
		}
		vector<ll> a;
		for(int i = 0; i < cnt; ++i){
			if(b[i] % 2 == 0){ a.push_back(b[i] / a0); }
		}
		sort(a.begin(), a.end());
		ll mul = sqrt(smallestOdd / (a[0] * a[1]));
		cout << a0 / mul << endl;
		for(int i = 0; i < a.size(); ++i){
			cout << a[i] * mul;
			if(i != a.size() - 1){ cout << " "; }
		}
		cout << endl;
	}
	return 0;
}

// O(log n)

function binarySearch(array, item) {
  let startIndex = 0;
  let endIndex = (array.length) -1;

  while (startIndex <= endIndex) {
    let pivot = Math.floor(( startIndex + endIndex) / 2);

    if (array[pivot] === item){
         return `Item ${item} está na posição ${pivot}`;
    } else if (array[pivot] < item){
        startIndex = pivot + 1;
    } else {
        endIndex = pivot - 1;
    }
  }

  return false;
}

#include <stdio.h>
#define SIZE 8

int count;

void display_outcome(int *answer){
	int i;
	for(i=0;i<SIZE;i++)
		printf("%d ",answer[i]);
	printf("\n");
	count++;
}

int inDiagonal(int x1,int y1,int x2,int y2){
	if(y1-y2==x1-x2 || y1-y2==x2-x1)
		return 1;
	return 0;
}

int condition(int *answer,int step,int select){
	int i;
	for(i=0;i<step;i++)
		if(answer[i]==select || inDiagonal(i,answer[i],step,select))
			return 0;
	return 1;
}

void create_candidate(int *answer,int step,int *candidate,int *candidate_size){
	int i,sp=0;
	for(i=0;i<SIZE;i++){
		if(condition(answer,step,i))
			candidate[sp++]=i;
	}
	*candidate_size=sp;
}

void backtrack(int *answer,int step){
	if(step==SIZE){
		display_outcome(answer);
	}else{
		int candidate[SIZE];
		int candidate_size;
		create_candidate(answer,step,candidate,&candidate_size);
		int i;
		for(i=0;i<candidate_size;i++){
			answer[step]=candidate[i];
			backtrack(answer,step+1);
		}
