void forceInComp(int x, map<int, int> &comp) {
	if (comp.count(x) == 0) {
		int ita = comp.size();
		comp[x] = ita;
	}
}

int main() {
	int n; scanf("%d", &n);
	vector<int> x(n), y(n);
	for (int i = 0; i < n; ++i) {
		scanf("%d %d", &x[i], &y[i]);
	}
	map<int, int> xcomp, ycomp;
	for (int i = 0; i < n; ++i) {
		forceInComp(x[i], xcomp);
		forceInComp(y[i], ycomp);
	}
//	for (auto pp : xcomp) printf("x %d %d\n", pp.first, pp.second);
//	for (auto pp : ycomp) printf("y %d %d\n", pp.first, pp.second);
	int a = xcomp.size(), b = ycomp.size();
	vector<vector<int>> graph(a + b);
	for (int i = 0; i < n; ++i) {
//		printf("adding edge %d %d\n", xcomp[x[i]], ycomp[y[i]] + a);
		graph[xcomp[x[i]]].push_back(ycomp[y[i]] + a);
		graph[ycomp[y[i]] + a].push_back(xcomp[x[i]]);
	}
	vector<int> compid(a + b, -1);
	int curcc = 0;
	for (int i = 0; i < a + b; ++i) {
		queue<int> q;
		if (compid[i] == -1) {
			q.push(i);
			compid[i] = curcc;
			while (!q.empty()) {
				int cur = q.front(); q.pop();
				for (int next : graph[cur]) {
					if (compid[next] == -1) {
						compid[next] = curcc;
						q.push(next);
					}
				}
			}
			++curcc;
		}
	}
	vector<int> cxct(curcc), cyct(curcc);
//	for (int i = 0; i < a + b; ++i) printf("in comp %d %d\n", compid[i], i);
	for (int i = 0; i < a; ++i) ++cxct[compid[i]];
	for (int i = a; i < a + b; ++i) ++cyct[compid[i]];
	vector<int> cect(curcc);
	for (int i = 0; i < n; ++i) ++cect[compid[xcomp[x[i]]]];
	ll ans = 0;
	for (int i = 0; i < curcc; ++i) {
//		printf("comp %d x y e %d %d %d\n", i, cxct[i], cyct[i], cect[i]);
		ans += (ll)cxct[i] * cyct[i] - cect[i];
	}
	printf("%lld\n", ans);
	return 0;
}

#include<bits/stdc++.h>
#define F first
#define S second
#define int long long
using namespace std;
const int maxN = (1 << 15) + 13, N = 15 + 3;
int n, par[N], x[N], y[N], a[N];
long double dp[maxN], dis[N][N];
int get_par(int x) {
    if (x == par[x])
	return x;
    return par[x] = get_par(par[x]);
}

long double mst (int x) {
    long double ret = 0;
    vector<pair<long double, pair<int, int>>> d;
    vector<int> vec;
    vec.clear();
    d.clear();
    for (int i = 0; i < n; i++) {
	if ((1 << i) & x) {
	    vec.push_back(i);
	    par[i] = i;
	}
    }
    for (auto a : vec)
	for (auto b : vec) {
	    if (a != b) 
		d.push_back({dis[a][b], {a, b}});
	    
	}
    sort(d.begin(), d.end());
    for (auto a : d) {
	int u = a.S.F, v = a.S.S;
	long double w = a.F;
	int p1 = get_par(v), p2 = get_par(u);
	if (p1 != p2) {
	    par[p1] = p2;
	    ret += w;
	}
    }
    return ret;
}

int32_t main () {
    cin >> n;
    for (int i = 0; i < n; i++)
	cin >> x[i] >> y[i] >> a[i];
    for (int i = 0; i < n; i++)
	for (int j = 0; j < n; j++) {
	    dis[i][j] = sqrt((x[i] - x[j]) * (x[i] - x[j]) + (y[i] - y[j]) * (y[i] - y[j]));
	}

    for (int i = 1; i < (1 << n); i++) {
	int cnt = __builtin_popcount(i), sum = 0;
	long double val = mst(i);
	for (int j = 0; j < n; j++)
	    if ((1 << j) & i) {
		sum += a[j];
	    }
	//cout << fixed << setprecision(10) << sum << " " << val << " " << cnt << endl;
	dp[i] = ((double)sum - val) / cnt;
	//cout << i << " " <<  dp[i] << endl;
    }

    for (int i = 1; i < (1 << n); i++) {
	for (int j = (i - 1) & i; j; j = (j - 1) & i)
	    dp[i] = max(dp[i], min(dp[j], dp[i ^ j]));
	//cout << i << " " << dp[i] << endl;
    }

    cout << fixed << setprecision(10) << dp[(1 << n) - 1] << endl;
}

// Write a menu driven program to demonstrate the operations performed on stack using linked list and suitable user defined functions for each case.
// Operations: PUSH, POP, DISPLAY, EXIT

#include <stdio.h>
#include <stdlib.h>

struct Node
{
    int data;
    struct Node *next;
};

typedef struct Node Node;

Node *top = NULL;

void push(int value);
void pop();
void display();
void traverseStack();

int main()
{
    int choice, value;

    while (1)
    {
        printf("\nStack Operations:\n");
        printf("1. PUSH\n");
        printf("2. POP\n");
        printf("3. DISPLAY\n");
        printf("4. EXIT\n");
        printf("Enter your choice: ");
        scanf("%d", &choice);

        switch (choice)
        {
        case 1:
            printf("Enter the value to push: ");
            scanf("%d", &value);
            push(value);
            break;
        case 2:
            pop();
            break;
        case 3:
            // display();
            traverseStack();
            break;
        case 4:
            printf("Exiting the program.\n");
            exit(0);
        default:
            printf("Invalid choice. Please enter a valid option.\n");
        }
    }

    return 0;
}

void push(int value)
{
    Node *newNode = (Node *)malloc(sizeof(Node));
    if (newNode == NULL)
    {
        printf("Memory allocation failed. Cannot push element %d.\n", value);
        return;
    }

    newNode->data = value;
    newNode->next = top;
    top = newNode;

    printf("Pushed %d onto the stack.\n", value);
}

void pop()
{
    if (top == NULL)
    {
        printf("Stack Underflow. Cannot pop from an empty stack.\n");
        return;
    }

    Node *temp = top;
    top = top->next;

    printf("Popped element: %d\n", temp->data);
    free(temp);
}

