bool IsPossible(int a, int b, int c, int d) {
  if (considered[a][b][c][d]) return result[a][b][c][d];
  considered[a][b][c][d] = true;

  Circle cs[] = {{rocks[a], A}, {rocks[b], A}, {rocks[c], C}, {rocks[d], C}};
  vector<Point> cc1 = CrossPointCC(cs[0], cs[1]);
  vector<Point> cc2 = CrossPointCC(cs[2], cs[3]);
  if (cc1.empty()) return false;
  if (cc2.empty()) return false;

  vector<Point> rough_cand1(cc1);
  vector<Point> rough_cand2(cc2);
  for (int i=0; i<2; i++) {
    for (int j=2; j<4; j++) {
      Line l(cs[i].c, cs[j].c);
      for (int k=0; k<2; k++) {
        vector<Point> cl = CrossPointCL(cs[k], l);
        rough_cand1.insert(rough_cand1.end(), cl.begin(), cl.end());
        rough_cand2.insert(rough_cand2.end(), cl.begin(), cl.end());
      }

      for (int k=2; k<4; k++) {
        vector<Point> cl = CrossPointCL(cs[k], l);
        rough_cand2.insert(rough_cand2.end(), cl.begin(), cl.end());
      }
    }
  }

  for (int i=0; i<2; i++) {
    for (Point p2 : cc2) {
      Line l(cs[i].c, p2);
      for (int j=0; j<2; j++) {
        vector<Point> cl1 = CrossPointCL(cs[j], l);
        rough_cand1.insert(rough_cand1.end(), cl1.begin(), cl1.end());
      }
    }
  }

  for (int i=2; i<4; i++) {
    for (Point p1 : cc1) {
      Line l(cs[i].c, p1);
      for (int k=2; k<4; k++) {
        vector<Point> cl2 = CrossPointCL(cs[k], l);
        rough_cand2.insert(rough_cand2.end(), cl2.begin(), cl2.end());
      }
    }
  }
  
  vector<Point> cand1;
  vector<Point> cand2;

  for (Point p1 : rough_cand1) {
    if (abs(p1-cs[0].c) >= cs[0].r + EPS) continue;
    if (abs(p1-cs[1].c) >= cs[1].r + EPS) continue;
    cand1.push_back(p1);
  }

  for (Point p2 : rough_cand2) {
    if (abs(p2-cs[2].c) >= cs[2].r + EPS) continue;
    if (abs(p2-cs[3].c) >= cs[3].r + EPS) continue;
    cand2.push_back(p2);
  }

  sort(cand1.begin(), cand1.end());
  cand1.erase(unique(cand1.begin(), cand1.end()), cand1.end());
  sort(cand2.begin(), cand2.end());
  cand2.erase(unique(cand2.begin(), cand2.end()), cand2.end());
  for (Point p1 : cand1) {
    for (Point p2 : cand2) {
      if (abs(p1-p2) < B+EPS) return result[a][b][c][d] = true;
    }
  }

  return result[a][b][c][d] = false;
}

