#include <bits/stdc++.h>
using namespace std;
const int MOD = 1000000007;
const int MOD1 = 131;
const int MOD2 = 149;
struct RollingHash {
    vector<long long> H1, H2, M1, M2;
    RollingHash(const string &s) {
        H1.resize(s.size() + 1);
        H2.resize(s.size() + 1);
        M1.resize(s.size());
        M2.resize(s.size());
        M1[0] = M2[0] = 1;
        for (int i = 1; i < s.size(); i++) {
            M1[i] = M1[i - 1] * MOD1 % MOD;
            M2[i] = M2[i - 1] * MOD2 % MOD;
        }
        for (int i = 0; i < s.size(); i++) {
            H1[i + 1] = (H1[i] * MOD1 + s[i]) % MOD;
            H2[i + 1] = (H2[i] * MOD2 + s[i]) % MOD;
        }
    }
    long long hash(int L, int R) {
        int h1 = (H1[R] + MOD - H1[L] * M1[R - L] % MOD) % MOD;
        int h2 = (H2[R] + MOD - H2[L] * M2[R - L] % MOD) % MOD;
        return (long long)h1 << 32 | h2;
    }
};
int main() {
    int N; cin >> N;
    string S; cin >> S;
    RollingHash H(S);
    int ok = 0, ng = N + 1;
    while (abs(ok - ng) > 1) {
        int mid = (ok + ng) / 2;
        bool found = false;
        for (int i = 0; i <= N - mid; i++) {
            for (int j = i + mid; j <= N - mid; j++) {
                if (H.hash(i, i + mid) == H.hash(j, j + mid)) {
                    found = true;
                    goto FOUND;
                }
            }
        }
        FOUND:;
        (found ? ok : ng) = mid;
    }
    cout << ok << endl;
    return 0;
}

