    while (m > 0)
    {
        rev = rev * 10 + m % 10;
        m /= 10;
    }
    return rev == n;
}

int is_prime(int x)
{
    if (x < 2)
        return 0;
    for (int i = 2; i * i <= x; i++)
        if (x % i == 0)
            return 0;
    return 1;
}

