const int nmax=300010;
set<pii> LIS[nmax];
vector<tii> ary;

void ins(int pos,pii p){
	auto it=LIS[pos].lower_bound(p);
	auto it2=it;it2--;
	if(it2->second<=p.second) return;
	while(p.second<=it->second) LIS[pos].erase(it++);
	LIS[pos].insert(p);
}

bool mini(int pos,pii p){
	auto it=LIS[pos].lower_bound(p);
	while(it->second<p.second){
		if(it->first<p.first) return true;
		it--;
	}
	return false;
}


inline int rng(int &a,int &b){
	const int C = ~(1<<31), M = (1<<16)-1;
	a=36969*(a & M)+(a >> 16);
	b=18000*(b & M)+(b >> 16);
	return (C&((a<<16)+b))%1000000;
}

