	int n,m,A,B;
	while(cin >> n >> m >> A >> B){
		if(n==0&&m==0) break;
		rep(i,nmax){
			LIS[i].clear();
			LIS[i].insert(mp(inf,-1));
			LIS[i].insert(mp(-1,inf));
		}
		ary.clear();
		rep(i,n){
			int x,y,z;
			cin >> x >> y >> z;
			ary.pb(mp(-z,mp(y,x)));
		}
		rep(i,m){
			int x=rng(A,B),y=rng(A,B),z=rng(A,B);
			ary.pb(mp(-z,mp(y,x)));
		}
		sort(ary.rbegin(),ary.rend());
		int ans=0;
		rep(i,n+m){
			int l=-1,r=ans;
			while(r-l>1){
