#define FOR_LT(i, beg, end) for (int i = beg; i < end; i++)
#define FOR_LE(i, beg, end) for (int i = beg; i <= end; i++)
#define FOR_DW(i, beg, end) for (int i = beg; end <= i; i--)

using namespace std;

struct P {
	int  i;
	int  s;
};

struct E {
	int a;
	int i;
};

int main()
{
	ios_base::sync_with_stdio(false);
	cin.tie(NULL);
	cout << fixed << setprecision(20);

	int n, m; cin >> n >> m;
	vector<P> ps(n + 1);
	FOR_LE(i, 1, n) {
		ps[i].i = i;
		cin >> ps[i].s;
	}
	vector<P> pss = ps;
	sort(ps.begin(), ps.end(), [](const auto& lhs, const auto& rhs) {
		return lhs.s < rhs.s;
	});

	vector<vector<E>> es(n + 1);
	FOR_LT(i, 0, m) {
		int a, b; cin >> a >> b;
		es[a].push_back({ b, i });
		es[b].push_back({ a,i });
	}

	vector<int> ess(m);
	vector<int> pbs(n + 1);

	FOR_LE(i, 1, n) {
		P& cp = ps[i];
		int a = cp.i;
		if (pbs[a] != 0) continue;

		bool has_peer = false;
		int  peer_i   = 0;
		int  peer_ei = -1;
		bool has_pair = false;
		for (auto& e : es[a]) {
			if (pbs[e.a] != 0) {
				has_peer = true;
				peer_i = e.a;
				peer_ei = e.i;
				break;
			}
			
			if (pss[e.a].s == cp.s) {
				has_pair = true;
				peer_i = e.a;
				peer_ei = e.i;
			}
		}

		if (!has_peer && !has_pair) {
			cout << -1 << endl;
			return 0;
		}

		if (has_peer) {
			pbs[a] = (pbs[peer_i] == 1) ? 2 : 1;
			ess[peer_ei] = cp.s;
		}
		else {
			pbs[a] = 1;
			pbs[peer_i] = 2;
			ess[peer_ei] = cp.s;
		}
	}

	FOR_LE(i, 1, n) {
		cout << (pbs[i] == 1 ? "B" : "W");
	}
	cout << endl;
	FOR_LT(i, 0, m) {
		cout << ((ess[i] != 0) ? ess[i] : 1000000000) << endl;
	}

	return 0;
}

/*
核心: 有效数字的模式有两种:1)A[.[B]][e|EC]  2).B[e|EC]; 其中,A、C是整数，B是正整数
有A的话,有没有B都可以
没有A的话, 必须有B
*/
class Solution {
    //扫描字符串时的索引
    int i=0;
    public boolean isNumber(String s) {
        //input check
        if(s==null || s.length()==0)
            return false;
        //去掉首尾的空字符
        s = s.trim();
        boolean A = scanInteger(s), B=false, C=false;
        //判断是否有B; 使用索引时要确保索引不越界
        if(i<s.length() && s.charAt(i)=='.'){
            i++;
            B = scanUnsignedInteger(s);
        }
        //判断是否有C
        if(i<s.length() && (s.charAt(i)=='e' || s.charAt(i)=='E')){
            i++;
            C = scanInteger(s);
            //如果存在e|E, 但是没有C, 说明不是数字
            if(C==false)
                return false;
        }
        //here, 说明C是合格的, 只需判断A和B的情况
        //i必须扫描完整个字符串 && (A合格则B合不合格都可以, A不合格则B必须合格)
        return i==s.length() && (A || B);

    }
    private boolean scanInteger(String s){
        if(i<s.length() && (s.charAt(i)=='+' || s.charAt(i)=='-'))
            i++;
        return scanUnsignedInteger(s);
    }
    private boolean scanUnsignedInteger(String s){
        //起始索引
        int start = i;
        while(i<s.length() && s.charAt(i)>='0' && s.charAt(i)<='9'){
            i++;
        }
        //i>start说明扫描到了数字;
        //i<=start说明没有扫描到数字, 此种情况说明要么start越界, 要么s.charAt(start)不是数字
        return i > start;
    }
}

