 public static void divi(int n) {
  for(int i=2; i*i<n ; i++) {
   if(n%i==0) {
    int j = n/i;
    if(i!=j)
     ll.add(new pair(i,j));
   }
  }
 }
 public static void divi2(int n) {
  for(int i=2; i*i<n ; i++) {
   if(n%i==0) {
    int j = n/i;
    if(i!=j)
     ll2.add(new pair(i,j));
   }
  }
 }

