function binarySearch(arr = [], key) {
    function search(arr, low, high, key) {
        if (high < low) {
            return -1;
        }

        const mid = low + Math.floor((high - low) / 2);

        if (arr[mid] === key) {
            return mid;
        } else if (key < arr[mid]) {
            return search(arr, low, mid - 1, key);
        } else {
            return search(arr, mid + 1, high, key);
        }
    }

    return search(arr, 0, arr.length - 1, key)
}

