// A Dynamic Programming based C++ Program for the Egg Dropping Puzzle 
# include <stdio.h> 
# include <limits.h> 

int max(int a, int b) { return (a > b)? a: b; } 

int eggDrop(int n, int k) 
{ 
    int eggFloor[n+1][k+1]; 
    int res; 
    int i, j, x; 

    for (i = 1; i <= n; i++) 
    { 
        eggFloor[i][1] = 1; 
        eggFloor[i][0] = 0; 
    } 

    for (j = 1; j <= k; j++) 
        eggFloor[1][j] = j; 

    for (i = 2; i <= n; i++) 
    { 
        for (j = 2; j <= k; j++) 
        { 
            eggFloor[i][j] = INT_MAX; 
            for (x = 1; x <= j; x++) 
            { 
                res = 1 + max(eggFloor[i-1][x-1], eggFloor[i][j-x]); 
                if (res < eggFloor[i][j]) 
                    eggFloor[i][j] = res; 
            } 
        } 
    } 

    return eggFloor[n][k]; 
} 

