int hashAddress(int key, int partSize) {
    int sum = 0;
    int divisor = 1;

    for (int i = 0; i < partSize; i++)
        divisor *= 10;

    while (key > 0) {
        sum += key % divisor;
        key /= divisor;
    }

    return sum;
}

