	std::cout << "Enter text:";
	std::getline(std::cin, text);
	std::cout << "Pattern :";
	std::getline(std::cin, pattern);
	std::vector<size_t> indices = search(text, pattern);
	for (auto i : indices ) {
		std::cout << pattern << " occurs in given text starting at index " << i << std::endl;
	}
	return 0;
}

