vector<vector<bool> > go(int n, int dist)
{
    vector<vector<bool> >a(2 * n, vector<bool>(2 * n));
    if(dist % 2 == 1)
    {
        for(int i = 0; i < 2 * n; ++i)
            for(int j = 0; j < 2 * n; ++j)
            {
                if((i + j) & 1)
                    a[i][j] = 1;
                else
                    a[i][j] = 0;
            }
    }
    else
        if(dist % 4 != 0)
        {
            for(int i = 0; i < 2 * n; i++)
                for(int j = 0; j < 2 * n; ++j)
                    if(i % 2 == 1)
                        a[i][j] = 1;
                    else
                        a[i][j] = 0;
        }
        else
        {
            vector<vector<bool> > a2 = go((n+1) / 2, dist / 4);
            for(int i = 0; i < n; i++)
                for(int j = 0; j < n; j++)
                    if(a2[i][j])
                    {
                        for(int ii = 0; ii < 2; ii++)
                            for(int jj = 0; jj < 2; jj++)
                                a[2 * i + ii][2 * j + jj] = 1;
                    }
        }
    return a;
}
