			break;
		}
		V.pb(tmp);
		ST.insert(tmp);
	}

	int K = V.size() - hajimari;
	ll kei = 0;
	for (int i = hajimari; i < V.size(); i++) kei += V[i];

	if (N <= hajimari) {
		ll kotae = X - x;
		rep(i, N) {
			kotae += V[i];
		}
		co(kotae);
		return 0;
	}

	ll kotae = X - x;
	rep(i, hajimari) {
		kotae += V[i];
	}
	N -= hajimari;

	ll shou = N / K;
	int amari = N % K;

	kotae += shou * kei;
	for (int i = hajimari; i < hajimari + amari; i++) kotae += V[i];
	
	co(kotae);

	Would you please return 0;
}

