void bfs(int graph[][MAX],int visit[],int n,int start)
{
    int f=0,r=-1,i;
    int q[10],node;
    visit[start]=1;
    q[++r]=start;
    while(f<=r)
    {
        node=q[f++];
        for(i=0;i<n;i++)
        {
            if(graph[node][i]==1&&visit[i]==0)
            {
                visit[i]=1;
                q[++r]=i;
            }
        }
    }
}

