int binary_search(int x)
{
	int l = 0, r = longest - 1;
	do
	{
		int mid = (l + r) >> 1;
		if (least[mid] >= x)
		{
			r = mid;
		}
		else
		{
			l = mid + 1;
		}
	} while (l < r);
	return l;
}

