void insertion_sort(int *a, int n) {
    int i, j, temp;

    for (i = 1; i < n; i++)
    {
        temp = a[i];
        j = i;
        while (j > 0 && a[j - 1] > temp)
        {
            a[j] = a[j - 1];
            j--;
        }
        a[j] = temp;
    }
}

