function result(v, w, ts, i) {
  //console.log(v, w, ts);
  if (ts.length === i) {
    return [v, w];
  }
  var a = ts[i];
  if (a[1] > w) {
    return result(v, w, ts, i + 1);//[v, w];
  }
  return comp(result(v + a[0], w - a[1], ts, i + 1), result(v, w, ts, i + 1))
}

function comp(a, b) {
  if (a[0] > b[0]) {
    return a;
  } else if (a[0] < b[0]) {
    return b;
  } else if (a[1] > b[1]) {
    return a;
  } else {
    return b;
  }
}

