const int MAXN = 60;
std::vector<int> A[MAXN], B[MAXN], C[MAXN], D[MAXN];
int fa[MAXN], n;
void dfs(int u) { for (int i : A[u]) if (i != fa[u]) fa[i] = u, dfs(i); }
int mark[MAXN];
void dfs1(int u, int fa = 0) {
	for (int i : C[u]) if (i != fa)
		mark[u] || mark[i] ? 0 : (D[i].push_back(u), 0), dfs1(i, u);
}
void dfs2(int u, int fa = 0) {
	for (int i : B[u]) if (i != fa)
		mark[u] || mark[i] ? 0 : (D[u].push_back(i), 0), dfs2(i, u);
}
inline bool lb(const std::vector<int> & x, int v) {
	auto at = std::lower_bound(x.begin(), x.end(), v);
	return at != x.end() && *at == v;
}
void dfs3(int u, int fa = 0) {
	mark[u] = true; for (int i : B[u]) if (lb(C[u], i) && i != fa) dfs3(i, u);
}
int ind[MAXN];
std::queue<int> q;
int solve(int rt) {
	for (int i = 1; i <= n; ++i) C[i].clear(), D[i].clear();
	std::fill(ind + 1, ind + 1 + n, 0);
	std::fill(mark + 1, mark + 1 + n, 0);
	for (int i = 1; i <= n; ++i) if (fa[i]) {
		C[fa[i]].push_back(i);
		C[i].push_back(fa[i]);
	}
	for (int i = 1; i <= n; ++i) std::sort(C[i].begin(), C[i].end());
	dfs3(rt); dfs1(rt); dfs2(rt);
	for (int i = 1; i <= n; ++i) for (auto j : D[i]) ++ind[j];
	for (int i = 1; i <= n; ++i) if (ind[i] == 0) q.push(i);
	while (!q.empty()) {
		int t = q.front(); q.pop();
		for (auto i : D[t]) if (!--ind[i]) q.push(i);
	}
	int res = n - std::accumulate(mark + 1, mark + 1 + n, 0);
	return *std::max_element(ind + 1, ind + 1 + n) ? n + 1 : res;
}
