int sgn(double x)
{
	if (x < -eps) return -1;
	if (x > eps) return 1;
	return 0;
}

double dbl(double x)
{
	return x * x;
}

struct Point {
	double x, y;
	Point() {}
	Point(const double _x, const double _y) {
		x = _x, y = _y;
	}
	friend Point operator + (const Point &a, const Point &b) {
		return Point(a.x + b.x, a.y + b.y);
	}
	friend Point operator - (const Point &a, const Point &b) {
		return Point(a.x - b.x, a.y - b.y);
	}
	friend Point operator * (const Point &a, const double k) {
		return Point(a.x * k, a.y * k);
	}
	friend Point operator / (const Point &a, const double k) {
		return Point(a.x / k, a.y / k);
	}
	friend double dot(const Point &a, const Point &b) {
		return (a.x * b.x + a.y * b.y);
	}
	friend double det(const Point &a, const Point &b) {
		return (a.x * b.y - a.y * b.x);
	}
	friend double len(const Point &a) {
		return sqrt(a.x * a.x + a.y * a.y);
	}
	void read() {
		cin >> x >> y;
	}
	void write() const {
		cout << x << " " << y << endl;
	}
};

struct Seg {
	Point u, v, w;
	double dist;
	Seg() {}
	Seg(const Point &_u, const Point &_v) {
		u = _u, v = _v;
	}
	void read() {
		u.read();
		v.read();
	}
	void prepare() {
		w = v - u;
		w = Point(-w.y, w.x);
		dist = len(v - u);
	}
} seg[N];

bool intersect(const Point &a, const Point &b, const Point &c, const Point &d, Point &e)
{
	double s1 = det(c - a, d - a);
	double s2 = det(d - b, c - b);
	if (!sgn(s1 + s2)) return false;
	e = (b - a) * (s1 / (s1 + s2)) + a;
	return true;
}

double rectify(double x)
{
	while (x < -eps) x += 2 * PI;
	while (x > 2 * PI + eps) x -= 2 * PI;
	return x;
}

int n;
Point center[N];
double amax, radius[N], angle[N], vmax[N][2];

double calc(double vstart, double vend, double dist)
{
	double vm = sqrt((2 * amax * dist + dbl(vstart) + dbl(vend)) / 2.0);
	double ret = (2 * vm - vstart - vend) / amax;
	return ret;
}

int main()
{
