	cin >> n >> amax;
	for (int i = 1; i <= n; ++i) {
		seg[i].read();
		seg[i].prepare();
	}
	for (int i = 1; i < n; ++i) {
		static Point u, v;
		static double ang1, ang2;
		
		bool ret = intersect(seg[i].v, seg[i].v + seg[i].w, seg[i + 1].u, seg[i + 1].u + seg[i + 1].w, center[i]);
		if (!ret) center[i] = (seg[i].v + seg[i + 1].u) / 2.0;

		radius[i] = len(seg[i].v - center[i]);
		u = seg[i].v - center[i];
		v = seg[i + 1].u - center[i];
		ang1 = atan2(u.y, u.x);
		ang2 = atan2(v.y, v.x);
		if (sgn(det(seg[i].v - center[i], seg[i].v - seg[i].u)) > 0) {
			angle[i] = rectify(ang2 - ang1);
		} else {
			angle[i] = rectify(ang1 - ang2);
		}
	}
	/*
	for (int i = 1; i < n; ++i) {
		cout << center[i].x << " " << center[i].y << " " << angle[i] << endl;
	}
	*/
	vmax[n][1] = 0.0;
	vmax[n][0] = sqrt(2 * amax * seg[n].dist);
	
	for (int i = n - 1; i >= 1; --i) {
		vmax[i][1] = min(vmax[i + 1][0], sqrt(amax * radius[i]));
		vmax[i][0] = sqrt(dbl(vmax[i][1]) + 2 * amax * seg[i].dist);
	}

	double times = 0;
	double v = 0;

	for (int i = 1; i <= n; ++i) {
		if (v > vmax[i][1]) {
			times += calc(v, vmax[i][1], seg[i].dist);
			v = vmax[i][1];
		} else {
			if (dbl(v) + 2 * amax * seg[i].dist <= dbl(vmax[i][1])) {
				times += (sqrt(dbl(v) + 2 * amax * seg[i].dist) - v) / amax;
				v = sqrt(dbl(v) + 2 * amax * seg[i].dist);
			} else {
				times += calc(v, vmax[i][1], seg[i].dist);
				v = vmax[i][1];
			}
		}
		if (i < n) {
			times += radius[i] * angle[i] / v;
		}
	}

	cout << setiosflags(ios::fixed) << setprecision(8) << times << endl;
	
	return 0;
}

