        // Leave one element in q1 and  
        // push others in q2. 
        while (q1.size() != 1) 
        { 
            q2.push(q1.front()); 
            q1.pop(); 
        } 

        // Pop the only left element  
        // from q1 
        q1.pop(); 
        curr_size--; 

        // swap the names of two queues 
        queue<int> q = q1; 
        q1 = q2; 
        q2 = q; 
    } 

    void push(int x) 
    { 
        q1.push(x); 
        curr_size++; 
    } 

    int top() 
    { 
        if (q1.empty()) 
            return -1; 

        while( q1.size() != 1 ) 
        { 
           q2.push(q1.front()); 
           q1.pop(); 
        }  

        // last pushed element 
        int temp = q1.front(); 

        // to empty the auxiliary queue after 
        // last operation 
        q1.pop(); 

        // push last element to q2 
        q2.push(temp); 

        // swap the two queues names 
        queue<int> q = q1; 
        q1 = q2; 
        q2 = q; 
        return temp; 
    } 

    int size() 
    { 
        return curr_size; 
    } 
}; 

int main() 
{ 
    Stack s; 
    s.push(1); 
    s.push(2); 
    s.push(3); 
