#include <stdio.h>
#include <stdlib.h>

// Node contains data and link to next node
struct Node
{
    int data;
    struct Node *link;
};

// Head pointer to linked list
struct Node *head = NULL;

// ======= REVERSE FUNCTIONS =======//

// METHOD 1: Iterative
// Time complexity: O(n)
void reverse_iterative()
{
    struct Node *prev, *current, *next;
    prev = NULL;
    current = head;
    while (current != NULL)
    {
        next = current->link;
        current->link = prev;
        prev = current;
        current = next;
    }
    head = prev;
}

// METHOD 2: Recursive
// Time complexity: O(n)
void reverse_recursive(struct Node *ptr)
{
    if (ptr->link == NULL)
    {
        head = ptr;
        return;
    }
    reverse_recursive(ptr->link);
    struct Node *temp = ptr->link;
    temp->link = ptr;
    ptr->link = NULL;
}

