long long solve(long long a, long long b) {
	if (b == 1) return 1;
	if (a < 0) return 0;
	if (a == 0) return 1;
	if (dp[a][b]) return dp[a][b];
	return dp[a][b] = (solve(a,b-1) + solve(a-b,b)) % MOD;
}
