  var alphabets = 'abcdefghijklmnopqrstuvwxyz'.split('');
  return p.split('').map(function(e) {
    var index = alphabets.indexOf(e);
    if (index < 0) {
      return e;
    }
    index += n;
    if (index >= alphabets.length) {
      index -= alphabets.length;
    }
    return alphabets[index];
  }).join('');
