function prime_numbers(n) {
    var tbl = [-1, -1];
    for (var i = 2; i <= n; i++) {
        tbl.push(0)
    }

    for (var i = 2; i <= Math.sqrt(n); i++) {
        if (tbl[i] === 0) {
            for (var j = i * 2; j <= n; j += i) {
                tbl[j] = -1;
            }
        }
    }
    var res = [];
    tbl.forEach(function (t, number) {
        if (t === 0) {
            res.push(number);
        }
    });
    return res;
}

