	const int SPEC_Gs = 0x0100;
	const int SPEC_A  = 0x0200;
	const int SPEC_As = 0x0400;
	const int SPEC_B  = 0x0800;
	base_table.insert(pis(SPEC_C | SPEC_E | SPEC_G, ""));
	base_table.insert(pis(SPEC_C | SPEC_E | SPEC_G | SPEC_As, "7"));
	base_table.insert(pis(SPEC_C | SPEC_E | SPEC_G | SPEC_B, "M7"));
	base_table.insert(pis(SPEC_C | SPEC_Ds | SPEC_G, "m"));
	base_table.insert(pis(SPEC_C | SPEC_Ds | SPEC_G | SPEC_As, "m7"));
	multimap<int, string> spec_table;
	for(
		map<int, string>::iterator it = base_table.begin();
		it != base_table.end(); ++it)
	{
#define SPEC_INSERT(NOTE, TEXT) { \
			if(!(it->first & (NOTE))){ \
				spec_table.insert( \
					pis(it->first | (NOTE), it->second + (TEXT))); \
			} \
		}
		SPEC_INSERT(0      , "");
		SPEC_INSERT(SPEC_Cs, "(-9)");
		SPEC_INSERT(SPEC_D , "(9)");
		SPEC_INSERT(SPEC_Ds, "(+9)");
		SPEC_INSERT(SPEC_E , "(-11)");
		SPEC_INSERT(SPEC_F , "(11)");
		SPEC_INSERT(SPEC_Fs, "(+11)");
		SPEC_INSERT(SPEC_Gs, "(-13)");
		SPEC_INSERT(SPEC_A , "(13)");
		SPEC_INSERT(SPEC_As, "(+13)");
		if(!(it->first & SPEC_Fs)){
			spec_table.insert(
				pis(it->first & ~SPEC_G | SPEC_Fs, it->second + "(-5)"));
		}
		if(!(it->first & SPEC_Gs)){
			spec_table.insert(
				pis(it->first & ~SPEC_G | SPEC_Gs, it->second + "(+5)"));
		}
	}
