using namespace std;

const int N = 250; //max size of vertex
const int inf = 1<<29;
int n,m,l;
int cap[N][N],flow[N][N];
int level[N];
int adj[N][N];
bool finished[N];

inline int residue(int s,int t) { return cap[s][t] - flow[s][t]; }

void makeLevel(int s) {
    memset(level, -1, sizeof(level));
    level[s] = 0;
    queue<int> Q; Q.push(s);
    while(!Q.empty()) {
        int here = Q.front(); Q.pop();
        for(int there=0; there<n*2+2; ++there) {
            if(level[there] < 0 && residue(here,there) > 0) {
                level[there] = level[here]+1;
                Q.push(there);
            }
        }
    }
}

int augment(int here,int curf,int t) {
    if(here == t || curf == 0) return curf;
    if(finished[here] != 0) return 0;
    finished[here] = 1;
    for(int there=0; there<n*2+2; ++there) {
        if(level[there] > level[here]) {
            int f = augment(there, min(curf, residue(here, there)), t);
            if(f > 0) {
                flow[here][there] += f;
                flow[there][here] -= f;
                finished[here] = false;
                return f;
            }
        }
    }
    return 0;
}

int Dinic(int s,int t) {
    memset(flow, 0, sizeof(flow));
    int ret = 0;
    for(bool cont = true; cont; ) {
        cont = false;
        makeLevel(s);
        memset(finished, 0, sizeof(finished));
        for(int f; (f = augment(s, inf, t)) > 0; cont = true)
            ret += f;
    }
    return ret;
}

