void ShellSort(int array[], int n)
{
    int i, j, k, temp;
    for (i = n / 2; i > 0; i /= 2)
    {
        for (j = i; j < n; j++)
        {
            temp = array[j];
            for (k = j; k >= i && array[k - i] > temp; k -= i)
            {
                array[k] = array[k - i];
            }
            array[k] = temp;
        }
    }
}

