  seq_queue_q q = ( seq_queue_q )malloc( sizeof( seq_queue ) );
  q->head = 0;
  q->tail = 0;

  // 获取长度
  length = get_length( q );
  printf( "length : %d\n", length );

  // 入列
  add_to_q( q, 1 );
