        } else if (pos == 2) {
            insertAtEnd();

            printf("\n Do you insert more elements ? Enter: 1 Or exit: 0 \n\t Enter decision: ");
            scanf("%d", &continous);

            if (continous == 0) {
                printf("\n\t You'r successfully exit !");
                break;
            }
        } else if (pos == 3) {
