void get_input(int n,vector<pii> *rule,int &p){
  rep(i,n){
    string in;
    cin>>in;
    if (in.size()== 2){//SPACE
      leadSpace[in[0]]=true;
      rule[in[0]].pb(mp(SPACE,SPACE));
    }else{
      int me  = in[0];
      REP(j,2,(int)in.size()-1){
	//	cout <<"rule "<< me <<" " << (int)in[j] <<" " <<p << endl;
	rule[me].pb(mp(in[j],p));
	me=p;
