void topview(Node* root) 
{ 
    if(root==NULL) 
       return; 
     queue<Node*>qa; 
     map<int,int> mp;  
     int hd=0; 
     root->hd=hd; 

    qa.push(root); 

    cout<< "The top view of the tree - "; 

    while(qa.size()) 
    { 
        hd=root->hd; 

        // count function returns 1 if the container  
        // contains an element whose key is equivalent  
        // to hd, or returns zero otherwise. 
        if(mp.count(hd)==0)   
        mp[hd]=root->data; 
        if(root->left) 
        { 
            root->left->hd=hd-1; 
            qa.push(root->left); 
        } 
        if(root->right) 
        { 
            root->right->hd=hd+1; 
            qa.push(root->right); 
        } 
        qa.pop(); 
        root=qa.front(); 

    } 



     for(auto i=mp.begin();i!=mp.end();i++) 
    { 
        cout<<i->second<<" "; 
    } 

} 

