    var tmp = '';
    for (var i = 0; i < 26; i++) {
        tmp += String.fromCharCode(((a * i + b) % 26) + acode);
    }
    var res = '';
    for (var i = 0; i < str.length; i++) {
        if (str.charAt(i) === ' ') {
            res += ' ';
        } else {
            res += String.fromCharCode(tmp.indexOf(str.charAt(i)) + acode);
        }
    }
    return res;

