def gcd(a, b):
    if a == 0:
        return b
    return gcd(b%a, a)

# product = lcm * gcd --> lcm = product / gcd 
def lcm(a, b):
    prod = a*b
    hcf = gcd(min(a, b), max(a, b))
    return prod // hcf

