int binary_search(int arr[] ,int n , int key , int low , int high){
    // For Ascending Order
    if(arr[0] < arr[n-1]){
    if(low > high){
        return -1;
    }
    int mid = (low+high)/2;
    if(key == arr[mid]){
        return mid;
    }
    else if(key > arr[mid]){
        binary_search(arr,n,key,low+1,high);
    }
    else{
        binary_search(arr,n,key,low,mid-1);
    }
    }
    // For Descending order
    else{
    if(low > high){
        return -1;
    }
    int mid = (low+high)/2;
    if(key == arr[mid]){
        return mid;
    }
    else if(key < arr[mid]){
        binary_search(arr,n,key,low+1,high);
    }
    else{
        binary_search(arr,n,key,low,mid-1);
    }
    }


}


