# class ListNode:
#     def __init__(self, x):
#         self.val = x
#         self.next = None

class Solution:
    def detectCycle(self, head: Optional[ListNode]) -> Optional[ListNode]:
        current = head#current assigned to head
        unique = []#storage of elements
        while current !=None:
            if current not in unique:
                unique.append(current)#stores current vals
                current = current.next#moves current 
            else:
                return current
        return None

// Implementation of Binary Search Tree 
#include <stdio.h>
#include <stdlib.h>

struct BST {
    int data;
    struct BST* left;
    struct BST* right;
};

struct BST *CreateNode() {
    struct BST* new = (struct BST*) malloc(sizeof(struct BST));
    new->left = NULL;
    new->right = NULL;
    return new; 
};

void Insert(struct BST** RootPtr, int value) {
    struct BST* temp = *RootPtr;
    if (temp == NULL) { /*When list is empty*/
        struct BST* NewNode = CreateNode();
        NewNode->data = value;
        *RootPtr = NewNode;
    } else if (value <= temp->data) { /*If user value is less then current node value insert in left of the node...*/
        struct BST* NewNode = CreateNode();
        NewNode->data = value;
        temp->left = NewNode;
    } else { /*If user value is greater then current node value insert at right of the node*/
        struct BST* NewNode = CreateNode();
        NewNode->data = value;
        temp->right = NewNode;
    }
}

int Search(struct BST* RootPtr, int item) { /*Implemented search using recursion*/
    if(RootPtr == NULL) {
        return 0; /*Returns 0 if list is empty*/
    } else if(item == RootPtr->data) {
        return 1; /*Returns 1 when element found*/
    } else if(item < RootPtr->data) {
        Search(RootPtr->left, item); /*Otherwise search in left side of binary tree if searching value is less then the current node value*/
    } else {
        Search(RootPtr->right, item); /*Otherwise search in right side of binary tree if searching value is greater then the current node value*/
    }
}

void main() {
    struct BST* RootPtr = NULL;
    int item, cont, key;
    do {
        printf("Enter item: ");
        scanf("%d",&item);
        Insert(&RootPtr, item);

        printf("\n1 to keep inserting/ 0 to Exit: ");
        scanf("%d",&cont);
    } while(cont == 1);

    printf("\nEnter element to search: ");
    scanf("%d",&key);

    if(Search(RootPtr, key) == 0) {
        printf("\nFound\n");
    } else {
        printf("\nNot Found\n");
    }
}

/**
 * [3] 不修改数组找到重复的数字
 * 
 * 题目: 在一个长度为 n + 1 的数组里的所有数字都在 [1, n]的范围内, 所以数组中至少有一个数字是重复的. 请找出数组中任意一个重复的数字.
 *      但不能修改输入的数组.
 *
 * 思路: 类二分查找, 将数组分为含*一定*包含重复元素部分和*不一定*包含重复元素部分
 */
class Solution {
    /**
     * 时间复杂度: O(n * logn)
     * 空间复杂度: O(1)
     */
    public int findDuplicate(int[] nums) {
        if (nums.length == 0) return -1;
        int n = nums.length;
        // from [1, n] to find duplication
        int l = 1, r = n;
        while (l < r) {
            int mid = l + r >> 1;
            // duplication is in left part
            if (check(nums, l, mid)) r = mid;
            // duplication is in right part
            else l = mid + 1;
        }
        return l;
    }

    // judge the range of [start, end] has duplication or not
    private boolean check(int[] nums, int st, int ed) {
        int cnt = 0;
        for (int num : nums) {
            if (num >= st && num <= ed) cnt++;
        }
        return cnt > ed - st + 1;
    }
}

