void subsets(vector<int> U, int m) 
{
    long nSub = 1 << m;
    
    for(long i = 0; i < nSub; i++)
    {
        long d = 0;
        
        for(int k = 0; k < m; k++)
        {
            if((1 << k) & i)
            {
                d += (1 << U[k]);
            } 
        }
        
        printf("%ld:", d);
        for(int k = 0; k < m; k++)
            if((1 << k) & i)
                printf(" %d", U[k]);
        printf("\n");
    }
}

