int hash(Coordinates *coordinates, int size)
{
    int diff = coordinates->x - coordinates->y;
    if (diff < 0)
        diff = -diff;
    int sum = coordinates->x + coordinates->y;
    int h = (31 * coordinates->x) + (37 * coordinates->y) + (41 * diff) + (47 * sum);
    return h % size;
}

