ListNode * addLists( ListNode * list1, ListNode *list2 )
{
    ListNode *list3 = nullptr;
    ListNode *curr = nullptr;
    int carry = 0;

    // both list1 and list2 are not null
    while ( list1 && list2 ) {
        int x = list1->val + list2->val + carry;
        if ( x  > 9 ) {
            carry = 1;
            x -= 10;
        } else {
            carry = 0;
        }
        if (list3 == nullptr) {
            list3 = new ListNode(x);
            curr = list3;
        } else {
            curr->next = new ListNode(x);
            curr = curr->next;
        }
        list1 = list1->next;
        list2 = list2->next;
    }

    // list2 is null
    while(list1) {
        int x = list1->val + carry;
        if ( x  > 9 ) {
            carry = 1;
            x -= 10;
        } else {
            carry = 0;
        }
        curr->next = new ListNode(x);
        curr = curr->next;
        list1 = list1->next;
    }

    // list1 is null
    while(list2) {
        int x = list2->val + carry;
        if ( x  > 9 ) {
            carry = 1;
            x -= 10;
        } else {
            carry = 0;
        }
        curr->next = new ListNode(x);
        curr = curr->next;
        list2 = list2->next;
    }
    if (carry > 0) {
        curr->next = new ListNode(carry);
        curr  = curr->next;
    }
    return list3;
}

