        // a prev node beacuse we need to reconnect the prev one with newNode
        ListNode<T> prev  = head;

        //  reaching that point
        while(index>0){
            prev=temp;
            temp=temp.next;
            index--;
        }
        //    change the refernce variable of prev to next one
        prev.next=temp.next;
        temp.next=null;
        //   decearse in length
        length--;
        return temp.val;
    }

