def bottomView(root):
	if root is not None:
		botView = {}
		q	= deque()
		q.append((root, 0))
		while q:
			node, index = q.popleft()
			botView[index] = node.data
			if node.left is not None:
				q.append((node.left, index-1))
			if node.right is not None:
				q.append((node.right, index+1))
		return botView

