using namespace std;

long long N, K, S, X[2009], Y[2009], Z[2009], col[2009], cnts; vector<int>x[2009], G[2009]; bool used[2009];

void init() {
	for (int i = 0; i < 2009; i++) {
		X[i] = 0; Y[i] = 0; Z[i] = 0; cnts = 0; col[i] = 0;
		x[i].clear(); G[i].clear(); used[i] = false;
	}
}

void dfs(int pos) {
	if (col[pos] >= 1) return;
	col[pos] = cnts; G[cnts].push_back(pos);
	for (int i = 0; i < x[pos].size(); i++) dfs(x[pos][i]);
}

long long reduction(long long a, long long b) {
	long long G1 = abs(X[a] - X[b]); G1 = S - G1;
	long long G2 = abs(Y[a] - Y[b]); G2 = S - G2;
	long long G3 = abs(Z[a] - Z[b]); G3 = S - G3;
	return G1*G2 + G2*G3 + G3*G1;
}

long long solve(vector<long long>A, bool ispath) {
	if (ispath == false) {
		long long minx = (1LL << 60);
		for (int i = 0; i < A.size(); i++) {
			int LL = i, RR = i + K - 1;

			long long V = 0;
			for (int j = LL; j <= RR; j++) V += S*S * 6;
			long long E = 0; if (A.size() == K) E = 1;
			for (int j = LL; j < RR + E; j++) V -= 2LL * reduction(A[j % A.size()], A[(j + 1) % A.size()]);
			minx = min(minx, V);
		}
		return minx;
	}
	if (ispath == true) {
		long long minx = (1LL << 60);
		for (int i = 0; i < A.size(); i++) {
			int LL = i, RR = i + K - 1; if (RR >= A.size()) continue;

			long long V = 0;
			for (int j = LL; j <= RR; j++) V += S*S * 6;
			for (int j = LL; j < RR; j++) V -= 2LL * reduction(A[j], A[j + 1]);
			minx = min(minx, V);
		}
		return minx;
	}
}

int main() {
	while (true) {
		cin >> N >> K >> S; init(); if (N + K + S == 0) break;
		for (int i = 1; i <= N; i++) cin >> X[i] >> Y[i] >> Z[i];
		for (int i = 1; i <= N; i++) {
			for (int j = 1; j <= N; j++) {
				if (abs(X[i] - X[j]) <= S && abs(Y[i] - Y[j]) <= S && abs(Z[i] - Z[j]) <= S && i != j) {
					x[i].push_back(j);
				}
			}
		}
		for (int i = 1; i <= N; i++) {
			if (col[i] == 0) { cnts++; dfs(i); }
		}
		long long minx = (1LL << 60);
		for (int i = 1; i <= cnts; i++) {
			vector<long long>A;
			int t = -1; bool ispath = true;
			for (int j = 0; j < G[i].size(); j++) {
				if (x[G[i][j]].size() <= 1) t = G[i][j];
			}
			if (t == -1) { t = G[i][0]; ispath = false; }

			while (true) {
				A.push_back(t); used[t] = true;
				int u = -1;
				for (int j = 0; j < x[t].size(); j++) {
					if (used[x[t][j]] == false) u = x[t][j];
				}
				if (u == -1) break;
				t = u;
			}
			minx = min(minx, solve(A, ispath));
		}
		if (minx == (1LL << 60)) minx = -1;
		cout << minx << endl;
	}
	return 0;
}

class Node {
  constructor(value = null, left = null, right = null) {
    this.value = value;

    this.right = right;
    this.left = left;
  }

  insert(value) {
    if (value < this.value) {
      if (this.left === null) {
        this.left = new Node(value);
      } else {
        this.left.insert(value);
      }
    } else {
      if (this.right === null) {
        this.right = new Node(value);
      } else {
        this.right.insert(value);
      }
    }
  }

  contains(value) {
    if (this.value === value) {
      return true;
    }

    if (value < this.value) {
      if (this.left === null) {
        return false;
      }

      return this.left.contains(value);
    }

    if (this.right === null) {
      return false;
    }

    return this.right.contains(value);
  }

  printInOrder() {
    if (this.left !== null) {
      this.left.printInOrder();
    }

    console.log(this.value);

    if (this.right !== null) {
      this.right.printInOrder();
    }
  }

  printPreOrder() {
    console.log(this.value);

    if (this.left !== null) {
      this.left.printInOrder();
    }

    if (this.right !== null) {
      this.right.printInOrder();
    }
  }

  printPostOrder() {
    if (this.left !== null) {
      this.left.printInOrder();
    }

    if (this.right !== null) {
      this.right.printInOrder();
    }

    console.log(this.value);
  }
}

