  REP(i,M){
    if((bcs>>i&1) == 0 || (bps>>as[i]&1) == 0) continue;
    res += ((cs[i].c - q).norm() - (cs[i].r * cs[i].r)) / (vs[i] * vs[i]);
  }
  return res;
}
 
int main(){
  cin.tie(0);
  ios_base::sync_with_stdio(false);
 
  while(cin>>N>>M,N){
    vector<Point> ps(N);
    REP(i,N) cin >> ps[i].x >> ps[i].y;
    VI as(M), bs(M);
    vector<double> vs(M);
    vector<Circle> cs(M);
    REP(i,M){
      cin >> as[i] >> bs[i] >> vs[i];
      --as[i];
      --bs[i];
      cs[i].c = ps[as[i]];
      cs[i].r = (ps[bs[i]] - ps[as[i]]).abs();
    }
