      cout << fixed << setprecision(9) << 0. << endl;
      continue;
    }
 
    set<LL> planes;
    set<PLL> points;
    partCircles(cs, planes);
    partPoints(ps, points);
 
    double best = 0.;
    for(auto&& bpos: points){
      double d1 = 0, d2 = 0;
      for(auto&& bpls: planes){
        mini(d1, calcBest(bpos.FF, bpls, as, vs, cs));
        mini(d2, calcBest(bpos.SS, bpls, as, vs, cs));
      }
      mini(best, d1+d2);
    }
 
