const int N = 100010;
int par[N];
int dw[N];

void init(int n){
	rep(i, n) par[i] = i, dw[i] = 0;
}

int find(int x){
	if(x == par[x]) return x;
	int p = find(par[x]);
	dw[x] += dw[par[x]];
	return par[x] = p;
}

bool same(int x, int y){
	return find(x) == find(y);
}

void unite(int x, int y, int d){
	int rx = find(x), ry = find(y);
	// dw[x] = w[x]-w[rx]
	// dw[y] = w[y]-w[ry]
	// dw[x]-dw[y] = (w[x]-w[y])-(w[rx]-w[ry])
	// dw[x]-dw[y] = -d-(w[rx]-w[ry]) ∵w[x]+d = w[y]
	// dw[x]-dw[y] = -d+dw[ry] ∵dw[ry] = w[ry]-w[rx]
	// dw[ry] = dw[x]-dw[y]+d
	dw[ry] = dw[x]-dw[y]+d;
	par[ry] = rx;
}

