class Queue {
  constructor() {
    this.datastore = []
    this.size = 0
  }

  enqueue(data) {
    this.datastore[this.datastore.length++] = data
    this.size++
    return this.datastore
  }

  dequeue() {
    this.datastore.splice(0, 1)
    this.size--
    return this.datastore
  }

  peek() {
    return this.datastore[0]
  }

  backPeek() {
    return this.datastore[this.size - 1]
  }

  isEmpty() {
    return this.size === 0
  }

  display() {
    let items = ''
    for (let item of this.datastore) {
      items += item + '\n'
    }
    return items
  }
}

