bool isSubSet(int set[], int sum, int n)
{

    if (sum == 0)
        return true;

    if (n == 0 && sum != 0)
        return false;
    if (sum < set[n - 1])
        return isSubSet(set, sum, n - 1);

    return isSubSet(set, sum, n - 1) || isSubSet(set, sum - set[n - 1], n - 1);
}

