struct node {
    int value;
    struct node *previous;
};

struct node *last = NULL;

int is_empty() {
    if (last == NULL)
        return 1;
    else return 0;
}

void push(int value) {
    struct node *cell = (struct node *) malloc(sizeof(struct node));
    cell->value = value;
    cell->previous = last;
    last = cell;
}

int pop() {
    if (is_empty()) {
        return 0;
    }
    struct node *temporary = last;
    int temp = temporary->value;
    last = last->previous;
    free(temporary);
    return temp;
}

