#define FOR(i,bg,ed) for(int i=(bg);i<(ed);i++)
#define REP(i,n) FOR(i,0,n)

string S="()01+-*=";

bool flag=false;

#define NONE -1
int n;
string s;
int F(int &id);
int E(int &id,int sgn);

int getnum(int &id){
    int cnt=0,num=0;
    bool firstzero=s[id]=='0';
    while(id<n&&(s[id]=='0'||s[id]=='1')){
        num*=2;
        num+=(s[id]-'0');
        id++;
        cnt++;
    }
    if(firstzero&&cnt>1){
        flag=false;
    }
    return num;
}

int F(int &id){
    if(id<n){
        if(s[id]=='0'||s[id]=='1')return getnum(id);
        else if(s[id]=='('){
                id++;
                int num=E(id,1);
                if(id<n&&s[id]==')'){
                    id++;
                    return num;
                }
        }
        else if(s[id]=='-'){
            id++;
            return -F(id);
        }
    }
    flag=false;
    return 0;
}
int T(int &id){
    int sum=1;
    if(s[id]=='('||s[id]=='-'||s[id]=='0'||s[id]=='1')sum*=F(id);
    else{
        flag=false;
        return 0;
    }
    if(!flag)return false;
    if(id==n||s[id]==')'||s[id]=='='||s[id]=='+'||s[id]=='-'){
        return sum;
    }
    if(s[id]=='*'){
        id++;
        return sum*T(id);
    }
    else{
        flag=false;
        return 0;
    }    

}
int E(int &id,int sgn){
    int sum=0;
    if(s[id]=='('||s[id]=='-'||s[id]=='0'||s[id]=='1')sum=sgn*T(id);
    else{
        flag=false;
        return 0;
    }
    if(!flag)return false;
    if(id==n||s[id]==')'||s[id]=='='){
        return sum;
    }
    if(s[id]=='+'){
        id++;
        return sum+E(id,1);
    }
    else if(s[id]=='-'){
        id++;
        return sum+E(id,-1);
    }
    else{
        flag=false;
        return 0;
    }    
}

bool Q(){
    int L,R;flag=true;
    int eq=NONE,id;
    REP(i,n){
        if(s[i]=='='){
            if(eq==NONE)
                eq=i;
            else
                return false;
        }
    }
    if(eq==NONE)return false;
    L=E(id=0,1);
    if(!flag||id!=eq)return false;
    R=E(id=eq+1,1);
    if(!flag||id!=n)return false;
    return L==R;
}
