RollingHash rh[2];
bool memo[500005] = {0};
long long used[500005] = {0};
long long tsize, ssize;

long long solve();

int main() {
  cin >> s >> t;
  tsize = t.size();
  ssize = s.size();
  ns = s + s;
  while((long long)ns.size() <
        (long long)2 * (long long)max(t.size(), s.size()))
    ns += s;
  rh[0] = RollingHash(ns);
  rh[1] = RollingHash(t);
  cout << solve() << endl;
  return 0;
}

long long solve() {
  long long ans = 0;
  for(int i = 0; i < ssize; ++i)
    memo[i] = rh[0].calchash(i, i + tsize) ==
              rh[1].calchash(0, tsize);
  for(int i = 0; i < ssize; ++i) used[i] = -1;
  for(int i = 0; i < ssize; ++i)
    if(used[i] == -1) {
      long long cnt = 0, now = i;
      stack<long long> st;
      while(1) {
        st.push(now);
        if(used[now] != -1) break;
        used[now] = -2;
        if(memo[now])
          now = (now + tsize) % ssize;
        else {
          used[now] = 0;
          break;
        }
        if(used[now] == -2) return -1;
      }
      cnt = used[now] - 1;
      while(st.size() > 0) {
        used[st.top()] = ++cnt;
        st.pop();
      }
      ans = max(ans, cnt);
    }
  if(ans == inf) return -1;
  return ans;
}

