vi divs[MAXN];

void solve(){
	int n;
	scanf("%d%s", &n, &s[0]);
	st2[0] = 1ll;
	REPN(i, 1, 2 * n) {
		st2[i] = (st2[i - 1] * 2) % MOD;
	}
	REPN(i, 1, 2 * n) {
		for(int j = i + i; j <= 2 * n; j += i) {
			divs[j].pb(i);
		}
	}
	REPN(i, 2, 2 * n) {
		if ((2 * n) % i == 0 && i % 2 == 0 && ((2 * n) / i) % 2 == 1) {
			int len = i / 2;
			REP(j, 0, len) {
				ans[len] = (ans[len] * 2 + s[j] - '0') % MOD;
			}
			REP(j, 0, n) {
				d[j] = s[j % len];
				if ((j / len) % 2 == 1) {
					d[j] ^= 1;
				}
			}
			if (strcmp(d, s) <= 0) {
				ans[len] = (ans[len] + 1) % MOD;
			}
			REP(j, 0, SZ(divs[len])) {
				ans[len] = (ans[len] + MOD - ans[divs[len][j]]) % MOD;
			}
		}
	}
	ll sum = 0ll;
	REPN(i, 0, 2 * n) {
		sum = (sum + ans[i] * 2 * i) % MOD;
	}
