            else Pre[i][j] = i+1;
        }
    }

    for (k = 0; k < V; k++) {
        for (i = 0; i < V; i++) {
            for (j = 0; j < V; j++) {
                if (dist[i][k] + dist[k][j] < dist[i][j]) {
                    dist[i][j] = dist[i][k] + dist[k][j];
                    Pre[i][j] = Pre[k][j];
                }
            }
        }
    }

    printSolution();
    printPre();
}

void printSolution()
{
    printf ("Following matrix shows the shortest distances"
            " between every pair of vertices \n");
    for (int i = 0; i < V; i++)
    {
        for (int j = 0; j < V; j++)
        {
            if (dist[i][j] == INF)
                printf("%7s", "INF");
            else
                printf ("%7d", dist[i][j]);
        }
        printf("\n");
    }
}

void printPre()
{
    printf ("Following matrix shows the Pre \n");
    for (int i = 0; i < V; i++)
    {
        for (int j = 0; j < V; j++)
        {
            if (Pre[i][j] == INF)
                printf("%7s", "INF");
            else
                printf ("%7d", Pre[i][j]);
        }
        printf("\n");
    }
}

void findPath(int start, int end) {
    vector<int> paths;
    paths.push_back(end);
    while(Pre[start-1][end-1] != start) {
        paths.push_back(Pre[start-1][end-1]);
        end = Pre[start-1][end-1];
    }
    paths.push_back(start);
    printf("The path : ");
    for(int i = paths.size()-1;i >= 0;i--)
        printf("%i ", paths[i]);
    printf("\n");
}

