int minval(LL l,LL r){
    int ret=0;
    for(int i=59;~i;i--){
        if((l&(1ll<<i))==(r&(1ll<<i))) ret+=(l>>i)&1;
        else{ ret+=(l&((1ll<<i)-1))?1:0; break; }
    }
    return ret;
}

map<vector<LL>,vector<PLL> > Map;

void modify(int pos,LL k){
    if(k<0) return;
    LL w=INF; vector<LL> t;
    for(int i=1;i<=n;i++){
        t.pb(p[i].b-(i<=pos));
        chkmin(w,t.back());
    }
    if(w<0) return;
    for(int i=0;i<n;i++) t[i]-=w;
    sort(ALL(t));
    Map[t].pb(mp(max(w-k,0ll),w));
}

