    auto f = [&](double t) {
        double Mx = -inf, mx = inf;
        double My = -inf, my = inf;
        rep(i, n) {
            double nx = x[i], ny = y[i];
            if (d[i] == 'R') nx += t;
            else if (d[i] == 'L') nx -= t;
            else if (d[i] == 'U') ny += t;
            else ny -= t;
            chmax(Mx, nx);
            chmin(mx, nx);
            chmax(My, ny);
            chmin(my, ny);
        }
        return (Mx - mx) * (My - my);
    };
    double l = 0, r = inf;
    rep(_, 100) {
        double m1 = (l * 2 + r) / 3;
        double m2 = (l + r * 2) / 3;
        if (f(m1) < f(m2)) r = m2;
        else l = m1;
    }
    cout << fixed << setprecision(20) << f(l) << endl;
