bool BinarySearch(int A[], int n,int key) {
	int left = 0, right = n;
	int mid;
	while (left < right) {
		mid = (left + right) / 2;
		if (A[mid] > key) {
			right = mid;
		}
		else if (A[mid] < key) {
			left = mid+1;
		}
		else {
			return key == A[mid];
		}
	}
	return false;
}

