    for(i = 0; i < n; i++)
        scanf("%d", &a[i]);

    heapsize = n - 1;

    heap_sort(a, heapsize);

    printf("After Sorting: ");
    for(i = 0;i < n; i++)
        printf(" %d", a[i]);

    return 0;
}

