#include <malloc.h>
#include <stdio.h>
#include <stdbool.h>

#define ELEMENT_TYPE int
#define MAX_HEAP_CAPACITY 100

// 实现最大完全二叉堆

typedef struct max_heap_node {
    ELEMENT_TYPE *data; // 数据数组
    int size; // 堆的当前大小
} MaxHeap;

MaxHeap *mh_create() {
    MaxHeap *heap = (MaxHeap *) malloc(sizeof(MaxHeap));
    heap->data = (ELEMENT_TYPE *) malloc(MAX_HEAP_CAPACITY * sizeof(ELEMENT_TYPE));
    heap->size = 0;
    return heap;
}

// 堆化数据
void mh_heapify(MaxHeap *heap, int i) {
    ELEMENT_TYPE data = heap->data[i];
    int child;
    while (i * 2 <= heap->size) {
        child = i * 2;
        if (child != heap->size && heap->data[child] < heap->data[child + 1]) {
            child++;
        }
        if (data >= heap->data[child]) {
            break;
        }
        heap->data[i] = heap->data[child];
        i = child;
    }
    heap->data[i] = data;
}

// offer插入数据，同时利用 Adjust 上浮操作建堆
void mh_offer(MaxHeap *heap, ELEMENT_TYPE data) {
    if (heap->size == MAX_HEAP_CAPACITY) {
        printf("Heap is full.\n");
        return;
    }
    heap->data[++heap->size] = data;
    int i = heap->size;
    while (i != 1 && data > heap->data[i / 2]) {
        heap->data[i] = heap->data[i / 2];
        i /= 2;
    }
    heap->data[i] = data;
}

// 提取的同时 利用 Adjust 建堆
ELEMENT_TYPE mh_poll(MaxHeap *heap) {
    if (heap->size == 0) {
        printf("Heap is empty.\n");
        return -1;
    }
    ELEMENT_TYPE data = heap->data[1];
    heap->data[1] = heap->data[heap->size--];
    mh_heapify(heap, 1);
    return data;
}

ELEMENT_TYPE mh_peek(MaxHeap *heap) {
    if (heap->size == 0) {
        printf("Heap is empty.\n");
        return -1;
    }
    return heap->data[1];
}

bool mh_empty(MaxHeap *heap) {
    return heap->size == 0;
}

void mh_clear(MaxHeap *heap) {
    heap->size = 0;
}

void mh_print(MaxHeap *heap) {
    if (mh_empty(heap)) {
        printf("Heap is empty.\n");
        return;
    }
    for (int i = 1; i <= heap->size; i++) {
        printf("%d ", heap->data[i]);
    }
    printf("\n");
}

//Implementation of Quick Sort in C
#include <stdio.h>
#include <stdlib.h>
#define swap(t, x, y) { t z = x; x = y; y = z; }
typedef int TYPE;
int partition(TYPE [], int, int);
void quick_sort(TYPE [], int, int);
void print_array(TYPE [], int);

int main(){
	puts("-----Quick Sort-----");
	TYPE A[] = {2, 3, 4, 156, 12, 44, 55, 68, 11, 2673, 666};
	int n = sizeof(A) / sizeof(TYPE);
	
	printf("Unsorted: ");
	print_array(A, n);
	
	printf("Sorted: ");
	quick_sort(A, 0, n - 1);
	print_array(A, n);
	
	return EXIT_SUCCESS;
}
int partition(TYPE A[], int p, int r) {
	TYPE x = A[r]; //pivot
	int i = p - 1, j;
	for(j = p; j < r ; j++) {
		if(A[j] <= x) {
			i = i + 1;
			swap(TYPE, A[i], A[j]); 
		}
	}
	i = i + 1;
	swap(TYPE, A[i], A[r]);
	return i;
}
void quick_sort(TYPE A[], int p, int r) {
	if(p < r) {
		int t = (rand() % ( r - p + 1) + p);
		swap(TYPE, A[t], A[r]); 
		//Used to avoid O(n^2) worst case
		
		int q = partition(A, p, r);
		quick_sort(A, p, q - 1);
		quick_sort(A, q + 1, r);
	}
}
void print_array(TYPE A[], int n) {
	int i = 0;
	putchar('[');
	while(i < n) {
		if(i > 0) printf(", ");
		printf("%d", A[i++]); 
	}
	puts("]");
}

