		dfs(i);
	}
}

void go(int cur){
	//cout<<(char)cur<<endl;
	if(E==0)return;
	int successed=0;
	rep(i,N)if(g[cur][i]){
		g[cur][i]=0;
		fill(vis,vis+N,0);
		dfs(i);
		int ok=1;
		//rep(j,N)if(islower(j))cout<<(char)j<<vis[j]<<" ";cout<<endl;
