			if(in[j]>0 && !vis[j]){
				//cout<<(char)j<<" "<<in[j]<<endl;
				ok=0;break;
			}
		}
		//cout<<(char)cur<<"->"<<(char)i<<" ("<<E<<") :"<<(ok?"OK":"NG")<<endl;
		if(ok){
			if(successed){
				//cout<<"Found: "<<(char)successed<<endl;
				twoways=1;
				return;
			}
			successed=i;
			in[i]--;
			E--;
			go(i);
		}
		g[cur][i]=1;
		in[i]++;
		E++;
	}
}

