    sprintf(str2, "%d", *(int *)b);
    return strcmp(str1, str2);
}

int findKthNumber2(int n, int k) {
    int *arr = malloc(n * sizeof(int));
    for (int i = 0; i < n; ++i)
        arr[i] = i + 1;
    qsort(arr, n, sizeof(int), cmp);
    int result = arr[k - 1];
    free(arr);
    return result;
}
