            for (int j = 0; j < A.length; j++) {
                if ((A[j] & (1 << i)) >= 1) {
                    count++;
                }
            }
            ans += 2 * count * (A.length - count);
            ans = ans % mod;
        }

        return (int) ans;
    }
}

