package combinatorics;

import java.util.Arrays;

public class BracketSequences {
    public static boolean nextBracketSequence(char[] s) {
        int n = s.length;
        for (int i = n - 1, balance = 0; i >= 0; i--) {
            balance += s[i] == '(' ? -1 : 1;
            if (s[i] == '(' && balance > 0) {
                --balance;
                int open = (n - i - 1 - balance) / 2;
                int close = n - i - 1 - open;
                s[i] = ')';
                Arrays.fill(s, i + 1, i + 1 + open, '(');
                Arrays.fill(s, i + 1 + open, i + open + close, ')');
                return true;
            }
        }
        return false;
    }

    // Usage example
    public static void main(String[] args) {
        char[] s = "((()))".toCharArray();
        do {
            System.out.println(new String(s));
        } while (nextBracketSequence(s));
    }
}

#include <iostream>
using namespace std;

struct Dice {
    int a, b, c, d, e, f;
    void setFaces(int a, int b, int c, int d, int e, int f) {
        this->a = a;
        this->b = b;
        this->c = c;
        this->d = d;
        this->e = e;
        this->f = f;
    }
    void rotate(char dir) {
        switch (dir) {
            case 'N':
                setFaces(b, f, c, d, a, e);
                break;                
            case 'E':
                setFaces(d, b, a, f, e, c);
                break;                
            case 'S':
                setFaces(e, a, c, d, f, b);
                break;                
            case 'W':
                setFaces(c, b, f, a, e, d);
                break;
            case 'L':
                setFaces(a, d, b, e, c, f);
                break;
            case 'R':
                setFaces(a, c, e, b, d, f);
                break;
        }
    }
    void roll(string s) {
        for (int i=0; i<s.size(); i++)
            rotate(s[i]);
    }
    bool equal(Dice dice) {
        if (dice.a == a && dice.b == b && dice.c == c 
            && dice.d == d && dice.e == e && dice.f == f)
            return true;
        else
            return false;
    }
    bool equivalent(Dice dice) {
        string s = "EEEENEEEENEEEENEEEENLEEEELLEEEE";
        for (int i=0; i<s.size(); i++) {
            dice.rotate(s[i]);
            if (equal(dice))
                return true;
        }
        return false;
    }
};

int main() {
    int n, a, b, c, d, e, f;
    Dice dice[100];

    cin >> n;
    for (int i=0; i<n; i++) {
        cin >> a >> b >> c >> d >> e >> f;
        dice[i].setFaces(a, b, c, d, e, f);
    }

    bool flag = true;
    for (int i=0; i<n; i++)
        for (int j=i+1; j<n; j++)
            if (dice[i].equivalent(dice[j]))
                flag = false;

    if (flag)
        cout << "Yes" << endl;
    else
        cout << "No" << endl;
}

//Implementation of Selection sort in C
#include <stdio.h>
#include <stdlib.h>
#define swap(t, x, y) t z = x; x = y; y = z;
typedef int TYPE;
void selection_sort(TYPE [], int);
void print_array(TYPE [], int);

int main(){
	TYPE A[] = {16, 3, 154, 86, 11};
	int n = sizeof(A) / sizeof(TYPE);
	
	printf("Unsorted: ");
	print_array(A, n);
	
	printf("Sorted (descending): ");
	selection_sort(A, n);
	print_array(A, n);
	
	return EXIT_SUCCESS;
}

void selection_sort(TYPE A[], int n) {
	int i, j, max;
	for(i = 0; i < n - 1; i++) {
		max = i;
		for(j = i + 1; j < n; j++) {
			if(A[max] < A[j]) max = j;
		}
		if(max != i) { 
			swap(TYPE, A[i], A[max]); 
			// '{' and '}' are  needed when using macros inside condition
		}
	}
}
void print_array(TYPE A[], int n) {
	int i = 0;
	putchar('[');
	while(i < n) {
		if(i > 0) printf(", ");
		printf("%d", A[i++]); //first A[i] is done then i = i + 1
	}
