struct UnionFind
{
  vector<int> data;
  UnionFind(){}
  UnionFind(int sz):data(sz, -1){};
  int size(int x) { return -data[find(x)]; }
  int find(int x) { return data[x] < 0 ? x : data[x] = find(data[x]); }
  bool same(int x, int y) { return find(x) == find(y); }
  int unite(int x, int y)
  {
    x = find(x), y = find(y);
    if(x != y) {
      if(data[x] < data[y]) swap(x, y);
      data[x] += data[y]; data[y] = x;
    }
    return -data[x];
  }
  void init(int sz) {
    data.clear();
    data.resize(sz, -1);
  }
};

UnionFind uf;

int N, M;
vector<string> lang;
map<string, int> mp;
map<string, int> group;
vector<int> vec;
vector<string> ans;

bool input() {
  cin >> N >> M;
  if(!N && !M) return false;

  lang.clear();
  mp.clear();
  rep(i, N) {
    string l;
    cin >> l;
    lang.push_back(l);
    mp[l] = i;
  }

  vec.clear();
  group.clear();
  rep(i, M) {
    int k; cin >> k;
    int bit = 0;
    rep(j, k) {
      string l; cin >> l;
      bit |= 1<<mp[l];
      group[l] |= 1<<i;
    }
    vec.push_back(bit);
  }

  return true;
}

void solve(int idx, int bit) {
  if(__builtin_popcount(bit) > 5) return;
  if(uf.size(N) == __builtin_popcount(bit)+M) {
    if(ans.empty() || __builtin_popcountll(bit) < ans.size()) {
      ans.clear();
      rep(i, N) if((bit>>i)&1) ans.push_back(lang[i]);
    }
  }

  reps(i, idx, N) {
    if((bit>>i)&1) continue;
    UnionFind tmp = uf;
    rep(j, M) if((vec[j]>>i)&1) uf.unite(i, N+j);
    solve(i+1, bit|(1<<i));
    uf = tmp;
  }
}

