struct ListNode* reverseList(struct ListNode * head)
{
    struct ListNode* tail = NULL;
    struct ListNode* new_head = NULL;
    while(head){
        new_head = head;
        head = head->next;
        new_head->next = tail;
        tail = new_head;
    }
    tail = NULL;
    return new_head;
}

