void qsort(int l, int r)
{
	if (l < r)
	{
		int x = d[r];
		int j = l - 1;

		for (int i = l; i <= r; i++)
		{
			if (d[i] <= x)
			{
				j++;
				int temp = d[i];
				d[i] = d[j];
				d[j] = temp;
			}
		}

		qsort(l, j - 1);
		qsort(j + 1, r);
	}
}

