long long solve1(int x,int y,int p,int q)
{
	if(x>y||p>q)
	{
		if(x>y&&p>q)return 1ll;
		return 0ll;
	}
	if(vis1[x][y][p][q])return dp1[x][y][p][q];
	dp1[x][y][p][q]=0;
	for(int i=x;i<=y;i++)
		for(int j=p;j<=q;j++)
			dp1[x][y][p][q]+=solve2(x,i,j,q)*solve1(i+1,y,p,j-1);
	vis1[x][y][p][q]=true;
	return dp1[x][y][p][q];
}
long long solve2(int x,int y,int p,int q)
{
	if(vis2[x][y][p][q])return dp2[x][y][p][q];
	dp2[x][y][p][q]=0;
	for(int i=x;i<=y;i++)
		for(int j=p;j<=q;j++)
			if(A[i][j]=='1')
				dp2[x][y][p][q]+=solve1(x,i-1,i+1,y)*solve1(p,j-1,j+1,q);
	vis2[x][y][p][q]=true;
	return dp2[x][y][p][q];
}
