int fibonacci(int no)
{
    if (no <= 1)
    {
        return no; // Base cases: fibonacci(0) = 0, fibonacci(1) = 1
    }
    else
    {
        return fibonacci(no - 1) + fibonacci(no - 2); // Recursive case
    }
}

