__int128_t recursion(int n, __int128_t *map) {
    if (n == 1) {
        return 4;
    } else if (n == 2) {
        return 1;
    } else if (n == 3) {
        return -1;
    } else if (map[n] != 0) {
        return map[n];
    } else {
        map[n] = recursion(n - 1, map) - 4 * recursion(n - 2, map) + recursion(n - 3, map);
        return map[n];
    }
}

