int solve(int idx, vector<int>& arr, vector<int>& dp){
    if(idx >= arr.size()-1)
        return 0;
    if(dp[idx] != -1)
        return dp[idx];
    if(idx == arr.size()-2)
        return dp[idx] = abs(arr[idx]-arr[idx+1]);
    return dp[idx] = min(abs(arr[idx]-arr[idx+1])+solve(idx+1,arr,dp), 
        abs(arr[idx]-arr[idx+2])+solve(idx+2,arr,dp));
}
