var longestCommonPrefix = function(strs) {
  if(strs.length === 0) return "";

  return strs.reduce((result, curr)=>{
    let i = 0;
    while(result[i] && curr[i] && result[i] === curr[i]) i++;
    return result.slice(0, i);
  });
};

