pt linedist00(double x,double y,double vx,double vy){
	double l=(x*vy-y*vx)/(vx*vx+vy*vy);
	return pt(l*vy,-l*vx);
}
pair<double,pair<double,double> > culc(double r,double x,double y,double vx,double vy){
	pt p2=linedist00(x,y,vx,vy);
	double vv=dis(pt(0,0),pt(vx,vy));
	double d2=dis(pt(0,0),p2);
	if(d2 <= r*r){
		double l=r*r-d2;
		double t;
		if(vx==0 && vy==0) return pair<double,pair<double,double> >(INF,pair<double,double>(INF,INF));
		else if(vx==0) t= (p2.second-y)/vy;
		else t= (p2.first-x)/vx;
		double dt=sqrt(l/vv);
		return pair<double,pair<double,double> >(t-dt,pair<double,double>(t,t+dt));
	}else{
		return pair<double,pair<double,double> >(INF,pair<double,double>(INF,INF));
	}
}
