            ( dp[q][nj][nk][nz] += dp[p][j][k][z] ) %= mod;
            ( dp2[q][nj][nk][nz] +=
              (dp2[p][j][k][z] + add * dp[p][j][k][z] % mod) % mod ) %= mod;

          }
        }
      }
    }
  }
  int res = 0;
  for(int j = pattern.size()-1; j >= 0; --j) {
    for(int k = 0; k < 2; ++k) {
      for(int z = 0; z < 2; ++z) {
        ( res += dp2[X.size()%2][j][k][z] ) %= mod;
      }
    }
  }
  return res;
}

