void merge(int *nums1, int m, int *nums2, int n)
{
    int len = m + n;

    m--; n--;
    while(m >= 0 && n >= 0){
        if(nums1[m] > nums2[n]){
            nums1[--len] = nums1[m--];
        }else{
            nums1[--len] = nums2[n--];
        }
    }
    while(n >= 0){  // nums2 does not finished
        nums1[--len] = nums2[n--];
    }
}

