struct edge
{
    int u, v;
    double w;
    bool operator <(const edge &a) const
    {
        return (w>a.w);
    }
};

priority_queue<edge> pq_prim;

//Primov algoritam za racunanje minimalnog stabla razapinjanja datog tezinskog grafa
//Slozenost: O((V+E)log V)

inline int Prim()
{
    int xt = 0;
    int ret = 0;
    int amt = 0;
    while (amt < n-1)
    {
        mark[xt]=true;
        for (int i=0;i<graf[xt].adj.size();i++)
        {
            if (!mark[graf[xt].adj[i]])
            {
                edge E;
                E.u = xt;
                E.v = graf[xt].adj[i];
                E.w = graf[xt].weight[i];
                pq_prim.push(E);
            }
        }
        while (!pq_prim.empty())
        {
            edge X = pq_prim.top();
            pq_prim.pop();
            if (!mark[X.v])
            {
                ret += X.w;
                xt = X.v;
                amt++;
                break;
            }
        }
    }
    return ret;
}

