#define llint long long
#define inf 1e18

using namespace std;
typedef pair<double, pair<int, int> >  edge;

struct UnionFind{
	int size;
	vector<int> parent;
	
	UnionFind(){}
	UnionFind(int size){
		this->size = size;
		parent.resize(size+1);
		init();
	}
	void init(){
		for(int i = 0; i <= size; i++) parent[i] = i;
	}
	int root(int i){
		if(parent[i] == i) return i;
		return parent[i] = root(parent[i]);
	}
	bool same(int i, int j){
		return root(i) == root(j);
	}
	void unite(int i, int j){
		int root_i = root(i), root_j = root(j);
		if(root_i == root_j) return;
		parent[root_i] = root_j;
	}
};

llint N;
double x[15], y[15];
llint a[15];
double G[15][15];
vector<edge> E;
UnionFind uf(16);

double mst[1<<15];
double sum[1<<15];
double dp[1<<15];

int main(void)
{
	cin >> N;
	for(int i = 0; i < N; i++) cin >> x[i] >> y[i] >> a[i];
	for(int i = 0; i < N; i++){
		for(int j = 0; j < N; j++){
			if(i == j) G[i][j] = 0.0;
			else{
				G[i][j] = sqrt((x[i]-x[j])*(x[i]-x[j]) + (y[i]-y[j])*(y[i]-y[j]));
			}
		}
	}
	
	int S = 1 << N;
	for(int s = 0; s < S; s++){
		E.clear();
		for(int i = 0; i < N; i++){
			if((s & (1<<i)) == 0) continue; 
			for(int j = 0; j < N; j++){
				if(i >= j) continue;
				if((s & (1<<j)) == 0) continue; 
				E.push_back(make_pair(G[i][j], make_pair(i, j)));
			}
		}
		sort(E.begin(), E.end());
		uf.init();
		double sum = 0;
		for(int i = 0; i < E.size(); i++){
			edge e = E[i];
			if(uf.same(e.second.first, e.second.second)) continue;
			uf.unite(e.second.first, e.second.second);
			sum += e.first;
		}
		mst[s] = sum;
	}
	for(int s = 0; s < S; s++){
		for(int i = 0; i < N; i++){
			if(s & (1<<i)) sum[s] += a[i];
		}
	}
	
	vector<int> vec;
	dp[0] = -inf;
	for(int s = 1; s < S; s++){
		vec.clear();
		for(int i = 0; i < N; i++) if(s & (1<<i)) vec.push_back(i);
		int n = vec.size();
		dp[s] = (sum[s] - mst[s]) / n;
		for(int i = 0; i < (1<<n); i++){
			int bit = 0, cbit = 0;
			for(int j = 0; j < n; j++){
				if(i & (1<<j)) bit |= (1<<vec[j]);
				else cbit |= (1<<vec[j]);
			}
			dp[s] = max(dp[s], min(dp[bit], dp[cbit]));
		}
	}
	
	//for(int i = 1; i < S; i++) cout << dp[i] << " ";  cout << endl;
	
	printf("%.11f\n", dp[S-1]);
	return 0;
}

