    niz[6] = 3;

    InitTree(1, 1, n);
    printf("%d\n",Query(1, 1, 3, 1, n));

    Update(1, 4, 10, 1, n);
    Update(1, 5, 0, 1, n);
    printf("%d\n",Query(1, 4, 6, 1, n));

    return 0;
}

