#define DIV (60*60*12)

int N;
int cTos[60][60][60];
vector<vector<int> > secs;
int times[100];
pair<int,int> dfs(int idx, int times[100]){
	if(idx == N){
		int mins= 60 * 60 * 12;
		int maxs = 0;
		for(int i = 0; i < N; i++){
			mins = min(mins,times[i]);
			maxs = max(maxs, times[i]);
		}
		return pair<int,int>(mins, maxs);

	}else{
		pair<int, int> ans(0, 60*60*12);
		for(auto s : secs[idx]){
			times[idx] = s;
			pair<int, int> ret = dfs(idx + 1, times);
			if(ret.second - ret.first < ans.second - ans.first ||
				(ret.second - ret.first == ans.second - ans.first && ret.first < ans.first)){
				ans = ret;
			}
		}
		return ans;
	}
}

