#define MOD (ll)998244353

template<typename T>
struct SegTree{
    int num,bt;
    vector<T> node;

    void init(int num,T n){
        int i = 0,j=1;
        this->num = num;
        for (i = 0; j < num+1;i++)
            j*=2;
        j *= 2;
        bt = j / 2 - 1;

        node.resize((j - 1),0);
        for (int i = 0; i < num; i++){
            sett(i, n);
        }
    }
    inline T calc(T& a,T& b){
        return a + b;
    }
    void sett(int x,T n){
        int i = bt+x;
        node[i] = n;
        while(i!=0){
            i = (i - 1) / 2;
            node[i] = calc(node[i * 2 + 1],node[i * 2 + 2]);
        }
    }
    T gett(int x,int y){
        int i = bt+x;
        T sss = 0;
        if(x==0&&y==num-1){
            return node[0];
        }
        if(x!=0){
            int i = bt + x-1;
            int j = 1,l=x-1,r=x-1;
            while(i!=0){
                if(i%2&&x<=l+j&&r+j<=y){
                    sss = calc(node[i + 1],sss);
                }
                i = (i - 1) / 2;
                j *= 2;
                l = l / j*j;
                r = r / j*j+j-1;
            }
        }

        i = bt + y+1;
        int j = 1,l=y+1,r=y+1;
        while(i!=0){
            if(i%2==0&&x<=l-j&&r-j<=y){
                sss = calc(node[i - 1],sss);
            }
            i = (i - 1) / 2;
            j *= 2;
            l = l / j*j;
            r = r / j*j+j-1;
        }
        return sss;
    }
};


