template<typename T> inline void gn(T &x) {
    char ch=getchar(), pl=0; x=0;
    while(!isdigit(ch)) pl=(ch=='-'), ch=getchar();
    while(isdigit(ch)) x=x*10+ch-'0', ch=getchar(); x*=pl?-1:1;
}

int qpow(int x, int y) {
    int ret=1;
    while(y) {
        if(y&1) ret=1ll*ret*x%MOD;
        x=1ll*x*x%MOD, y>>=1;
    }
    return ret;
}

const int N=2e6+10;
int fac[N], finv[N];
int C(int x, int y) { return 1ll*fac[x]*finv[y]%MOD*finv[x-y]%MOD; }

int main() {
    finv[0]=fac[0]=fac[1]=finv[1]=1;
    for(int i=2; i<N; i++) finv[i]=MOD-1ll*MOD/i*finv[MOD%i]%MOD, fac[i]=1ll*i*fac[i-1]%MOD;
    for(int i=2; i<N; i++) finv[i]=1ll*finv[i]*finv[i-1]%MOD;
    int n, m;
    gn(n), gn(m);
    if(n<m) swap(n, m);
    int ans=0;
    for(int i=1; i<=m; i++) ans=(ans+1ll*C(2*i, i)*C(n+m-2*i, n-i))%MOD;
    ans=1ll*ans*qpow(C(n+m, m)*2, MOD-2)%MOD;
    (ans+=n)%=MOD;
    // printf("%d\n", (n+m-ans+MOD)%MOD);
    printf("%d\n", ans);
    return 0;
}

