function productExceptSelf(nums) {
    const n = nums.length;
    const result = new Array(n);

    // Calculate prefix products
    result[0] = 1;
    for (let i = 1; i < n; i++) {
        result[i] = result[i - 1] * nums[i - 1];
    }

    // Calculate suffix products and multiply with prefix products
    let suffixProduct = 1;
    for (let i = n - 1; i >= 0; i--) {
        result[i] *= suffixProduct;
        suffixProduct *= nums[i];
    }

    return result;
}

// Example usage:
const nums1 = [1, 2, 3, 4];
console.log(productExceptSelf(nums1)); // Output: [24, 12, 8, 6]

const nums2 = [-1, 1, 0, -3, 3];
console.log(productExceptSelf(nums2)); // Output: [0, 0, 9, 0, 0]

const nums3 = [1, 0];
console.log(productExceptSelf(nums3)); // Output: [0, 1]

const nums4 = [0, 0];
console.log(productExceptSelf(nums4)); // Output: [0, 0]

const nums5 = [2,3];
console.log(productExceptSelf(nums5)); // Output: [3,2]

const nums6 = [-1,1];
console.log(productExceptSelf(nums6)); // Output: [1,-1]

// Solution Explanation:
// The key idea is to calculate the product of all elements to the left of each element and the product of all elements to the right of each element. The 1  product except self is then the product of these two values.   

// Prefix Products: We first calculate the prefix products and store them in the result array. result[i] stores the product of all elements from nums[0] to nums[i-1].
// Suffix Products: Then, we iterate from right to left, calculating the suffix products. suffixProduct stores the product of all elements from nums[i+1] to nums[n-1].
// Final Calculation: In the same right-to-left loop, we multiply result[i] (the prefix product) by suffixProduct to get the final result.


// Time Complexity: O(n), as we iterate through the array twice.
// Space Complexity: O(n) because we use the result array to store the output. Note that the output array does not count towards extra space for the purpose of space complexity analysis. If we were not allowed to use the output array, and had to return the result in place, then the space complexity would be O(1)

/*

Source: https://leetcode.com/problems/check-if-a-string-contains-all-binary-codes-of-size-k/

Time: O(n)
Space: O(2 ^ k)

*/

class Solution {
  public static boolean hasAllCodes(String s, int k) {
    int need = 1 << k;
    boolean[] got = new boolean[need];
    int allOne = need - 1;
    int hashVal = 0;

    for (int i = 0; i < s.length(); i++) {
      hashVal = ((hashVal << 1) & allOne) | (s.charAt(i) - '0');
      if (i >= k - 1 && !got[hashVal]) {
        got[hashVal] = true;
        need--;
        if (need == 0) {
          return true;
        }
      }
    }
    return false;
  }
}

package com.thealgorithms.backtracking;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;

/**
 * The KnightsTour class solves the Knight's Tour problem using backtracking.
 *
 * Problem Statement:
 * Given an N*N board with a knight placed on the first block, the knight must
 * move according to chess rules and visit each square on the board exactly once.
 * The class outputs the sequence of moves for the knight.
 *
 * Example:
 * Input: N = 8 (8x8 chess board)
 * Output: The sequence of numbers representing the order in which the knight visits each square.
 */
public final class KnightsTour {
    private KnightsTour() {
    }

    // The size of the chess board (12x12 grid, with 2 extra rows/columns as a buffer around a 8x8 area)
    private static final int BASE = 12;

    // Possible moves for a knight in chess
    private static final int[][] MOVES = {
        {1, -2},
        {2, -1},
        {2, 1},
        {1, 2},
        {-1, 2},
        {-2, 1},
        {-2, -1},
        {-1, -2},
    };

    // Chess grid representing the board
    static int[][] grid;

    // Total number of cells the knight needs to visit
    static int total;

    /**
     * Resets the chess board to its initial state.
     * Initializes the grid with boundary cells marked as -1 and internal cells as 0.
     * Sets the total number of cells the knight needs to visit.
     */
    public static void resetBoard() {
        grid = new int[BASE][BASE];
        total = (BASE - 4) * (BASE - 4);
        for (int r = 0; r < BASE; r++) {
            for (int c = 0; c < BASE; c++) {
                if (r < 2 || r > BASE - 3 || c < 2 || c > BASE - 3) {
                    grid[r][c] = -1; // Mark boundary cells
                }
            }
        }
    }

    /**
     * Recursive method to solve the Knight's Tour problem.
     *
     * @param row   The current row of the knight
     * @param column The current column of the knight
     * @param count  The current move number
     * @return True if a solution is found, False otherwise
     */
    static boolean solve(int row, int column, int count) {
        if (count > total) {
            return true;
        }

        List<int[]> neighbor = neighbors(row, column);

        if (neighbor.isEmpty() && count != total) {
            return false;
        }

        // Sort neighbors by Warnsdorff's rule (fewest onward moves)
        neighbor.sort(Comparator.comparingInt(a -> a[2]));

        for (int[] nb : neighbor) {
            int nextRow = nb[0];
            int nextCol = nb[1];
            grid[nextRow][nextCol] = count;
            if (!orphanDetected(count, nextRow, nextCol) && solve(nextRow, nextCol, count + 1)) {
                return true;
            }
            grid[nextRow][nextCol] = 0; // Backtrack
        }

        return false;
    }

    /**
     * Returns a list of valid neighboring cells where the knight can move.
     *
     * @param row   The current row of the knight
     * @param column The current column of the knight
     * @return A list of arrays representing valid moves, where each array contains:
     *         {nextRow, nextCol, numberOfPossibleNextMoves}
     */
    static List<int[]> neighbors(int row, int column) {
        List<int[]> neighbour = new ArrayList<>();

        for (int[] m : MOVES) {
            int x = m[0];
            int y = m[1];
            if (row + y >= 0 && row + y < BASE && column + x >= 0 && column + x < BASE && grid[row + y][column + x] == 0) {
                int num = countNeighbors(row + y, column + x);
                neighbour.add(new int[] {row + y, column + x, num});
            }
        }
        return neighbour;
    }

    /**
     * Counts the number of possible valid moves for a knight from a given position.
     *
     * @param row    The row of the current position
     * @param column The column of the current position
     * @return The number of valid neighboring moves
     */
    static int countNeighbors(int row, int column) {
        int num = 0;
        for (int[] m : MOVES) {
            int x = m[0];
            int y = m[1];
            if (row + y >= 0 && row + y < BASE && column + x >= 0 && column + x < BASE && grid[row + y][column + x] == 0) {
                num++;
            }
        }
        return num;
    }

    /**
     * Detects if moving to a given position will create an orphan (a position with no further valid moves).
     *
     * @param count   The current move number
     * @param row     The row of the current position
     * @param column  The column of the current position
     * @return True if an orphan is detected, False otherwise
     */
    static boolean orphanDetected(int count, int row, int column) {
        if (count < total - 1) {
            List<int[]> neighbor = neighbors(row, column);
            for (int[] nb : neighbor) {
                if (countNeighbors(nb[0], nb[1]) == 0) {
                    return true;
                }
            }
        }
        return false;
    }
}

