void dfs1(int n, mat &G, vec &ord){
    int k(0);
    vector<int> iter(n, -1);
    stack<int> sta;
    rep(i, n) {
        if(iter[i] < 0) sta.push(i);
        while (!sta.empty()) {
            int v = sta.top();
            if ((++iter[v]) == G[v].size()) {
                ord[k++] = v;
                sta.pop();
            } else {
                int to = G[v][iter[v]];
                if(iter[to] < 0) sta.push(to);
            }
        }
    }
}
void dfs2(int n, mat &G, vec &ord, mat &res){
    int k(0);
    vector<bool> used(n, false);
    stack<int> sta;
    Rrep(i, n){
        int s = ord[i];
        if(!used[s]){
            used[s] = true;
            sta.push(s);
            while(!sta.empty()){
                int v = sta.top(); sta.pop();
                res[k].push_back(v);
                for(int to : G[v]) {
                    if(!used[to]) {
                        used[to] = true;
                        sta.push(to);
                    }
                }
            }
            ++k;
        }
    }
    res.resize(k);
}

