def convert_into_linearized_rep(parse, input_str):
    words = input_str.split(" ")
    brackets = get_node_brackets(parse)

    def fn(st, en):
        if st == en:
            return words[st]
        else:
            split_point = brackets[(st, en)]
            lc = fn(st, split_point)
            rc = fn(split_point + 1, en)
            return "( {} {} )".format(lc, rc)

    return fn(0, len(words) - 1)


