namespace flow_algorithm
{
  template<class Flow>
  struct edge
  {
    int to;
    Flow cap, rev;
  };
  
  /*
  template<class Flow>
  using edges = vector<edge<Flow>>;
  
  template<class Flow>
  using graph = vector<edges<Flow>>;
  */
  typedef vector<edge<ll>> edges;
  typedef vector<edges> graph;
  
  template<class Flow>
  class ford_fulkerson
  {
  private:
    
    int V;
    //    graph<Flow> g;
    graph g;
    vector<bool> used;
    
    //   Flow static constexpr Inf = numeric_limits<Flow>::max() / 4;
    
  private:
    
    Flow dfs(int curr, int tar, Flow flow) {
      if(curr == tar) { return flow; }
      used[curr] = true;
      rep(i, g[curr].size()) {
        edge<Flow>& e = g[curr][i];
        if(!used[e.to] && e.cap > 0) {
          Flow d = dfs(e.to, tar, min(flow, e.cap));
          if(d <= 0) { continue; }
          e.cap -= d;
          g[e.to][e.rev].cap += d;
          return d;
        }
      }
      return 0;
    }
    
  public:
    
    ford_fulkerson(int V_)
    {
      V = V_;
      g.resize(V_);
      used.resize(V_);
    }
    
    void add_edge(int from, int to, Flow cap)
    {
      g[from].push_back({to, cap, (Flow)g[to].size()});
      g[to].push_back({from, 0, (Flow)g[from].size()-1});
    }
    
    Flow max_flow(int s, int t)
    {
      Flow ret = 0;
      for(;;) {
        rep(i, V) used[i] = false;
        Flow f = dfs(s, t, Inf);
        if(f == 0) { return ret; }
        ret += f;
      }
    }
    
  };
}

