import numpy as np
from foronoi.graph import Coordinate


class Algebra:
    @staticmethod
    def distance(point_a, point_b):
        x1 = point_a.xd
        x2 = point_b.xd
        y1 = point_a.yd
        y2 = point_b.yd

        return np.sqrt((x2 - x1) ** 2 + (y2 - y1)**2)

    @staticmethod
    def magnitude(vector):
        return np.sqrt(np.dot(np.array(vector), np.array(vector)))

    @staticmethod
    def norm(vector):
        if Algebra.magnitude(np.array(vector)) == 0:
            return np.array(vector)
        return np.array(vector) / Algebra.magnitude(np.array(vector))

    @staticmethod
    def line_ray_intersection_point(ray_orig, ray_end, point_1, point_2):
        # Convert to numpy arrays
        orig = np.array(ray_orig, dtype=float)
        end = np.array(ray_end, dtype=float)
        direction = np.array(Algebra.norm(end - orig), dtype=float)
        point_1 = np.array(point_1, dtype=float)
        point_2 = np.array(point_2, dtype=float)

        # Ray-Line Segment Intersection Test in 2D
        # http://bit.ly/1CoxdrG
        v1 = orig - point_1
        v2 = point_2 - point_1
        v3 = np.array([-direction[1], direction[0]])

        if np.dot(v2, v3) == 0:
            return []

        t1 = np.cross(v2, v1) / np.dot(v2, v3)
        t2 = np.dot(v1, v3) / np.dot(v2, v3)

        if t1 > 0.0 and 0.0 <= t2 <= 1.0:
            return [orig + t1 * direction]
        return []

    @staticmethod
    def get_intersection(orig: Coordinate, end: Coordinate, p1: Coordinate, p2: Coordinate):
        if not orig or not end:
            return None

        point = Algebra.line_ray_intersection_point([orig.xd, orig.yd], [end.xd, end.yd], [p1.xd, p1.yd], [p2.xd, p2.yd])

        if len(point) == 0:
            return None

        return Coordinate(point[0][0], point[0][1])

    @staticmethod
    def calculate_angle(point, center):
        dx = point.xd - center.xd
        dy = point.yd - center.yd
        return np.math.degrees(np.math.atan2(dy, dx)) % 360

    @staticmethod
    def check_clockwise(a, b, c, center):
        angle_1 = Algebra.calculate_angle(a, center)
        angle_2 = Algebra.calculate_angle(b, center)
        angle_3 = Algebra.calculate_angle(c, center)

        counter_clockwise = (angle_3 - angle_1) % 360 > (angle_3 - angle_2) % 360

        if counter_clockwise:
            return False

        return True


