function item_getter_key(x, desc, func_when_eq) {
    var sign = 1;
    if (desc) {
        sign = -1;
    }
    return function (a, b) {
        if (a[x] < b[x]) return -1 * sign;
        else if (a[x] > b[x]) return sign;

        if (func_when_eq === undefined) {
            return 0;
        } else {
            return func_when_eq(a, b);
        }
    };
}


