	a[y][x] = -1;
	for (int k = 0; k < 6; k++) {
		int _x = x + dx[k], _y = y + dy[k];
		if (_y >= 0 && _y < N && _x >= 0 && _x <= _y && a[_y][_x] == C)
			dfs(N, C, _x, _y, a);
	}
