int f(int N, int C, vector< vector<int> > a) {
	for (int y = 0; y < N; y++)
		for (int x = 0; x <= y; x++) {
			if (a[y][x] != 0) continue;
			for (int k = 0; k < 6; k++) {
				int _x = x + dx[k], _y = y + dy[k];
				if (_y >= 0 && _y < N && _x >= 0 && _x <= _y && a[_y][_x] > 0)
					dfs(N, a[_y][_x], _x, _y, a);
			}
		}
