  // findStronglyConnectedComponents
  // Requirement: Detect strongly connected todo dependency groups using Tarjan's algorithm.
  class TodoApp {
    constructor() {
      this.graph = new Map();
    }

    addTodo(name) {
      this.graph.set(name, []);
    }

    addDependency(from, to) {
      this.graph.get(from).push(to);
    }

    findStronglyConnectedComponents() {
      let index = 0;

      const stack = [];
      const onStack = new Set();

      const indexes = new Map();
      const lowLinks = new Map();

      const components = [];

      const visit = (node) => {
        indexes.set(node, index);
        lowLinks.set(node, index);

        index++;

        stack.push(node);
        onStack.add(node);

        for (const next of this.graph.get(node)) {
          if (!indexes.has(next)) {
            visit(next);

            lowLinks.set(
              node,
              Math.min(lowLinks.get(node), lowLinks.get(next)),
            );
          } else if (onStack.has(next)) {
            lowLinks.set(node, Math.min(lowLinks.get(node), indexes.get(next)));
          }
        }

        if (lowLinks.get(node) === indexes.get(node)) {
          const component = [];

          let current;

          do {
            current = stack.pop();
            onStack.delete(current);
            component.push(current);
          } while (current !== node);

          components.push(component);
        }
      };

      for (const node of this.graph.keys()) {
        if (!indexes.has(node)) {
          visit(node);
        }
      }

      return components;
    }
  }

  // Example
  const myTodos = new TodoApp();

  for (const name of ["A", "B", "C", "D"]) {
    myTodos.addTodo(name);
  }

