ll rec(ll h, ll w){
    ll sum = 0;
    if(h % w == 0){
        sum += h / w * 2 * w - w;
    }
    else{
        sum += h / w * 2 * w;
        sum += rec(w, h - h / w * w);
    }
    return sum;
}

