def relativeSortArray(self, arr1: List[int], arr2: List[int]) -> List[int]:
    # counter the arr1 and sort
    arrCounter = Counter(arr1)
    arr1.sort()
    
    setArr2=set(arr2)
    res = []
    for num in arr2:
        if num in arrCounter:
            res.extend([num]*arrCounter[num])

    for num in arr1:
        if num not in setArr2:
            res.append(num)

    return res

# Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def deep(self, root: Optional[TreeNode], deep=0) -> int:
        if not root:
            return deep
        deep += 1
        return max(self.deep(root.left, deep), self.deep(root.right, deep))

    def maxDepth(self, root: Optional[TreeNode]) -> int:
        return self.deep(root)

