int leVetor(int ** v) {
    int i, input, size;

    scanf("%d", &size);

    if(size < 1) {
        printf("erro\n");
        exit(0);
    }

    *v = (int *) calloc(size, sizeof(int));

    for(i = 0; i < size; i++) {
        scanf("%d", &input);
        if(elementoExiste(*v, size, input)) {
            (*v)[i] = input;
        } else {
            printf("erro\n");
            exit(0);
        }
    }

    return size;
}

