        obj.addNode(13);
        obj.addNode(17);
        obj.addNode(19);
        System.out.println("Inorder of original Tree");
        obj.inorder(obj.root);

        System.out.println();
        System.out.println("Inorder of original Tree");
        Node mirror_node;
        mirror_node = obj.mirror();
        obj.inorder(mirror_node);

    }
}

