    cin >> N;
    for(int i = 1; i <= N; i++){
        cin >> a[i] >> b[i];
        add_edge(0, i, 1);
    }
    for(int i = 1; i <= N; i++){
        cin >> c[i] >> d[i];
        add_edge(N+i, 2*N+1, 1);
    }
    for(int i = 1; i <= N; i++){
        for(int j = 1; j <= N; j++){
            if(a[i] < c[j] && b[i] < d[j]){
                add_edge(i, N+j, 1);
            }
        }
    }
    int flow = 0;
    while(true){
        memset(used, 0, sizeof(used));
        int f = dfs(0, 2*N+1, INF, G);
        if(f == 0){
            cout << flow << endl;
            break;
        }
        flow += f;
    }
}

