// delete element in single LinkedList at beginning
void deleteAtBeg() {
    printf("\n ===> Delete At Beginning <=== \n");

    temp = head;
    head = head ->next;
    free(temp);
}

// delete element in single LinkedList at end
void deleteAtEnd() {
    printf("\n ===> Delete At End <=== \n");

    struct node *prevnode;
    temp = head;

    while(temp -> next != 0) {
        prevnode = temp;
        temp = temp ->next;
    }

    if(temp == head) {
        head = 0;
    } else {
        prevnode = 0;
        free(temp);
    }
}

