void bubbleSort(int* array, int size) {
    int temp;
    for (int pass = 0; pass < size - 1; pass++) { 
        printf("Working on pass number %d\n", pass + 1);
        for (int i = 0; i < size - 1 - pass; i++) { 
            if (array[i] > array[i + 1]) {
                temp = array[i];
                array[i] = array[i + 1];
                array[i + 1] = temp;
            }
        }
    }
}

void bubbleSortAdaptive(int* array, int size) {
    int temp;
    int isAlreadySorted;
    for (int pass = 0; pass < size - 1; pass++) { 
        printf("Working on pass number %d\n", pass + 1);
        isAlreadySorted = 1; 
        for (int i = 0; i < size - 1 - pass; i++) { 
            if (array[i] > array[i + 1]) {
                temp = array[i];
                array[i] = array[i + 1];
                array[i + 1] = temp;
                isAlreadySorted = 0; 
            }
        }
        if (isAlreadySorted) {
            return;
        }
    }
}

