using namespace std;
typedef long long ll;
const ll MAX = 2 * 100010;

int N;
ll A[MAX];

int main() {
    cin >> N;
    for (int i=1; i<=N; i++) {
        cin >> A[i];
    }

    for (int i=0; i<N; i++) {
        A[i+1] += A[i];
    }

    ll answer = 1e18;
    for (int i=2; i<N; i++) {
        int left = 0;
        int right = i;
        while (1 < right - left) {
            int mid = (right + left)/2;
            if (A[mid] < A[i] - A[mid]) {
                left = mid;
            } else {
                right = mid;
            }
        }
        ll B = A[left];
        ll C = A[i] - A[left];
        ll B2 = A[right];
        ll C2 = A[i] - A[right];
        ll lmin = min(B,C);
        ll lmax = max(B,C);
        if (abs(B2-C2) < abs(B-C)) {
            lmin = min(B2,C2);
            lmax = max(B2,C2);
        }

        left = i;
        right = N;
        while (1 < right - left) {
            int mid = (right + left)/2;
            if (A[mid] - A[i] < A[N] - A[mid]) {
                left = mid;
            } else {
                right = mid;
            }
        }
        ll D = A[left] - A[i];
        ll E = A[N] - A[left];
        ll D2 = A[right] - A[i];
        ll E2 = A[N] - A[right];
        ll rmin = min(D,E);
        ll rmax = max(D,E);
        if (abs(D2-E2) < abs(D-E)) {
            rmin = min(D2,E2);
            rmax = max(D2,E2);
        }
        answer = min(answer, max(lmax, rmax) - min(lmin, rmin));
    }
    cout << answer << endl;
}

