            // what happens if one of these cut off a square for another one? Actually that should be impossible.
            if (rd == 1 || cd == 1) {
                pos = 0;
                break;
            }
            ll avail = max(0ll, (rd * cd) - (n * m - i));
            pos *= avail;
            pos %= MOD;
            if (!pos) break;
        }
        // cout << x << ' ' << y << '\n';
        // cout << i << ' ' << pos << '\n';
    }

    cout << pos;
}

