function bigAdd(A, B)
{
    var m, n, mn, i, j, carry, tmp;
    var buf, a1, a2;
    
    if(A.length > B.length){
        m = A.length;
        n = B.length;
        a1 = A.split("");
        a2 = B.split("");
    }
    else{
        m = B.length;
        n = A.length;
        a1 = B.split("");
        a2 = A.split("");
    }
    
    if( m > 80 ){
        console.log("overflow");
        return;
    }
    
    mn = m + 1;
    buf = new Array(mn);
    for(j=m-1,i=n-1,carry=0;i>=0;--i,--j){
        tmp = parseInt(a1[j]) + parseInt(a2[i]) + carry;
        buf[j+1] = tmp % 10;
        carry = parseInt(tmp / 10);
    }
    // Rest
    for(;j>=0;--j){
        tmp = parseInt(a1[j]) + carry;
        buf[j+1] = tmp % 10;
        carry = parseInt(tmp / 10);
    }
    buf[0] = carry;
    
    if( carry > 0 ){
        if( m == 80 ){
            console.log("overflow");
        }
        else{
            console.log(buf.join(""));
        }
    }
    else{
        console.log(buf.slice(1,mn).join(""));
    }
}

