//Mozemo uzimati beskonacno od svake vrste predmeta
//Slozenost O(n*K)

inline int Knapsack()
{
    Sol[0] = 0;
    for (int i=1;i<=capacity;i++)
    {
        int maks = 0;
        int tek;
        for (int j=0;j<n;j++)
        {
            if (Weight[j] <= i)
            {
                tek = Value[j] + Sol[i-Weight[j]];
                if (tek > maks) maks = tek;
            }
        }
        Sol[i] = maks;
    }
    return Sol[capacity];
}

