class Solution:
    def mergeTwoLists(self, list1: Optional[ListNode], list2: Optional[ListNode]) -> Optional[ListNode]:
        result = dummy = ListNode()
        def merge(l1, l2, result):
            if l1 == None:
                result.next = l2
                return result
            if l2 == None:
                result.next = l1
                return result
            if l1.val < l2.val:
                result.next = l1
                result = result.next
                l1 = l1.next
                return merge(l1, l2, result)
            else:
                result.next = l2
                result = result.next
                l2 = l2.next
                return merge(l1, l2, result)
        merge(list1, list2, result)
        return dummy.next

class Solution:
    def search(self, nums: List[int], target: int) -> int:
        l , r = 0 , len(nums) - 1

        while l <= r:
            mid = (l+r)//2

            if nums[mid] == target:
                return mid
            elif nums[l] <= nums[mid]:
                if nums[l] <= target < nums[mid]:
                    r = mid - 1
                else:
                    l = mid + 1
            elif nums[mid] <= nums[r]:
                if nums[mid] < target <= nums[r]:
                    l = mid +1
                else:
                    r = mid -1
                    
        return -1

import java.io.*;
import java.util.Collection;
