        while j < len(arr2) and pos < len(arr1):
            i = pos
            while i < len(arr1):
                if arr1[i] == arr2[j]:
                    arr1[pos], arr1[i] = arr1[i], arr1[pos]
                    pos += 1
                i += 1
            j += 1
        
        k=len(arr2)-1
        while ( k in range(len(arr1))) and (arr1[k] in arr2):
