struct Edge {
    int from, to, cost;
    Edge(int a, int b, int c) : from(a), to(b), cost(c) {}
    bool operator<(const Edge &x) const {
        return cost < x.cost;
    }
};

struct UnionFind {
    int node[1010];
    UnionFind() {
        memset(node, -1, sizeof(node));
    }
    int find(int x) {
        return node[x] < 0 ? x : node[x] = find(node[x]);
    }
    int size(int x) {
        return -node[find(x)];
    }
    bool unite(int x, int y) {
        x = find(x), y = find(y);
        if(x == y) return false;
        if(size(x) > size(y)) swap(x, y);
        node[y] += node[x];
        node[x] = y;
        return true;
    }
};

