using namespace std;
const int INF = 1 << 30;

struct Dinic
{


  struct edge
  {
    int to, cap, rev;
  };

  vector< vector< edge > > graph;
  vector< int > min_cost, iter;

  Dinic(int n)
  {
    graph.resize(n);
  }

  void add_edge(int from, int to, int cap)
  {
    graph[from].push_back((edge) {to, cap, (int) graph[to].size()});
    graph[to].push_back((edge) {from, 0, (int) graph[from].size() - 1});
  }

  bool bfs(int s, int t)
  {
    min_cost.assign(graph.size(), -1);
    queue< int > que;
    min_cost[s] = 0;
    que.push(s);
    while(!que.empty()) {
      int p = que.front();
      que.pop();
      for(int i = 0; i < graph[p].size(); i++) {
        const edge &e = graph[p][i];
        if(e.cap > 0 && min_cost[e.to] == -1) {
          min_cost[e.to] = min_cost[p] + 1;
          que.push(e.to);
        }
      }
    }
    return (min_cost[t] != -1);
  }

  int dfs(int idx, const int t, int flow)
  {
    if(idx == t) return (flow);
    for(int &i = iter[idx]; i < graph[idx].size(); i++) {
      edge &e = graph[idx][i];
      if(e.cap > 0 && min_cost[idx] < min_cost[e.to]) {
        int d = dfs(e.to, t, min(flow, e.cap));
        if(d > 0) {
          e.cap -= d;
          graph[e.to][e.rev].cap += d;
          return (d);
        }
      }
    }
    return (0);
  }

  int max_flow(int s, int t)
  {
    int flow = 0;
    while(bfs(s, t)) {
      iter.assign(graph.size(), 0);
      int f = 0;
      while((f = dfs(s, t, INF)) > 0) {
        flow += f;
      }
    }
    return (flow);
  }
};

int main()
{
  int H, W;
  string S[100];

  cin >> H >> W;
  for(int i = 0; i < H; i++) {
    cin >> S[i];
  }
  Dinic flow(H * W * 2);
  int add = H * W;
  auto to = [&](int y, int x, bool in)
  {
    if(in) return (y * W + x + add);
    return (y * W + x);
  };

  int s, t;

  for(int i = 0; i < H; i++) {
    for(int j = 0; j < W; j++) {
      if(S[i][j] == 'S') s = to(i, j, false);
      if(S[i][j] == 'T') t = to(i, j, true);

      if(S[i][j] != '.') {
        flow.add_edge(to(i, j, true), to(i, j, false), 1);
        for(int k = 0; k < H; k++) {
          if(i == k) continue;
          if(S[k][j] != '.') {
            flow.add_edge(to(i, j, false), to(k, j, true), INF);
          }
        }
      }
      if(S[i][j] != '.') {
        for(int k = 0; k < W; k++) {
          if(j == k) continue;
          if(S[i][k] != '.') {
            flow.add_edge(to(i, j, false), to(i, k, true), INF);
          }
        }
      }
    }
  }
  auto get = flow.max_flow(s, t);
  if(get >= INF) {
    cout << -1 << endl;
  } else {
    cout << get << endl;
  }
}

