package com.freetymekiyan.algorithms.level.hard;

import java.util.ArrayList;
import java.util.List;

/**
 * N-Queens
 * The n-queens puzzle is the problem of placing n queens on an n×n chessboard such that no two queens attack each
 * other.
 * Given an integer n, return all distinct solutions to the n-queens puzzle.
 * Each solution contains a distinct board configuration of the n-queens' placement, where 'Q' and '.' both indicate a
 * queen and an empty space respectively.
 * For example,
 * There exist two distinct solutions to the 4-queens puzzle:
 * <p>
 * [
 * [".Q..",  // Solution 1
 * "...Q",
 * "Q...",
 * "..Q."],
 * ["..Q.",  // Solution 2
 * "Q...",
 * "...Q",
 * ".Q.."]
 * ]
 * Tags:  Backtracking
 * Similar Problems:(H) N-Queens II
 *
 * @auther chenshuna
 */

class NQueens {

    public static List<List<String>> solveNQueens(int n) {
        List<List<String>> res = new ArrayList<List<String>>();
        int[] board = new int[n];
        queenDFS(n, 0, board, res);
        return res;
    }

    public static void queenDFS(int nrow, int row, int[] board, List<List<String>> res) {
        if (nrow == row) {
            List<String> s1 = new ArrayList<String>();
            for (int i = 0; i < nrow; i++) {
                StringBuilder s2 = new StringBuilder();
                for (int j = 0; j < nrow; j++) {
                    if (board[i] == j) {
                        s2.append('Q');
                    } else {
                        s2.append('.');
                    }
                }
                s1.add(s2.toString());
            }
            res.add(s1);
            return;
        } else {
            for (int i = 0; i < nrow; i++) {
                board[row] = i;
                if (isValid(row, board)) {
                    queenDFS(nrow, row + 1, board, res);
                }
            }
        }
    }

    public static boolean isValid(int row, int[] board) {
        for (int i = 0; i < row; i++) {
            if (board[row] == board[i] || Math.abs(board[row] - board[i]) == row - i) {
                return false;
            }
        }
        return true;
    }

    /**
     * N-Queens II
     * Follow up for N-Queens problem.
     * Now, instead outputting board configurations, return the total number of distinct solutions.
     */

    public static int totalNQueens(int n) {
        int res[] = {0};
        int[] board = new int[n];
        totalNQueensDFS(n, 0, board, res);
        return res[0];
    }

    public static void totalNQueensDFS(int nrow, int row, int[] board, int[] res) {
        if (row == nrow) {
            res[0]++;
        } else {
            for (int i = 0; i < nrow; i++) {
                board[row] = i;
                if (isValid(row, board)) {
                    totalNQueensDFS(nrow, row + 1, board, res);
                }
            }
        }
    }

    public static void main(String[] args) {
        System.out.print(solveNQueens(4));
        System.out.print(totalNQueens(4));
    }
}

/*
 * Problem: 
 * Given an unsorted array of integers, find a pair with given sum in it.
 * For example,
 * Input:
 * arr = [8, 7, 2, 5, 3, 1]
 * sum = 10
 *
 * Output: 
 * Pair found at index 0 and 2 (8 + 2)
 * OR
 * Pair found at index 1 and 4 (7 + 3)
 */


#include <iostream>
#include <vector>
#include <unordered_map>


void printPairWithSum(const std::vector<int>& arr, const int sum)
{
    std::unordered_map<int, int> hashMap;
    bool found = false;
    for (unsigned int i = 0; i < arr.size(); ++i)
    {
        // We need to check if pair(arr[i], sum-arr[i]) already
        // exists in the map
        //
        if (hashMap.find(sum-arr[i]) != hashMap.end())
        {
            std::cout << "Found pair with sum: " << sum
                << " with values (" << sum-arr[i] << " ," << arr[i]
                << ") at indices (" <<  hashMap[sum-arr[i]] << " ,"
                << i << ")" << std::endl;
            found = true;
        }
        hashMap[arr[i]] = i;
    }
    if (!found) std::cout << "Pair not found\n";
}

int main()
{
    std::vector<int> arr {8, 7, 2, 5, 3, 1};
    printPairWithSum(arr, 10);
    return 0;
}

from __future__ import annotations

# built-in
from itertools import takewhile
from typing import Sequence

# app
from .base import Base as _Base, BaseSimilarity as _BaseSimilarity
from .types import SimFunc


__all__ = [
    'Prefix', 'Postfix', 'Length', 'Identity', 'Matrix',
    'prefix', 'postfix', 'length', 'identity', 'matrix',
]


class Prefix(_BaseSimilarity):
    """prefix similarity
    """

    def __init__(self, qval: int = 1, sim_test: SimFunc = None) -> None:
        self.qval = qval
        self.sim_test = sim_test or self._ident

    def __call__(self, *sequences: Sequence) -> Sequence:
        if not sequences:
            return ''
        sequences = self._get_sequences(*sequences)

        def test(seq):
            return self.sim_test(*seq)

        result = [c[0] for c in takewhile(test, zip(*sequences))]

        s = sequences[0]
        if isinstance(s, str):
            return ''.join(result)
        if isinstance(s, bytes):
            return b''.join(result)
        return result

    def similarity(self, *sequences: Sequence) -> int:
        return len(self(*sequences))


class Postfix(Prefix):
    """postfix similarity
    """

    def __call__(self, *sequences: Sequence) -> Sequence:
        s = sequences[0]
        sequences = [list(reversed(s)) for s in sequences]
        result = reversed(super().__call__(*sequences))
        if isinstance(s, str):
            return ''.join(result)
        if isinstance(s, bytes):
            return b''.join(result)
        return list(result)


class Length(_Base):
    """Length distance
    """

    def __call__(self, *sequences: Sequence) -> int:
        lengths = list(map(len, sequences))
        return max(lengths) - min(lengths)


class Identity(_BaseSimilarity):
    """Identity similarity
    """

    def maximum(self, *sequences: Sequence) -> int:
        return 1

    def __call__(self, *sequences: Sequence) -> int:
        return int(self._ident(*sequences))


class Matrix(_BaseSimilarity):
    """Matrix similarity
    """

    def __init__(
        self,
        mat=None,
        mismatch_cost: int = 0,
        match_cost: int = 1,
        symmetric: bool = True,
        external: bool = True,
    ) -> None:
        self.mat = mat
        self.mismatch_cost = mismatch_cost
        self.match_cost = match_cost
        self.symmetric = symmetric

    def maximum(self, *sequences: Sequence) -> int:
        return self.match_cost

    def __call__(self, *sequences: Sequence) -> int:
        if not self.mat:
            if self._ident(*sequences):
                return self.match_cost
            return self.mismatch_cost

        # search in matrix
        if sequences in self.mat:
            return self.mat[sequences]
        # search in symmetric matrix
        if self.symmetric:
            sequences = tuple(reversed(sequences))
            if sequences in self.mat:
                return self.mat[sequences]
        # if identity then return match_cost
        if self._ident(*sequences):
            return self.match_cost
        # not found
        return self.mismatch_cost


prefix = Prefix()
postfix = Postfix()
length = Length()
identity = Identity()
matrix = Matrix()

