// Example 1:
// Use echo.key() to track variables across iterations in a loop.
function binarySearch(key, array) {
  let lo = 0;
  let hi = array.length - 1;
  while (lo <= hi) {
    const mi = (lo + hi) >>> 1;
    const val = array[mi];
    echo.key("lo")(lo);
    echo.key("hi")(hi);
    echo.key("mi")(mi);
    echo.key("val")(val);
    if (val < key) lo = mi + 1;
    else if (val > key) hi = mi - 1;
    else return mi;
  }
  return -1;
}

