P dfs(int x,int d){
  ull res1=0;
  int res2=d;
  
  rep(i,G[x].size()){
    P r=dfs(G[x][i],d+1);
    res1+=r.first*A[maxd[x]-r.second];
    res2=max(res2,r.second);
  }
  res1+=A[res2-d];
  
  if(S.count(res1))S[res1]++;
  else S[res1]=1;
  
  return P(res1,res2);
}

