int getLength(struct ListNode *head){
    /* Input Validation */
    if (head == NULL) { 
       printf("Error : Invalid ListNode pointer !!!\n");       
       return 0;  
    }
      
    int length =0;
    while(head != NULL){
        head = head->next;
        length++;
    }
    return length;
}


int checkLoop(struct ListNode *head) {
    struct ListNode *slow, *fast;
    slow = fast = head;
   
    while(fast && fast->next) {
        /* Slow pointer will move one node per iteration whereas fast node will move two nodes per iteration */
        slow = slow->next;
        fast  = fast->next->next;
        if (slow == fast) {
           printf("\n Linked list contains a loop\n");
           return 1;
        }
    }
    printf("\n No loop in linked list\n");
    return 0;
}

int loopLength(struct ListNode * head) {
    struct ListNode *slow = head, *fast = head;
    int loopExists = 0, counter = 0;
    while (fast && fast->next) {
        slow = slow->next;
        fast = fast->next->next;
        if (slow == fast){
            loopExists = 1;
            break;
        }
    }
    if(loopExists) {
        counter = 1;
        fast = fast->next;
        while(slow  != fast) {
            fast = fast->next;
            counter++;  
        }
        return counter;
    }
    return 0;
}

