void merge(int A[],int l,int mid,int h){
	int i,j,k;
	i=l;
	k=0;
	j=mid+1;
	int B[100];
	while(i<=mid && j<=h){
		if(A[i]<A[j]){
			B[k++]=A[i++];
		}else{
			B[k++]=A[j++];
		}
	}
	while(i<=mid){
		B[k++]=A[i++];
	}
	while(j<=h){
		B[k++]=A[j++];
	}
	k=0;
	for(i=l;i<=h;i++){
		A[i]=B[k++];
	}
}

void mergeSort(int A[],int l,int h){
	if(l<h){
		int mid=(l+h)/2;
		mergeSort(A,l,mid);
		mergeSort(A,mid+1,h);
		merge(A,l,mid,h);
			
	}

}


