//Problem: https://www.hackerrank.com/challenges/luck-balance
//Java 8
/*
Initial Thoughts:
We should automatically lose all unimportant contest
to increase our rating, and then we should lose the
k highest luck contests. The sum of all these contests
will give us the maximum luck we can achieve before 
the competition

To do this, we would need to sort the important contest
by their luck descending and add the first k and subtract
the rest

Time Complexity: O(n log(n)) //We have to sort the important contest then do n iterations
Space Complexity: O(1) //Considering the inputs as given

*/
import java.io.*;
import java.util.*;
import java.text.*;
import java.math.*;
import java.util.regex.*;

public class Solution { 

    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);
        ///////Variables//////
        int n = input.nextInt();
        int k = input.nextInt();
        int maxLuck = 0;
        ArrayList<Integer> importantContests = new ArrayList<>();
        //////////////////////

        //Build list of important contests
        for(int i = 0; i < n; i++){
            int luck = input.nextInt();
            int important = input.nextInt();

            if(important != 1)
            {
                maxLuck += luck;
            } 

            else
                importantContests.add(luck);
        }

        //Sort the important contests in descending order
        Collections.sort(importantContests, Collections.reverseOrder());

        //Lose the k largest contests and win the rest
        for(int i = 0; i < importantContests.size(); i++){
            if(i < k)
                maxLuck += importantContests.get(i);            
            else
                maxLuck -= importantContests.get(i);                
        }

        System.out.println(maxLuck);
    }
}

def madd(x, y):
    return (x[0]+y[0])%M, (x[1]+y[1])%M, (x[2]+y[2])%M, (x[3]+y[3])%M

def mmul(x, y):
    return (x[0]*y[0]+x[1]*y[2])%M, (x[0]*y[1]+x[1]*y[3])%M, (x[2]*y[0]+x[3]*y[2])%M, (x[2]*y[1]+x[3]*y[3])%M

def mpow(x, n):
    if n == 0: return 1, 0, 0, 1
    if n%2: return mmul(x, mpow(x, n-1))
    return mmul(t:=mpow(x, n//2), t)

class Node:
    def __init__(s, l, r):
        s.l = l; s.r = r; s.lc = s.rc = None; s.s = s.z = 1, 0, 0, 1
    def push(s):
        if s.l == s.r: return
        mi = (s.l+s.r)//2
        if not s.lc: s.lc = Node(s.l, mi); s.rc = Node(mi+1, s.r)
        s.lc.s = mmul(s.lc.s, s.z); s.lc.z = mmul(s.lc.z, s.z); s.rc.s = mmul(s.rc.s, s.z); s.rc.z = mmul(s.rc.z, s.z); s.z = 1, 0, 0, 1
    def add(s, lq, rq, v):
        if s.l > rq or s.r < lq: return
        if s.l >= lq and s.r <= rq: s.s = mmul(s.s, v); s.z = mmul(s.z, v); return
        s.push(); s.lc.add(lq, rq, v); s.rc.add(lq, rq, v); s.s = madd(s.lc.s, s.rc.s)
    def get(s, lq, rq):
        if s.l > rq or s.r < lq: return 0, 0, 0, 0
        if s.l >= lq and s.r <= rq: return s.s
        s.push(); return madd(s.lc.get(lq, rq), s.rc.get(lq, rq))

