int k;
string s;
int n;
int mn, mx, c;

string dfs(int i, int rem, vector<vector<string>>& dp) {
	if(i == n) return "";
	if(dp[i][rem] != "") return dp[i][rem];
	string ret = "";
	if(n - (i + mx) >= rem * mn) {
		ret = max(s.substr(i, mx), dfs(i + mx, rem, dp));
	}
	if(rem) {
		if(ret == "") ret = dfs(i + mn, rem - 1, dp);
		else ret = min(ret, dfs(i + mn, rem - 1, dp));
	}
	return dp[i][rem] = ret;
}

