class LinkedList {
    constructor() {
        this.root = undefined;
    }

    enQueue(value) {
        let node =  new Node(value);
        if(!this.root) {
            this.root = node;
        } else {
            let temp = this.root;
            while(temp.getNext()) {
                temp = temp.getNext();
            }
            temp.setNext(node);
        }
    }

    print() {
        let result = [];
        let temp = this.root;
        while(temp) {
            result.push(temp.getData());
            temp = temp.getNext();
        }
        console.log(result.join( ' => '));
    }

    deQueue(val) {
        let temp;
        let previousNode;
        if (!this.root) {
            return;
        }

        if(this.root.getData() === val) {
            this.root = this.root.getNext();
            return;
        }
        previousNode = this.root;
        temp = this.root.getNext();
        while(temp) {
            if (temp.getData() !== val) {
                previousNode = temp;
                temp = temp.getNext();
            } else {
                previousNode.setNext(temp.getNext());
                break;
            }
        }
    }
}

