            }
            vis[u]=1;
            for(int v=0; v<n; v++)
                if(!hash[v]&&!vis[v])
                {
                    w[v]+=dis[u][v];
                    q.push(make_pair(w[v],v));
                }
            for(int tot=2; tot<=cot; tot++)
            {
                int maxi,maxn=-1;
                for(int u=0; u<n; u++)
                    if(!hash[u]&&!vis[u])
                    {
                        if(w[u]>maxn)
                        {
                            maxn=w[u];
                            maxi=u;
                        }
                    }
                vis[maxi]=tot;
                for(int v=0; v<n; v++)
                    if(!hash[v]&&!vis[v])
                    {
                        w[v]+=dis[maxi][v];
                    }
            }
            for(int i=0; i<n; i++)
            {
                if(vis[i]==cot-1)S=i;
                else if(vis[i]==cot)T=i;
            }
            ans=min(ans,w[T]);
            hash[T]=true;
            for(int i=0; i<n; i++)
            {
                dis[S][i]+=dis[T][i];
                dis[i][S]+=dis[i][T];
            }
        }
        printf("%lld\n",ans+tmp);
    }
    return 0;
}

