int BinPow(int x, int k){
    if(k == 0)
        return 1;
    else if(k == 1)
        return x;
    else{
        int sum1 = BinPow(x, k/2) % mod;
        sum1 = (sum1 * sum1)%mod;
        if(k % 2 != 0){
            sum1 = (sum1 * x)%mod, sum1 %= mod;
        }
        return sum1;
    }
}

