void mergesort(int a[], int low, int high)
{
    int mid;
    if(low<high)
    {
        mid=(low+high)/2;
        mergesort(a,low,mid);
        mergesort(a,mid+1,high);
        merge(a,low,mid,high);
    }
}

void merge(int a[], int low, int mid, int high)
{
    int b[1200],i=low,j=mid+1,k=low;
    while(i<=mid && j<=high)
    {
        if(a[i]<a[j])
            b[k++]=a[i++];
        else
            b[k++]=a[j++];
        count++;
    }
    while(i<=mid)
    {
        b[k++]=a[i++];
        count++;
    }
    while(j<=high)
    {
        b[k++]=a[j++];
        count++;
    }
    for(k=low;k<=high;k++)
        a[k]=b[k];
}

